static const char *get_mode_log_filename(asciichat_mode_t mode) {
  switch (mode) {
  case MODE_SERVER:
    return "server.log";
  case MODE_CLIENT:
    return "client.log";
  case MODE_MIRROR:
    return "mirror.log";
  case MODE_DISCOVERY_SERVICE:
    return "acds.log";
  case MODE_DISCOVERY:
    return "discovery.log";
  case MODE_INVALID:
  default:
    return "ascii-chat.log";
  }
}

static void generate_default_log_path(asciichat_mode_t mode, char *buf, size_t buf_size) {
  if (!buf || buf_size == 0) {
    return;
  }

  // Get mode-specific log filename
  const char *log_filename = get_mode_log_filename(mode);

#ifndef NDEBUG
  // Debug mode: use current working directory
  SAFE_STRNCPY(buf, log_filename, buf_size - 1);
#else
  // Non-debug mode: use system temp directory
#ifdef _WIN32
  const char *temp_dir = SAFE_GETENV("TEMP");
  if (!temp_dir) {
    temp_dir = SAFE_GETENV("TMP");
  }
  if (!temp_dir) {
    temp_dir = SAFE_GETENV("USERPROFILE");
  }
  if (!temp_dir) {
    temp_dir = ".";
  }
  safe_snprintf(buf, buf_size, "%s\\ascii-chat\\%s", temp_dir, log_filename);
#else
  safe_snprintf(buf, buf_size, "/tmp/ascii-chat/%s", log_filename);
#endif
  // Create directory if it doesn't exist (non-debug mode only)
  char dir_path[PATH_MAX];
  SAFE_STRNCPY(dir_path, buf, sizeof(dir_path) - 1);
  char *last_slash = strrchr(dir_path, '/');
#ifdef _WIN32
  char *last_backslash = strrchr(dir_path, '\\');
  if (last_backslash && (!last_slash || last_backslash > last_slash)) {
    last_slash = last_backslash;
  }
#endif
  if (last_slash) {
    *last_slash = '\0';
    platform_mkdir_recursive(dir_path, 0700);
  }
#endif
}

bool should_exit(void) {
  return atomic_load_bool(&g_should_exit);
}

void signal_exit(void) {
  // Note: This function may be called from a signal handler context where
  // other threads may hold mutex locks. We avoid log_console() here to prevent
  // deadlock (render loop holds terminal lock, signal handler can't acquire it).
  // The shutdown will be logged by normal thread context later.
  atomic_store_bool(&g_should_exit, true);
  void (*cb)(void) = g_interrupt_callback;
  if (cb) {
    cb();
  }
}

void set_interrupt_callback(void (*cb)(void)) {
  g_interrupt_callback = cb;
}

static void handle_sigterm(int sig) {
  // Write to stderr about which signal was received for debugging
  const char *sig_name = (sig == SIGTERM)  ? "SIGTERM"
                         : (sig == SIGINT) ? "SIGINT"
                         : (sig == SIGHUP) ? "SIGHUP"
                                           : "UNKNOWN";
  char log_out[64];
  safe_snprintf(log_out, sizeof(log_out), "Signal '%s' received", sig_name);

  // If Ctrl+C (SIGINT) and help screen is active, close it instead of exiting
  if (sig == SIGINT && keyboard_help_is_active_global()) {
    log_console(LOG_INFO, "Ctrl+C received - closing help screen");
    keyboard_help_toggle_global();
    return; // Help is now closed, don't exit
  }

  if (sig == SIGTERM || sig == SIGHUP || sig == SIGINT) {
    safe_snprintf(log_out, sizeof(log_out), "%s - shutting down", log_out);
  }
  // log_console() is async-signal-safe - uses atomic ops and platform_write_all()
  log_console(LOG_INFO, log_out);

#ifndef NDEBUG
  // Trigger debug sync state printing on shutdown (async-signal-safe)
  debug_sync_trigger_print();
  debug_errno_trigger_print();
  debug_stats_trigger_print();
#endif

  // Call signal_exit() to set flag AND interrupt blocking socket operations
  signal_exit();
}

static bool console_ctrl_handler(console_ctrl_event_t event) {
  if (event != CONSOLE_CTRL_C && event != CONSOLE_CTRL_BREAK && event != CONSOLE_CLOSE) {
    return false;
  }

  // Check if keyboard help screen is active (defined in session/display.c)
  // Uses atomic load only - safe from signal context
  if (keyboard_help_is_active_global()) {
    // Help screen is active - close it instead of exiting
    log_console(LOG_INFO, "Ctrl+C received - closing help screen");
    keyboard_help_toggle_global();
    return true; // Handled - don't exit
  }

  log_console(LOG_INFO, "Ctrl+C received - shutting down");

#ifndef NDEBUG
  // Trigger debug sync state printing on shutdown (async-signal-safe)
  debug_sync_trigger_print();
  debug_errno_trigger_print();
  debug_stats_trigger_print();
#endif

  // Double Ctrl+C forces immediate exit
  static atomic_t ctrl_c_count = {0};
  static bool ctrl_c_count_registered = false;
  if (!ctrl_c_count_registered) {
    NAMED_REGISTER_ATOMIC(&ctrl_c_count, "ctrl_c_interrupt_count", NULL);
    ctrl_c_count_registered = true;
  }
  if (atomic_fetch_add_int(&ctrl_c_count, 1) + 1 > 1) {
    platform_force_exit(1);
  }

  signal_exit();
  return true;
}

static void common_handle_sigusr1(int sig) {
  (void)sig;
  debug_sync_trigger_print();
  debug_errno_trigger_print();
  debug_stats_trigger_print();
}

static void common_handle_sigusr2(int sig) {
  (void)sig;
  // Log to stderr directly since we're in signal context
  // (avoid logging system which uses mutexes)
  debug_memory_trigger_report();
}

void setup_signal_handlers(void) {
  platform_set_console_ctrl_handler(console_ctrl_handler);

#ifndef _WIN32
  platform_signal_handler_t handlers[] = {
      {SIGINT, handle_sigterm},
      {SIGTERM, handle_sigterm},
      {SIGPIPE, SIG_IGN},
  };
  platform_register_signal_handlers(handlers, 3);
  log_debug("Signal handlers registered");
#endif
}

static void print_usage(asciichat_mode_t mode) {
  // Use the new usage() function from common.c which handles mode-specific help properly
  usage(stdout, mode);
}

static const mode_descriptor_t *find_mode(asciichat_mode_t mode) {
  // Bounds check: ensure mode is within valid range (0 to MODE_INVALID)
  if (mode < MODE_SERVER || mode > MODE_INVALID) {
    return NULL;
  }
  return g_mode_lookup[mode];
}

static void on_exit_show_cursor(void) {
  ui_controller_restore_terminal();
}

int main(int argc, char *argv[]) {
  // Set global argc/argv for early argv inspection (e.g., in terminal.c)
  g_argc = argc;
  g_argv = argv;

  // Validate basic argument structure
  if (argc < 1 || argv == NULL || argv[0] == NULL) {
    return 1;
  }

  // Initialize the named registry for debugging (allows --debug-state to show registered synchronization primitives)
#ifndef NDEBUG
  named_init();
  // Initialize atomic operations debug tracking
  debug_atomic_init();
  // Register global atomics with descriptive names for debug sync state monitoring
  REGISTER_GLOBAL_ATOMICS();
  // Static atomics are now auto-registered via ATOMIC_INIT_AUTO macro at definition time
  // Register all packet types from the packet_type_t enum
  named_registry_register_packet_types();
#endif

  // Register the main thread IMMEDIATELY after named_init() to ensure it's available for all subsequent allocations
#ifndef NDEBUG
#ifdef _WIN32
  NAMED_REGISTER_THREAD(GetCurrentThread(), "main", NULL);
#else
  NAMED_REGISTER_THREAD((asciichat_thread_t)asciichat_thread_self(), "main", NULL);
#endif
  // Also save main thread ID for memory reporting (must be very early)
  debug_stats_set_main_thread_id();
#endif

  // Preserve arguments before environment consumers or option parsing retain pointers.
  asciichat_errno_scope_t title_init_scope = asciichat_errno_scope_begin();
  asciichat_error_t title_init_result = platform_process_title_init(argc, &argv);
  if (title_init_result == ASCIICHAT_OK)
    ASSERT_NO_ERRNO_SINCE(title_init_scope);
  asciichat_errno_scope_end(title_init_scope, ASCIICHAT_ERRNO_DISMISSED);
  g_argv = argv;
  (void)atexit(platform_process_title_destroy);

  // Show cursor early in case a previous session crashed with it hidden.
  if (platform_isatty(STDOUT_FILENO))
    (void)ui_controller_write(STDOUT_FILENO, "\033[?25h", 6);

  // VERY FIRST: Scan for --color BEFORE ANY logging initialization
  // This sets global flags that persist through cleanup, enabling --color to force colors
  for (int i = 1; i < argc; i++) {
    if (strcmp(argv[i], "--color") == 0 || strcmp(argv[i], "--color=true") == 0) {
      g_color_flag_passed = true;
      g_color_flag_value = true;
      break;
    } else if (strncmp(argv[i], "--color=", 8) == 0) {
      g_color_flag_passed = true;
      g_color_flag_value = strcmp(argv[i], "--color=false") != 0;
      break;
    }
  }

  // SECOND: Scan for --grep BEFORE ANY logging initialization
  // This ensures ALL logs (including from shared_init) can be filtered
  // Supports multiple --grep patterns (ORed together)
  for (int i = 1; i < argc - 1; i++) {
    if (strcmp(argv[i], "--grep") == 0) {
      const char *pattern = argv[i + 1];
      asciichat_error_t filter_result = grep_init(pattern);
      if (filter_result != ASCIICHAT_OK) {
        log_error("Invalid --grep pattern or invalid flags: \"%s\" - use /pattern/flags format (e.g., \"/query/ig\" or "
                  "\"/literal/F\")",
                  pattern);
        return 1;
      }
      i++; // Skip the pattern argument
    }
  }

  // Detect terminal capabilities early so colored help output works
  // Logging will be initialized by asciichat_shared_init() before options_init()
  log_redetect_terminal_capabilities();
  terminal_capabilities_t caps = detect_terminal_capabilities();
  caps = apply_color_mode_override(caps);

  // Warn if Release build was built from dirty working tree
#if ASCII_CHAT_GIT_IS_DIRTY
  if (strcmp(ASCII_CHAT_BUILD_TYPE, "Release") == 0) {
    // Dirty git warning will be logged after logging initialization
  }
#endif

  // Load color scheme early (from config files and CLI) before logging initialization
  // This allows logging to use the correct colors from the start
  options_colorscheme_init_early(argc, argv);

  // Parse --color-scheme from argv early to set logging colors for help output
  const char *colorscheme_name = "pastel"; // default
  for (int i = 1; i < argc - 1; i++) {
    if (strcmp(argv[i], "--color-scheme") == 0) {
      colorscheme_name = argv[i + 1];
      break;
    }
  }

  // Load and apply colorscheme to logging BEFORE options_init() so help gets colors
  color_scheme_t scheme;
  if (colorscheme_load_builtin(colorscheme_name, &scheme) == ASCIICHAT_OK) {
    log_set_color_scheme(&scheme);
  } else {
    // Fall back to default pastel if scheme not found
    if (colorscheme_load_builtin("pastel", &scheme) == ASCIICHAT_OK) {
      log_set_color_scheme(&scheme);
    }
  }

  // Initialize logging colors so they're ready for help output
  log_init_colors();

  // EARLY PARSE: Find the mode position (first positional argument)
  // Binary-level options must appear BEFORE the mode
  int mode_position = -1;
  for (int i = 1; i < argc; i++) {
    if (argv[i][0] != '-') {
      // Found a positional argument - this is the mode or session string
      mode_position = i;
      break;
    }

    // Skip option and its argument if needed
    // Check if this is an option that takes a required argument
    const char *arg = argv[i];
    const char *opt_name = arg;
    if (arg[0] == '-') {
      opt_name = arg + (arg[1] == '-' ? 2 : 1);
    }

    // Handle --option=value format
    if (strchr(opt_name, '=')) {
      continue; // Value is part of this arg, no need to skip next
    }

    // Options that take required arguments
    if (strcmp(arg, "--log-file") == 0 || strcmp(arg, "-L") == 0 || strcmp(arg, "--log-level") == 0 ||
        strcmp(arg, "--config") == 0 || strcmp(arg, "--color-scheme") == 0 || strcmp(arg, "--log-template") == 0) {
      if (i + 1 < argc) {
        i++; // Skip the argument value
      }
    }
  }

  // EARLY PARSE: Determine mode from argv to know if this is client-like mode
  // The first positional argument (after options) is the mode: client, server, mirror, discovery, acds
  bool is_client_like_mode = false;
  if (mode_position > 0) {
    const char *first_arg = argv[mode_position];
    if (strcmp(first_arg, "client") == 0 || strcmp(first_arg, "mirror") == 0 || strcmp(first_arg, "discovery") == 0) {
      is_client_like_mode = true;
    }
  }

  // EARLY PARSE: Extract log file from argv (--log-file or -L)
  // Must appear BEFORE the mode
  // Generate default log path based on build type and mode
  char default_log_path[PATH_MAX];
  asciichat_mode_t detected_mode = MODE_INVALID;
  if (mode_position > 0) {
    const char *mode_str = argv[mode_position];
    // Convert mode string to enum
    if (strcmp(mode_str, "server") == 0) {
      detected_mode = MODE_SERVER;
    } else if (strcmp(mode_str, "client") == 0) {
      detected_mode = MODE_CLIENT;
    } else if (strcmp(mode_str, "mirror") == 0) {
      detected_mode = MODE_MIRROR;
    } else if (strcmp(mode_str, "acds") == 0 || strcmp(mode_str, "discovery-service") == 0) {
      detected_mode = MODE_DISCOVERY_SERVICE;
    } else if (strcmp(mode_str, "discovery") == 0) {
      detected_mode = MODE_DISCOVERY;
    }
  }
  generate_default_log_path(detected_mode, default_log_path, sizeof(default_log_path));

  const char *log_file = default_log_path;
  int max_search = (mode_position > 0) ? mode_position : argc;
  for (int i = 1; i < max_search - 1; i++) {
    if ((strcmp(argv[i], "--log-file") == 0 || strcmp(argv[i], "-L") == 0)) {
      log_file = argv[i + 1];
      break;
    }
  }

  // EARLY PARSE: Check for --json (JSON logging format)
  // If JSON format is enabled, we'll use the JSON filename during early init
  // --json MUST appear BEFORE the mode
  bool early_json_format = false;
  if (mode_position > 0) {
    for (int i = 1; i < mode_position; i++) {
      if (strcmp(argv[i], "--json") == 0) {
        early_json_format = true;
        break;
      }
    }
  } else {
    // If no mode found, search entire argv
    for (int i = 1; i < argc; i++) {
      if (strcmp(argv[i], "--json") == 0) {
        early_json_format = true;
        break;
      }
    }
  }

  // EARLY PARSE: Extract log template from argv (--log-template)
  // Note: This is for format templates, different from --log-format which is the output format
  // Binary-level options must appear BEFORE the mode
  const char *early_log_template = NULL;
  bool early_log_template_console_only = false;
  for (int i = 1; i < max_search - 1; i++) {
    if (strcmp(argv[i], "--log-template") == 0) {
      early_log_template = argv[i + 1];
      break;
    }
  }
  for (int i = 1; i < max_search; i++) {
    if (strcmp(argv[i], "--log-format-console-only") == 0) {
      early_log_template_console_only = true;
      break;
    }
  }

  // Documentation actions should not be preceded by startup diagnostics.
  bool early_quiet_output = false;
  for (int i = 1; i < argc; i++) {
    if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--version") == 0 ||
        strcmp(argv[i], "-V") == 0) {
      early_quiet_output = true;
      break;
    }
  }

  // Initialize shared subsystems BEFORE options_init()
  // This ensures options parsing can use properly configured logging with colors
  // If JSON format is requested, don't write text logs to file
  // All logs will be JSON formatted later once options_init() runs
  const char *early_log_file = early_json_format ? NULL : log_file;
  asciichat_error_t init_result = asciichat_shared_init(early_log_file, is_client_like_mode, early_quiet_output);
  if (init_result != ASCIICHAT_OK) {
    return init_result;
  }

  // Route logs to stderr if stdout is piped (MUST happen early, before options_init logs)
  // This keeps stdout clean for data output (e.g., --snapshot mode piped to file)
  if (terminal_should_force_stderr()) {
    log_set_force_stderr(true);
  }

  // Keep documentation output free of diagnostics while parsing the options.
  if (early_quiet_output) {
    log_set_terminal_output(false);
  }

  // Register cleanup of shared subsystems to run on normal exit
  // Library code doesn't call atexit() - the application is responsible
  // IMPORTANT: atexit handlers run in LIFO order - last registered runs first
  // So register order (top to bottom) = execution order (bottom to top):
  // 1. PCRE2 cleanup (runs last) - frees compiled regexes after all code stops using them
  // 2. Path cleanup (runs 3rd) - now a no-op but kept for API compatibility
  // 3. Shared destroy (runs 2nd) - frees all shared resources
  // 4. Cursor show (runs 1st) - shows cursor before exit
  (void)atexit(asciichat_pcre2_cleanup_all);
  (void)atexit(path_cleanup_thread_locals);
  (void)atexit(asciichat_shared_destroy);
  (void)atexit(on_exit_show_cursor);

  // SECRET: Check for --backtrace (debug builds only) BEFORE options_init()
  // Prints a backtrace and exits immediately - useful for debugging hangs
#ifndef NDEBUG
  for (int i = 1; i < argc; i++) {
    if (strcmp(argv[i], "--backtrace") == 0) {
      log_info("=== Backtrace at startup ===");
      backtrace_print_simple(0);
      log_info("=== End Backtrace ===");
      asciichat_shared_destroy();
      return 0;
    }
  }
#endif

  // NOW parse all options - can use logging with colors!
  asciichat_error_t options_result = options_init(argc, argv);
  if (options_result != ASCIICHAT_OK) {
    asciichat_error_context_t error_ctx;
    if (HAS_ERRNO(&error_ctx)) {
      NOTICE(WARNING, "INVALID OPTIONS", "%s", error_ctx.context_message);
    } else {
      NOTICE(WARNING, "OPTIONS INITIALIZATION FAILED", "Failed to initialize options (error code: %d)", options_result);
    }

    // Clean up options state before exiting
    options_state_destroy();
    options_cleanup_schema();

    exit(options_result);
  }

  // Get parsed options
  const options_t *opts = options_get();
  if (!opts) {
    log_error("Error: Options not initialized");
    return 1;
  }

  // Apply the parsed level after the early logger has initialized.
  log_set_level(opts->log_level);
  // Determine output format early to decide on filename and logging strategy
  bool use_json_logging = GET_OPTION(json);

  // Determine the log filename
  // Check if user explicitly passed --log-file (not just the mode-specific default from options_init)
  bool user_specified_log_file = false;
  for (int i = 1; i < argc - 1; i++) {
    if (strcmp(argv[i], "--log-file") == 0 || strcmp(argv[i], "-L") == 0) {
      user_specified_log_file = true;
      break;
    }
  }

  const char *final_log_file = opts->log_file;
  char json_filename_buf[256];

  if (use_json_logging) {
    // When JSON logging is enabled, determine JSON output filename
    if (user_specified_log_file) {
      // User explicitly specified a log file - use it exactly for JSON output
      SAFE_STRNCPY(json_filename_buf, final_log_file, sizeof(json_filename_buf) - 1);
    } else {
      // Using default: replace .log with .json in the mode-specific default
      // e.g., server.log -> server.json, mirror.log -> mirror.json, etc.
      size_t len = strlen(final_log_file);
      if (len > 4 && strcmp(&final_log_file[len - 4], ".log") == 0) {
        // File ends with .log - replace with .json
        SAFE_STRNCPY(json_filename_buf, final_log_file, sizeof(json_filename_buf) - 1);
        // Replace .log with .json
        asciichat_error_t strcpy_result =
            SAFE_STRCPY(&json_filename_buf[len - 4], sizeof(json_filename_buf) - (len - 4), ".json");
        if (strcpy_result != ASCIICHAT_OK) {
          log_error("Failed to write .json extension: %s", asciichat_error_string(strcpy_result));
        }
      } else {
        // File doesn't end with .log - just append .json
        snprintf(json_filename_buf, sizeof(json_filename_buf), "%s.json", final_log_file);
      }
    }
    final_log_file = json_filename_buf;
    // For JSON mode: Initialize logging without file (text will be disabled)
    // We'll set up JSON output separately below
    // Note: log_init() was already called in asciichat_shared_init()
  } else {
    // Text logging mode: use the file from options (which is mode-specific default or user-specified)
    // Note: log_init() was already called in asciichat_shared_init()
  }

  // Apply custom log template if specified (use early parsed value if available, otherwise use options)
  const char *final_format = early_log_template ? early_log_template : GET_OPTION(log_template);
  bool final_format_console_only =
      early_log_template ? early_log_template_console_only : GET_OPTION(log_format_console_only);
  if (final_format && final_format[0] != '\0') {
    asciichat_error_t fmt_result = log_set_format(final_format, final_format_console_only);
    if (fmt_result != ASCIICHAT_OK) {
      log_error("Failed to apply custom log format");
    }
  }

  // Configure JSON output if requested
  if (use_json_logging) {
    // Open the JSON file for output
    int json_fd = platform_open("main_log_file", final_log_file, O_CREAT | O_RDWR | O_TRUNC, FILE_PERM_PRIVATE);
    if (json_fd >= 0) {
      log_set_json_output(json_fd);
    } else {
      // Failed to open JSON file - report error and exit
      SET_ERRNO(ERROR_CONFIG, "Failed to open JSON output file: %s", final_log_file);
      return ERROR_CONFIG;
    }
  }

  // Initialize colors now that logging is fully initialized
  // This must happen after log_init() since log_init_colors() checks if g_log.initialized
  log_init_colors();
  log_debug("SIMD luminance backend: %s", simd_backend()->name);

  // Apply quiet mode - disables terminal output
  // Status screen mode only disables terminal output if terminal is interactive
  // In non-interactive mode (piped output), logs go to stdout/stderr normally
  if (GET_OPTION(quiet) ||
      (opts->detected_mode == MODE_SERVER && GET_OPTION(status_screen) && terminal_is_interactive())) {
    log_set_terminal_output(false);
  }

  // Initialize palette based on command line options
  const char *custom_chars = opts && opts->palette_custom_set ? opts->palette_custom : NULL;
  if (apply_palette_config(GET_OPTION(palette_type), custom_chars) != 0) {
    FATAL(ERROR_CONFIG, "Failed to apply palette configuration");
  }

  // Set quiet mode for memory debugging
#if defined(DEBUG_MEMORY) && !defined(USE_MIMALLOC_DEBUG) && !defined(NDEBUG)
  debug_memory_set_quiet_mode(GET_OPTION(quiet));
#endif

  // Truncate log if it's already too large
  log_truncate_if_large();
  fflush(stderr);

  // Handle --help and --version (these are detected and flagged by options_init)
  // Terminal capabilities already initialized before options_init() at startup
  if (opts->help) {
    log_set_terminal_output(true);
    print_usage(opts->detected_mode);
    fflush(NULL);
    _Exit(0);
  }

  if (opts->version) {
    log_set_terminal_output(true);
    action_show_version();
    // action_show_version() calls _Exit(), so we don't reach here
  }

#ifndef NDEBUG
  // Handle --debug-state (debug builds only)
  // Sleep for specified time AFTER mode initialization so locks are created
  if (IS_OPTION_EXPLICIT(debug_sync_state_time, opts) && opts->debug_sync_state_time > 0.0) {
    log_info("Will print sync state after %f seconds", opts->debug_sync_state_time);
  }
#endif

  // For server mode with status screen: disable terminal output only if interactive
  // In non-interactive mode (piped output), logs go to stdout/stderr normally
  // The status screen (when shown) will capture and display logs in its buffer instead
  if (opts->detected_mode == MODE_SERVER && opts->status_screen && terminal_is_interactive()) {
    log_set_terminal_output(false);
  }

  log_dev("Logging initialized to %s", final_log_file);

  // Note: We do NOT auto-disable colors when stdout appears to be piped, because:
  // 1. Tools like ripgrep can display ANSI colors when piped
  // 2. Sandboxed/containerized environments may report false positives for isatty()
  // 3. Users can explicitly disable colors with --color=false if needed
  // Color behavior is now fully controlled by --color and --color-mode options.

#ifndef NDEBUG
  // Initialize lock debugging system after logging is fully set up
  log_debug("Initializing lock debug system...");
  int debug_sync_result = debug_stats_init();
  if (debug_sync_result != 0) {
    LOG_ERRNO_IF_SET("Debug sync system initialization failed");
    FATAL(ERROR_PLATFORM_INIT, "Debug sync system initialization failed");
  }
  log_debug("Debug sync system initialized successfully");

  // Initialize memory debug system
  // TEMPORARILY DISABLED: these calls hang in non-interactive mode
  // log_debug("Initializing memory debug system...");
  // int debug_memory_result = debug_memory_thread_init();
  // if (debug_memory_result != 0) {
  //   LOG_ERRNO_IF_SET("Memory debug system initialization failed");
  //   FATAL(ERROR_PLATFORM_INIT, "Memory debug system initialization failed");
  // }
  // log_debug("Memory debug system initialized successfully");

  // Start memory debug (now just prints report directly)
  // if (debug_memory_thread_start() != 0) {
  //   LOG_ERRNO_IF_SET("Memory debug startup failed");
  //   FATAL(ERROR_THREAD, "Memory debug startup failed");
  // }

#ifndef _WIN32
  // Unblock SIGUSR1 and SIGUSR2 at process level to ensure delivery
  sigset_t set;
  sigemptyset(&set);
  sigaddset(&set, SIGUSR1);
  sigaddset(&set, SIGUSR2);
  sigprocmask(SIG_UNBLOCK, &set, NULL);

  // Register SIGUSR1 to trigger synchronization debugging output in all modes
  signal_handler_t old_usr1 = platform_signal(SIGUSR1, common_handle_sigusr1);
  if (old_usr1 == SIG_ERR) {
    log_warn("Failed to register SIGUSR1 handler");
  } else {
    log_debug("SIGUSR1 handler registered successfully");
  }

  // Register SIGUSR2 to trigger memory report in all modes
  signal_handler_t old_usr2 = platform_signal(SIGUSR2, common_handle_sigusr2);
  if (old_usr2 == SIG_ERR) {
    log_warn("Failed to register SIGUSR2 handler");
  } else {
    log_debug("SIGUSR2 handler registered successfully");
  }
#endif
#endif

  if (opts->fps > 0) {
    if (opts->fps < 1 || opts->fps > 144) {
      log_warn("FPS value %d out of range (1-144), using default", opts->fps);
    } else {
      log_debug("FPS set from command line: %d", opts->fps);
    }
  }

  // Automatic update check in background thread (once per week maximum)
  if (!GET_OPTION(no_check_update)) {
    update_banner_start_check();
  }

  // Set up global signal handlers BEFORE mode dispatch
  // All modes use the same centralized exit mechanism
  setup_signal_handlers();

  // Register application callbacks so lib code can check exit flags
  // This connects the render loop's should_exit check to signal_exit()
  static const app_callbacks_t app_callbacks = {
      .should_exit = should_exit,
      .signal_exit = signal_exit,
      .platform_get_monotonic_time_us = platform_get_monotonic_time_us,
      .platform_sleep_ms = platform_sleep_ms,
  };
  app_callbacks_register(&app_callbacks);

  // Register shutdown callback so splash thread and other code can check for exit
  shutdown_register_callback((shutdown_check_fn)should_exit);

  // Diagnostic monitoring is Debug-only; error storage is available in every build.
#ifndef NDEBUG
  if (debug_sync_start_thread() != ASCIICHAT_OK) {
    FATAL(ERROR_THREAD, "Cannot start synchronization worker");
  }
  if (debug_errno_start_thread() != ASCIICHAT_OK) {
    FATAL(ERROR_THREAD, "Cannot start errno worker");
  }
  if (debug_stats_start_thread() != ASCIICHAT_OK) {
    FATAL(ERROR_THREAD, "Cannot start diagnostics worker");
  }
#endif

  // Find and dispatch to mode entry point
  const mode_descriptor_t *mode = find_mode(opts->detected_mode);
  if (!mode) {
    log_error("Error: Mode not found for detected_mode=%d", opts->detected_mode);
    return 1;
  }

  // Call the mode-specific entry point
  // Mode entry points use options_get() to access parsed options
  if (title_init_result == ASCIICHAT_OK) {
    asciichat_errno_scope_t title_scope = asciichat_errno_scope_begin();
    asciichat_error_t title_result = platform_process_title_set_args(mode->name, argc, argv, opts->mode_arg_index);
    if (title_result != ASCIICHAT_OK) {
      log_debug("Could not set process title for %s mode", mode->name);
    } else {
      ASSERT_NO_ERRNO_SINCE(title_scope);
    }
    asciichat_errno_scope_end(title_scope, ASCIICHAT_ERRNO_DISMISSED);
  } else {
    log_debug("Process title initialization was unavailable (error %d)", title_init_result);
  }
  asciichat_error_t stats_result = stats_runtime_start(mode->name, (unsigned)GET_OPTION(stats_interval));
  if (stats_result != ASCIICHAT_OK)
    return stats_result;
  int exit_code = mode->entry_point();
  asciichat_error_t requested_exit = asciichat_errno_exit_code();
  if (requested_exit != ASCIICHAT_OK)
    exit_code = requested_exit;
  stats_runtime_stop();

  // Named registry cleanup is handled by asciichat_shared_destroy()
  // (called via atexit handler), which runs AFTER the memory report

  if (exit_code == ERROR_USAGE) {
    exit(ERROR_USAGE);
  }

  return exit_code;
}

static int audio_queue_packet(const uint8_t *opus_data, size_t opus_size, const uint16_t *frame_sizes,
                              int frame_count) {
  if (!lifecycle_is_initialized(&g_audio_send_queue_lc) || !opus_data || opus_size == 0) {
    return -1;
  }

  mutex_lock(&g_audio_send_queue_mutex);

  // Check if queue is full
  int next_head = (g_audio_send_queue_head + 1) % AUDIO_SEND_QUEUE_SIZE;
  if (next_head == g_audio_send_queue_tail) {
    mutex_unlock(&g_audio_send_queue_mutex);
    log_warn_every(LOG_RATE_FAST, "Audio send queue full, dropping packet");
    return -1;
  }

  // Copy packet to queue
  audio_send_packet_t *packet = &g_audio_send_queue[g_audio_send_queue_head];
  if (opus_size > sizeof(packet->data)) {
    mutex_unlock(&g_audio_send_queue_mutex);
    log_warn("Audio packet too large for queue: %zu > %zu bytes", opus_size, sizeof(packet->data));
    return -1;
  }

  memcpy(packet->data, opus_data, opus_size);
  packet->size = opus_size;
  packet->frame_count = frame_count;
  for (int i = 0; i < frame_count && i < 8; i++) {
    packet->frame_sizes[i] = frame_sizes[i];
  }
  g_audio_send_queue_head = next_head;

  // Signal sender thread (must be held while signaling)
  cond_signal(&g_audio_send_queue_cond);
  mutex_unlock(&g_audio_send_queue_mutex);

  return 0;
}

static void *audio_sender_thread_func(void *arg) {
  (void)arg;
  log_debug("Audio sender thread started");

  static int send_count = 0;

  while (!atomic_load_bool(&g_audio_sender_should_exit)) {
    mutex_lock(&g_audio_send_queue_mutex);

    // Wait for packet or exit signal (cond_wait re-acquires mutex before returning)
    while (g_audio_send_queue_head == g_audio_send_queue_tail && !atomic_load_bool(&g_audio_sender_should_exit)) {
      cond_wait(&g_audio_send_queue_cond, &g_audio_send_queue_mutex);
    }

    // Check exit flag after waking from cond_wait
    if (atomic_load_bool(&g_audio_sender_should_exit)) {
      mutex_unlock(&g_audio_send_queue_mutex);
      break;
    }

    // Safety check: ensure queue actually has data (handle spurious wakeups)
    if (g_audio_send_queue_head == g_audio_send_queue_tail) {
      // Spurious wakeup - queue is empty, go back to waiting
      mutex_unlock(&g_audio_send_queue_mutex);
      continue;
    }

    // Dequeue packet
    audio_send_packet_t packet = g_audio_send_queue[g_audio_send_queue_tail];
    g_audio_send_queue_tail = (g_audio_send_queue_tail + 1) % AUDIO_SEND_QUEUE_SIZE;

    mutex_unlock(&g_audio_send_queue_mutex);

    // Send packet (may block on network I/O - that's OK, we're not in capture thread)
    asciichat_errno_scope_t send_scope = asciichat_errno_scope_begin();
    START_TIMER("network_send_audio");
    asciichat_error_t send_result =
        threaded_send_audio_opus_batch(packet.data, packet.size, packet.frame_sizes, packet.frame_count);
    double send_time_ns = STOP_TIMER("network_send_audio");

    send_count++;
    if (send_result != ASCIICHAT_OK) {
      LOG_ERRNO_IF_SET("Failed to send audio packet");
      if (!network_error_is_local_rejection(send_result))
        break;
      asciichat_errno_scope_end(send_scope, ASCIICHAT_ERRNO_HANDLED);
    } else {
      ASSERT_NO_ERRNO_SINCE(send_scope);
      asciichat_errno_scope_end(send_scope, ASCIICHAT_ERRNO_HANDLED);
    }
    if (send_result == ASCIICHAT_OK && send_count % 50 == 0) {
      char duration_str[32];
      time_pretty((uint64_t)(send_time_ns), -1, duration_str, sizeof(duration_str));
      log_debug("Audio network send #%d: %zu bytes (%d frames) in %s", send_count, packet.size, packet.frame_count,
                duration_str);
    }
  }

  // Clean up thread-local error context before exit

  // Signal that audio sender thread has exited
  atomic_store_bool(&g_audio_sender_exited, true);

  return NULL;
}

void audio_sender_init(void) {
  log_debug("[AUDIO_SENDER_INIT] Starting audio sender initialization");

  if (!lifecycle_init(&g_audio_send_queue_lc, "audio_queue")) {
    log_debug("[AUDIO_SENDER_INIT] Already initialized, returning early");
    return; // Already initialized
  }

  log_debug("[AUDIO_SENDER_INIT] Initializing mutex");
  // Initialize queue structures with error checking
  if (mutex_init(&g_audio_send_queue_mutex, "audio_send_queue_mutex") != 0) {
    log_error("[AUDIO_SENDER_INIT] Failed to initialize audio queue mutex");
    return;
  }

  log_debug("[AUDIO_SENDER_INIT] Initializing condition variable");
  if (cond_init(&g_audio_send_queue_cond, "audio_send_queue_cond") != 0) {
    log_error("[AUDIO_SENDER_INIT] Failed to initialize audio queue condition variable");
    mutex_destroy(&g_audio_send_queue_mutex);
    return;
  }

  log_debug("[AUDIO_SENDER_INIT] Setting queue state");
  g_audio_send_queue_head = 0;
  g_audio_send_queue_tail = 0;
  atomic_store_bool(&g_audio_sender_should_exit, false);
  atomic_store_bool(&g_audio_sender_exited, false);

  log_debug("[AUDIO_SENDER_INIT] Spawning audio sender thread");
  // Start sender thread (after lock release to avoid blocking other threads)
  if (thread_pool_spawn(g_client_worker_pool, audio_sender_thread_func, NULL, 5, "audio_sender") == ASCIICHAT_OK) {
    g_audio_sender_thread_created = true;
    log_debug("[AUDIO_SENDER_INIT] ✓ Audio sender thread created successfully");
  } else {
    log_error("[AUDIO_SENDER_INIT] Failed to spawn audio sender thread in worker pool");
    LOG_ERRNO_IF_SET("Audio sender thread creation failed");
  }
}

void audio_sender_cleanup(void) {
  // Signal thread to exit
  if (lifecycle_is_initialized(&g_audio_send_queue_lc)) {
    atomic_store_bool(&g_audio_sender_should_exit, true);
    mutex_lock(&g_audio_send_queue_mutex);
    cond_signal(&g_audio_send_queue_cond);
    mutex_unlock(&g_audio_send_queue_mutex);
  }

  // The worker is joined by thread_pool_stop_all() in protocol_stop_connection().
  // Keep the queue synchronization objects alive until that join completes.
  if (THREAD_IS_CREATED(g_audio_sender_thread_created)) {
    log_debug("Audio sender thread will be joined by thread pool");
  }
}

void audio_sender_finalize(void) {
  if (!lifecycle_is_initialized(&g_audio_send_queue_lc)) {
    return;
  }

  // thread_pool_stop_all() normally joins this worker. If the sender was
  // blocked in transport I/O when the pool timeout elapsed, wait for the
  // shutdown signal to be observed before destroying its queue mutex.
  for (int i = 0; i < 200 && !atomic_load_bool(&g_audio_sender_exited); i++) {
    platform_sleep_us(10 * US_PER_MS_INT);
  }
  if (!atomic_load_bool(&g_audio_sender_exited)) {
    log_warn("Audio sender thread did not exit before queue cleanup");
    return;
  }

  mutex_destroy(&g_audio_send_queue_mutex);
  cond_destroy(&g_audio_send_queue_cond);
  lifecycle_shutdown(&g_audio_send_queue_lc);
  g_audio_sender_thread_created = false;
}

void audio_process_received_samples(const float *samples, int num_samples) {
  // Validate parameters
  if (!samples || num_samples <= 0) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Invalid audio samples: samples=%p, num_samples=%d", (void *)samples, num_samples);
    return;
  }

  if (!GET_OPTION(audio_enabled)) {
    log_warn_every(NS_PER_MS_INT, "Received audio samples but audio is disabled");
    return;
  }

  // Allow both single packets and batched packets
  if (num_samples > AUDIO_BATCH_SAMPLES) {
    log_warn("Audio packet too large: %d samples (max %d)", num_samples, AUDIO_BATCH_SAMPLES);
    return;
  }

  // Calculate RMS energy of received samples
  float sum_squares = 0.0f;
  for (int i = 0; i < num_samples; i++) {
    sum_squares += samples[i] * samples[i];
  }
  float received_rms = sqrtf(sum_squares / num_samples);

  // DUMP: Received audio from server (before playback processing)
  if (g_wav_playback_received) {
    wav_writer_write(g_wav_playback_received, samples, num_samples);
  }

  // Track samples for analysis
  if (GET_OPTION(audio_analysis_enabled)) {
    for (int i = 0; i < num_samples; i++) {
      audio_analysis_track_received_sample(samples[i]);
    }
  }

  // Copy samples to playback buffer (no processing needed - mixer already handled clipping)
  float audio_buffer[AUDIO_BATCH_SAMPLES];
  memcpy(audio_buffer, samples, (size_t)num_samples * sizeof(float));

  // DEBUG: Log what we're writing to playback buffer (with first 4 samples to verify audio integrity)
  static int recv_count = 0;
  recv_count++;
  if (recv_count <= 10 || recv_count % 50 == 0) {
    float peak = 0.0f;
    for (int i = 0; i < num_samples; i++) {
      float abs_val = fabsf(samples[i]);
      if (abs_val > peak)
        peak = abs_val;
    }
    log_debug("CLIENT AUDIO RECV #%d: %d samples, RMS=%.6f, Peak=%.6f, first4=[%.4f,%.4f,%.4f,%.4f]", recv_count,
              num_samples, received_rms, peak, num_samples > 0 ? samples[0] : 0.0f, num_samples > 1 ? samples[1] : 0.0f,
              num_samples > 2 ? samples[2] : 0.0f, num_samples > 3 ? samples[3] : 0.0f);
  }

  // Submit to playback system (goes to jitter buffer and speakers)
  // NOTE: AEC3's AnalyzeRender is called in output_callback() when audio actually plays,
  // NOT here. The jitter buffer adds 50-100ms delay, so calling AnalyzeRender here
  // would give AEC3 the wrong timing and break echo cancellation.
  audio_write_samples(&g_audio_context, audio_buffer, num_samples);

  // Log latency after writing to playback buffer
  if (g_audio_context.playback_buffer) {
    size_t buffer_samples = audio_ring_buffer_available_read(g_audio_context.playback_buffer);
    float buffer_latency_ms = (float)buffer_samples / 48.0f;
    log_dev_every(500 * US_PER_MS_INT, "LATENCY: Client playback buffer after recv: %.1fms (%zu samples)",
                  buffer_latency_ms, buffer_samples);
  }

#ifdef DEBUG_AUDIO
  log_debug_every(US_PER_SEC_INT, "Processed %d received audio samples", num_samples);
#endif
}

static void *audio_capture_thread_func(void *arg) {
  (void)arg;

  log_debug("Audio capture thread started");

  // FPS tracking for audio capture thread (tracking Opus frames, ~50 FPS at 20ms per frame)
  static fps_t fps_tracker = {0};
  static bool fps_tracker_initialized = false;
  if (!fps_tracker_initialized) {
    fps_init(&fps_tracker, 50, "AUDIO_TX");
    fps_tracker_initialized = true;
  }

  // Detailed timing stats
  static double total_loop_ns = 0;
  static double total_read_ns = 0;
  static double total_encode_ns = 0;
  static double total_queue_ns = 0;
  static double max_loop_ns = 0;
  static double max_read_ns = 0;
  static double max_encode_ns = 0;
  static double max_queue_ns = 0;
  static uint64_t timing_loop_count = 0;

// Opus frame size: 960 samples = 20ms @ 48kHz (must match pipeline config)
#define OPUS_FRAME_SAMPLES 960
#define OPUS_MAX_PACKET_SIZE 500 // Max Opus packet size

  // Read enough samples per iteration to drain faster than we fill
  // Buffer holds multiple Opus frames worth to prevent overflow
  // 4 frames = 3840 samples = 80ms, but we'll read what's available up to this
#define CAPTURE_READ_SIZE (OPUS_FRAME_SAMPLES * 4)

  float audio_buffer[CAPTURE_READ_SIZE];
  static bool wav_dumpers_initialized = false;

  // Initialize WAV dumpers only once (file handles persist)
  if (!wav_dumpers_initialized && wav_dump_enabled()) {
    char tmp[PLATFORM_MAX_PATH_LENGTH];
    if (platform_get_temp_dir(tmp, sizeof(tmp))) {
      char path[PLATFORM_MAX_PATH_LENGTH];
      safe_snprintf(path, sizeof(path), "%s/audio_capture_raw.wav", tmp);
      g_wav_capture_raw = wav_writer_open(path, AUDIO_SAMPLE_RATE, 1);
      safe_snprintf(path, sizeof(path), "%s/audio_capture_processed.wav", tmp);
      g_wav_capture_processed = wav_writer_open(path, AUDIO_SAMPLE_RATE, 1);
      log_debug("Audio debugging enabled: dumping to %s/audio_capture_*.wav", tmp);
    }
    wav_dumpers_initialized = true;
  }

  // Accumulator for building complete Opus frames
  float opus_frame_buffer[OPUS_FRAME_SAMPLES];
  int opus_frame_samples_collected = 0;

  // Batch buffer for multiple Opus frames - send all at once to reduce blocking
#define MAX_BATCH_FRAMES 8
#define BATCH_TIMEOUT_NS (40LL * NS_PER_MS_INT) // Flush batch after 40ms even if not full (2 Opus frames @ 20ms each)
  static uint8_t batch_buffer[MAX_BATCH_FRAMES * OPUS_MAX_PACKET_SIZE];
  static uint16_t batch_frame_sizes[MAX_BATCH_FRAMES];
  static int batch_frame_count = 0;
  static size_t batch_total_size = 0;
  static uint64_t batch_start_time_ns = 0;
  static bool batch_has_data = false;

  while (!should_exit() && !server_connection_is_lost()) {
    START_TIMER("audio_capture_loop_iteration");
    timing_loop_count++;

    if (!server_connection_is_active()) {
      STOP_TIMER("audio_capture_loop_iteration"); // Don't count sleep time
      platform_sleep_us(100 * US_PER_MS_INT);     // Wait for connection
      continue;
    }

    // Check if pipeline is ready
    if (!g_audio_pipeline) {
      STOP_TIMER("audio_capture_loop_iteration"); // Don't count sleep time
      platform_sleep_us(100 * US_PER_MS_INT);
      continue;
    }

    // Check how many samples are available in the ring buffer
    int available = audio_ring_buffer_available_read(g_audio_context.capture_buffer);
    if (available <= 0) {
      // Flush partial batch before sleeping (prevent starvation during idle periods)
      if (batch_has_data && batch_frame_count > 0) {
        uint64_t now_ns = time_get_ns();
        uint64_t elapsed_ns = time_elapsed_ns(batch_start_time_ns, now_ns);

        if (elapsed_ns >= BATCH_TIMEOUT_NS) {
          long elapsed_ms = (long)time_ns_to_ms(elapsed_ns);
          log_debug_every(LOG_RATE_FAST, "Idle timeout flush: %d frames (%zu bytes) after %ld ms", batch_frame_count,
                          batch_total_size, elapsed_ms);
          (void)audio_queue_packet(batch_buffer, batch_total_size, batch_frame_sizes, batch_frame_count);
          batch_frame_count = 0;
          batch_total_size = 0;
          batch_has_data = false;
        }
      }

      // Sleep briefly to reduce CPU usage when idle
      // 5ms polling = 200 times/sec, fast enough to catch audio promptly
      // Note: 50ms was causing 872ms gaps in audio transmission!
      STOP_TIMER("audio_capture_loop_iteration"); // Must stop before loop repeats
      platform_sleep_us(5 * US_PER_MS_INT);       // 5ms (was 50ms - caused huge gaps!)
      continue;
    }

    // Read as many samples as possible (up to CAPTURE_READ_SIZE) to drain faster
    // This prevents buffer overflow when processing is slower than capture
    int to_read = (available < CAPTURE_READ_SIZE) ? available : CAPTURE_READ_SIZE;

    START_TIMER("audio_read_samples");
    asciichat_error_t read_result = audio_read_samples(&g_audio_context, audio_buffer, to_read);
    double read_time_ns = STOP_TIMER("audio_read_samples");

    total_read_ns += read_time_ns;
    if (read_time_ns > max_read_ns)
      max_read_ns = read_time_ns;

    if (read_result != ASCIICHAT_OK) {
      log_error("Failed to read audio samples from ring buffer");
      STOP_TIMER("audio_capture_loop_iteration"); // Don't count sleep time
      platform_sleep_us(5 * US_PER_MS_INT);       // 5ms (error path - was 50ms, caused gaps!)
      continue;
    }

    int samples_read = to_read;

    // Log every 10 reads to see if we're getting samples
    static int total_reads = 0;
    total_reads++;
    if (total_reads % 10 == 0) {
      log_debug("Audio capture loop iteration #%d: available=%d, samples_read=%d", total_reads, available,
                samples_read);
    }

    if (samples_read > 0) {
      // Normalize input to prevent clipping: bring peak to ±0.99
      // Calculate peak level first
      float peak = 0.0f;
      for (int i = 0; i < samples_read; i++) {
        float abs_val = fabsf(audio_buffer[i]);
        if (abs_val > peak)
          peak = abs_val;
      }

      // Apply normalization if peak exceeds 1.0
      // Use 0.99 to leave headroom for processing
      if (peak > 1.0f) {
        float gain = 0.99f / peak;
        for (int i = 0; i < samples_read; i++) {
          audio_buffer[i] *= gain;
        }
        static int norm_count = 0;
        norm_count++;
        if (norm_count <= 5 || norm_count % 100 == 0) {
          log_debug("Input normalization #%d: peak=%.4f, gain=%.4f", norm_count, peak, gain);
        }
      }

      // DUMP: Raw captured audio (before any processing)
      if (g_wav_capture_raw) {
        wav_writer_write(g_wav_capture_raw, audio_buffer, samples_read);
      }

      // DEBUG: Log EVERY read to see what we're getting from the ring buffer
      static int read_count = 0;
      read_count++;
      float sum_squares = 0.0f;
      for (int i = 0; i < samples_read && i < 10; i++) {
        sum_squares += audio_buffer[i] * audio_buffer[i];
      }
      float rms = sqrtf(sum_squares / (samples_read > 10 ? 10 : samples_read));
      if (read_count <= 5 || read_count % 20 == 0) {
        log_debug("Audio capture read #%d: available=%d, samples_read=%d, first=[%.6f,%.6f,%.6f], RMS=%.6f", read_count,
                  available, samples_read, samples_read > 0 ? audio_buffer[0] : 0.0f,
                  samples_read > 1 ? audio_buffer[1] : 0.0f, samples_read > 2 ? audio_buffer[2] : 0.0f, rms);
      }

      // Track sent samples for analysis
      if (GET_OPTION(audio_analysis_enabled)) {
        for (int i = 0; i < samples_read; i++) {
          audio_analysis_track_sent_sample(audio_buffer[i]);
        }
      }

      // Accumulate samples into Opus frame buffer
      int samples_to_process = samples_read;
      int sample_offset = 0;

      while (samples_to_process > 0) {
        // How many samples can we add to current frame?
        int space_in_frame = OPUS_FRAME_SAMPLES - opus_frame_samples_collected;
        int samples_to_copy = (samples_to_process < space_in_frame) ? samples_to_process : space_in_frame;

        // Copy samples to frame buffer
        memcpy(&opus_frame_buffer[opus_frame_samples_collected], &audio_buffer[sample_offset],
               (size_t)samples_to_copy * sizeof(float));

        opus_frame_samples_collected += samples_to_copy;
        sample_offset += samples_to_copy;
        samples_to_process -= samples_to_copy;

        // Do we have a complete frame?
        if (opus_frame_samples_collected >= OPUS_FRAME_SAMPLES) {
          // Process through pipeline: AEC, filters, AGC, noise gate, Opus encode
          uint8_t opus_packet[OPUS_MAX_PACKET_SIZE];

          START_TIMER("opus_encode");
          int opus_len = client_audio_pipeline_capture(g_audio_pipeline, opus_frame_buffer, OPUS_FRAME_SAMPLES,
                                                       opus_packet, OPUS_MAX_PACKET_SIZE);

          static int encode_count = 0;
          encode_count++;
          double opus_elapsed_ns = STOP_TIMER("opus_encode");
          if (encode_count % 50 == 0) {
            if (opus_elapsed_ns >= 0.0) {
              char _duration_str[32];
              time_pretty((uint64_t)(opus_elapsed_ns), -1, _duration_str, sizeof(_duration_str));
              log_dev("Opus encode #%d: %d samples -> %d bytes in %s", encode_count, OPUS_FRAME_SAMPLES, opus_len,
                      _duration_str);
            }
          }

          double encode_time_ns = 0; // Timing already logged

          total_encode_ns += encode_time_ns;
          if (encode_time_ns > max_encode_ns)
            max_encode_ns = encode_time_ns;

          if (opus_len > 0) {

            log_debug_every(LOG_RATE_VERY_FAST, "Pipeline encoded: %d samples -> %d bytes (compression: %.1fx)",
                            OPUS_FRAME_SAMPLES, opus_len,
                            (float)(OPUS_FRAME_SAMPLES * sizeof(float)) / (float)opus_len);

            // Add to batch buffer
            if (batch_frame_count < MAX_BATCH_FRAMES && batch_total_size + (size_t)opus_len <= sizeof(batch_buffer)) {
              // Mark batch start time on first frame
              if (batch_frame_count == 0) {
                batch_start_time_ns = time_get_ns();
                batch_has_data = true;
              }

              memcpy(batch_buffer + batch_total_size, opus_packet, (size_t)opus_len);
              batch_frame_sizes[batch_frame_count] = (uint16_t)opus_len;
              batch_total_size += (size_t)opus_len;
              batch_frame_count++;

              if (GET_OPTION(audio_analysis_enabled)) {
                audio_analysis_track_sent_packet((size_t)opus_len);
              }
            }
          } else if (opus_len == 0) {
            // DTX frame (silence) - no data to send
            log_debug_every(LOG_RATE_VERY_FAST, "Pipeline DTX frame (silence detected)");
          }

          // Reset frame buffer
          opus_frame_samples_collected = 0;
        }
      }

      // Queue batch for async sending (non-blocking - sender thread handles network I/O)
      if (batch_frame_count > 0) {
        static int batch_send_count = 0;
        batch_send_count++;

        START_TIMER("audio_queue_packet");
        int queue_result = audio_queue_packet(batch_buffer, batch_total_size, batch_frame_sizes, batch_frame_count);
        double queue_time_ns = STOP_TIMER("audio_queue_packet");

        total_queue_ns += queue_time_ns;
        if (queue_time_ns > max_queue_ns)
          max_queue_ns = queue_time_ns;

        if (queue_result < 0) {
          log_debug_every(LOG_RATE_VERY_FAST, "Failed to queue audio batch (queue full)");
        } else {
          if (batch_send_count <= 10 || batch_send_count % 50 == 0) {
            char queue_duration_str[32];
            time_pretty((uint64_t)(queue_time_ns), -1, queue_duration_str, sizeof(queue_duration_str));
            log_debug("CLIENT: Queued Opus batch #%d (%d frames, %zu bytes) in %s", batch_send_count, batch_frame_count,
                      batch_total_size, queue_duration_str);
          }
          // Track audio frame for FPS reporting
          fps_frame_ns(&fps_tracker, time_get_ns(), "audio batch queued");
        }

        // Reset batch
        batch_frame_count = 0;
        batch_total_size = 0;
        batch_has_data = false;
      }

      // Log overall loop iteration time periodically
      double loop_time_ns = STOP_TIMER("audio_capture_loop_iteration");
      total_loop_ns += loop_time_ns;
      if (loop_time_ns > max_loop_ns)
        max_loop_ns = loop_time_ns;

      // Comprehensive timing report every 100 iterations (~2 seconds)
      if (timing_loop_count % 100 == 0) {
        char avg_loop_str[32], max_loop_str[32];
        char avg_read_str[32], max_read_str[32];
        char avg_encode_str[32], max_encode_str[32];
        char avg_queue_str[32], max_queue_str[32];

        time_pretty((uint64_t)(total_loop_ns / timing_loop_count), -1, avg_loop_str, sizeof(avg_loop_str));
        time_pretty((uint64_t)(max_loop_ns), -1, max_loop_str, sizeof(max_loop_str));
        time_pretty((uint64_t)(total_read_ns / timing_loop_count), -1, avg_read_str, sizeof(avg_read_str));
        time_pretty((uint64_t)(max_read_ns), -1, max_read_str, sizeof(max_read_str));
        time_pretty((uint64_t)(total_encode_ns / timing_loop_count), -1, avg_encode_str, sizeof(avg_encode_str));
        time_pretty((uint64_t)(max_encode_ns), -1, max_encode_str, sizeof(max_encode_str));
        time_pretty((uint64_t)(total_queue_ns / timing_loop_count), -1, avg_queue_str, sizeof(avg_queue_str));
        time_pretty((uint64_t)(max_queue_ns), -1, max_queue_str, sizeof(max_queue_str));

        log_debug("CAPTURE TIMING #%lu: loop avg=%s max=%s, read avg=%s max=%s", timing_loop_count, avg_loop_str,
                  max_loop_str, avg_read_str, max_read_str);
        log_debug("  encode avg=%s max=%s, queue avg=%s max=%s", avg_encode_str, max_encode_str, avg_queue_str,
                 max_queue_str);
      }

      // Check if we have a partial batch that's been waiting too long (time-based flush)
      // This prevents batches from sitting indefinitely when audio capture is irregular
      if (batch_has_data && batch_frame_count > 0) {
        uint64_t now_ns = time_get_ns();
        uint64_t elapsed_ns = time_elapsed_ns(batch_start_time_ns, now_ns);

        if (elapsed_ns >= BATCH_TIMEOUT_NS) {
          static int timeout_flush_count = 0;
          timeout_flush_count++;

          long elapsed_ms = (long)time_ns_to_ms(elapsed_ns);
          log_debug_every(LOG_RATE_FAST, "Timeout flush #%d: %d frames (%zu bytes) after %ld ms", timeout_flush_count,
                          batch_frame_count, batch_total_size, elapsed_ms);

          // Queue partial batch
          int queue_result = audio_queue_packet(batch_buffer, batch_total_size, batch_frame_sizes, batch_frame_count);
          if (queue_result == 0) {
            // Track audio frame for FPS reporting
            fps_frame_ns(&fps_tracker, time_get_ns(), "audio batch timeout flush");
          }

          // Reset batch
          batch_frame_count = 0;
          batch_total_size = 0;
          batch_has_data = false;
        }
      }

      // Yield to reduce CPU usage - audio arrives at ~20ms per Opus frame (960 samples @ 48kHz)
      // Without sleep, thread spins at 90-100% CPU constantly checking for new samples
      // Even 1ms sleep reduces CPU usage from 90% to <10% with minimal latency impact
      platform_sleep_us(1 * US_PER_MS_INT); // 1ms
    } else {
      // Track loop time even when no samples processed
      double loop_time_ns = STOP_TIMER("audio_capture_loop_iteration");
      total_loop_ns += loop_time_ns;
      if (loop_time_ns > max_loop_ns)
        max_loop_ns = loop_time_ns;

      // Flush partial batch before sleeping on error path (prevent starvation)
      if (batch_has_data && batch_frame_count > 0) {
        uint64_t now_ns = time_get_ns();
        uint64_t elapsed_ns = time_elapsed_ns(batch_start_time_ns, now_ns);

        if (elapsed_ns >= BATCH_TIMEOUT_NS) {
          long elapsed_ms = (long)time_ns_to_ms(elapsed_ns);
          log_debug_every(LOG_RATE_FAST, "Error path timeout flush: %d frames (%zu bytes) after %ld ms",
                          batch_frame_count, batch_total_size, elapsed_ms);
          (void)audio_queue_packet(batch_buffer, batch_total_size, batch_frame_sizes, batch_frame_count);
          batch_frame_count = 0;
          batch_total_size = 0;
          batch_has_data = false;
        }
      }

      platform_sleep_us(5 * US_PER_MS_INT); // 5ms (error path - was 50ms, caused gaps!)
    }
  }

  log_debug("Audio capture thread stopped");
  atomic_store_bool(&g_audio_capture_thread_exited, true);

  // Clean up thread-local error context before exit

  return NULL;
}

int audio_client_init() {
  if (!GET_OPTION(audio_enabled)) {
    return 0; // Audio disabled - not an error
  }

  // Use lifecycle to ensure only one thread initializes audio at a time
  // This prevents race conditions in worker thread creation
  if (!lifecycle_init_once(&g_audio_client_init_lc)) {
    // Another thread is already initializing, wait for it to complete
    while (!lifecycle_is_initialized(&g_audio_client_init_lc)) {
      platform_sleep_us(1000); // 1ms
    }
    return 0; // Already initialized by another thread
  }

  // Clean up previous audio context if it was already initialized
  // This prevents leaks and thread creation issues on reconnection
  if (g_audio_context.initialized) {
    log_debug("Cleaning up previous audio context before reinitializing");
    audio_destroy(&g_audio_context);
    // NOTE: Do NOT reset lifecycle - keep it INITIALIZED so only ONE global
    // audio context is ever created. Subsequent calls will return early.
  }

  // Initialize WAV dumper for received audio if debugging enabled
  if (wav_dump_enabled()) {
    char tmp[PLATFORM_MAX_PATH_LENGTH];
    if (platform_get_temp_dir(tmp, sizeof(tmp))) {
      char path[PLATFORM_MAX_PATH_LENGTH];
      safe_snprintf(path, sizeof(path), "%s/audio_playback_received.wav", tmp);
      g_wav_playback_received = wav_writer_open(path, AUDIO_SAMPLE_RATE, 1);
      if (g_wav_playback_received) {
        log_debug("Audio debugging enabled: dumping received audio to %s", path);
      }
    }
  }

  // Initialize PortAudio context using library function
  log_debug("DEBUG: About to call audio_init()...");
  if (audio_init(&g_audio_context) != ASCIICHAT_OK) {
    log_error("Failed to initialize audio system");
    // Clean up WAV writer if it was opened
    if (g_wav_playback_received) {
      wav_writer_close(g_wav_playback_received);
      g_wav_playback_received = NULL;
    }
    lifecycle_init_abort(&g_audio_client_init_lc);
    return -1;
  }
  log_debug("DEBUG: audio_init() completed successfully");

  lifecycle_init_commit(&g_audio_client_init_lc);

  // Create unified audio pipeline (handles AEC, AGC, noise suppression, Opus)
  bool has_media_audio = media_source_has_audio(capture_get_media_source());
  client_audio_pipeline_config_t pipeline_config = client_audio_pipeline_config_for_source(has_media_audio);

  // Enable echo cancellation, AGC, and essential processing for clear audio
  // Noise suppression and VAD can destroy music quality, so keep them disabled
  pipeline_config.flags.echo_cancel = true;     // ENABLE: removes echo
  pipeline_config.flags.jitter_buffer = true;   // ENABLE: needed for AEC sync
  pipeline_config.flags.noise_suppress = false; // DISABLED: destroys music quality
  pipeline_config.flags.agc = true;             // ENABLE: boost quiet microphones (35 dB gain)
  pipeline_config.flags.vad = false;            // DISABLED: destroys music quality
  pipeline_config.flags.compressor = true;      // ENABLE: prevent clipping from AGC boost
  pipeline_config.flags.noise_gate = false;     // DISABLED: would cut quiet music passages
  pipeline_config.flags.highpass = true;        // ENABLE: remove rumble and low-frequency feedback
  pipeline_config.flags.lowpass = false;        // DISABLED: preserve high-frequency content

  // Applied before streams start; actual underflows increase this bounded target.
  audio_ring_buffer_set_jitter_target(g_audio_context.playback_buffer,
                                      (uint32_t)pipeline_config.jitter_margin_ms * 48);

  log_debug("DEBUG: About to create audio pipeline...");
  g_audio_pipeline = client_audio_pipeline_create(&pipeline_config);
  log_debug("DEBUG: client_audio_pipeline_create() returned");
  if (!g_audio_pipeline) {
    log_error("Failed to create audio pipeline");
    audio_destroy(&g_audio_context);
    // Clean up WAV writer if it was opened
    if (g_wav_playback_received) {
      wav_writer_close(g_wav_playback_received);
      g_wav_playback_received = NULL;
    }
    return -1;
  }

  log_debug("Audio pipeline created: %d Hz sample rate, %d bps bitrate", pipeline_config.sample_rate,
            pipeline_config.opus_bitrate);

  // Associate pipeline with audio context for echo cancellation
  // The audio output callback will feed playback samples directly to AEC3 from the speaker output,
  // ensuring proper timing synchronization (not from the decode path 50-100ms earlier)
  audio_set_pipeline(&g_audio_context, (void *)g_audio_pipeline);

  // Audio streams start from protocol_start_connection() after the network
  // connection succeeds, so local media playback does not advance while dialing.

  return 0;
}

int audio_start_thread() {
  log_debug("audio_start_thread called: audio_enabled=%d", GET_OPTION(audio_enabled));

  // Register audio atomics for debug sync state monitoring (one-time registration)
  static bool audio_atomics_registered = false;
  if (!audio_atomics_registered) {
    NAMED_REGISTER_ATOMIC(&g_audio_capture_thread_exited, "audio_capture_thread_exit_confirmation", NULL);
    NAMED_REGISTER_ATOMIC(&g_audio_sender_should_exit, "audio_sender_exit_flag", NULL);
    NAMED_REGISTER_ATOMIC(&g_audio_sender_exited, "audio_sender_exited_confirmation", NULL);
    audio_atomics_registered = true;
  }

  if (!GET_OPTION(audio_enabled)) {
    log_debug("Audio is disabled, skipping audio capture thread creation");
    return 0; // Audio disabled - not an error
  }

  // Check if thread is already running (not just created flag)
  if (g_audio_capture_thread_created && !atomic_load_bool(&g_audio_capture_thread_exited)) {
    log_warn("Audio capture thread already running");
    return 0;
  }

  // If thread exited, allow recreation
  if (g_audio_capture_thread_created && atomic_load_bool(&g_audio_capture_thread_exited)) {
    log_debug("Previous audio capture thread exited, recreating");
    // Use timeout to prevent indefinite blocking
    int join_result = asciichat_thread_join_timeout(&g_audio_capture_thread, NULL, 5000 * NS_PER_MS_INT);
    if (join_result != 0) {
      log_warn("Audio capture thread join timed out after 5s - thread may be deadlocked, "
               "forcing thread handle reset (stuck thread resources will not be cleaned up)");
      // Thread is stuck - we can't safely reuse the handle, but we can reset our tracking
      // This is a resource leak of the stuck thread but continuing is safer than hanging
    }
    g_audio_capture_thread_created = false;
  }

  // Note: STREAM_START for audio was already sent by protocol_start_connection()
  // No need to send it again here - the protocol layer handles sending combined stream types

  // Start audio capture thread
  atomic_store_bool(&g_audio_capture_thread_exited, false);
  if (thread_pool_spawn(g_client_worker_pool, audio_capture_thread_func, NULL, 4, "audio_capture") != ASCIICHAT_OK) {
    log_error("Failed to spawn audio capture thread in worker pool");
    LOG_ERRNO_IF_SET("Audio capture thread creation failed");
    return -1;
  }

  g_audio_capture_thread_created = true;

  return 0;
}

void audio_stop_thread() {
  // If audio was never initialized (e.g., in snapshot mode), nothing to stop
  if (!lifecycle_is_initialized(&g_audio_client_init_lc)) {
    log_debug("[AUDIO_STOP] Audio never initialized, nothing to stop");
    return;
  }

  // Ensure only one thread performs cleanup - prevent double-join and double-cleanup
  // First, initialize the lifecycle if it hasn't been yet (moves UNINITIALIZED → INITIALIZED)
  if (!lifecycle_is_initialized(&g_audio_stop_thread_lc)) {
    if (!lifecycle_init(&g_audio_stop_thread_lc, "audio_stop_thread")) {
      // Already initialized by another thread or being destroyed
      log_debug("[AUDIO_STOP] Lifecycle already initialized by another thread");
      return;
    }
    log_debug("[AUDIO_STOP] Initialized stop thread lifecycle");
  }

  // Now destroy it (moves INITIALIZED → DESTROYING)
  if (!lifecycle_destroy_once(&g_audio_stop_thread_lc)) {
    log_debug("[AUDIO_STOP] lifecycle_destroy_once() returned false - already destroying/destroyed");
    log_debug("[AUDIO_STOP] Audio stop already in progress or completed, skipping");
    return;
  }
  log_debug("[AUDIO_STOP] lifecycle_destroy_once() returned true, proceeding with audio stop");

  // Signal audio worker thread to exit first (stop processing)
  log_debug("[AUDIO_STOP] Signaling audio worker thread to stop");
  atomic_store_bool(&g_audio_context.worker_should_stop, true);
  // Wake up the worker thread if it's waiting on condition variable
  mutex_lock(&g_audio_context.worker_mutex);
  cond_signal(&g_audio_context.worker_cond);
  mutex_unlock(&g_audio_context.worker_mutex);
  log_debug("[AUDIO_STOP] Worker thread stop signal sent");

  // Signal audio sender thread to exit first.
  // This must happen before thread_pool_stop_all() is called, otherwise the sender
  // thread will be stuck in cond_wait() and thread_pool_stop_all() will hang forever.
  // The sender thread uses a condition variable to wait for packets - we must wake it up.
  // NOTE: Only do this if audio_sender_init() was actually called
  if (lifecycle_is_initialized(&g_audio_send_queue_lc)) {
    log_debug("[AUDIO_STOP] Signaling audio sender thread to exit");
    atomic_store_bool(&g_audio_sender_should_exit, true);
    mutex_lock(&g_audio_send_queue_mutex);
    cond_signal(&g_audio_send_queue_cond);
    mutex_unlock(&g_audio_send_queue_mutex);
    log_debug("[AUDIO_STOP] Signal sent to sender thread");

    // Wait for audio sender thread to exit gracefully
    // This must complete before thread_pool_stop_all() to prevent deadlock
    // CRITICAL: Longer timeout to ensure thread completes any in-flight send operations
    // Network operations can block for 10-50ms, so we need to wait longer
    int wait_count = 0;
    log_debug("[AUDIO_STOP] Waiting for sender thread to exit, max 500ms");
    while (wait_count < 50 && !atomic_load_bool(&g_audio_sender_exited)) {
      platform_sleep_us(10 * US_PER_MS_INT); // 10ms * 50 = 500ms max wait
      wait_count++;
    }

    if (!atomic_load_bool(&g_audio_sender_exited)) {
      log_warn("[AUDIO_STOP] Audio sender thread not responding after 500ms - will be joined by thread pool");
    } else {
      log_debug("[AUDIO_STOP] Sender thread exited successfully");
    }
  } else {
    log_debug("[AUDIO_STOP] Audio sender was never initialized (connection failed), skipping sender shutdown");
  }

  log_debug("[AUDIO_STOP] Checking if capture thread was created: g_audio_capture_thread_created=%d",
            g_audio_capture_thread_created);
  if (!THREAD_IS_CREATED(g_audio_capture_thread_created)) {
    log_debug("[AUDIO_STOP] Capture thread was not created, committing lifecycle and returning");
    lifecycle_destroy_commit(&g_audio_stop_thread_lc);
    log_debug("[AUDIO_STOP] Lifecycle committed, returning");
    return;
  }
  log_debug("[AUDIO_STOP] Capture thread was created, waiting for it to exit");

  // Note: We don't call signal_exit() here because that's for global shutdown only
  // The audio capture thread checks server_connection_is_active() to detect connection loss

  // Wait for thread to exit gracefully
  // Threads check should_exit() every 1-5ms, so timeout can be much shorter than 500ms
  int wait_count2 = 0;
  log_debug("[AUDIO_STOP] Waiting for capture thread to exit, max 50ms");
  while (wait_count2 < 5 && !atomic_load_bool(&g_audio_capture_thread_exited)) {
    platform_sleep_us(10 * US_PER_MS_INT); // 10ms * 5 = 50ms max wait (threads respond in ~1-5ms)
    wait_count2++;
  }

  if (!atomic_load_bool(&g_audio_capture_thread_exited)) {
    log_warn("[AUDIO_STOP] Audio capture thread not responding - will be joined by thread pool");
  } else {
    log_debug("[AUDIO_STOP] Capture thread exited successfully");
  }

  // Thread will be joined by thread_pool_stop_all() in protocol_stop_connection()
  g_audio_capture_thread_created = false;

  lifecycle_destroy_commit(&g_audio_stop_thread_lc);

  log_debug("Audio capture thread stopped");
}

bool audio_thread_exited() {
  return atomic_load_bool(&g_audio_capture_thread_exited);
}

void audio_cleanup() {
  if (!GET_OPTION(audio_enabled)) {
    return;
  }

  // Stop capture thread first (stops producing packets)
  audio_stop_thread();

  // Stop async sender thread (drains queue and exits)
  audio_sender_cleanup();

  // Stop audio stream before destroying pipeline to prevent race condition.
  // PortAudio may invoke the callback one more time after we request stop.
  // We need to clear the pipeline pointer first so the callback can't access freed memory.
  if (g_audio_context.initialized) {
    audio_stop_duplex(&g_audio_context);
  }

  // Clear the pipeline pointer from audio context BEFORE destroying pipeline
  // This prevents any lingering PortAudio callbacks from trying to access freed memory
  audio_set_pipeline(&g_audio_context, NULL);
  audio_terminate_portaudio_final();

  // Sleep to allow CoreAudio threads to finish executing callbacks.
  // On macOS, CoreAudio's internal threads may continue running after Pa_StopStream() returns.
  // The duplex_callback may still be in-flight on other threads. Even after we set the pipeline
  // pointer to NULL, a CoreAudio thread may have already cached the pointer before the assignment.
  // This sleep ensures all in-flight callbacks have fully completed before we destroy the pipeline.
  // WORKAROUND: Skip sleep during shutdown (process is exiting anyway)
  // 500ms is sufficient on macOS for CoreAudio's internal thread pool to completely wind down.
  // platform_sleep_us(500 * US_PER_MS_INT); // 500ms - macOS CoreAudio needs time to shut down all threads

  // Destroy audio pipeline (handles Opus, AEC, etc.)
  if (g_audio_pipeline) {
    client_audio_pipeline_destroy(g_audio_pipeline);
    g_audio_pipeline = NULL;
    log_debug("Audio pipeline destroyed");
  }

  // Close WAV dumpers
  if (g_wav_capture_raw) {
    wav_writer_close(g_wav_capture_raw);
    g_wav_capture_raw = NULL;
    log_debug("Closed audio capture raw dump");
  }
  if (g_wav_capture_processed) {
    wav_writer_close(g_wav_capture_processed);
    g_wav_capture_processed = NULL;
    log_debug("Closed audio capture processed dump");
  }
  if (g_wav_playback_received) {
    wav_writer_close(g_wav_playback_received);
    g_wav_playback_received = NULL;
    log_debug("Closed audio playback received dump");
  }

  // Finally destroy the audio context
  if (g_audio_context.initialized) {
    audio_destroy(&g_audio_context);
  }
}

client_audio_pipeline_t *audio_get_pipeline(void) {
  return g_audio_pipeline;
}

int audio_decode_opus(const uint8_t *opus_data, size_t opus_len, float *output, int max_samples) {
  if (!g_audio_pipeline || !output || max_samples <= 0) {
    return -1;
  }

  return client_audio_pipeline_playback(g_audio_pipeline, opus_data, (int)opus_len, output, max_samples);
}

audio_context_t *audio_get_context(void) {
  return &g_audio_context;
}

static void *webcam_capture_thread_func(void *arg) {
  (void)arg;

  // FPS tracking for webcam capture thread
  static fps_t fps_tracker = {0};
  static bool fps_tracker_initialized = false;
  static uint64_t capture_frame_count = 0;
  static uint64_t last_capture_frame_time_ns = 0;
  static image_t *last_frame = NULL; // Cache last frame to render when paused
  const char *video_codec = GET_OPTION(video_codec);
  bool automatic_codec = strcmp(video_codec, "auto") == 0;
  video_codec_t selected_codec = strcmp(video_codec, "raw") == 0    ? VIDEO_CODEC_RGBA
                                 : strcmp(video_codec, "h264") == 0 ? VIDEO_CODEC_H264
                                                                    : VIDEO_CODEC_H265;
  // Each connection starts at the requested codec with a fresh bitstream.
  h265_encoder_destroy(g_video_encoder);
  g_video_encoder = NULL;
  if (!fps_tracker_initialized) {
    int target_fps = (int)session_capture_get_target_fps(g_capture_capture_ctx);
    fps_init(&fps_tracker, target_fps, "WEBCAM_TX");
    fps_tracker_initialized = true;
  }

  while (!should_exit() && !server_connection_is_lost()) {
    // Check connection status
    if (!server_connection_is_active()) {
      log_debug_every(LOG_RATE_NORMAL, "Capture thread: waiting for connection to become active");
      platform_sleep_us(100 * US_PER_MS_INT); // Wait for connection
      continue;
    }

    // Frame rate limiting using session capture adaptive sleep
    session_capture_sleep_for_fps(g_capture_capture_ctx);

    // Re-check connection after FPS sleep in case it was lost during sleep (reconnection)
    if (!server_connection_is_active() || server_connection_is_lost()) {
      log_debug("Capture thread: connection lost after FPS sleep, exiting");
      break;
    }

    // Read frame using session capture library
    asciichat_errno_scope_t frame_scope = asciichat_errno_checkpoint();
    image_t *image = session_capture_read_frame(g_capture_capture_ctx);
    asciichat_error_context_t capture_failure;
    if (!image && asciichat_errno_peek_since(frame_scope, &capture_failure)) {
      asciichat_errno_request_exit(capture_failure.code);
      signal_exit();
      break;
    }

    // Check if media is paused and we have a last frame - render last frame to keep keyboard polling active
    if (!image) {
      media_source_t *source = (media_source_t *)session_capture_get_media_source(g_capture_capture_ctx);
      if (source && media_source_get_type(source) == MEDIA_SOURCE_FILE && media_source_is_paused(source) &&
          last_frame) {
        // Use last frame when paused (keeps display thread rendering and keyboard polling active)
        image = last_frame;
        log_debug_every(LOG_RATE_SLOW, "Using cached frame while paused");
      } else if (session_capture_at_end(g_capture_capture_ctx)) {
        // Check if we've reached end of file for media sources
        log_debug("Media source reached end of file");
        image_destroy(last_frame);
        last_frame = NULL;
        break; // Exit capture loop - end of media
      } else {
        log_debug_every(LOG_RATE_SLOW, "No frame available from media source yet (returned NULL)");
        platform_sleep_us(10 * US_PER_MS_INT); // 10ms delay before retry
        continue;
      }
    }

    // Track frame for FPS reporting
    fps_frame_ns(&fps_tracker, time_get_ns(), "webcam frame captured");

    // Process frame for network transmission using session library
    // session_capture_process_for_transmission() returns a new image that we own
    // NOTE: The original 'image' is owned by media_source - do NOT free it!
    image_t *processed_image = session_capture_process_for_transmission(g_capture_capture_ctx, image);
    if (!processed_image) {
      SET_ERRNO(ERROR_INVALID_STATE, "Failed to process frame for transmission");
      // NOTE: Do NOT free 'image' - it's owned by capture context
      continue;
    }

    // Check connection before sending
    if (!server_connection_is_active()) {
      log_warn("Connection lost before sending, stopping video transmission");
      image_destroy(processed_image);
      break;
    }

    // Send frame packet to server using proper packet format
    acip_transport_t *transport = server_connection_get_transport();
    if (!transport || !server_connection_is_active()) {
      log_warn("Transport became unavailable during capture, stopping transmission");
      image_destroy(processed_image);
      break;
    }

    uint64_t send_start_ns = time_get_ns();

    asciichat_errno_scope_t send_scope = asciichat_errno_scope_begin();
    asciichat_error_t send_result;
    bool encoding_failed = false;
    for (;;) {
      if (selected_codec == VIDEO_CODEC_RGBA) {
        send_result = threaded_send_image_frame(processed_image->pixels, (uint32_t)processed_image->w,
                                                (uint32_t)processed_image->h, 1);
        break;
      }
      asciichat_errno_scope_t encode_scope = asciichat_errno_scope_begin();
      send_result = threaded_send_image_frame_encoded(processed_image->pixels, (uint32_t)processed_image->w,
                                                      (uint32_t)processed_image->h, selected_codec, &encoding_failed);
      if (!encoding_failed || !automatic_codec || send_result == ERROR_MEMORY) {
        if (send_result == ASCIICHAT_OK)
          asciichat_errno_scope_end(encode_scope, ASCIICHAT_ERRNO_HANDLED);
        break;
      }
      log_warn("%s encoding failed; automatic video is switching to %s",
               selected_codec == VIDEO_CODEC_H265 ? "HEVC" : "H.264",
               selected_codec == VIDEO_CODEC_H265 ? "H.264" : "raw");
      asciichat_errno_scope_end(encode_scope, ASCIICHAT_ERRNO_DISMISSED);
      h265_encoder_destroy(g_video_encoder);
      g_video_encoder = NULL;
      selected_codec = selected_codec == VIDEO_CODEC_H265 ? VIDEO_CODEC_H264 : VIDEO_CODEC_RGBA;
      encoding_failed = false;
    }
    const char *codec_name = selected_codec == VIDEO_CODEC_H265   ? "H265"
                             : selected_codec == VIDEO_CODEC_H264 ? "H264"
                                                                  : "RAW";
    if (encoding_failed) {
      log_error("%s video encoding failed (%s). Use --video-codec auto for fallback or --video-codec raw.", codec_name,
                asciichat_error_string(send_result));
      asciichat_errno_request_exit(send_result);
      signal_exit();
      image_destroy(processed_image);
      break;
    }

    // If send failed due to connection loss, break out of loop
    if (send_result != ASCIICHAT_OK && !server_connection_is_active()) {
      log_debug("Connection lost during send, stopping transmission");
      image_destroy(processed_image);
      break;
    }
    uint64_t send_duration_ns = time_elapsed_ns(send_start_ns, time_get_ns());

    if (send_result != ASCIICHAT_OK && network_error_is_local_rejection(send_result)) {
      LOG_ERRNO_IF_SET("Dropping locally rejected video frame");
      asciichat_errno_scope_end(send_scope, ASCIICHAT_ERRNO_HANDLED);
      image_destroy(processed_image);
      continue;
    }
    if (send_result != ASCIICHAT_OK) {
      log_error("🔴 CAPTURE_SEND_FAILED: IMAGE_FRAME_%s send error=%d (%s) after %.1fms, closing connection",
                codec_name, send_result, asciichat_error_string(send_result), (double)send_duration_ns / 1e6);
      server_connection_lost();
      image_destroy(processed_image);
      break;
    }

    ASSERT_NO_ERRNO_SINCE(send_scope);
    asciichat_errno_scope_end(send_scope, ASCIICHAT_ERRNO_HANDLED);
    if (send_duration_ns > 500 * NS_PER_MS_INT) {
      log_warn("⚠️  SLOW_FRAME_SEND: %.1fms to send %ux%u %s frame (may indicate full send buffer)",
               (double)send_duration_ns / 1e6, processed_image->w, processed_image->h, codec_name);
    }

    log_debug_every(LOG_RATE_NORMAL, "CAPTURE_FRAME_SENT: IMAGE_FRAME_%s delivered to server in %.1fms", codec_name,
                    (double)send_duration_ns / 1e6);

    // Cache last frame for rendering when paused
    // Make a copy since the original is owned by media_source
    if (last_frame) {
      image_destroy(last_frame);
    }
    last_frame = image_new(processed_image->w, processed_image->h);
    if (last_frame) {
      memcpy(last_frame->pixels, processed_image->pixels,
             (size_t)processed_image->w * (size_t)processed_image->h * sizeof(rgb_pixel_t));
    }

    // FPS tracking - frame successfully captured and sent
    capture_frame_count++;

    // Calculate time since last frame for lag detection (using nanosecond precision internally)
    uint64_t frame_capture_time_ns = time_get_ns();

    uint64_t frame_interval_ns = time_elapsed_ns(last_capture_frame_time_ns, frame_capture_time_ns);
    last_capture_frame_time_ns = frame_capture_time_ns;

    // Expected frame interval in nanoseconds
    uint64_t expected_interval_ns = NS_PER_SEC_INT / (uint64_t)session_capture_get_target_fps(g_capture_capture_ctx);
    uint64_t lag_threshold_ns = expected_interval_ns + (expected_interval_ns / 2); // 50% over expected

    // Log warning if frame took too long to capture (display in milliseconds for readability)
    if (capture_frame_count > 1 && frame_interval_ns > lag_threshold_ns) {
      double late_ms = (double)(frame_interval_ns - expected_interval_ns) / 1e6;
      double expected_ms = (double)expected_interval_ns / 1e6;
      double actual_ms = (double)frame_interval_ns / 1e6;
      double actual_fps = 1e9 / (double)frame_interval_ns;
      log_warn_every(LOG_RATE_FAST,
                     "CLIENT CAPTURE LAG: Frame captured %.1fms late (expected %.1fms, got %.1fms, actual fps: %.1f)",
                     late_ms, expected_ms, actual_ms, actual_fps);
    }

    // Clean up processed frame
    image_destroy(processed_image);
    processed_image = NULL;

    // Yield to reduce CPU usage
    platform_sleep_us(1 * US_PER_MS_INT); // 1ms
  }

#ifdef DEBUG_THREADS
  log_debug("Webcam capture thread stopped");
#endif

  // Clean up cached frame before thread exit
  if (last_frame) {
    image_destroy(last_frame);
    last_frame = NULL;
  }

  log_debug("CAPTURE_THREAD_EXIT: About to mark thread as exited");
  atomic_store_bool(&g_capture_thread_exited, true);
  log_debug("CAPTURE_THREAD_EXIT: Thread marked as exited, cleaning up errno");

  // Clean up thread-local error context before exit

  log_debug("CAPTURE_THREAD_EXIT: Exiting capture thread");
  return NULL;
}

int capture_init() {
  // Build capture configuration from options
  session_capture_config_t config = {0};
  const char *media_url = GET_OPTION(media_url);
  const char *media_file = GET_OPTION(media_file);
  bool media_from_stdin = GET_OPTION(media_from_stdin);

  if (media_url && media_url[0] != '\0') {
    // Network URL streaming (takes priority over --file)
    // Don't open webcam when streaming from URL
    config.type = MEDIA_SOURCE_FILE;
    config.path = media_url;
    config.loop = false; // Network URLs cannot be looped
    log_debug("Using network URL: %s (webcam disabled)", media_url);
  } else if (media_file && media_file[0] != '\0') {
    // File or stdin streaming - don't open webcam
    config.type = media_from_stdin ? MEDIA_SOURCE_STDIN : MEDIA_SOURCE_FILE;
    config.path = media_file;
    config.loop = GET_OPTION(media_loop) && !media_from_stdin;
    log_debug("Using media %s: %s (webcam disabled)", media_from_stdin ? "stdin" : "file", media_file);
  } else if (GET_OPTION(test_pattern)) {
    // Test pattern mode - don't open real webcam
    config.type = MEDIA_SOURCE_TEST;
    config.path = NULL;
    log_debug("Using test pattern mode");
  } else {
    // Webcam mode (default)
    static char webcam_index_str[32];
    safe_snprintf(webcam_index_str, sizeof(webcam_index_str), "%u", GET_OPTION(webcam_index));
    config.type = MEDIA_SOURCE_WEBCAM;
    config.path = webcam_index_str;
    log_debug("Using webcam device %u", GET_OPTION(webcam_index));
  }
  int configured_fps = GET_OPTION(fps);
  config.target_fps = configured_fps > 0 ? (uint32_t)configured_fps : CAPTURE_TARGET_FPS;
  config.resize_for_network = true; // Client always resizes for network transmission

  // Configure audio capture with fallback to microphone
  config.enable_audio = true;
  config.audio_fallback_to_mic = true;
  config.mic_audio_ctx = audio_get_context();

  // Add seek timestamp if specified
  config.initial_seek_timestamp = GET_OPTION(media_seek_timestamp);

  // Create capture context using session library
  asciichat_errno_scope_t create_scope = asciichat_errno_checkpoint();
  g_capture_capture_ctx = session_capture_create(&config);
  if (!g_capture_capture_ctx) {
    // Check if there's already an error set (e.g., ERROR_WEBCAM_IN_USE)
    asciichat_error_context_t failure;
    asciichat_error_t existing_error = asciichat_errno_peek_since(create_scope, &failure) ? failure.code : ASCIICHAT_OK;
    log_debug("session_capture_create failed, GET_ERRNO() returned: %d", existing_error);
    if (existing_error != ASCIICHAT_OK) {
      log_debug("Returning existing error code %d", existing_error);
      return existing_error;
    }
    SET_ERRNO(ERROR_MEDIA_INIT, "Failed to initialize capture source");
    return -1;
  }

  return 0;
}

int capture_start_thread() {
  if (THREAD_IS_CREATED(g_capture_thread_created)) {
    log_warn("Capture thread already created");
    return 0;
  }

  // Register capture atomics with named debug registry
  static bool capture_atomics_registered = false;
  if (!capture_atomics_registered) {
    NAMED_REGISTER_ATOMIC(&g_capture_thread_exited, "capture_webcam_thread_exit_confirmation", NULL);
    capture_atomics_registered = true;
  }

  // Start webcam capture thread
  atomic_store_bool(&g_capture_thread_exited, false);
  if (thread_pool_spawn(g_client_worker_pool, webcam_capture_thread_func, NULL, 2, "webcam_capture") != ASCIICHAT_OK) {
    SET_ERRNO(ERROR_THREAD, "Webcam capture thread creation failed");
    LOG_ERRNO_IF_SET("Webcam capture thread creation failed");
    return -1;
  }

  g_capture_thread_created = true;
  log_debug("Webcam capture thread created successfully");

  return 0;
}

void capture_stop_thread() {
  if (!THREAD_IS_CREATED(g_capture_thread_created)) {
    return;
  }

  // Wait for thread to exit gracefully
  int wait_count = 0;
  while (wait_count < 20 && !atomic_load_bool(&g_capture_thread_exited)) {
    platform_sleep_us(100 * US_PER_MS_INT); // 100ms
    wait_count++;
  }

  if (!atomic_load_bool(&g_capture_thread_exited)) {
    log_warn("Capture thread not responding after 2 seconds - will be joined by thread pool");
  }

  // Thread will be joined by thread_pool_stop_all() in protocol_stop_connection()
  g_capture_thread_created = false;
}

bool capture_thread_exited() {
  return atomic_load_bool(&g_capture_thread_exited);
}

void capture_cleanup() {
  capture_stop_thread();

  // Destroy capture context
  if (g_capture_capture_ctx) {
    session_capture_destroy(g_capture_capture_ctx);
    g_capture_capture_ctx = NULL;
  }
}

void *capture_get_media_source(void) {
  return session_capture_get_media_source(g_capture_capture_ctx);
}

void client_crypto_set_mode(uint8_t mode) {
  log_debug("CLIENT_CRYPTO: Setting crypto mode to 0x%02x", mode);
  g_crypto_mode = mode;
}

int client_crypto_init(void) {
  log_debug("CLIENT_CRYPTO_INIT: Starting crypto initialization");

  // Reset if already initialized (allows reinit on reconnection)
  if (lifecycle_reset(&g_crypto_lc)) {
    log_debug("CLIENT_CRYPTO_INIT: Already initialized, resetting for reinit");
    crypto_handshake_destroy(&g_crypto_ctx);
  }

  log_debug("CLIENT_CRYPTO_INIT: Initializing crypto handshake context");
  log_debug("CLIENT_CRYPTO_INIT: crypto_mode=%d (NONE=0, ENCRYPT=1, AUTH=2, FULL=3)", g_crypto_mode);

  // Check if we have an SSH key, password, or neither
  int result;
  bool is_ssh_key = false;
  private_key_t private_key;

  // Get string options safely
  const options_t *opts = options_get();
  const char *encrypt_key = opts && opts->encrypt_key[0] != '\0' ? opts->encrypt_key : "";
  const char *password = opts && opts->password[0] != '\0' ? opts->password : "";
  const char *address = opts && opts->address[0] != '\0' ? opts->address : "localhost";
  int port = opts ? opts->port : OPT_PORT_INT_DEFAULT;
  const char *server_key = opts && opts->server_key[0] != '\0' ? opts->server_key : "";

  // Load client private key if provided via --key
  if (strlen(encrypt_key) > 0) {
    // --key supports file-based authentication (SSH keys, GPG keys via gpg:keyid)

    // For SSH key files (not gpg:keyid format), validate the file exists
    if (strncmp(encrypt_key, "gpg:", 4) != 0) {
      if (validate_ssh_key_file(encrypt_key) != 0) {
        return -1;
      }
    }

    // Parse key (handles SSH files and gpg:keyid format)
    log_debug("CLIENT_CRYPTO_INIT: Loading private key for authentication: %s", encrypt_key);
    if (parse_private_key(encrypt_key, &private_key) == ASCIICHAT_OK) {
      log_debug("Successfully parsed SSH private key");
      log_debug("CLIENT_CRYPTO_INIT: Parsed key type=%d, KEY_TYPE_ED25519=%d", private_key.type, KEY_TYPE_ED25519);
      is_ssh_key = true;
    } else {
      NOTICE(DANGER, "IDENTITY KEY COULD NOT BE LOADED", "Failed to parse SSH key file: %s", encrypt_key);
      log_error("This may be due to:");
      log_error("  - Wrong password for encrypted key");
      log_error("  - Unsupported key type (only Ed25519 is currently supported)");
      log_error("  - Corrupted key file");
      log_error("");
      log_error("Note: RSA and ECDSA keys are not yet supported");
      log_error("To generate an Ed25519 key: ssh-keygen -t ed25519");
      return -1;
    }
  }

  if (is_ssh_key) {
    // Use SSH private key for authentication
    log_debug("CLIENT_CRYPTO_INIT: Using SSH key for authentication");

    // Initialize crypto context (generates ephemeral X25519 keys)
    result = crypto_handshake_init("crypto_client_local", &g_crypto_ctx, false); // false = client
    if (result != ASCIICHAT_OK) {
      FATAL(result, "Failed to initialize crypto handshake");
    }

    // Store the Ed25519 keys for authentication
    memcpy(&g_crypto_ctx.client_private_key, &private_key, sizeof(private_key_t));

    // Extract Ed25519 public key from private key
    g_crypto_ctx.client_public_key.type = KEY_TYPE_ED25519;
    memcpy(g_crypto_ctx.client_public_key.key, private_key.public_key, ED25519_PUBLIC_KEY_SIZE);
    SAFE_STRNCPY(g_crypto_ctx.client_public_key.comment, private_key.key_comment,
                 sizeof(g_crypto_ctx.client_public_key.comment) - 1);

    // Extract GPG key ID if this is a GPG key (format: "gpg:KEYID")
    if (strncmp(encrypt_key, "gpg:", 4) == 0) {
      const char *key_id = encrypt_key + 4;
      size_t key_id_len = strlen(key_id);
      // Accept 8, 16, or 40 character GPG key IDs (short/long/full fingerprint)
      if (key_id_len == 8 || key_id_len == 16 || key_id_len == 40) {
        SAFE_STRNCPY(g_crypto_ctx.client_gpg_key_id, key_id, sizeof(g_crypto_ctx.client_gpg_key_id));
        log_debug("CLIENT_CRYPTO_INIT: Extracted client GPG key ID (%zu chars): %s", key_id_len,
                  g_crypto_ctx.client_gpg_key_id);
      } else {
        log_warn("CLIENT_CRYPTO_INIT: Invalid GPG key ID length: %zu (expected 8, 16, or 40)", key_id_len);
        g_crypto_ctx.client_gpg_key_id[0] = '\0';
      }
    } else {
      // Not a GPG key, clear the field
      g_crypto_ctx.client_gpg_key_id[0] = '\0';
    }

    // SSH key is already configured in the handshake context above
    // No additional setup needed - SSH keys are used only for authentication

    // Clear the temporary private_key variable (we've already copied it to g_crypto_ctx)
    sodium_memzero(&private_key, sizeof(private_key));

    // If password is also provided, derive password key for dual authentication
    if (strlen(password) > 0) {
      log_debug("CLIENT_CRYPTO_INIT: Password also provided, deriving password key");
      crypto_result_t crypto_result = crypto_derive_password_key(&g_crypto_ctx.crypto_ctx, password);
      if (crypto_result != CRYPTO_OK) {
        log_error("Failed to derive password key: %s", crypto_result_to_string(crypto_result));
        return -1;
      }
      g_crypto_ctx.crypto_ctx.has_password = true;
      log_debug("Password authentication enabled alongside SSH key");
    }

  } else if (strlen(GET_OPTION(password)) > 0) {
    // Password provided - use password-based initialization
    log_debug("CLIENT_CRYPTO_INIT: Using password authentication");
    result = crypto_handshake_init_with_password("crypto_client_local", &g_crypto_ctx, false,
                                                 GET_OPTION(password)); // false = client
    if (result != ASCIICHAT_OK) {
      FATAL(result, "Failed to initialize crypto handshake with password");
    }
  } else {
    // No password or SSH key - use standard initialization with random keys
    log_debug("CLIENT_CRYPTO_INIT: Using standard initialization");
    result = crypto_handshake_init("crypto_client_local", &g_crypto_ctx, false); // false = client
    if (result != ASCIICHAT_OK) {
      FATAL(result, "Failed to initialize crypto handshake");
    }
  }

  log_debug("CLIENT_CRYPTO_INIT: crypto_handshake_init succeeded");

  // Set up server connection info for known_hosts
  SAFE_STRNCPY(g_crypto_ctx.server_hostname, address, sizeof(g_crypto_ctx.server_hostname) - 1);
  const char *server_ip = server_connection_get_ip();
  log_debug("CLIENT_CRYPTO_INIT: server_connection_get_ip() returned: '%s'", server_ip ? server_ip : "NULL");
  SAFE_STRNCPY(g_crypto_ctx.server_ip, server_ip ? server_ip : "", sizeof(g_crypto_ctx.server_ip) - 1);

  // Use port from server_connection_set_port() if available (e.g., from WebSocket URL),
  // otherwise use the port from options (TCP/default path)
  int connection_port = server_connection_get_port();
  g_crypto_ctx.server_port = (uint16_t)(connection_port > 0 ? connection_port : port);
  log_debug("CLIENT_CRYPTO_INIT: Set server_ip='%s', server_port=%u", g_crypto_ctx.server_ip, g_crypto_ctx.server_port);

  // Configure server key verification if specified
  if (strlen(server_key) > 0) {
    g_crypto_ctx.verify_server_key = true;
    SAFE_STRNCPY(g_crypto_ctx.expected_server_key, server_key, sizeof(g_crypto_ctx.expected_server_key) - 1);
    log_debug("Server key verification enabled: %s", server_key);
  }

  // If --require-client-verify is set, perform ACDS session lookup for server identity
  if (GET_OPTION(require_client_verify) && strlen(GET_OPTION(session_string)) > 0) {
    log_debug("--require-client-verify enabled: performing ACDS session lookup for '%s'", GET_OPTION(session_string));

    // Connect to ACDS server (configurable via --acds-server and --acds-port options)
    acds_client_config_t acds_config;
    acds_client_config_init_defaults(&acds_config);
    SAFE_STRNCPY(acds_config.server_address, GET_OPTION(discovery_server), sizeof(acds_config.server_address));
    acds_config.server_port = GET_OPTION(discovery_port);
    acds_config.timeout_ms = 5 * MS_PER_SEC_INT;
    acds_config.identity_key = GET_OPTION(encrypt_key);

    // ACDS key verification (optional in debug builds, only if --discovery-service-key is provided)
    if (strlen(GET_OPTION(discovery_service_key)) > 0) {
      log_debug("Verifying ACDS server key for %s...", acds_config.server_address);
      uint8_t acds_pubkey[32];
      asciichat_error_t verify_result =
          discovery_keys_verify(acds_config.server_address, GET_OPTION(discovery_service_key), acds_pubkey);
      if (verify_result != ASCIICHAT_OK) {
        NOTICE(DANGER, "ACDS VERIFICATION FAILED", "ACDS key verification failed for %s", acds_config.server_address);
        return -1;
      }
      log_debug("ACDS server key verified successfully");
    }
#ifndef NDEBUG
    else {
      log_debug("Skipping ACDS key verification (debug build, no --discovery-service-key provided)");
    }
#endif

    acds_client_t acds_client;
    asciichat_error_t acds_result = acds_client_connect(&acds_client, &acds_config);
    if (acds_result != ASCIICHAT_OK) {
      log_error("Failed to connect to ACDS server at %s:%d", acds_config.server_address, acds_config.server_port);
      return -1;
    }

    // Perform SESSION_LOOKUP to get server's identity
    acds_session_lookup_result_t lookup_result;
    acds_result = acds_session_lookup(&acds_client, GET_OPTION(session_string), &lookup_result);
    acds_client_disconnect(&acds_client);

    if (acds_result != ASCIICHAT_OK || !lookup_result.found) {
      log_error("ACDS session lookup failed for '%s': %s", GET_OPTION(session_string),
                lookup_result.found ? "session not found" : "lookup error");
      return -1;
    }

    // Convert server's Ed25519 public key (32 bytes) to hex string
    char server_key_hex[65]; // 32 bytes * 2 + null terminator
    for (size_t i = 0; i < 32; i++) {
      SAFE_SNPRINTF(&server_key_hex[i * 2], 3, "%02x", lookup_result.host_pubkey[i]);
    }
    server_key_hex[64] = '\0';

    // Set expected server key for verification during handshake
    g_crypto_ctx.verify_server_key = true;
    SAFE_STRNCPY(g_crypto_ctx.expected_server_key, server_key_hex, sizeof(g_crypto_ctx.expected_server_key) - 1);
    log_debug("ACDS session lookup succeeded - server identity will be verified");
    log_debug("Expected server key (from ACDS): %s", server_key_hex);
  }

  // Mark initialization as complete
  lifecycle_init(&g_crypto_lc, "client_crypto");

  log_debug("Client crypto handshake initialized");
  log_debug("CLIENT_CRYPTO_INIT: Initialization complete");
  return 0;
}

asciichat_error_t client_crypto_handshake(acip_transport_t *transport) {
  // If we reach here, crypto must be initialized for encryption
  if (!lifecycle_is_initialized(&g_crypto_lc)) {
    NOTICE(DANGER, "ENCRYPTION REQUIRED",
           "Server requires an encrypted connection but client crypto is not initialized.\n"
           "Use --key to specify a client key or --password for password authentication.");
    return SET_ERRNO(ERROR_CRYPTO_AUTH,
                     "Crypto authentication requirements not satisfied"); // No retry - configuration error
  }

  log_debug("Starting crypto handshake with server...");

  START_TIMER("client_crypto_handshake");

  // Step 0a: Send protocol version to server
  protocol_version_packet_t client_version = {0};
  client_version.protocol_version = HOST_TO_NET_U16(1);  // Protocol version 1
  client_version.protocol_revision = HOST_TO_NET_U16(0); // Revision 0
  client_version.supports_encryption = g_crypto_mode;    // Send crypto mode bitmask
  client_version.compression_algorithms = 0;             // No compression for now
  client_version.compression_threshold = 0;
  client_version.feature_flags = HOST_TO_NET_U16(PROTOCOL_FEATURE_RECOVERABLE_ERRORS);

  int result =
      packet_send_via_transport(transport, PACKET_TYPE_PROTOCOL_VERSION, &client_version, sizeof(client_version), 0);
  if (result != 0) {
    log_error("Failed to send protocol version to server");
    STOP_TIMER("client_crypto_handshake");
    return SET_ERRNO(ERROR_CRYPTO_HANDSHAKE, "Crypto protocol negotiation failed");
  }
  log_debug("CLIENT_CRYPTO_HANDSHAKE: Protocol version sent successfully");

  // Step 0b: Receive server's protocol version
  packet_type_t packet_type;
  void *payload = NULL;
  void *alloc_buffer = NULL;
  size_t payload_len = 0;

  result = packet_receive_via_transport(transport, &packet_type, &payload, &payload_len, &alloc_buffer);
  if (result == ASCIICHAT_OK && packet_type == PACKET_TYPE_ERROR_MESSAGE) {
    asciichat_error_t rejection = network_error_decode(packet_type, payload, payload_len);
    if (alloc_buffer)
      buffer_release(alloc_buffer);
    STOP_TIMER("client_crypto_handshake");
    return rejection;
  }
  if (result != ASCIICHAT_OK || packet_type != PACKET_TYPE_PROTOCOL_VERSION) {
    log_error("Failed to receive server protocol version (got type %u)", packet_type);
    log_error("Packet type 0x%x (decimal %u) - Expected 0x%x (decimal %d)", packet_type, packet_type,
              PACKET_TYPE_PROTOCOL_VERSION, PACKET_TYPE_PROTOCOL_VERSION);
    log_error("This suggests a protocol mismatch or packet corruption");
    log_error("Raw packet type bytes: %02x %02x %02x %02x", (packet_type >> 0) & 0xFF, (packet_type >> 8) & 0xFF,
              (packet_type >> 16) & 0xFF, (packet_type >> 24) & 0xFF);
    if (alloc_buffer) {
      buffer_release(alloc_buffer);
    }
    STOP_TIMER("client_crypto_handshake");
    return SET_ERRNO(ERROR_CRYPTO_HANDSHAKE, "Crypto protocol negotiation failed");
  }

  if (payload_len != sizeof(protocol_version_packet_t)) {
    log_error("Invalid protocol version packet size: %zu, expected %zu", payload_len,
              sizeof(protocol_version_packet_t));
    buffer_release(alloc_buffer);
    STOP_TIMER("client_crypto_handshake");
    return SET_ERRNO(ERROR_CRYPTO_HANDSHAKE, "Crypto protocol negotiation failed");
  }

  protocol_version_packet_t server_version;
  memcpy(&server_version, payload, sizeof(protocol_version_packet_t));
  buffer_release(alloc_buffer);

  // Convert from network byte order
  uint16_t server_proto_version = NET_TO_HOST_U16(server_version.protocol_version);
  uint16_t server_proto_revision = NET_TO_HOST_U16(server_version.protocol_revision);
  uint8_t server_mode = server_version.supports_encryption;

  log_info("Server protocol version: %u.%u (crypto mode: 0x%02x)", server_proto_version, server_proto_revision,
           server_mode);

  // Verify server echoed our mode
  if (server_mode != g_crypto_mode) {
    log_error("Server mode mismatch: got 0x%02x, expected 0x%02x", server_mode, g_crypto_mode);
    STOP_TIMER("client_crypto_handshake");
    return SET_ERRNO(ERROR_CRYPTO_AUTH, "Crypto authentication requirements not satisfied");
  }

  if (g_crypto_mode == ACIP_CRYPTO_NONE) {
    STOP_TIMER("client_crypto_handshake");
    return ASCIICHAT_OK;
  }

  // Step 0c: Send crypto capabilities to server
  log_debug("CLIENT_CRYPTO_HANDSHAKE: Sending crypto capabilities");
  crypto_capabilities_packet_t client_caps = {0};
  client_caps.supported_kex_algorithms = HOST_TO_NET_U16(KEX_ALGO_X25519);
  client_caps.supported_auth_algorithms = HOST_TO_NET_U16(AUTH_ALGO_ED25519 | AUTH_ALGO_NONE);
  client_caps.supported_cipher_algorithms = HOST_TO_NET_U16(CIPHER_ALGO_XSALSA20_POLY1305 | CIPHER_ALGO_NONE);
  client_caps.requires_verification =
      (g_crypto_ctx.verify_server_key && g_crypto_ctx.expected_server_key[0] != '\0') ? 1 : 0;
  client_caps.preferred_kex = KEX_ALGO_X25519;
  client_caps.preferred_auth = ACIP_CRYPTO_HAS_AUTH(g_crypto_mode) ? AUTH_ALGO_ED25519 : AUTH_ALGO_NONE;
  client_caps.preferred_cipher =
      ACIP_CRYPTO_HAS_ENCRYPT(g_crypto_mode) ? CIPHER_ALGO_XSALSA20_POLY1305 : CIPHER_ALGO_NONE;

  result = packet_send_via_transport(transport, PACKET_TYPE_CRYPTO_CAPABILITIES, &client_caps, sizeof(client_caps), 0);
  if (result != 0) {
    log_error("Failed to send crypto capabilities to server");
    STOP_TIMER("client_crypto_handshake");
    return SET_ERRNO(ERROR_CRYPTO_HANDSHAKE, "Crypto protocol negotiation failed");
  }
  log_debug("CLIENT_CRYPTO_HANDSHAKE: Crypto capabilities sent successfully");

  // Step 0d: Receive server's crypto parameters
  log_debug("CLIENT_CRYPTO_HANDSHAKE: Receiving server crypto parameters");
  payload = NULL;
  alloc_buffer = NULL;
  payload_len = 0;

  result = packet_receive_via_transport(transport, &packet_type, &payload, &payload_len, &alloc_buffer);
  if (result != ASCIICHAT_OK || packet_type != PACKET_TYPE_CRYPTO_PARAMETERS) {
    log_error("Failed to receive server crypto parameters (got type %u)", packet_type);
    if (alloc_buffer) {
      buffer_release(alloc_buffer);
    }
    STOP_TIMER("client_crypto_handshake");
    return SET_ERRNO(ERROR_CRYPTO_HANDSHAKE, "Crypto protocol negotiation failed");
  }

  if (payload_len != sizeof(crypto_parameters_packet_t)) {
    log_error("Invalid crypto parameters packet size: %zu, expected %zu", payload_len,
              sizeof(crypto_parameters_packet_t));
    buffer_release(alloc_buffer);
    STOP_TIMER("client_crypto_handshake");
    return SET_ERRNO(ERROR_CRYPTO_HANDSHAKE, "Crypto protocol negotiation failed");
  }

  crypto_parameters_packet_t server_params;
  memcpy(&server_params, payload, sizeof(crypto_parameters_packet_t));
  buffer_release(alloc_buffer);

  // Convert from network byte order
  uint16_t kex_pubkey_size = NET_TO_HOST_U16(server_params.kex_public_key_size);
  uint16_t auth_pubkey_size = NET_TO_HOST_U16(server_params.auth_public_key_size);
  uint16_t signature_size = NET_TO_HOST_U16(server_params.signature_size);
  uint16_t shared_secret_size = NET_TO_HOST_U16(server_params.shared_secret_size);

  log_debug("Server crypto parameters: KEX=%u, Auth=%u, Cipher=%u (key_size=%u, auth_size=%u, sig_size=%u, "
            "secret_size=%u, verification=%u)",
            server_params.selected_kex, server_params.selected_auth, server_params.selected_cipher, kex_pubkey_size,
            auth_pubkey_size, signature_size, shared_secret_size, server_params.verification_enabled);
  log_debug("Raw server_params.kex_public_key_size = %u (network byte order)", server_params.kex_public_key_size);

  // Set the crypto parameters in the handshake context
  result = crypto_handshake_set_parameters(&g_crypto_ctx, &server_params);
  if (result != ASCIICHAT_OK) {
    return SET_ERRNO((asciichat_error_t)result, "Failed to set crypto parameters");
  }

  // Store verification flag - server will verify client identity (whitelist check)
  // This is independent of whether server provides its own identity
  if (server_params.verification_enabled) {
    g_crypto_ctx.server_uses_client_auth = true;
    g_crypto_ctx.require_client_auth = true;
    log_info("Server will verify client identity (whitelist enabled)");
  }

  // Validate that server chose algorithms we support
  if (server_params.selected_kex != KEX_ALGO_X25519) {
    log_error("Server selected unsupported KEX algorithm: %u", server_params.selected_kex);
    STOP_TIMER("client_crypto_handshake");
    return SET_ERRNO(ERROR_CRYPTO_AUTH, "Crypto authentication requirements not satisfied");
  }

  // Validate cipher selection based on negotiated mode
  bool expect_cipher = ACIP_CRYPTO_HAS_ENCRYPT(g_crypto_mode);
  if (expect_cipher && server_params.selected_cipher != CIPHER_ALGO_XSALSA20_POLY1305) {
    log_error("Server selected unsupported cipher algorithm: %u", server_params.selected_cipher);
    STOP_TIMER("client_crypto_handshake");
    return SET_ERRNO(ERROR_CRYPTO_AUTH, "Crypto authentication requirements not satisfied");
  }
  if (!expect_cipher && server_params.selected_cipher != CIPHER_ALGO_NONE) {
    NOTICE(DANGER, "ENCRYPTION MODE MISMATCH", "Server chose cipher %u but client requested no encryption",
           server_params.selected_cipher);
    STOP_TIMER("client_crypto_handshake");
    return SET_ERRNO(ERROR_CRYPTO_AUTH, "Crypto authentication requirements not satisfied");
  }

  log_debug("CLIENT_CRYPTO_HANDSHAKE: Protocol negotiation completed successfully");

  // Step 0.5: Send CRYPTO_CLIENT_HELLO with expected server key (multi-key support)
  // This allows the server to select the correct identity key from g_server_identity_keys[]
  if (g_crypto_ctx.verify_server_key && strlen(g_crypto_ctx.expected_server_key) > 0) {
    log_debug("CLIENT_CRYPTO_HANDSHAKE: Sending expected server key to support multi-key selection");

    // Parse expected server key to get the Ed25519 public key
    public_key_t expected_keys[MAX_CLIENTS];
    size_t num_expected_keys = 0;

    if (parse_public_keys(g_crypto_ctx.expected_server_key, expected_keys, &num_expected_keys, MAX_CLIENTS) == 0 &&
        num_expected_keys > 0) {
      // Send the first expected key (client should only have one expected server key)
      // Format: 32-byte Ed25519 public key
      log_debug("Sending CRYPTO_CLIENT_HELLO with expected server key for multi-key selection");
      result = packet_send_via_transport(transport, PACKET_TYPE_CRYPTO_CLIENT_HELLO, expected_keys[0].key,
                                         ED25519_PUBLIC_KEY_SIZE, 0);

      if (result != ASCIICHAT_OK) {
        return SET_ERRNO((asciichat_error_t)result, "Failed to send CRYPTO_CLIENT_HELLO packet");
      }

      // Log the key fingerprint for debugging
      char hex_key[65];
      pubkey_to_hex(expected_keys[0].key, hex_key);
      log_debug("Sent expected server key: %s", hex_key);
    } else {
      log_warn("Failed to parse expected server key '%s' - server will use default key",
               g_crypto_ctx.expected_server_key);
    }
  }

  // Step 1: Receive server's public key and send our public key
  log_debug("CLIENT_CRYPTO_HANDSHAKE: Starting key exchange");
  {
    packet_type_t packet_type;
    void *payload = NULL;
    void *alloc_buffer = NULL;
    size_t payload_len = 0;
    int recv_result = packet_receive_via_transport(transport, &packet_type, &payload, &payload_len, &alloc_buffer);
    if (recv_result != ASCIICHAT_OK) {
      if (alloc_buffer) {
        buffer_release(alloc_buffer);
      }
      return SET_ERRNO((asciichat_error_t)recv_result, "Failed to receive KEY_EXCHANGE_INIT from server");
    }
    // Client handshake functions consume the received payload buffer
    result = crypto_handshake_client_key_exchange(&g_crypto_ctx, transport, packet_type, payload, payload_len);
    buffer_release(alloc_buffer);
  }
  if (result != ASCIICHAT_OK) {
#ifdef _WIN32
    // On Windows: Cleanup capture resources before exiting to prevent Media Foundation threads from hanging exit()
    // Media Foundation creates background COM threads that can block exit() if not properly shut down
    capture_cleanup();
#endif
    return SET_ERRNO((asciichat_error_t)result, "Crypto key exchange failed");
  }
  log_debug("CLIENT_CRYPTO_HANDSHAKE: Key exchange completed successfully");

  // SECURITY: Warn when server requires client verification but client has no identity key
  bool client_has_identity = (g_crypto_ctx.client_public_key.type == KEY_TYPE_ED25519);

  if (g_crypto_ctx.require_client_auth && !client_has_identity) {
    // Server requires client verification but client has no identity key
    log_warn("Server requires client verification but client has no identity key");

    // Check if we're running interactively (stdin is a terminal)
    // In debug builds with CLAUDECODE, skip interactive prompts (LLM can't type)
#ifndef NDEBUG
    bool skip_interactive = platform_getenv("CLAUDECODE") != NULL;
#else
    bool skip_interactive = false;
#endif
    if (!skip_interactive && platform_is_interactive()) {
      // Interactive mode - prompt user for confirmation
      // Prompt user - default is No since this will likely fail
      if (!ui_notice_confirm(UI_NOTICE_WARNING,
                             "CLIENT AUTHENTICATION REQUIRED\nThe server requires a client identity key, but "
                             "--key was not supplied.\n\n"
                             "1. Generate a key: ssh-keygen -t ed25519\n"
                             "2. Add its public key to the server --client-keys list.\n"
                             "3. Connect with: ascii-chat client --key /path/to/private/key\n\n"
                             "Continue without a key (this will likely fail)",
                             30)) {
        log_plain("Connection aborted by user.");
        exit(0); // User declined - exit cleanly
      }

      NOTICE(WARNING, "CLIENT IDENTITY MISSING",
             "Warning: Continuing without client identity key (connection may fail).\n");
    } else {
      // Non-interactive mode (background/script) - just log warning and continue
      NOTICE(WARNING, "CLIENT AUTHENTICATION REQUIRED",
             "Non-interactive mode: Continuing without client identity key (connection may fail)");
    }
  }

  // Step 2: Receive auth challenge and send response
  log_debug("CLIENT_CRYPTO: Sending auth response to server...");
  log_debug("CLIENT_CRYPTO_HANDSHAKE: Starting auth response");
  {
    packet_type_t packet_type;
    void *payload = NULL;
    void *alloc_buffer = NULL;
    size_t payload_len = 0;
    int recv_result = packet_receive_via_transport(transport, &packet_type, &payload, &payload_len, &alloc_buffer);
    if (recv_result != ASCIICHAT_OK) {
      if (alloc_buffer) {
        buffer_release(alloc_buffer);
      }
      return SET_ERRNO((asciichat_error_t)recv_result, "Failed to receive auth challenge from server");
    }
    // Client handshake functions consume the received payload buffer
    result = crypto_handshake_client_auth_response(&g_crypto_ctx, transport, packet_type, payload, payload_len);
    buffer_release(alloc_buffer);
  }
  if (result != ASCIICHAT_OK) {
    return SET_ERRNO((asciichat_error_t)result, "Crypto authentication failed");
  }
  log_debug("CLIENT_CRYPTO: Auth response sent successfully");
  log_debug("CLIENT_CRYPTO_HANDSHAKE: Auth response completed successfully");

  // Check if handshake completed during auth response (no authentication needed)
  if (g_crypto_ctx.state == CRYPTO_HANDSHAKE_READY) {
    // Propagate encryption flag to crypto context
    g_crypto_ctx.crypto_ctx.encrypt_data = ACIP_CRYPTO_HAS_ENCRYPT(g_crypto_mode);
    // Set crypto context on the persistent transport now that handshake is complete
    transport->crypto_ctx = (crypto_context_t *)crypto_client_get_context();
    STOP_TIMER_AND_LOG(debug, 100 * NS_PER_MS_INT, "client_crypto_handshake",
                       "Crypto handshake completed successfully (no authentication)");
    return ASCIICHAT_OK;
  }

  // Step 3: Receive handshake complete message
  log_debug("CLIENT_CRYPTO_HANDSHAKE: Waiting for handshake complete message");
  {
    packet_type_t packet_type;
    void *payload = NULL;
    void *alloc_buffer = NULL;
    size_t payload_len = 0;
    int recv_result = packet_receive_via_transport(transport, &packet_type, &payload, &payload_len, &alloc_buffer);
    if (recv_result != ASCIICHAT_OK) {
      if (alloc_buffer) {
        buffer_release(alloc_buffer);
      }
      return SET_ERRNO((asciichat_error_t)recv_result, "Failed to receive handshake completion from server");
    }
    // Client handshake functions consume the received payload buffer
    result = crypto_handshake_client_complete(&g_crypto_ctx, transport, packet_type, payload, payload_len);
    buffer_release(alloc_buffer);
  }
  if (result != ASCIICHAT_OK) {
    return SET_ERRNO((asciichat_error_t)result, "Crypto handshake completion failed");
  }

  // Propagate encryption flag to crypto context
  g_crypto_ctx.crypto_ctx.encrypt_data = ACIP_CRYPTO_HAS_ENCRYPT(g_crypto_mode);
  // Set crypto context on the persistent transport now that handshake is complete
  transport->crypto_ctx = (crypto_context_t *)crypto_client_get_context();

  STOP_TIMER_AND_LOG(debug, 100 * NS_PER_MS_INT, "client_crypto_handshake", "Crypto handshake completed successfully");
  log_debug("CLIENT_CRYPTO_HANDSHAKE: Handshake completed successfully, state=%d", g_crypto_ctx.state);
  return ASCIICHAT_OK;
}

bool crypto_client_is_ready(void) {
  if (!lifecycle_is_initialized(&g_crypto_lc) || g_crypto_mode == ACIP_CRYPTO_NONE) {
    return false;
  }

  return crypto_handshake_is_ready(&g_crypto_ctx);
}

const crypto_context_t *crypto_client_get_context(void) {
  if (!crypto_client_is_ready()) {
    return NULL;
  }

  return crypto_handshake_get_context(&g_crypto_ctx);
}

int crypto_client_encrypt_packet(const uint8_t *plaintext, size_t plaintext_len, uint8_t *ciphertext,
                                 size_t ciphertext_size, size_t *ciphertext_len) {
  return crypto_encrypt_packet_or_passthrough(&g_crypto_ctx, crypto_client_is_ready(), plaintext, plaintext_len,
                                              ciphertext, ciphertext_size, ciphertext_len);
}

int crypto_client_decrypt_packet(const uint8_t *ciphertext, size_t ciphertext_len, uint8_t *plaintext,
                                 size_t plaintext_size, size_t *plaintext_len) {
  return crypto_decrypt_packet_or_passthrough(&g_crypto_ctx, crypto_client_is_ready(), ciphertext, ciphertext_len,
                                              plaintext, plaintext_size, plaintext_len);
}

void crypto_client_cleanup(void) {
  // Shutdown if initialized
  if (lifecycle_shutdown(&g_crypto_lc)) {
    crypto_handshake_destroy(&g_crypto_ctx);
    log_debug("Client crypto handshake cleaned up");
  }
}

bool crypto_client_should_rekey(void) {
  if (!lifecycle_is_initialized(&g_crypto_lc) || !crypto_client_is_ready() || !g_crypto_ctx.crypto_ctx.encrypt_data) {
    return false;
  }
  return crypto_handshake_should_rekey(&g_crypto_ctx);
}

int crypto_client_initiate_rekey(void) {
  if (!lifecycle_is_initialized(&g_crypto_lc) || !crypto_client_is_ready()) {
    log_error("Cannot initiate rekey: crypto not initialized or not ready");
    return -1;
  }

  acip_transport_t *transport = server_connection_get_transport();
  if (!transport) {
    log_error("Cannot initiate rekey: invalid transport");
    return -1;
  }

  asciichat_error_t result = crypto_handshake_rekey_request(&g_crypto_ctx, transport);
  if (result != ASCIICHAT_OK) {
    log_error("Failed to send REKEY_REQUEST: %d", result);
    return -1;
  }

  return 0;
}

int crypto_client_process_rekey_request(const uint8_t *packet, size_t packet_len) {
  if (!lifecycle_is_initialized(&g_crypto_lc) || !crypto_client_is_ready()) {
    log_error("Cannot process rekey request: crypto not initialized or not ready");
    return -1;
  }

  asciichat_error_t result = crypto_handshake_process_rekey_request(&g_crypto_ctx, packet, packet_len);
  if (result != ASCIICHAT_OK) {
    log_error("Failed to process REKEY_REQUEST: %d", result);
    return -1;
  }

  return 0;
}

int crypto_client_send_rekey_response(void) {
  if (!lifecycle_is_initialized(&g_crypto_lc) || !crypto_client_is_ready()) {
    log_error("Cannot send rekey response: crypto not initialized or not ready");
    return -1;
  }

  acip_transport_t *transport = server_connection_get_transport();
  if (!transport) {
    log_error("Cannot send rekey response: invalid transport");
    return -1;
  }

  asciichat_error_t result = crypto_handshake_rekey_response(&g_crypto_ctx, transport);
  if (result != ASCIICHAT_OK) {
    log_error("Failed to send REKEY_RESPONSE: %d", result);
    return -1;
  }

  return 0;
}

int crypto_client_process_rekey_response(const uint8_t *packet, size_t packet_len) {
  if (!lifecycle_is_initialized(&g_crypto_lc) || !crypto_client_is_ready()) {
    log_error("Cannot process rekey response: crypto not initialized or not ready");
    return -1;
  }

  asciichat_error_t result = crypto_handshake_process_rekey_response(&g_crypto_ctx, packet, packet_len);
  if (result != ASCIICHAT_OK) {
    log_error("Failed to process REKEY_RESPONSE: %d", result);
    return -1;
  }

  return 0;
}

int crypto_client_send_rekey_complete(void) {
  if (!lifecycle_is_initialized(&g_crypto_lc) || !crypto_client_is_ready()) {
    log_error("Cannot send rekey complete: crypto not initialized or not ready");
    return -1;
  }

  acip_transport_t *transport = server_connection_get_transport();
  if (!transport) {
    log_error("Cannot send rekey complete: invalid transport");
    return -1;
  }

  asciichat_error_t result = crypto_handshake_rekey_complete(&g_crypto_ctx, transport);
  if (result != ASCIICHAT_OK) {
    log_error("Failed to send REKEY_COMPLETE: %d", result);
    return -1;
  }

  return 0;
}

void display_set_context(session_display_ctx_t *display_ctx) {
  g_display_ctx = display_ctx;
  g_keyboard_enabled = display_ctx && terminal_is_stdin_tty();
}

int display_init() {
  // Build display configuration from options
  session_display_config_t config = {
      .snapshot_mode = GET_OPTION(snapshot_mode),
      .palette_type = GET_OPTION(palette_type),
      .custom_palette = GET_OPTION(palette_custom_set) ? GET_OPTION(palette_custom) : NULL,
      .color_mode = TERM_COLOR_AUTO // Will be overridden by command-line options
  };

  // Create display context using session library
  g_display_ctx = session_display_create(&config);
  if (!g_display_ctx) {
    SET_ERRNO(ERROR_DISPLAY, "Failed to initialize display");
    return -1;
  }

  // Check if client mode should load local media (--file or --url)
  const char *media_url = GET_OPTION(media_url);
  const char *media_file = GET_OPTION(media_file);

  if ((media_url && strlen(media_url) > 0) || (media_file && strlen(media_file) > 0)) {
    // Client mode with local media file/URL - create capture context for keyboard controls
    session_capture_config_t capture_config = {0};
    capture_config.target_fps = 60;
    capture_config.resize_for_network = false;
    capture_config.should_exit_callback = NULL;
    capture_config.callback_data = NULL;

    if (media_url && strlen(media_url) > 0) {
      capture_config.type = MEDIA_SOURCE_FILE;
      capture_config.path = media_url;
    } else {
      if (strcmp(media_file, "-") == 0) {
        capture_config.type = MEDIA_SOURCE_STDIN;
        capture_config.path = NULL;
      } else {
        capture_config.type = MEDIA_SOURCE_FILE;
        capture_config.path = media_file;
      }
    }

    capture_config.loop = GET_OPTION(media_loop);
    capture_config.initial_seek_timestamp = GET_OPTION(media_seek_timestamp);

    g_display_capture_ctx = session_capture_create(&capture_config);
    if (!g_display_capture_ctx) {
      log_warn("Failed to create capture context for local media - keyboard seek/pause disabled");
      g_display_capture_ctx = NULL;
    }
  }

  // Keyboard is pre-initialized from asciichat_shared_init()
  // Only enable keyboard input if stdin is a TTY (avoid interfering with piped/redirected I/O)
  g_keyboard_enabled = terminal_is_stdin_tty();

  // Register display atomics with named debug registry
  static bool display_atomics_registered = false;
  if (!display_atomics_registered) {
    NAMED_REGISTER_ATOMIC(&g_is_first_frame_of_connection, "first_frame_of_display_connection", NULL);
    display_atomics_registered = true;
  }

  return 0;
}

bool display_has_tty() {
  return session_display_has_tty(g_display_ctx);
}

void display_full_reset() {
  if (g_display_ctx && !should_exit()) {
    session_display_reset(g_display_ctx);
  }
}

void display_reset_for_new_connection() {
  atomic_store_bool(&g_is_first_frame_of_connection, true);
}

void display_disable_logging_for_first_frame() {
  // Atomically check if this is the first frame and mark as not-first
  // Avoids TOCTOU race where multiple threads could both think they're first
  bool was_first_frame = atomic_exchange_bool(&g_is_first_frame_of_connection, false);

  if (was_first_frame) {
    // Disable terminal logging before clearing display and rendering first frame
    log_set_terminal_output(false);

    // Signal the intro splash screen to stop - first frame is ready to render
    splash_intro_done();
  }
}

void display_render_frame(const char *frame_data) {
  if (!frame_data) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Attempted to render NULL frame data");
    return;
  }

  // Stop splash screen animation on first frame
  // This must be called BEFORE any frame rendering to prevent splash/frame flickering
  display_disable_logging_for_first_frame();

  // Render help screen if active (suppresses frame rendering)
  if (keyboard_help_is_active(g_display_ctx)) {
    keyboard_help_render(g_display_ctx);

    // Still poll keyboard for interactive controls while help is visible
    if (g_keyboard_enabled) {
      keyboard_key_t key = ui_input_read_key(UI_SCREEN_MEDIA);
      if (key != KEY_NONE) {
        session_handle_keyboard_input(g_display_capture_ctx, g_display_ctx, key);
      }
    }
    return; // Skip normal frame rendering
  }

  // Use session display library for frame rendering
  session_display_render_frame(g_display_ctx, frame_data);

  // Poll for keyboard input and handle interactive controls
  // - If client mode has local media (--file/--url), pass capture context for full controls
  //   (seek, pause, play, volume, color mode, flip)
  // - If client mode is network-only, pass NULL (volume, color mode, flip work; seek/pause ignored)
  if (g_keyboard_enabled) {
    keyboard_key_t key = ui_input_read_key(UI_SCREEN_MEDIA);
    if (key != KEY_NONE) {
      session_handle_keyboard_input(g_display_capture_ctx, g_display_ctx, key);
    }
  }
}

void display_cleanup() {
  // Cleanup keyboard input if it was initialized
  if (g_keyboard_enabled) {
    ui_controller_remove(UI_SCREEN_HELP);
    ui_controller_remove(UI_SCREEN_MEDIA);
    g_keyboard_enabled = false;
  }

  // Cleanup optional local media capture context if it was created
  if (g_display_capture_ctx) {
    session_capture_destroy(g_display_capture_ctx);
    g_display_capture_ctx = NULL;
  }

  // Display context is now managed by session_client_like framework
  // Do not destroy it here - the framework will handle cleanup
  g_display_ctx = NULL;
}

static void *ping_thread_func(void *arg) {
  (void)arg;

#ifdef DEBUG_THREADS
  log_debug("Ping thread started");
#endif

  // FPS tracking for keepalive thread (ping sent every 1 second)
  static fps_t fps_tracker = {0};
  static bool fps_tracker_initialized = false;
  if (!fps_tracker_initialized) {
    fps_init_with_interval(&fps_tracker, 1, "KEEPALIVE",
                           100 * NS_PER_MS_INT); // Report keepalive metrics every 100ms
    fps_tracker_initialized = true;
  }

  // Startup grace period: Allow connection initialization to complete before checking state
  // Prevents race condition where thread spawns before transport is fully configured
  APP_CALLBACK_VOID(platform_pump_events);
  platform_sleep_ms(100);

  while (!should_exit() && !server_connection_is_lost()) {
    // Check if connection is still active before sending
    if (!server_connection_is_active()) {
      log_debug("Connection inactive, exiting ping thread");
      break;
    }

    // Check if session rekeying should be triggered
    if (crypto_client_should_rekey()) {
      log_debug("Rekey threshold reached, initiating session rekey");
      if (crypto_client_initiate_rekey() < 0) {
        log_error("Failed to initiate rekey");
        // Don't break - continue with keepalive, rekey will be retried
      }
    }

    // Send ping packet every PING_INTERVAL_SECONDS to keep connection alive
    // Server timeout is 5 seconds, so 3-second pings provide safety margin
    if (threaded_send_ping_packet() != ASCIICHAT_OK) {
      log_debug("Failed to send ping packet");
      // Set connection lost flag so main loop knows to reconnect
      server_connection_lost();
      break;
    }

    // Track ping for FPS reporting
    uint64_t ping_start_ns = time_get_ns();
    fps_frame_ns(&fps_tracker, ping_start_ns, "ping sent");

    // Sleep with early wake capability for responsive shutdown
    // Break sleep into intervals to check shutdown flags and rekey triggers
    while (!should_exit() && !server_connection_is_lost() && server_connection_is_active()) {
      uint64_t now_ns = time_get_ns();
      uint64_t elapsed_ns = time_elapsed_ns(ping_start_ns, now_ns);

      if (elapsed_ns >= PING_INTERVAL_NS) {
        break; // Time for next ping
      }

      // Sleep for one interval or until next ping, whichever is sooner
      uint64_t remaining_ns = PING_INTERVAL_NS - elapsed_ns;
      uint64_t sleep_ns = (remaining_ns > PING_SLEEP_INTERVAL_NS) ? PING_SLEEP_INTERVAL_NS : remaining_ns;
      platform_sleep_ns(sleep_ns);
    }
  }

#ifdef DEBUG_THREADS
  log_debug("Ping thread stopped");
#endif

  atomic_store_bool(&g_ping_thread_exited, true);

  // Clean up thread-local error context before exit

  return NULL;
}

int keepalive_start_thread() {
  if (g_ping_thread_created) {
    log_warn("Ping thread already created");
    return 0;
  }

  // Register keepalive atomics with named debug registry
  static bool keepalive_atomics_registered = false;
  if (!keepalive_atomics_registered) {
    NAMED_REGISTER_ATOMIC(&g_ping_thread_exited, "keepalive_ping_thread_exit_confirmation", NULL);
    keepalive_atomics_registered = true;
  }

  // Start ping thread for keepalive
  atomic_store_bool(&g_ping_thread_exited, false);
  if (thread_pool_spawn(g_client_worker_pool, ping_thread_func, NULL, 3, "keepalive_ping") != ASCIICHAT_OK) {
    log_error("Failed to spawn ping thread in worker pool");
    LOG_ERRNO_IF_SET("Ping thread creation failed");
    return -1;
  }

  g_ping_thread_created = true;
  return 0;
}

void keepalive_stop_thread() {
  if (!g_ping_thread_created) {
    return;
  }

  // Don't call signal_exit() here - that's for global shutdown only!
  // The ping thread monitors connection state and will exit when connection is lost

  // Wait for thread to exit gracefully
  int wait_count = 0;
  while (wait_count < 20 && !atomic_load_bool(&g_ping_thread_exited)) {
    platform_sleep_ns(100 * NS_PER_MS_INT); // 100ms
    wait_count++;
  }

  if (!atomic_load_bool(&g_ping_thread_exited)) {
    log_warn("Ping thread not responding - will be joined by thread pool");
  }

  // Thread will be joined by thread_pool_stop_all() in protocol_stop_connection()
  g_ping_thread_created = false;

  log_debug("Ping thread stopped and joined");
}

bool keepalive_thread_exited() {
  return atomic_load_bool(&g_ping_thread_exited);
}

static void client_handle_sigwinch(int sigwinch) {
  (void)(sigwinch);

  // Terminal was resized, update dimensions and recalculate aspect ratio
  // ONLY if both width and height are auto (not manually set)
  if (GET_OPTION(auto_width) && GET_OPTION(auto_height)) {
    // Get terminal size and update via proper RCU setters
    unsigned short int term_width, term_height;
    if (get_terminal_size(&term_width, &term_height) == ASCIICHAT_OK) {
      options_set_int("width", (int)term_width);
      options_set_int("height", (int)term_height);
    }

    // Send new size to server if connected
    if (server_connection_is_active()) {
      if (threaded_send_terminal_size_with_auto_detect((int)terminal_get_effective_width(),
                                                       (int)terminal_get_effective_height()) < 0) {
        log_warn("Failed to send terminal capabilities to server: %s", network_error_string());
      } else {
        display_full_reset();
        log_set_terminal_output(false);
      }
    }
  }
}

static void shutdown_client() {
  // Guard against double cleanup (can be called explicitly + via atexit)
  static bool shutdown_done = false;
  if (shutdown_done) {
    return;
  }
  shutdown_done = true;
  log_debug("[SHUTDOWN] 1. Starting shutdown");

  // Set global shutdown flag to stop all threads
  signal_exit();

  // Stop splash animation thread before any resource cleanup
  splash_intro_done();

  // IMPORTANT: Stop all protocol threads BEFORE cleaning up resources
  // protocol_stop_connection() shuts down the socket to interrupt blocking recv(),
  // then waits for the data reception thread and capture thread to exit.
  // This prevents race conditions where threads access freed resources.
  log_debug("[SHUTDOWN] 4. About to call protocol_stop_connection()");
  protocol_stop_connection();

  // Destroy client worker thread pool (all threads already stopped by protocol_stop_connection)
  if (g_client_worker_pool) {
    thread_pool_destroy(g_client_worker_pool);
    g_client_worker_pool = NULL;
  }

  // Destroy application client context
  log_debug("[SHUTDOWN] 8. About to destroy app_client");
  if (g_client) {
    app_client_destroy(&g_client);
  }

  // Now safe to cleanup server connection (socket already closed by protocol_stop_connection)
  // Legacy cleanup - will be removed after full migration to tcp_client
  log_debug("[SHUTDOWN] 10. About to cleanup server connection");
  server_connection_cleanup();

  // Cleanup capture subsystems (capture thread already stopped by protocol_stop_connection)
  log_debug("[SHUTDOWN] 12. About to cleanup capture");
  audio_cleanup();
  capture_cleanup();

  // Cleanup video encoder
  if (g_video_encoder) {
    log_debug("[SHUTDOWN] 14a. About to cleanup video encoder");
    h265_encoder_destroy(g_video_encoder);
    g_video_encoder = NULL;
  }

  // Print audio analysis report if enabled
  // Print audio analysis report if enabled
  if (GET_OPTION(audio_analysis_enabled)) {
    audio_analysis_print_report();
    audio_analysis_destroy();
  }

  // Cleanup display and terminal state
  // WORKAROUND: Skip cleanup during shutdown to avoid hanging
  // display_cleanup();

  // Cleanup core systems
  // WORKAROUND: Skip cleanup during shutdown to avoid hanging
  // buffer_system_cleanup();

  // Disable keepawake mode (re-allow OS to sleep)
  platform_disable_keepawake();

  log_debug("Client shutdown complete");
  log_destroy();
}

static int initialize_client_systems(void) {
  // All shared subsystem initialization (timer, logging, platform, buffer domain)
  // is now done by asciichat_shared_init() in src/main.c BEFORE options_init()

  // Initialize client worker thread pool (needed for network protocol threads)
  // This is required for all modes that connect to the server, including snapshot mode
  if (!g_client_worker_pool) {
    g_client_worker_pool = thread_pool_create("client_workers");
    if (!g_client_worker_pool) {
      log_fatal("Failed to create client worker thread pool");
      return ERROR_THREAD;
    }
  }

  // Ensure logging output is available for connection attempts (unless it was disabled with --quiet)
  if (!GET_OPTION(quiet)) {
    log_set_terminal_output(true);
  }
  log_truncate_if_large();

  // Display subsystem is now initialized by session_client_like_run()
  // No need to call display_init() here

  // Initialize application client context
  if (!g_client) {
    g_client = app_client_create();
    if (!g_client) {
      log_fatal("Failed to create application client context");
      return ERROR_NETWORK;
    }
    log_debug("Application client context created successfully");
  }

  // Initialize server connection management (legacy - will be migrated to tcp_client)
  if (server_connection_init() != 0) {
    log_fatal("Failed to initialize server connection");
    return ERROR_NETWORK;
  }

  // Initialize capture subsystems
  int capture_result = capture_init();
  if (capture_result != 0) {
    log_fatal("Failed to initialize capture subsystem");
    return capture_result;
  }

  // Timed recordings capture call audio; immediate snapshots need only one frame.
  if (GET_OPTION(audio_enabled) && (!GET_OPTION(snapshot_mode) || GET_OPTION(snapshot_delay) > 0)) {
    if (audio_client_init() != 0) {
      NOTICE(WARNING, "AUDIO UNAVAILABLE", "Failed to initialize audio system");
      // Continue without audio instead of crashing (e.g., ARM systems with audio device incompatibility)
    }

    // Initialize audio analysis if requested
    if (GET_OPTION(audio_analysis_enabled)) {
      if (audio_analysis_init() != 0) {
        log_warn("Failed to initialize audio analysis");
      }
    }
  }

  return 0;
}

static bool client_should_reconnect(asciichat_error_t last_error, int attempt_number, void *user_data) {
  if (last_error == ERROR_CRYPTO_AUTH || last_error == ERROR_CRYPTO_KEY || last_error == ERROR_CRYPTO_VERIFICATION ||
      last_error == ERROR_CONFIG || last_error == ERROR_INVALID_PASSWORD || last_error == ERROR_INVALID_SIGNATURE ||
      last_error == ERROR_NETWORK_PROTOCOL || last_error == ERROR_INTERNAL)
    return false;
  (void)attempt_number;
  (void)user_data;

  // In snapshot mode, don't reconnect - exit after first failure
  if (GET_OPTION(snapshot_mode)) {
    log_error("Connection lost in snapshot mode - not retrying");
    return false;
  }

  // Otherwise, allow reconnection (framework handles max_reconnect_attempts limit)
  return true;
}

static asciichat_error_t client_run(session_capture_ctx_t *capture, session_display_ctx_t *display, void *user_data) {
  (void)capture;   // Provided by session_client_like, used by protocol threads
  (void)user_data; // Unused

  // Make the framework-created display context available to protocol threads
  display_set_context(display);

  // Get the render loop's should_exit callback for monitoring
  bool (*render_should_exit)(void *) = session_client_like_get_render_should_exit();
  if (!render_should_exit) {
    return SET_ERRNO(ERROR_INVALID_STATE, "Render should_exit callback not initialized");
  }

  // Attempt connection with fallback stages (TCP, WebRTC+STUN, WebRTC+TURN)
  server_connection_set_remote_error(ASCIICHAT_OK);
  asciichat_error_t connection_result = connection_attempt_tcp(
      &g_client_session.connection_ctx,
      g_client_session.discovered_address != NULL ? g_client_session.discovered_address : "",
      (uint16_t)(g_client_session.discovered_port > 0 ? g_client_session.discovered_port : 27224));

  // Check if shutdown was requested during connection attempt
  if (should_exit()) {
    log_info("Shutdown requested during connection attempt");
    return ERROR_NETWORK;
  }

  if (connection_result != ASCIICHAT_OK) {
    // Connection failed - need to stop audio threads that were initialized early
    // (even though protocol_start_connection was never called)
    audio_stop_thread();
    // Framework will handle retry based on config
    NOTICE(WARNING, "CONNECTION FAILED", "Connection attempt failed");
    LOG_ERRNO_IF_SET("Connection attempt failed");
    return connection_result;
  }

  // Connection successful - integrate transport into server layer
  if (g_client_session.connection_ctx.connection.transport) {
    server_connection_set_transport(g_client_session.connection_ctx.connection.transport);
    g_client_session.connection_ctx.connection.transport = NULL;
  } else {
    log_error("Connection succeeded but no active transport");
    return ERROR_NETWORK;
  }

  // Log connection status
  if (!g_client_session.has_ever_connected) {
    log_info("Connected");
    g_client_session.has_ever_connected = true;
  } else {
    log_info("Reconnected");
  }

  // Start protocol worker threads for this connection
  if (protocol_start_connection() != 0) {
    log_error("Failed to start connection protocols");
    protocol_stop_connection();
    server_connection_close();
    return ERROR_NETWORK;
  }

  // Monitor connection until it breaks or shutdown is requested
  static bool snapshot_check_logged_once = false;
  while (!should_exit() && server_connection_is_active()) {
    if (protocol_connection_lost()) {
      log_debug("Connection lost detected");
      break;
    }

    // Check if snapshot_delay timer has fired (in case frames stopped arriving)
    // This is a safety check for when frame reception is sparse or stops entirely
    extern uint64_t g_snapshot_first_frame_time_ns;
    bool snapshot_mode_enabled = GET_OPTION(snapshot_mode);

    if (!snapshot_check_logged_once) {
      log_info("CLIENT_MAIN_LOOP: snapshot_mode=%d first_frame_time=%llu snapshot_delay=%.1f", snapshot_mode_enabled,
               (unsigned long long)g_snapshot_first_frame_time_ns, GET_OPTION(snapshot_delay));
      snapshot_check_logged_once = true;
    }

    if (snapshot_mode_enabled && g_snapshot_first_frame_time_ns > 0) {
      uint64_t current_time_ns = time_get_ns();
      double elapsed = time_ns_to_s(time_elapsed_ns(g_snapshot_first_frame_time_ns, current_time_ns));
      double snapshot_delay = GET_OPTION(snapshot_delay);

      // Log progress every 500ms
      static uint64_t last_progress_log_ns = 0;
      if (current_time_ns - last_progress_log_ns > 500 * 1000 * 1000) {
        log_debug("[MAIN_LOOP_SNAPSHOT_CHECK] elapsed=%.3f target=%.3f first_frame_ns=%llu current_ns=%llu", elapsed,
                  snapshot_delay, (unsigned long long)g_snapshot_first_frame_time_ns,
                  (unsigned long long)current_time_ns);
        last_progress_log_ns = current_time_ns;
      }

      if (elapsed >= snapshot_delay) {
        char duration_str[32];
        time_pretty((uint64_t)(elapsed * 1e9), -1, duration_str, sizeof(duration_str));
        log_info("🎬 SNAPSHOT TIMEOUT FIRED (IN_MAIN_LOOP): Snapshot captured after %s! (target=%.3f)", duration_str,
                 snapshot_delay);
        signal_exit();
        break; // Exit loop, proper shutdown will follow
      }
    }

    platform_sleep_us(100 * US_PER_MS_INT);
  }

  if (should_exit()) {
    log_debug("Shutdown requested, cleaning up connection");
  } else {
    log_info("[ELSE_BRANCH] Connection lost path (should_exit=0, connection_active=0)");
    // Connection lost - check if snapshot_delay timer has fired before exiting
    extern uint64_t g_snapshot_first_frame_time_ns;
    if (GET_OPTION(snapshot_mode) && g_snapshot_first_frame_time_ns > 0) {
      uint64_t current_time_ns = time_get_ns();
      double elapsed = time_ns_to_s(time_elapsed_ns(g_snapshot_first_frame_time_ns, current_time_ns));
      double snapshot_delay = GET_OPTION(snapshot_delay);

      log_info("[CONNECTION_LOSS_SNAPSHOT_CHECK] elapsed=%.3f target=%.3f (checking if timer fired)", elapsed,
               snapshot_delay);

      if (elapsed >= snapshot_delay) {
        char duration_str[32];
        time_pretty((uint64_t)(elapsed * 1e9), -1, duration_str, sizeof(duration_str));
        log_info("🎬 SNAPSHOT TIMEOUT FIRED (ON_CONNECTION_LOSS): Snapshot captured after %s! (target=%.3f)",
                 duration_str, snapshot_delay);
        signal_exit();
        // Don't return yet, allow normal cleanup to proceed below
      }
    }

    if (!should_exit()) {
      log_debug("Connection lost, preparing for reconnection attempt");
    }
  }

  // Clean up this connection for potential reconnection
  protocol_stop_connection();
  server_connection_close();

  // Clear transport reference from connection context since server_connection_close() already destroyed it
  // This prevents double-free when connection_context_cleanup() is called below
  g_client_session.connection_ctx.connection.transport = NULL;

  // Recreate thread pool for clean reconnection
  if (g_client_worker_pool) {
    thread_pool_destroy(g_client_worker_pool);
    g_client_worker_pool = NULL;
  }
  g_client_worker_pool = thread_pool_create("client_reconnect");
  if (!g_client_worker_pool) {
    log_error("Failed to recreate worker thread pool");
    return ERROR_THREAD;
  }

  // Reset connection context for next attempt
  connection_context_cleanup(&g_client_session.connection_ctx);
  memset(&g_client_session.connection_ctx, 0, sizeof(g_client_session.connection_ctx));
  if (connection_context_init(&g_client_session.connection_ctx) != ASCIICHAT_OK) {
    log_error("Failed to re-initialize connection context");
    return ERROR_NETWORK;
  }

  // A snapshot is complete once its first frame has been rendered. The peer
  // may close the connection while the snapshot shutdown is propagating, but
  // that is a successful snapshot rather than a reconnectable network error.
  extern uint64_t g_snapshot_first_frame_time_ns;
  if (GET_OPTION(snapshot_mode) && g_snapshot_first_frame_time_ns > 0 && should_exit()) {
    return ASCIICHAT_OK;
  }

  // The receive worker publishes the rejection before marking the connection lost.
  asciichat_error_t remote_error = server_connection_get_remote_error();
  if (remote_error != ASCIICHAT_OK)
    return SET_ERRNO(remote_error, "Server rejected connection: %s", asciichat_error_string(remote_error));
  return ERROR_NETWORK;
}

int client_main(void) {
  log_debug("client_main() starting");

  // Register client crypto callbacks for TCP connection path
  // The TCP path in lib/network/connection_attempt.c relies on these callbacks
  // to handle cryptographic operations and key exchange
  static const app_callbacks_t client_crypto_callbacks = {
      .should_exit = should_exit,
      .signal_exit = signal_exit,
      .platform_get_monotonic_time_us = platform_get_monotonic_time_us,
      .platform_sleep_ms = platform_sleep_ms,
      .server_connection_set_ip = server_connection_set_ip,
      .server_connection_set_port = server_connection_set_port,
      .client_crypto_set_mode = client_crypto_set_mode,
      .client_crypto_init = client_crypto_init,
      .client_crypto_handshake = client_crypto_handshake,
      .crypto_client_is_ready = crypto_client_is_ready,
      .crypto_client_get_context = crypto_client_get_context,
  };
  app_callbacks_register(&client_crypto_callbacks);

  // Initialize client-specific systems (NOT shared with session_client_like)
  // This includes: thread pool, display layer, app client context, server connection
  asciichat_errno_scope_t init_scope = asciichat_errno_scope_begin();
  int init_result = initialize_client_systems();
  if (init_result != 0) {
#ifndef NDEBUG
    // Debug builds: automatically fall back to test pattern if webcam is in use
    if (init_result == ERROR_WEBCAM_IN_USE && !GET_OPTION(test_pattern)) {
      log_warn("Webcam is in use - automatically falling back to test pattern mode (debug build only)");

      // Enable test pattern mode via RCU update
      asciichat_error_t update_result = options_set_bool("test_pattern", true);
      if (update_result != ASCIICHAT_OK) {
        log_error("Failed to update options for test pattern fallback");
        FATAL(init_result, "%s", asciichat_error_string(init_result));
      }

      // Retry initialization with test pattern enabled
      init_result = initialize_client_systems();
      if (init_result != 0) {
        log_error("Failed to initialize even with test pattern fallback");
        webcam_print_init_error_help(init_result);
        FATAL(init_result, "%s", asciichat_error_string(init_result));
      }
      log_debug("Successfully initialized with test pattern fallback");

      // Clear the error state since we successfully recovered
      asciichat_errno_scope_end(init_scope, ASCIICHAT_ERRNO_DISMISSED);
      ASSERT_NO_ERRNO_SINCE(init_scope);
    } else
#endif
    {
      // Release builds or other errors: print help and exit
      if (init_result == ERROR_WEBCAM || init_result == ERROR_WEBCAM_IN_USE || init_result == ERROR_WEBCAM_PERMISSION) {
        webcam_print_init_error_help(init_result);
        FATAL(init_result, "%s", asciichat_error_string(init_result));
      }
      // For other errors, just exit with the error code
      return init_result;
    }
  } else {
    ASSERT_NO_ERRNO_SINCE(init_scope);
    asciichat_errno_scope_end(init_scope, ASCIICHAT_ERRNO_HANDLED);
  }

  // Register cleanup function for graceful shutdown
  (void)atexit(shutdown_client);

  // Register client interrupt callback (socket shutdown on SIGTERM/Ctrl+C)
  // Global signal handlers (SIGTERM, SIGPIPE, Ctrl+C) are set up in setup_signal_handlers() in src/main.c
  set_interrupt_callback(server_connection_shutdown);

#ifndef _WIN32
  // Register SIGWINCH for terminal resize handling (client-specific, not in framework)
  platform_signal(SIGWINCH, client_handle_sigwinch);
#endif

  /* ========================================================================
   * Client-Specific: LAN/Session Discovery
   * ========================================================================
   * This phase discovers the server to connect to via:
   * - LAN discovery (mDNS)
   * - Session string lookup (ACDS)
   * - Direct address/port
   */

  // LAN Discovery: If --scan flag is set, discover servers on local network
  const options_t *opts = options_get();
  if (opts && opts->lan_discovery &&
      (opts->address[0] == '\0' || is_localhost_ipv4(opts->address) || strcmp(opts->address, "localhost") == 0)) {
    log_debug("LAN discovery: --scan flag set, querying for available servers");

    ui_mdns_config_t lan_config;
    memset(&lan_config, 0, sizeof(lan_config));
    lan_config.timeout_ms = 2 * MS_PER_SEC_INT; // Wait up to 2 seconds for responses
    lan_config.max_servers = 20;                // Support up to 20 servers on LAN
    lan_config.quiet = true;                    // Quiet during discovery, TUI will show status

    int discovered_count = 0;
    ui_mdns_server_t *discovered_servers = ui_mdns_query(&lan_config, &discovered_count);

    // Use TUI for server selection
    int selected_index = ui_mdns_select(discovered_servers, discovered_count);

    if (selected_index < 0) {
      // User cancelled or no servers found
      if (discovered_count == 0) {
        // No servers found - log message and prevent any further output
        // Lock the terminal so other threads can't write and our error
        // will be the last message
        log_lock_terminal();

        // Log single message with embedded newlines to prevent multiple log entries
        NOTICE(WARNING, "NO SERVERS FOUND",
               "No ascii-chat servers found on the local network.\nUse 'ascii-chat client <address>' to connect "
               "manually.");

        // Exit without cleanup
        ui_controller_finish(STDERR_FILENO, "", 0);
        platform_force_exit(1);
      }
      // User cancelled (had servers to choose from but pressed cancel)
      log_debug("LAN discovery: User cancelled server selection");
      if (discovered_servers) {
        ui_mdns_free_results(discovered_servers);
      }
      return 1; // User cancelled
    }

    // Update options with discovered server's address and port
    ui_mdns_server_t *selected = &discovered_servers[selected_index];
    const char *selected_address = ui_mdns_get_best_address(selected);

    // We need to modify options, but they're immutable via RCU
    // Create a new options copy with updated address/port
    options_t *opts_new = SAFE_MALLOC(sizeof(options_t), options_t *);
    if (opts_new) {
      memcpy(opts_new, opts, sizeof(options_t));
      SAFE_STRNCPY(opts_new->address, selected_address, sizeof(opts_new->address));

      opts_new->port = (int)selected->port;

      log_debug("LAN discovery: Selected server '%s' at %s:%d", selected->name, opts_new->address, opts_new->port);

      // Note: In a real scenario, we'd update the global options via RCU
      // For now, we'll use the updated values directly for connection
      // This is a known limitation - proper RCU update requires more infrastructure
    }

    ui_mdns_free_results(discovered_servers);
  }

  // =========================================================================
  // Client-Specific: Server Address Resolution
  // =========================================================================
  // Client mode supports:
  // 1. Direct address/port (--address HOST --port PORT) - handled by options
  // 2. LAN discovery (--scan) - handled above
  // 3. WebSocket URL (direct ws:// or wss:// connection string)
  //
  // Note: Session string discovery via ACDS is handled by discovery mode only.
  //       Client mode does NOT use ACDS or session strings.

  const char *discovered_address = NULL;
  int discovered_port = 0;

  // Check if user provided a WebSocket URL as the server address
  const options_t *opts_websocket = options_get();
  const char *provided_address = opts_websocket && opts_websocket->address[0] != '\0' ? opts_websocket->address : NULL;

  if (provided_address && url_is_websocket(provided_address)) {
    // Direct WebSocket connection
    log_debug("Client: Direct WebSocket URL: %s", provided_address);
    discovered_address = provided_address;
    discovered_port = 0; // Port is embedded in the URL
  }

  if (discovered_port > 0) {
    log_debug("Client: discovered_address=%s, discovered_port=%d", discovered_address ? discovered_address : "NULL",
              discovered_port);
  } else {
    log_debug("Client: discovered_address=%s", discovered_address ? discovered_address : "NULL");
  }

  // Store discovered address/port in session state for client_run() callback
  static char address_storage[BUFFER_SIZE_SMALL];
  if (discovered_address) {
    SAFE_STRNCPY(address_storage, discovered_address, sizeof(address_storage));
    g_client_session.discovered_address = address_storage;
    g_client_session.discovered_port = discovered_port;
  } else {
    const options_t *opts_fallback = options_get();
    if (opts_fallback && opts_fallback->address[0] != '\0') {
      SAFE_STRNCPY(address_storage, opts_fallback->address, sizeof(address_storage));
      g_client_session.discovered_address = address_storage;
      g_client_session.discovered_port = opts_fallback->port;
    } else {
      g_client_session.discovered_address = "localhost";
      g_client_session.discovered_port = 27224;
    }
  }

  // Initialize connection context for first attempt
  asciichat_error_t ctx_init_result = connection_context_init(&g_client_session.connection_ctx);
  if (ctx_init_result != ASCIICHAT_OK) {
    log_error("Failed to initialize connection context");
    return 1;
  }

  /* ========================================================================
   * Configure and Run Shared Client-Like Session Framework
   * ========================================================================
   * session_client_like_run() handles all shared initialization:
   * - Terminal output management (force stderr if piped)
   * - Keepawake system (platform sleep prevention)
   * - Splash screen lifecycle
   * - Media source selection (webcam, file, URL, test pattern)
   * - FPS probing for media files
   * - Audio initialization and lifecycle
   * - Display context creation
   * - Proper cleanup ordering (critical for PortAudio)
   *
   * Client mode provides:
   * - client_run() callback: connection loop, protocol startup, monitoring
   * - client_should_reconnect() callback: reconnection policy
   * - Reconnection configuration: attempts, delay, callbacks
   */

  // Get reconnect attempts setting (-1 = unlimited, 0 = no retry, >0 = retry N times)
  int reconnect_attempts = GET_OPTION(reconnect_attempts);

  // Configure session_client_like with client-specific settings
  session_client_like_config_t config = {
      .run_fn = client_run,
      .run_user_data = NULL,
      .kind = SESSION_CLIENT_LIKE_KIND_CLIENT,
      .discovery = NULL,
      .custom_should_exit = NULL,
      .exit_user_data = NULL,
      .keyboard_handler = NULL, // Client mode: server drives display
      .max_reconnect_attempts = reconnect_attempts,
      .should_reconnect_callback = client_should_reconnect,
      .reconnect_user_data = NULL,
      .reconnect_delay_ms = 1000,         // 1 second delay between reconnection attempts
      .print_newline_on_tty_exit = false, // Server/client manages cursor
  };

  log_debug("[CLIENT_MAIN] About to call session_client_like_run() with %d attempts", reconnect_attempts);
  asciichat_error_t session_result = session_client_like_run(&config);
  log_debug("[CLIENT_MAIN] session_client_like_run() returned %d", session_result);

  // Network client lifecycle is owned by connection_context_cleanup() after the session returns.

  // Cleanup connection context
  log_debug("[CLIENT_MAIN] About to call connection_context_cleanup()");
  connection_context_cleanup(&g_client_session.connection_ctx);
  log_debug("[CLIENT_MAIN] connection_context_cleanup() returned");

  // Cleanup session log buffer (used by splash screen in session_client_like)
  // NOTE: session_log_buffer_destroy() is already called in session_client_like_run()
  // during its cleanup phase, so we don't call it here to avoid double-destroy of mutex

  log_debug("[CLIENT_MAIN] ascii-chat client shutting down");

  // IMPORTANT: Stop worker threads and join them BEFORE memory report
  // atexit(shutdown_client) won't run if interrupted by SIGTERM, so call explicitly
  log_debug("[CLIENT_MAIN] About to call shutdown_client()");
  fflush(stderr);
  shutdown_client();
  log_debug("[CLIENT_MAIN] shutdown_client() returned");
  fflush(stderr);

  // Cleanup remaining shared subsystems (buffer domain, platform, etc.)
  log_debug("[CLIENT_MAIN] About to call asciichat_shared_destroy()");
  asciichat_shared_destroy();

  // Log final session statistics before exit
  // Note: Frame count is logged in protocol_stop_connection() if connection was established
  // This is a fallback in case the connection never started
  return session_result;
}

static void disconnect_server_for_bad_data(const char *format, ...) {
  va_list args;
  va_start(args, format);

  char message[BUFFER_SIZE_SMALL];
  safe_vsnprintf(message, sizeof(message), format, args);
  va_end(args);

  log_error("Server sent invalid data - disconnecting: %s", message);

  // Close the server connection
  server_connection_shutdown();
  server_connection_lost();
}

static char *decode_frame_data(const char *frame_data_ptr, size_t frame_data_len, bool is_compressed,
                               uint32_t original_size, uint32_t compressed_size) {
  return packet_decode_frame_data_malloc(frame_data_ptr, frame_data_len, is_compressed, original_size, compressed_size);
}

static void handle_ascii_frame_packet(const void *data, size_t len) {
  fflush(stdout);
  static int frame_count = 0;
  frame_count++;
  if (frame_count == 1) {
  }

  if (should_exit()) {
    return;
  }

  if (!data || len < sizeof(ascii_frame_packet_t)) {
    disconnect_server_for_bad_data("ASCII_FRAME payload too small: %zu (min %zu)", len, sizeof(ascii_frame_packet_t));
    return;
  }

  // FPS tracking for received ASCII frames using reusable tracker utility
  static fps_t fps_tracker = {0};
  static bool fps_tracker_initialized = false;

  // Initialize FPS tracker on first frame
  if (!fps_tracker_initialized) {
    int fps = GET_OPTION(fps);
    int expected_fps = fps > 0 ? ((fps > 144) ? 144 : fps) : DEFAULT_MAX_FPS;
    fps_init(&fps_tracker, expected_fps, "ASCII_RX");
    fps_tracker_initialized = true;
  }

  // Track this frame and detect lag
  fps_frame_ns(&fps_tracker, time_get_ns(), "ASCII frame");

  // Extract header from the packet
  ascii_frame_packet_t header;
  memcpy(&header, data, sizeof(ascii_frame_packet_t));

  // Convert from network byte order
  header.width = NET_TO_HOST_U32(header.width);
  header.height = NET_TO_HOST_U32(header.height);
  header.original_size = NET_TO_HOST_U32(header.original_size);
  header.compressed_size = NET_TO_HOST_U32(header.compressed_size);
  header.checksum = NET_TO_HOST_U32(header.checksum);
  header.flags = NET_TO_HOST_U32(header.flags);

  // Get the frame data (starts after the header)
  const char *frame_data_ptr = (const char *)data + sizeof(ascii_frame_packet_t);
  size_t frame_data_len = len - sizeof(ascii_frame_packet_t);

  // Decode frame data (handles both compressed and uncompressed)
  bool is_compressed = (header.flags & FRAME_FLAG_IS_COMPRESSED) && header.compressed_size > 0;
  char *frame_data =
      decode_frame_data(frame_data_ptr, frame_data_len, is_compressed, header.original_size, header.compressed_size);
  if (!frame_data) {
    return; // Error already logged by decode_frame_data
  }

  // Verify checksum
  uint32_t actual_crc = asciichat_crc32(frame_data, header.original_size);
  if (actual_crc != header.checksum) {
    log_error("Frame checksum mismatch: got 0x%x, expected 0x%x (size=%u, first_bytes=%02x%02x%02x%02x)", actual_crc,
              header.checksum, header.original_size, (unsigned char)frame_data[0], (unsigned char)frame_data[1],
              (unsigned char)frame_data[2], (unsigned char)frame_data[3]);

    // DEBUG: Try software CRC32 to compare
    uint32_t sw_crc = asciichat_crc32_sw(frame_data, header.original_size);
    log_error("Software CRC32: 0x%x (matches: %s)", sw_crc, (sw_crc == header.checksum) ? "YES" : "NO");

    SAFE_FREE(frame_data);
    return;
  }

  // Track frame dimension changes
  static uint32_t last_width = 0;
  static uint32_t last_height = 0;

  if (header.width > 0 && header.height > 0) {
    if (header.width != last_width || header.height != last_height) {
      last_width = header.width;
      last_height = header.height;
    }
  }

  // Handle snapshot mode timing
  if (GET_OPTION(snapshot_mode)) {
    static uint64_t first_frame_time_ns = 0;
    static bool first_frame_recorded = false;
    static int snapshot_frame_count = 0;

    snapshot_frame_count++;
    log_debug("Snapshot frame %d received", snapshot_frame_count);

    if (!first_frame_recorded) {
      first_frame_time_ns = time_get_ns();
      g_snapshot_first_frame_time_ns = first_frame_time_ns; // Also store globally for access from data_reception_thread
      log_info("[SNAPSHOT_INIT] SET g_snapshot_first_frame_time_ns=%llu first_frame_time_ns=%llu",
               (unsigned long long)g_snapshot_first_frame_time_ns, (unsigned long long)first_frame_time_ns);
      first_frame_recorded = true;

      if (GET_OPTION(snapshot_delay) == 0) {
        log_debug("Snapshot captured immediately (delay=0)!");
        signal_exit();
      } else {
        log_debug("Snapshot mode: first frame received, waiting %.2f seconds for webcam warmup...",
                  GET_OPTION(snapshot_delay));
      }
    } else {
      uint64_t current_time_ns = time_get_ns();
      double elapsed = time_ns_to_s(time_elapsed_ns(first_frame_time_ns, current_time_ns));
      double snapshot_delay = GET_OPTION(snapshot_delay);

      // Log every 0.5 seconds to debug timing
      static uint64_t last_debug_log_ns = 0;
      if (current_time_ns - last_debug_log_ns > 500 * 1000 * 1000) { // 500ms
        log_info("SNAPSHOT_DELAY_CHECK: elapsed=%.3f target=%.3f first_frame_ns=%llu current_ns=%llu", elapsed,
                 snapshot_delay, (unsigned long long)first_frame_time_ns, (unsigned long long)current_time_ns);
        last_debug_log_ns = current_time_ns;
      }

      if (elapsed >= snapshot_delay) {
        char duration_str[32];
        time_pretty((uint64_t)(elapsed * 1e9), -1, duration_str, sizeof(duration_str));
        log_info("🎬 SNAPSHOT TIMEOUT FIRED: Snapshot captured after %s! (target=%.3f) AT handle_ascii_frame_packet",
                 duration_str, snapshot_delay);
        signal_exit();
      }
    }
  }

  // Check if we need to clear console before rendering this frame
  // IMPORTANT: We track if this is the first frame to ensure proper initialization
  static bool first_frame_rendered = false;

  if (!first_frame_rendered) {
    // Always clear display and disable logging before rendering the first frame
    // This ensures clean ASCII display regardless of packet arrival order
    log_debug("First frame - clearing display and disabling terminal logging");
    log_set_terminal_output(false);
    display_full_reset();
    first_frame_rendered = true;
    g_server_state_initialized = true;        // Mark as initialized
    g_should_clear_before_next_frame = false; // Clear any pending clear request
    log_debug("CLIENT_DISPLAY: Display cleared, ready for ASCII frames");
  } else if (g_should_clear_before_next_frame) {
    // Subsequent clear request from server (e.g., after client list changes)
    log_debug("CLIENT_DISPLAY: Clearing display for layout change");
    log_set_terminal_output(false);
    display_full_reset();
    g_should_clear_before_next_frame = false;
  }

  // Safety check before rendering
  if (!frame_data || header.original_size == 0) {
    log_error("Invalid frame data for rendering: frame_data=%p, size=%u", frame_data, header.original_size);
    if (frame_data) {
      SAFE_FREE(frame_data);
    }
    return;
  }

  // The server paces frames using our negotiated desired_fps. Present received
  // frames without a second arrival-time limiter: network jitter can deliver a
  // correctly paced frame just before its nominal interval. The UI controller
  // coalesces pending frames if the terminal cannot keep up.

  // Frame counting now handled in session_display_write_ascii() which is called
  // by both client and host/discovery modes for consistent metrics

  // Render ASCII art frame (display_render_frame will apply effects like --matrix)
  log_debug("🎬 CALLING_DISPLAY_RENDER: frame_data=%p len=%zu, calling display_render_frame()", frame_data,
            strlen(frame_data));
  display_render_frame(frame_data);
  log_debug("🎬 DISPLAY_RENDER_RETURNED: frame was rendered");

  SAFE_FREE(frame_data);
}

static void handle_audio_packet(const void *data, size_t len) {
  if (!data || len == 0) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Invalid audio packet data");
    return;
  }

  if (!GET_OPTION(audio_enabled)) {
    log_warn_every(NS_PER_MS_INT, "Received audio packet but audio is disabled");
    return;
  }

  int num_samples = (int)(len / sizeof(float));
  if (num_samples > AUDIO_SAMPLES_PER_PACKET) {
    log_warn("Audio packet too large: %d samples", num_samples);
    return;
  }

  // Copy data to properly aligned buffer to avoid UndefinedBehaviorSanitizer errors
  float samples[AUDIO_SAMPLES_PER_PACKET];
  SAFE_MEMCPY(samples, sizeof(samples), data, len);

  // Process audio through audio subsystem
  audio_process_received_samples(samples, num_samples);

#ifdef DEBUG_AUDIO
  log_debug("Processed %d audio samples", num_samples);
#endif
}

static void handle_audio_opus_packet(const void *data, size_t len) {
  START_TIMER("audio_packet_total");

  // Validate parameters
  if (!data || len == 0) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Invalid audio opus packet: data=%p, len=%zu", data, len);
    return;
  }

  if (!GET_OPTION(audio_enabled)) {
    log_warn_every(NS_PER_MS_INT, "Received opus audio packet but audio is disabled");
    return;
  }

  // Data is raw Opus-encoded frame (no header parsing needed)
  const uint8_t *opus_data = (const uint8_t *)data;

  // Opus max frame size is 2880 samples (120ms @ 48kHz)
  float samples[2880];

  START_TIMER("opus_decode");
  int decoded_samples = audio_decode_opus(opus_data, len, samples, 2880);
  double decode_ns = STOP_TIMER("opus_decode");

  if (decoded_samples <= 0) {
    log_warn("Failed to decode Opus audio packet, decoded=%d", decoded_samples);
    return;
  }

  // Track received packet for analysis
  if (GET_OPTION(audio_analysis_enabled)) {
    audio_analysis_track_received_packet(len);
  }

  // Process decoded audio through audio subsystem
  START_TIMER("process_samples");
  audio_process_received_samples(samples, decoded_samples);
  double process_ns = STOP_TIMER("process_samples");

  double total_ns = STOP_TIMER("audio_packet_total");

  static int timing_count = 0;
  if (++timing_count % 100 == 0) {
    char decode_str[32], process_str[32], total_str[32];
    time_pretty((uint64_t)decode_ns, -1, decode_str, sizeof(decode_str));
    time_pretty((uint64_t)process_ns, -1, process_str, sizeof(process_str));
    time_pretty((uint64_t)total_ns, -1, total_str, sizeof(total_str));
    log_debug("Audio packet timing #%d: decode=%s, process=%s, total=%s", timing_count, decode_str, process_str,
              total_str);
  }

  log_debug_every(LOG_RATE_DEFAULT, "Processed Opus audio: %d decoded samples from %zu byte packet", decoded_samples,
                  len);
}

static void handle_audio_opus_batch_packet(const void *data, size_t len) {
  // Validate parameters
  if (!data || len == 0) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Invalid opus batch packet: data=%p, len=%zu", data, len);
    return;
  }

  // DEBUG: Log first 12 bytes of received Opus batch header
  if (len >= 12) {
    const uint8_t *bytes = (const uint8_t *)data;
    log_info("OPUS_BATCH_RECV_DEBUG: first_bytes=[%02x %02x %02x %02x][%02x %02x %02x %02x][%02x %02x %02x %02x]",
             bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7], bytes[8], bytes[9],
             bytes[10], bytes[11]);

    // Parse header manually to check values
    uint32_t sr, fd, fc;
    memcpy(&sr, bytes, 4);
    memcpy(&fd, bytes + 4, 4);
    memcpy(&fc, bytes + 8, 4);
    log_info("OPUS_BATCH_RECV_PARSED: sample_rate(net)=0x%08x frame_duration(net)=0x%08x frame_count(net)=0x%08x", sr,
             fd, fc);
    log_info("OPUS_BATCH_RECV_PARSED: sample_rate=%u frame_duration=%u frame_count=%u", NET_TO_HOST_U32(sr),
             NET_TO_HOST_U32(fd), NET_TO_HOST_U32(fc));
  }

  if (!GET_OPTION(audio_enabled)) {
    log_warn_every(NS_PER_MS_INT, "Received opus batch packet but audio is disabled");
    return;
  }

  // Parse batch header using av_receive_audio_opus_batch() for consistency
  const uint8_t *opus_data = NULL;
  size_t opus_size = 0;
  const uint16_t *frame_sizes = NULL;
  int sample_rate = 0;
  int frame_duration = 0;
  int frame_count = 0;

  asciichat_error_t result = packet_parse_opus_batch(data, len, &opus_data, &opus_size, &frame_sizes, &sample_rate,
                                                     &frame_duration, &frame_count);

  if (result != ASCIICHAT_OK) {
    log_warn("Failed to parse Opus batch packet");
    return;
  }

  if (frame_count <= 0 || frame_count > 256 || opus_size == 0) {
    log_warn("Invalid Opus batch: frame_count=%d, opus_size=%zu", frame_count, opus_size);
    return;
  }

  // Calculate samples per frame
  int samples_per_frame = (sample_rate * frame_duration) / 1000;
  if (samples_per_frame <= 0 || samples_per_frame > 2880) {
    log_warn("Invalid Opus frame parameters: samples_per_frame=%d", samples_per_frame);
    return;
  }

  // Allocate buffer for all decoded samples
  size_t max_decoded_samples = (size_t)samples_per_frame * (size_t)frame_count;
  float *all_samples = SAFE_MALLOC(max_decoded_samples * sizeof(float), float *);
  if (!all_samples) {
    SET_ERRNO(ERROR_MEMORY, "Failed to allocate memory for Opus batch decoding");
    return;
  }

  // Decode each Opus frame using frame_sizes array
  int total_decoded_samples = 0;
  size_t opus_offset = 0;

  for (int i = 0; i < frame_count; i++) {
    // Get frame size (convert from network byte order)
    size_t frame_size = (size_t)NET_TO_HOST_U16(frame_sizes[i]);

    if (opus_offset + frame_size > opus_size) {
      log_warn("Opus batch truncated at frame %d (offset=%zu, frame_size=%zu, total=%zu)", i, opus_offset, frame_size,
               opus_size);
      break;
    }

    // Decode frame through audio pipeline
    float *frame_buffer = all_samples + total_decoded_samples;
    int remaining_space = (int)(max_decoded_samples - (size_t)total_decoded_samples);
    int decoded = audio_decode_opus(opus_data + opus_offset, frame_size, frame_buffer, remaining_space);

    if (decoded <= 0) {
      log_warn("Concealing invalid Opus frame %d in batch", i);
      decoded = audio_decode_opus(NULL, 0, frame_buffer, samples_per_frame);
      if (decoded <= 0)
        break;
    }

    total_decoded_samples += decoded;
    opus_offset += frame_size;
  }

  if (total_decoded_samples > 0) {
    // Track received packet for analysis
    if (GET_OPTION(audio_analysis_enabled)) {
      audio_analysis_track_received_packet(len);
    }

    // Process decoded audio through audio subsystem
    audio_process_received_samples(all_samples, total_decoded_samples);

    log_debug_every(LOG_RATE_DEFAULT, "Processed Opus batch: %d decoded samples from %d frames", total_decoded_samples,
                    frame_count);
  }

  // Clean up
  SAFE_FREE(all_samples);
}

static bool handle_error_message_packet(const void *data, size_t len) {
  asciichat_error_t remote_error = ASCIICHAT_OK;
  char message[MAX_ERROR_MESSAGE_LENGTH + 1] = {0};

  asciichat_error_t parse_result = packet_parse_error_message(data, len, &remote_error, message, sizeof(message), NULL);
  if (parse_result != ASCIICHAT_OK) {
    log_error("Failed to parse error packet from server: %s", asciichat_error_string(parse_result));
    return false;
  }

  log_error("Server reported error %d (%s): %s", remote_error, asciichat_error_string(remote_error), message);
  remote_error = network_error_public_code(remote_error);
  asciichat_errno_scope_t notification = asciichat_errno_scope_begin();
  SET_ERRNO(remote_error, "Server notification: %s", asciichat_error_string(remote_error));
  if (network_error_action(remote_error) == NETWORK_ERROR_CONTINUE) {
    log_warn("Server audio unavailable; continuing video");
    asciichat_errno_scope_end(notification, ASCIICHAT_ERRNO_HANDLED);
    return true;
  }
  server_connection_set_remote_error(remote_error);
  if (network_error_action(remote_error) == NETWORK_ERROR_STOP) {
    asciichat_errno_request_exit(remote_error);
    signal_exit();
  }
  log_warn("Server rejected this connection; closing it");
  asciichat_errno_scope_end(notification, ASCIICHAT_ERRNO_HANDLED);
  server_connection_shutdown();
  server_connection_lost();
  return true;
}

static void handle_remote_log_packet(const void *data, size_t len) {
  log_level_t remote_level = LOG_INFO;
  remote_log_direction_t direction = REMOTE_LOG_DIRECTION_UNKNOWN;
  uint16_t flags = 0;
  char message[MAX_REMOTE_LOG_MESSAGE_LENGTH + 1] = {0};

  asciichat_error_t parse_result =
      packet_parse_remote_log(data, len, &remote_level, &direction, &flags, message, sizeof(message), NULL);
  if (parse_result != ASCIICHAT_OK) {
    log_error("Failed to parse remote log packet from server: %s", asciichat_error_string(parse_result));
    return;
  }

  if (direction != REMOTE_LOG_DIRECTION_SERVER_TO_CLIENT) {
    log_error("Remote log packet direction mismatch (direction=%u)", direction);
    return;
  }

  bool truncated = (flags & REMOTE_LOG_FLAG_TRUNCATED) != 0;

  if (truncated) {
    log_msg(remote_level, __FILE__, __LINE__, __func__, "[REMOTE SERVER] %s [message truncated]", message);
  } else {
    log_msg(remote_level, __FILE__, __LINE__, __func__, "[REMOTE SERVER] %s", message);
  }
}

static void handle_server_state_packet(const void *data, size_t len) {
  if (!data || len != sizeof(server_state_packet_t)) {
    log_error("Invalid server state packet size: %zu", len);
    return;
  }

  const server_state_packet_t *state = (const server_state_packet_t *)data;

  // Convert from network byte order
  uint32_t active_count = NET_TO_HOST_U32(state->active_client_count);

  // Check if connected count changed - if so, set flag to clear console before next frame
  if (g_server_state_initialized) {
    if (g_last_active_count != active_count) {
      log_debug("Active client count changed from %u to %u - will clear console before next frame", g_last_active_count,
                active_count);
      g_should_clear_before_next_frame = true;
    }
  } else {
    // First state packet received
    g_server_state_initialized = true;
    // Clear terminal before the very first frame
    g_should_clear_before_next_frame = true;
  }

  g_last_active_count = active_count;
}

const acip_client_callbacks_t *protocol_get_acip_callbacks() {
  return &g_acip_client_callbacks;
}

static void *data_reception_thread_func(void *arg) {
  (void)arg;

  log_warn("[FRAME_RECV_LOOP] 🔄 THREAD_STARTED: Data reception thread active, callbacks initialized");

#ifdef DEBUG_THREADS
  log_debug("[FRAME_RECV_LOOP] Thread lifecycle tracking enabled");
#endif

  int packet_count = 0;
  while (!should_exit() && server_connection_is_active()) {
    // Main loop: receive and process packets while connection is active
    // When connection becomes inactive or shutdown is requested, thread exits cleanly

    // Debug: periodically check loop condition
    if (packet_count % 50 == 0) {
      bool exit_flag = should_exit();
      bool conn_active = server_connection_is_active();
      if (packet_count > 0) {
        log_debug("[FRAME_RECV_LOOP] DEBUG: packet_count=%d, should_exit=%d, server_connection_is_active=%d",
                  packet_count, exit_flag, conn_active);
      }
    }

    // Receive and dispatch packet using ACIP transport API
    // This combines packet reception, decryption, parsing, handler dispatch, and cleanup
    acip_transport_t *transport = server_connection_get_transport();
    if (packet_count < 3) {
    }
    if (!transport) {
      log_error("[FRAME_RECV_LOOP] ❌ NO_TRANSPORT: connection lost, transport not available");
      server_connection_lost();
      break;
    }

    log_debug("[FRAME_RECV_LOOP] 📥 RECV_WAITING: awaiting packet #%d from server (transport ready)", packet_count + 1);

    if (packet_count == 0) {
    }
    // Use short 16ms timeout to allow rendering at 60 FPS
    // Instead of blocking indefinitely waiting for a packet,
    // we timeout quickly so main thread can continue rendering
    asciichat_errno_scope_t receive_scope = asciichat_errno_scope_begin();
    asciichat_error_t acip_result = acip_client_receive_and_dispatch(transport, &g_acip_client_callbacks);
    if (packet_count == 0) {
    }

    if (acip_result == ASCIICHAT_OK) {
      ASSERT_NO_ERRNO_SINCE(receive_scope);
      asciichat_errno_scope_end(receive_scope, ASCIICHAT_ERRNO_HANDLED);
      packet_count++;
      log_debug("[FRAME_RECV_LOOP] ✅ PACKET_%d_DISPATCHED: callbacks processed successfully", packet_count);
    } else if (acip_result == ERROR_NETWORK_TIMEOUT) {
      asciichat_errno_scope_end(receive_scope, ASCIICHAT_ERRNO_DISMISSED);
      // Network timeouts are expected - socket may have no data available
      // Continue looping to allow snapshot timer to expire
      log_debug("[FRAME_RECV_LOOP] ⏱️  TIMEOUT: No data available, retrying (packets received: %d)", packet_count);
      continue;
    } else if (acip_result == ERROR_NETWORK_INCOMPLETE &&
               HAS_ERRNO_CODE_SINCE(receive_scope, ERROR_NETWORK_INCOMPLETE)) {
      asciichat_errno_scope_end(receive_scope, ASCIICHAT_ERRNO_HANDLED);
      continue;
    } else {
      // Handle receive/dispatch errors - ALWAYS exit on network errors
      // NOTE: Log to file even if terminal logging is disabled (important for debugging)
      log_warn("[FRAME_RECV_LOOP] ⚠️  RECV_ERROR_BEFORE_SNAPSHOT_CHECK: acip_result=%d: %s (after %d packets received)",
               acip_result, asciichat_error_string(acip_result), packet_count);

      // Before breaking due to error, check if snapshot_delay timer has fired in snapshot mode
      bool should_break_now = true;
      if (GET_OPTION(snapshot_mode) && g_snapshot_first_frame_time_ns > 0) {
        uint64_t current_time_ns = time_get_ns();
        double elapsed = time_ns_to_s(time_elapsed_ns(g_snapshot_first_frame_time_ns, current_time_ns));
        double snapshot_delay = GET_OPTION(snapshot_delay);

        if (elapsed >= snapshot_delay) {
          char duration_str[32];
          time_pretty((uint64_t)(elapsed * 1e9), -1, duration_str, sizeof(duration_str));
          log_info("🎬 SNAPSHOT TIMEOUT FIRED (ON_ERROR): Snapshot captured after %s! (target=%.3f)", duration_str,
                   snapshot_delay);
          signal_exit();
          should_break_now = false; // Don't disconnect, let normal shutdown handle it
        }
      }

      if (should_break_now) {
        // Network errors (ERROR_NETWORK, ERROR_NETWORK_PROTOCOL, etc) always disconnect
        if (acip_result == ERROR_NETWORK || acip_result == ERROR_NETWORK_PROTOCOL) {
          log_warn("[FRAME_RECV_LOOP] ⚠️  NETWORK_ERROR: Server disconnected after %d packets, exiting loop",
                   packet_count);
          server_connection_lost();
          break;
        }

        // Check errno context for additional error details
        if (HAS_ERRNO_CODE_SINCE(receive_scope, ERROR_CRYPTO)) {
          NOTICE(DANGER, "ENCRYPTION POLICY VIOLATION", "Server violated the encryption policy; closing connection.");
          LOG_ERRNO_IF_SET("Server violated the encryption policy");
          asciichat_errno_request_exit(ERROR_CRYPTO);
          signal_exit();
          break;
        }

        // Other errors - still disconnect to prevent infinite loop
        log_error("[FRAME_RECV_LOOP] ❌ RECV_FAILED: packet #%d failed after %d packets, disconnecting",
                  packet_count + 1, packet_count);
        server_connection_lost();
        break;
      }
    }
  }

  // Log why the loop exited (DEBUG to avoid affecting timing)
  bool final_exit_flag = should_exit();
  bool final_conn_active = server_connection_is_active();
  log_debug("[FRAME_RECV_LOOP] ⏹️  LOOP_EXIT: should_exit=%d server_connection_is_active=%d (packets_received=%d)",
            final_exit_flag, final_conn_active, packet_count);

  // Before exiting due to connection loss, check if snapshot_delay timer has fired
  // If it has, take the snapshot and exit cleanly instead of abandoning the snapshot
  if (GET_OPTION(snapshot_mode)) {
    log_debug("[FRAME_RECV_LOOP] ⏰ SNAPSHOT_CHECK_ON_EXIT: snapshot_mode enabled, g_snapshot_first_frame_time_ns=%llu",
              (unsigned long long)g_snapshot_first_frame_time_ns);

    if (g_snapshot_first_frame_time_ns > 0) {
      uint64_t current_time_ns = time_get_ns();
      double elapsed = time_ns_to_s(time_elapsed_ns(g_snapshot_first_frame_time_ns, current_time_ns));
      double snapshot_delay = GET_OPTION(snapshot_delay);

      log_debug("[FRAME_RECV_LOOP] ⏰ SNAPSHOT_CHECK_DETAILS: elapsed=%.3f target=%.3f", elapsed, snapshot_delay);

      if (elapsed >= snapshot_delay) {
        char duration_str[32];
        time_pretty((uint64_t)(elapsed * 1e9), -1, duration_str, sizeof(duration_str));
        log_info("🎬 SNAPSHOT TIMEOUT FIRED (ON_CONNECTION_LOSS): Snapshot captured after %s! (target=%.3f)",
                 duration_str, snapshot_delay);
        signal_exit();
      }
    }
  }

  log_warn("[FRAME_RECV_LOOP] 🔴 THREAD_EXITING: received %d packets total, connection inactive or shutdown requested",
           packet_count);

#ifdef DEBUG_THREADS
  log_debug("[FRAME_RECV_LOOP] Thread lifecycle tracking - exit");
#endif

  atomic_store_bool(&g_data_thread_exited, true);

  // The platform thread wrapper unregisters pending errors on return.
  log_debug("[FRAME_RECV_LOOP] Thread terminating");
  return NULL;
}

int protocol_start_connection() {
  log_warn("[FRAME_RECV_INIT] 🟢 PROTOCOL_START: Starting client protocol initialization");

  // Register protocol atomics with named debug registry
  static bool protocol_atomics_registered = false;
  if (!protocol_atomics_registered) {
    NAMED_REGISTER_ATOMIC(&g_data_thread_exited, "protocol_data_reception_thread_exit_confirmation", NULL);
    NAMED_REGISTER_ATOMIC(&g_frames_rendered, "protocol_frames_successfully_rendered", NULL);
    protocol_atomics_registered = true;
  }

  // Reset protocol state for new connection
  g_server_state_initialized = false;
  g_last_active_count = 0;
  g_should_clear_before_next_frame = false;

  log_info("[FRAME_RECV_INIT] ✅ STATE_RESET: server_initialized=false, active_count=0, clear_flag=false");

  // Reset display state for new connection
  display_reset_for_new_connection();

  // Check if we're on a WebSocket transport (crypto handshake is async via ACIP callbacks)
  // For WS/WSS, we must start data_reception FIRST so it can handle the crypto handshake,
  // then wait for crypto to complete before sending CAPABILITIES/STREAM_START.
  // For TCP, crypto is already done synchronously before this function is called.
  acip_transport_t *init_transport = server_connection_get_transport();
  bool is_websocket = init_transport && acip_transport_get_type(init_transport) == ACIP_TRANSPORT_WEBSOCKET;

  if (is_websocket) {
    // WebSocket: start data reception thread FIRST to handle async crypto handshake.
    // TCP does crypto synchronously in connection_attempt.c, but WS crypto flows
    // asynchronously via ACIP callbacks in the data_reception thread.
    log_debug("[FRAME_RECV_INIT] WS: Starting data_reception for async crypto handshake");
    atomic_store_bool(&g_data_thread_exited, false);
    if (thread_pool_spawn(g_client_worker_pool, data_reception_thread_func, NULL, 1, "data_reception") !=
        ASCIICHAT_OK) {
      log_error("[FRAME_RECV_INIT] Failed to start data reception thread");
      LOG_ERRNO_IF_SET("Data reception thread creation failed");
      return -1;
    }
    log_debug("[FRAME_RECV_INIT] WS: Data thread spawned, waiting for crypto handshake");


  }

  // Send CLIENT_CAPABILITIES packet (after crypto is ready for both TCP and WS)
  // Server expects this as the first packet after crypto handshake
  log_debug("[FRAME_RECV_INIT] Sending CLIENT_CAPABILITIES (terminal size)");
  asciichat_error_t cap_result = threaded_send_terminal_size_with_auto_detect((int)terminal_get_effective_width(),
                                                                              (int)terminal_get_effective_height());
  if (cap_result != ASCIICHAT_OK) {
    log_error("[FRAME_RECV_INIT] Failed to send terminal size capabilities");
    return -1;
  }

  // Send STREAM_START packet with combined stream types
  uint32_t stream_types = STREAM_TYPE_VIDEO; // Always have video
  if (GET_OPTION(audio_enabled)) {
    stream_types |= STREAM_TYPE_AUDIO; // Add audio if enabled
  }
  log_debug("[FRAME_RECV_INIT] Sending STREAM_START: types=0x%x (video%s)", stream_types,
            (stream_types & STREAM_TYPE_AUDIO) ? "+audio" : "");
  asciichat_error_t stream_result = threaded_send_stream_start_packet(stream_types);
  if (stream_result != ASCIICHAT_OK) {
    log_error("[FRAME_RECV_INIT] Failed to send stream start");
    return -1;
  }

  // Start data reception thread (TCP only - WS already started it above for crypto)
  if (!is_websocket) {
    log_debug("[FRAME_RECV_INIT] TCP: Starting data reception thread");
    atomic_store_bool(&g_data_thread_exited, false);
    if (thread_pool_spawn(g_client_worker_pool, data_reception_thread_func, NULL, 1, "data_reception") !=
        ASCIICHAT_OK) {
      log_error("[FRAME_RECV_INIT] Failed to start data reception thread");
      LOG_ERRNO_IF_SET("Data reception thread creation failed");
      return -1;
    }
  }

  // Start webcam capture thread
  log_debug("Starting webcam capture thread...");
  if (capture_start_thread() != 0) {
    log_error("Failed to start webcam capture thread");
    return -1;
  }
  log_debug("Webcam capture thread started successfully");

  // Start local media audio only after the connection succeeds. Starting the
  // worker during client initialization would consume file audio while dialing.
  audio_context_t *audio_context = audio_get_context();
  if (audio_context && audio_context->initialized) {
    audio_context->capture_media_source = capture_get_media_source();
    if (audio_start_duplex(audio_context) != ASCIICHAT_OK) {
      log_error("Failed to start full-duplex audio");
      return -1;
    }
  }

  // Initialize audio sender thread BEFORE starting audio capture
  // This ensures sender is ready when capture thread starts queueing packets
  // Must happen after connection succeeds to prevent deadlock if connection fails
  audio_sender_init();

  // Start audio capture thread if audio is enabled
  log_debug("Starting audio capture thread...");
  if (audio_start_thread() != 0) {
    log_error("Failed to start audio capture thread");
    return -1;
  }
  log_debug("Audio capture thread started successfully (or skipped if audio disabled)");

  // Start keepalive/ping thread to prevent server timeout
  log_debug("Starting keepalive/ping thread...");
  if (keepalive_start_thread() != 0) {
    log_error("Failed to start keepalive/ping thread");
    return -1;
  }
  log_debug("Keepalive/ping thread started successfully");

  g_data_thread_created = true;
  return 0;
}

void protocol_stop_connection() {
  // Log final frame count before shutting down (always log for diagnostic purposes)
  int final_frame_count = atomic_load_u64(&g_frames_rendered);
  log_info("📊 CLIENT SESSION STATS: %d unique frames rendered during connection", final_frame_count);

  log_debug("[PROTOCOL_STOP] 1. Starting protocol_stop_connection");

  // Stop snapshot capture before flushing, then use the shared connection shutdown
  // to wake and join the audio sender and reception threads.
  if (GET_OPTION(snapshot_mode)) {
    log_debug("[PROTOCOL_STOP] Snapshot mode: stopping capture thread before flushing H.265 encoder");
    // The capture thread owns the encoder while it is producing frames. Join it
    // before flushing so shutdown cannot destroy encoder state underneath an
    // in-flight encode operation.
    capture_stop_thread();

    // Flush the encoder to output any buffered frames before exiting
    if (g_video_encoder) {
      // Allocate buffer large enough for worst-case H.265 encoded frame
      // Using 320x240 (typical test resolution) * 2x multiplier + header
      size_t flush_buf_size = 5 + (320 * 240 * 2);
      uint8_t *flush_buf = SAFE_MALLOC(flush_buf_size, uint8_t *);
      size_t flush_size = flush_buf_size;
      asciichat_errno_scope_t flush_scope = asciichat_errno_scope_begin();
      asciichat_error_t flush_result = h265_encoder_flush(g_video_encoder, flush_buf, &flush_size);
      if (flush_result != ASCIICHAT_OK) {
        // The snapshot is already delivered; failure to flush optional buffered
        // video (including an unavailable HEVC encoder) cannot undo it.
        asciichat_errno_scope_end(flush_scope, ASCIICHAT_ERRNO_DISMISSED);
      } else {
        ASSERT_NO_ERRNO_SINCE(flush_scope);
        asciichat_errno_scope_end(flush_scope, ASCIICHAT_ERRNO_HANDLED);
      }
      if (flush_result == ASCIICHAT_OK && flush_size > 0) {
        log_info("[PROTOCOL_STOP] Flushed H.265 encoder: got %zu bytes of buffered frames", flush_size);
        // Send the flushed frame if we got one
        acip_transport_t *transport = server_connection_get_transport();
        if (transport && server_connection_is_active()) {
          uint32_t width = 320, height = 240; // TODO: track actual dimensions
          log_debug("[PROTOCOL_STOP] Sending flushed frame: %ux%u, %zu bytes", width, height, flush_size);
        }
      }
      SAFE_FREE(flush_buf);
    }
  }

  // Don't call signal_exit() here - that's for global shutdown only!
  // We just want to stop threads for this connection, not exit the entire client

  // Shutdown the socket FIRST to interrupt any blocking network operations in worker threads
  // This must happen BEFORE audio_stop_thread() so audio sender thread unblocks from network send
  log_debug("[PROTOCOL_STOP] 2. About to call server_connection_shutdown");
  server_connection_shutdown();
  log_debug("[PROTOCOL_STOP] 3. server_connection_shutdown() returned");

  // Signal audio sender thread to exit
  // Must happen after socket shutdown so any blocked network calls fail
  // Snapshot recordings also transmit audio and must stop the sender.
  log_debug("[PROTOCOL_STOP] 4. About to call audio_stop_thread");
  audio_stop_thread();
  log_debug("[PROTOCOL_STOP] 5. audio_stop_thread() returned");

  // Early return if data thread was never created (e.g., mirror mode)
  // In mirror mode, we only need to stop the audio sender (done above)
  if (!g_data_thread_created) {
    log_debug("[PROTOCOL_STOP] 6. Data thread not created, returning");
    return;
  }

  // Stop keepalive/ping thread - it checks connection status and will exit
  log_debug("[PROTOCOL_STOP] 7. About to call keepalive_stop_thread");
  keepalive_stop_thread();
  log_debug("[PROTOCOL_STOP] 8. keepalive_stop_thread() returned");

  // Stop webcam capture thread
  log_debug("[PROTOCOL_STOP] 9. About to call capture_stop_thread");
  capture_stop_thread();
  log_debug("[PROTOCOL_STOP] 10. capture_stop_thread() returned");

  // Signal the audio sender while its queue synchronization objects are still valid.
  audio_sender_cleanup();

  // Wait for data reception thread to exit gracefully
  log_debug("[PROTOCOL_STOP] 11. Waiting for data thread to exit");
  // Thread checks should_exit() every read cycle (typically <1-5ms), so timeout can be much shorter
  int wait_count = 0;
  while (wait_count < 5 && !atomic_load_bool(&g_data_thread_exited)) {
    platform_sleep_us(10 * US_PER_MS_INT); // 10ms * 5 = 50ms max wait
    wait_count++;
  }

  if (!atomic_load_bool(&g_data_thread_exited)) {
    log_warn("Data thread not responding after 50ms - will be joined by thread pool");
  }
  log_debug("[PROTOCOL_STOP] 12. Data thread wait complete");

  // Join all threads in the client worker pool (in stop_id order)
  // This handles the data reception thread and (eventually) all other worker threads
  log_debug("[PROTOCOL_STOP] 13. About to call thread_pool_stop_all");
  if (g_client_worker_pool) {
    asciichat_error_t result = thread_pool_stop_all(g_client_worker_pool);
    if (result != ASCIICHAT_OK) {
      log_error("Failed to stop client worker threads");
      LOG_ERRNO_IF_SET("Thread pool stop failed");
    }
  }
  audio_sender_finalize();
  log_debug("[PROTOCOL_STOP] 14. thread_pool_stop_all() returned");

  g_data_thread_created = false;

#ifdef DEBUG_THREADS
  log_debug("Data reception thread stopped and joined by thread pool");
#endif
  log_debug("[PROTOCOL_STOP] 15. protocol_stop_connection complete");
}

bool protocol_connection_lost() {
  return atomic_load_bool(&g_data_thread_exited) || server_connection_is_lost();
}

static void acip_on_ascii_frame(const ascii_frame_packet_t *header, const void *frame_data, size_t data_len,
                                void *ctx) {
  (void)ctx;

  log_info("[FRAME_RECV_CALLBACK] 🎬 FRAME_RECEIVED: width=%u, height=%u, data_len=%zu bytes, flags=0x%x",
           header->width, header->height, data_len, header->flags);

  // Reconstruct full packet for existing handler (header + data)
  // IMPORTANT: header is already in HOST byte order from ACIP layer,
  // but handle_ascii_frame_packet() expects NETWORK byte order and does conversion.
  // So we need to convert back to network order before passing.
  size_t total_len = sizeof(*header) + data_len;
  log_debug("[FRAME_RECV_CALLBACK] 📦 FRAME_SIZE: header=%zu + data=%zu = total=%zu", sizeof(*header), data_len,
            total_len);

  uint8_t *packet = SAFE_MALLOC(total_len, uint8_t *);
  if (!packet) {
    log_error("[FRAME_RECV_CALLBACK] ❌ ALLOC_FAILED: cannot allocate %zu bytes for frame", total_len);
    return;
  }

  log_debug("[FRAME_RECV_CALLBACK] ✅ BUFFER_ALLOCATED: packet=%p, capacity=%zu", (void *)packet, total_len);

  // Convert header fields back to network byte order for handle_ascii_frame_packet()
  ascii_frame_packet_t net_header = *header;
  net_header.width = HOST_TO_NET_U32(header->width);
  net_header.height = HOST_TO_NET_U32(header->height);
  net_header.original_size = HOST_TO_NET_U32(header->original_size);
  net_header.compressed_size = HOST_TO_NET_U32(header->compressed_size);
  net_header.checksum = HOST_TO_NET_U32(header->checksum);
  net_header.flags = HOST_TO_NET_U32(header->flags);

  log_debug("[FRAME_RECV_CALLBACK] 🔄 BYTE_ORDER_CONVERSION: converting header to network byte order");

  memcpy(packet, &net_header, sizeof(net_header));
  memcpy(packet + sizeof(net_header), frame_data, data_len);

  log_info("[FRAME_RECV_CALLBACK] 📥 FRAME_DISPATCH: calling handle_ascii_frame_packet() with %zu bytes", total_len);
  handle_ascii_frame_packet(packet, total_len);
  log_info("[FRAME_RECV_CALLBACK] ✅ FRAME_DISPATCH_COMPLETE: frame processing finished");

  SAFE_FREE(packet);
  log_debug("[FRAME_RECV_CALLBACK] 🗑️  BUFFER_FREED: frame callback cleanup complete");
}

static void acip_on_audio_batch(const audio_batch_packet_t *header, const float *samples, size_t num_samples,
                                void *ctx) {
  (void)ctx;
  (void)header;

  if (!GET_OPTION(audio_enabled)) {
    return;
  }

  // Process samples directly (already dequantized by ACIP handler)
  audio_process_received_samples((float *)samples, (int)num_samples);

  if (GET_OPTION(audio_analysis_enabled)) {
    // Approximate packet size for analysis
    size_t approx_size = sizeof(*header) + (num_samples * sizeof(uint32_t));
    audio_analysis_track_received_packet(approx_size);
  }

  log_debug_every(LOG_RATE_DEFAULT, "Processed audio batch: %zu samples from server", num_samples);
}

