asciichat_error_t threaded_send_terminal_size_with_auto_detect(unsigned short width, unsigned short height) {
  // Log the dimensions being sent to server (helps debug dimension mismatch issues)
  log_debug("Sending terminal size to server: %ux%u (auto_width=%d, auto_height=%d)", width, height,
            GET_OPTION(auto_width), GET_OPTION(auto_height));

  // Connection and transport availability is checked by threaded_send_packet()

  // Build terminal capabilities packet locally
  // Detect terminal capabilities automatically
  terminal_capabilities_t caps = detect_terminal_capabilities();

  // Set wants_padding based on snapshot mode and TTY status
  // Disable padding when:
  // - In snapshot mode (one frame and exit)
  // - When stdout is not a TTY (piped/redirected output)
  // Enable padding for interactive terminal sessions
  bool is_snapshot_mode = GET_OPTION(snapshot_mode);
  bool is_interactive = terminal_is_interactive();
  caps.wants_padding = is_interactive && !is_snapshot_mode;

  log_debug("Client capabilities: wants_padding=%d (snapshot=%d, interactive=%d, stdin_tty=%d, stdout_tty=%d)",
            caps.wants_padding, is_snapshot_mode, is_interactive, terminal_is_stdin_tty(), terminal_is_stdout_tty());

  // Apply user's color mode override
  caps = apply_color_mode_override(caps);

  // Check if detection was reliable, use fallback only for auto-detection
  if (!caps.detection_reliable && GET_OPTION(color_mode) == COLOR_MODE_AUTO) {
    log_warn("Terminal capability detection not reliable, using fallback");
    SAFE_MEMSET(&caps, sizeof(caps), 0, sizeof(caps));
    caps.color_level = TERM_COLOR_NONE;
    caps.color_count = 2;
    caps.capabilities = 0;
    SAFE_STRNCPY(caps.term_type, "unknown", sizeof(caps.term_type));
    SAFE_STRNCPY(caps.colorterm, "", sizeof(caps.colorterm));
    caps.detection_reliable = 0;
    // Preserve wants_padding even in fallback mode
    caps.wants_padding = is_interactive && !is_snapshot_mode;
  }

  // Convert to network packet format with proper byte order
  terminal_capabilities_packet_t net_packet;
  net_packet.capabilities = HOST_TO_NET_U32(caps.capabilities);
  net_packet.color_level = HOST_TO_NET_U32(caps.color_level);
  net_packet.color_count = HOST_TO_NET_U32(caps.color_count);
  net_packet.render_mode = HOST_TO_NET_U32(caps.render_mode);
  net_packet.width = HOST_TO_NET_U16(width);
  net_packet.height = HOST_TO_NET_U16(height);
  net_packet.palette_type = HOST_TO_NET_U32(GET_OPTION(palette_type));
  net_packet.utf8_support = HOST_TO_NET_U32(caps.utf8_support ? 1 : 0);

  const options_t *opts = options_get();
  if (GET_OPTION(palette_type) == PALETTE_CUSTOM && GET_OPTION(palette_custom_set)) {
    const char *palette_custom = opts && opts->palette_custom_set ? opts->palette_custom : "";
    SAFE_STRNCPY(net_packet.palette_custom, palette_custom, sizeof(net_packet.palette_custom));
    net_packet.palette_custom[sizeof(net_packet.palette_custom) - 1] = '\0';
  } else {
    SAFE_MEMSET(net_packet.palette_custom, sizeof(net_packet.palette_custom), 0, sizeof(net_packet.palette_custom));
  }

  // Set desired FPS
  int fps = GET_OPTION(fps);
  if (fps > 0) {
    net_packet.desired_fps = (uint8_t)(fps > 144 ? 144 : fps);
  } else {
    net_packet.desired_fps = caps.desired_fps;
  }

  if (net_packet.desired_fps == 0) {
    net_packet.desired_fps = DEFAULT_MAX_FPS;
  }

  SAFE_STRNCPY(net_packet.term_type, caps.term_type, sizeof(net_packet.term_type));
  net_packet.term_type[sizeof(net_packet.term_type) - 1] = '\0';

  SAFE_STRNCPY(net_packet.colorterm, caps.colorterm, sizeof(net_packet.colorterm));
  net_packet.colorterm[sizeof(net_packet.colorterm) - 1] = '\0';

  net_packet.detection_reliable = caps.detection_reliable;
  // Send UTF-8 support flag: true for AUTO (default) and TRUE settings, false for FALSE setting
  net_packet.utf8_support = (GET_OPTION(force_utf8) != UTF8_SETTING_FALSE) ? 1 : 0;

  // Set wants_padding flag (1=padding enabled, 0=no padding for snapshot/piped modes)
  net_packet.wants_padding = caps.wants_padding ? 1 : 0;

  // Set codec capabilities (client supports all codecs by default)
  net_packet.codec_capabilities_video = HOST_TO_NET_U32(VIDEO_CODEC_CAP_ALL);
  net_packet.codec_capabilities_audio = HOST_TO_NET_U32(AUDIO_CODEC_CAP_ALL);

  // Use threaded_send_packet() which handles encryption
  return threaded_send_packet(PACKET_TYPE_CLIENT_CAPABILITIES, &net_packet, sizeof(net_packet));
}

asciichat_error_t threaded_send_client_join_packet(const char *display_name, uint32_t capabilities) {
  // Connection and transport availability is checked by threaded_send_packet()

  // Build CLIENT_JOIN packet locally
  client_info_packet_t join_packet;
  SAFE_MEMSET(&join_packet, sizeof(join_packet), 0, sizeof(join_packet));
  join_packet.client_id = HOST_TO_NET_U32(0); // Will be assigned by server
  SAFE_SNPRINTF(join_packet.display_name, MAX_DISPLAY_NAME_LEN, "%s", display_name ? display_name : "Unknown");
  join_packet.capabilities = HOST_TO_NET_U32(capabilities);

  // Use threaded_send_packet() which handles encryption
  int send_result = threaded_send_packet(PACKET_TYPE_CLIENT_JOIN, &join_packet, sizeof(join_packet));
  if (send_result == 0) {
    mutex_lock(&g_send_mutex);
    bool active = atomic_load_u64(&g_connection_active);
    socket_t socket_snapshot = g_sockfd;
    const crypto_context_t *crypto_ctx = crypto_client_is_ready() ? crypto_client_get_context() : NULL;
    if (active && socket_snapshot != INVALID_SOCKET_VALUE) {
      (void)log_network_message(
          socket_snapshot, (const struct crypto_context_t *)crypto_ctx, LOG_INFO, REMOTE_LOG_DIRECTION_CLIENT_TO_SERVER,
          "CLIENT_JOIN sent (display=\"%s\", capabilities=0x%x)", join_packet.display_name, capabilities);
    }
    mutex_unlock(&g_send_mutex);
  }
  return send_result;
}

static void ensure_mutex_initialized(void) {
  if (!lifecycle_init(&g_signaling_lc, "signaling"))
    return;
}

static asciichat_error_t client_send_sdp(const uint8_t session_id[16], const uint8_t recipient_id[16],
                                         const char *sdp_type, const char *sdp, void *user_data) {
  (void)user_data;

  if (!session_id || !recipient_id || !sdp_type || !sdp) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid SDP parameters");
  }

  ensure_mutex_initialized();
  mutex_lock(&g_signaling_mutex);

  // Check if ACDS connection is active
  if (!g_acds_transport) {
    mutex_unlock(&g_signaling_mutex);
    return SET_ERRNO(ERROR_INVALID_STATE, "ACDS transport not available");
  }

  // Check if session context is set
  if (!g_session_context.is_set) {
    mutex_unlock(&g_signaling_mutex);
    return SET_ERRNO(ERROR_INVALID_STATE, "Session context not set");
  }

  // Calculate SDP length
  size_t sdp_len = strlen(sdp);
  if (sdp_len == 0 || sdp_len >= 8192) {
    mutex_unlock(&g_signaling_mutex);
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid SDP length: %zu", sdp_len);
  }

  // Allocate packet buffer (header + SDP string)
  size_t total_len = sizeof(acip_webrtc_sdp_t) + sdp_len;
  uint8_t *packet = SAFE_MALLOC(total_len, uint8_t *);
  if (!packet) {
    mutex_unlock(&g_signaling_mutex);
    return SET_ERRNO(ERROR_MEMORY, "Failed to allocate SDP packet");
  }

  // Fill header
  acip_webrtc_sdp_t *header = (acip_webrtc_sdp_t *)packet;
  memcpy(header->session_id, session_id, 16);
  memcpy(header->sender_id, g_session_context.participant_id, 16);
  memcpy(header->recipient_id, recipient_id, 16);
  header->sdp_type = (strcmp(sdp_type, "offer") == 0) ? 0 : 1;
  header->sdp_len = HOST_TO_NET_U16((uint16_t)sdp_len);

  log_debug("SDP packet: session_id=%02x%02x%02x%02x..., sender=%02x%02x%02x%02x..., recipient=%02x%02x%02x%02x...",
            session_id[0], session_id[1], session_id[2], session_id[3], g_session_context.participant_id[0],
            g_session_context.participant_id[1], g_session_context.participant_id[2],
            g_session_context.participant_id[3], recipient_id[0], recipient_id[1], recipient_id[2], recipient_id[3]);

  // Copy SDP string after header
  // NOLINTNEXTLINE(bugprone-not-null-terminated-result) - binary packet data
  memcpy(packet + sizeof(acip_webrtc_sdp_t), sdp, sdp_len);

  log_info("Sending WebRTC SDP %s to participant (%.8s...) via ACDS", sdp_type, (const char *)recipient_id);

  // Send via ACDS transport using generic packet sender
  asciichat_error_t result =
      packet_send_via_transport(g_acds_transport, PACKET_TYPE_ACIP_WEBRTC_SDP, packet, total_len, 0);

  mutex_unlock(&g_signaling_mutex);

  SAFE_FREE(packet);

  if (result != ASCIICHAT_OK) {
    return SET_ERRNO(result, "Failed to send SDP via ACDS");
  }

  return ASCIICHAT_OK;
}

static asciichat_error_t client_send_ice(const uint8_t session_id[16], const uint8_t recipient_id[16],
                                         const char *candidate, const char *mid, void *user_data) {
  (void)user_data;

  if (!session_id || !recipient_id || !candidate || !mid) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid ICE parameters");
  }

  ensure_mutex_initialized();
  mutex_lock(&g_signaling_mutex);

  // Check if ACDS connection is active
  if (!g_acds_transport) {
    mutex_unlock(&g_signaling_mutex);
    return SET_ERRNO(ERROR_INVALID_STATE, "ACDS transport not available");
  }

  // Check if session context is set
  if (!g_session_context.is_set) {
    mutex_unlock(&g_signaling_mutex);
    return SET_ERRNO(ERROR_INVALID_STATE, "Session context not set");
  }

  // Calculate payload length (candidate + null + mid + null)
  size_t candidate_len = strlen(candidate);
  size_t mid_len = strlen(mid);
  size_t payload_len = candidate_len + 1 + mid_len + 1;

  if (payload_len >= 8192) {
    mutex_unlock(&g_signaling_mutex);
    return SET_ERRNO(ERROR_INVALID_PARAM, "ICE payload too large: %zu", payload_len);
  }

  // Allocate packet buffer (header + payload)
  size_t total_len = sizeof(acip_webrtc_ice_t) + payload_len;
  uint8_t *packet = SAFE_MALLOC(total_len, uint8_t *);
  if (!packet) {
    mutex_unlock(&g_signaling_mutex);
    return SET_ERRNO(ERROR_MEMORY, "Failed to allocate ICE packet");
  }

  // Fill header
  acip_webrtc_ice_t *header = (acip_webrtc_ice_t *)packet;
  memcpy(header->session_id, session_id, 16);
  memcpy(header->sender_id, g_session_context.participant_id, 16);
  memcpy(header->recipient_id, recipient_id, 16);
  header->candidate_len = HOST_TO_NET_U16((uint16_t)candidate_len); // FIXED: Use candidate length, not total payload

  // Copy candidate and mid after header
  uint8_t *payload = packet + sizeof(acip_webrtc_ice_t);
  memcpy(payload, candidate, candidate_len);
  payload[candidate_len] = '\0';
  memcpy(payload + candidate_len + 1, mid, mid_len);
  payload[candidate_len + 1 + mid_len] = '\0';

  log_debug("Sending WebRTC ICE candidate to participant (%.8s..., mid=%s) via ACDS", (const char *)recipient_id, mid);

  // Send via ACDS transport using generic packet sender
  asciichat_error_t result =
      packet_send_via_transport(g_acds_transport, PACKET_TYPE_ACIP_WEBRTC_ICE, packet, total_len, 0);

  mutex_unlock(&g_signaling_mutex);

  SAFE_FREE(packet);

  if (result != ASCIICHAT_OK) {
    return SET_ERRNO(result, "Failed to send ICE via ACDS");
  }

  return ASCIICHAT_OK;
}

webrtc_signaling_callbacks_t webrtc_get_signaling_callbacks(void) {
  ensure_mutex_initialized();

  webrtc_signaling_callbacks_t callbacks = {
      .send_sdp = client_send_sdp, .send_ice = client_send_ice, .user_data = NULL};

  return callbacks;
}

void webrtc_set_acds_transport(acip_transport_t *transport) {
  ensure_mutex_initialized();
  mutex_lock(&g_signaling_mutex);

  g_acds_transport = transport;

  if (transport) {
    log_debug("ACDS transport set for WebRTC signaling");
  } else {
    log_debug("ACDS transport cleared for WebRTC signaling");
  }

  mutex_unlock(&g_signaling_mutex);
}

void webrtc_set_session_context(const uint8_t session_id[16], const uint8_t participant_id[16]) {
  if (!session_id || !participant_id) {
    log_error("Invalid session context parameters");
    return;
  }

  ensure_mutex_initialized();
  mutex_lock(&g_signaling_mutex);

  memcpy(g_session_context.session_id, session_id, 16);
  memcpy(g_session_context.participant_id, participant_id, 16);
  g_session_context.is_set = true;

  log_info("Session context set for WebRTC signaling (session=%.8s..., participant=%.8s...)", (const char *)session_id,
           (const char *)participant_id);

  mutex_unlock(&g_signaling_mutex);
}

void webrtc_set_transport(acip_transport_t *transport) {
  ensure_mutex_initialized();
  mutex_lock(&g_signaling_mutex);

  g_webrtc_transport = transport;

  if (transport) {
    log_debug("WebRTC data channel transport set");
  } else {
    log_debug("WebRTC data channel transport cleared");
  }

  mutex_unlock(&g_signaling_mutex);
}

acip_transport_t *webrtc_get_transport(void) {
  ensure_mutex_initialized();
  mutex_lock(&g_signaling_mutex);

  acip_transport_t *transport = g_webrtc_transport;

  mutex_unlock(&g_signaling_mutex);

  return transport;
}

void webrtc_cleanup_transport(void) {
  ensure_mutex_initialized();
  mutex_lock(&g_signaling_mutex);

  if (g_webrtc_transport) {
    log_debug("Cleaning up WebRTC data channel transport");
    g_webrtc_transport = NULL;
  }

  mutex_unlock(&g_signaling_mutex);
}

static void *discovery_audio_send_thread(void *user_data) {
  discovery_video_receiver_t *ctx = user_data;
  float samples[960];
  uint8_t encoded[CLIENT_AUDIO_PIPELINE_MAX_OPUS_PACKET];
  while (atomic_load_bool(&ctx->running) && !should_exit()) {
    if (audio_ring_buffer_available_read(ctx->audio->capture_buffer) < 960) {
      platform_sleep_ns(NS_PER_MS_INT);
      continue;
    }
    if (audio_ring_buffer_read(ctx->audio->capture_buffer, samples, 960) != 960)
      continue;
    int size = client_audio_pipeline_capture(ctx->audio_pipeline, samples, 960, encoded, sizeof(encoded));
    if (size <= 0)
      continue;
    uint16_t frame_size = (uint16_t)size;
    asciichat_error_t result = acip_send_audio_opus_batch(ctx->transport, encoded, size, &frame_size, 1, 48000, 20);
    if (result != ASCIICHAT_OK) {
      log_warn("Discovery audio send failed: %d", result);
      atomic_store_bool(&ctx->running, false);
      break;
    }
  }
  return NULL;
}

static asciichat_error_t discovery_audio_play_packet(discovery_video_receiver_t *ctx, packet_type_t type,
                                                     const void *payload, size_t length) {
  if (!ctx->audio)
    return ASCIICHAT_OK;
  if (length < 16)
    return SET_ERRNO(ERROR_INVALID_PARAM, "Truncated discovery audio packet");
  float samples[5760];
  if (type == PACKET_TYPE_AUDIO_BATCH) {
    audio_batch_packet_t header;
    memcpy(&header, payload, sizeof(header));
    if (header.sample_rate != AUDIO_SAMPLE_RATE || header.channels != 1 ||
        header.total_samples != (length - sizeof(header)) / sizeof(float) ||
        (length - sizeof(header)) % sizeof(float) != 0)
      return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid discovery PCM audio batch");
    size_t offset = 0;
    while (offset < header.total_samples) {
      size_t count = header.total_samples - offset;
      if (count > 5760)
        count = 5760;
      memcpy(samples, (const uint8_t *)payload + sizeof(header) + offset * sizeof(float), count * sizeof(float));
      asciichat_error_t result = audio_write_samples(ctx->audio, samples, (int)count);
      if (result != ASCIICHAT_OK)
        return result;
      offset += count;
    }
  } else if (type == PACKET_TYPE_AUDIO_OPUS_BATCH) {
    const uint8_t *bytes = payload;
    uint32_t rate_net, duration_net;
    memcpy(&rate_net, bytes, 4);
    memcpy(&duration_net, bytes + 4, 4);
    if (NET_TO_HOST_U32(rate_net) != AUDIO_SAMPLE_RATE || NET_TO_HOST_U32(duration_net) < 1 ||
        NET_TO_HOST_U32(duration_net) > 120)
      return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid discovery Opus audio format");
    uint32_t count_net;
    memcpy(&count_net, bytes + 8, 4);
    size_t count = NET_TO_HOST_U32(count_net);
    if (count > (length - 16) / 2)
      return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid discovery Opus batch");
    size_t offset = 16 + count * 2;
    for (size_t i = 0; i < count; i++) {
      uint16_t size_net;
      memcpy(&size_net, bytes + 16 + i * 2, 2);
      size_t size = NET_TO_HOST_U16(size_net);
      if (!size || size > length - offset)
        return SET_ERRNO(ERROR_INVALID_PARAM, "Truncated discovery Opus frame");
      int decoded = client_audio_pipeline_playback(ctx->audio_pipeline, bytes + offset, (int)size, samples, 5760);
      if (decoded < 0)
        return SET_ERRNO(ERROR_AUDIO, "Failed to decode discovery Opus frame");
      if (decoded > 0) {
        asciichat_error_t result = audio_write_samples(ctx->audio, samples, decoded);
        if (result != ASCIICHAT_OK)
          return result;
      }
      offset += size;
    }
    if (offset != length)
      return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid discovery Opus batch length");
  }
  return ASCIICHAT_OK;
}

static void *discovery_video_receive_thread(void *user_data) {
  discovery_video_receiver_t *ctx = user_data;
  uint64_t report_start_ns = time_get_ns();
  uint64_t report_received_frames = 0;
  uint64_t report_rendered_frames = 0;
  uint64_t report_render_time_ns = 0;
  while (atomic_load_bool(&ctx->running) && !should_exit() && acip_transport_is_connected(ctx->transport)) {
    asciichat_error_t result = ASCIICHAT_OK;
    // Keep the newest display frame and bound receive work so capture cannot starve.
    char *latest_text = NULL;
    for (size_t received = 0; received < 128 && acip_transport_has_pending_data(ctx->transport); received++) {
      packet_type_t type;
      void *payload = NULL, *allocated = NULL;
      size_t length = 0;
      result = packet_receive_via_transport(ctx->transport, &type, &payload, &length, &allocated);
      if (result == ASCIICHAT_OK && type == PACKET_TYPE_ASCII_FRAME && length >= sizeof(ascii_frame_packet_t)) {
        report_received_frames++;
        ascii_frame_packet_t header;
        memcpy(&header, payload, sizeof(header));
        uint32_t original_size = NET_TO_HOST_U32(header.original_size);
        uint32_t compressed_size = NET_TO_HOST_U32(header.compressed_size);
        bool is_compressed = (NET_TO_HOST_U32(header.flags) & FRAME_FLAG_IS_COMPRESSED) != 0;
        size_t encoded_size = is_compressed ? compressed_size : original_size;
        size_t encoded_length = length - sizeof(header);
        if (encoded_size == encoded_length && (!is_compressed || compressed_size > 0)) {
          asciichat_errno_scope_t decode_scope = asciichat_errno_scope_begin();
          char *decoded = packet_decode_frame_data_malloc((const char *)payload + sizeof(header), encoded_length,
                                                          is_compressed, original_size, compressed_size);
          if (decoded) {
            ASSERT_NO_ERRNO_SINCE(decode_scope);
            asciichat_errno_scope_end(decode_scope, ASCIICHAT_ERRNO_HANDLED);
            if (latest_text)
              stats_counter_add(stats_runtime_scope(), STATS_COUNTER_FRAMES_SKIPPED, 1);
            SAFE_FREE(latest_text);
            latest_text = decoded;
          } else {
            log_warn_every(US_PER_SEC_INT, "Could not decode server ASCII frame (compressed=%d original=%u encoded=%u)",
                           is_compressed, original_size, compressed_size);
            asciichat_errno_scope_end(decode_scope, ASCIICHAT_ERRNO_DISMISSED);
          }
        } else {
          log_warn_every(US_PER_SEC_INT,
                         "Invalid server ASCII frame lengths (compressed=%d original=%u encoded=%u payload=%zu)",
                         is_compressed, original_size, encoded_size, encoded_length);
        }
      } else if (result == ASCIICHAT_OK && type == PACKET_TYPE_PING) {
        result = packet_send_via_transport(ctx->transport, PACKET_TYPE_PONG, payload, length, 0);
      } else if (result == ASCIICHAT_OK && (type == PACKET_TYPE_AUDIO_BATCH || type == PACKET_TYPE_AUDIO_OPUS_BATCH)) {
        result = discovery_audio_play_packet(ctx, type, payload, length);
      }
      if (allocated)
        buffer_release(allocated);
      if (result != ASCIICHAT_OK) {
        SAFE_FREE(latest_text);
        ctx->result = result;
        atomic_store_bool(&ctx->running, false);
        return NULL;
      }
    }
    if (latest_text) {
      uint64_t render_start_ns = time_get_ns();
      session_display_render_frame(ctx->display, latest_text);
      report_render_time_ns += time_get_ns() - render_start_ns;
      report_rendered_frames++;
      SAFE_FREE(latest_text);
      latest_text = NULL;
    }
    uint64_t now_ns = time_get_ns();
    uint64_t report_elapsed_ns = now_ns - report_start_ns;
    if (report_elapsed_ns >= NS_PER_SEC_INT) {
      log_info("Discovery ASCII receive/render rate: received=%.1f fps rendered=%.1f fps avg_render=%.2fms",
               (double)report_received_frames * NS_PER_SEC_INT / (double)report_elapsed_ns,
               (double)report_rendered_frames * NS_PER_SEC_INT / (double)report_elapsed_ns,
               report_rendered_frames ? (double)report_render_time_ns / (double)report_rendered_frames / 1e6 : 0.0);
      report_start_ns = now_ns;
      report_received_frames = 0;
      report_rendered_frames = 0;
      report_render_time_ns = 0;
    }
    platform_sleep_ns(NS_PER_MS_INT);
  }
  return NULL;
}

static void on_discovery_state_change(discovery_state_t new_state, void *user_data) {
  (void)user_data; // Unused
  static uint64_t setup_started;
  if (new_state == DISCOVERY_STATE_CONNECTING_ACDS)
    setup_started = time_get_ns();
  if (setup_started && (new_state == DISCOVERY_STATE_ACTIVE || new_state == DISCOVERY_STATE_FAILED)) {
    stats_duration_record(stats_runtime_scope(), STATS_DURATION_CONNECTION_SETUP, time_get_ns() - setup_started);
    setup_started = 0;
  }

  const char *state_names[] = {"INIT",         "CONNECTING_ACDS", "CREATING_SESSION", "JOINING_SESSION",
                               "WAITING_PEER", "NEGOTIATING",     "STARTING_HOST",    "CONNECTING_HOST",
                               "ACTIVE",       "MIGRATING",       "FAILED",           "ENDED"};

  if (new_state >= 0 && new_state < (int)(sizeof(state_names) / sizeof(state_names[0]))) {
    if (new_state == DISCOVERY_STATE_ACTIVE && g_discovery)
      stats_runtime_connection_state(discovery_session_is_host(g_discovery) ? "ACTIVE / host" : "ACTIVE / participant");
    else
      stats_runtime_connection_state(state_names[new_state]);
    log_info("Discovery state: %s", state_names[new_state]);
  }
}

static void on_session_ready(const char *session_string, void *user_data) {
  (void)user_data; // Unused

  if (session_string && session_string[0]) {
    const char *requested = GET_OPTION(session_string);
    splash_set_discovery_session(session_string, requested && requested[0]);
    log_info("Share this string to connect: %s", session_string);
    log_info("Run: ascii-chat %s", session_string);
  }
}

static void on_discovery_error(asciichat_error_t error, const char *message, void *user_data) {
  discovery_ui_state_t *ui = user_data;
  mutex_lock(&ui->mutex);
  SAFE_STRNCPY(ui->error, message ? message : "Unknown discovery error", sizeof(ui->error));
  ui->error_code = error;
  mutex_unlock(&ui->mutex);
  log_error("Discovery error (%d): %s", error, message ? message : "Unknown discovery error");
  signal_exit();
}

static bool discovery_capture_should_exit_adapter(void *user_data) {
  (void)user_data; // Unused parameter
  return should_exit();
}

static void discovery_keyboard_handler(session_capture_ctx_t *capture, int key, void *user_data) {
  (void)user_data; // Unused parameter
