}

static asciichat_error_t discovery_run(session_capture_ctx_t *capture, session_display_ctx_t *display,
                                       void *user_data) {
  (void)user_data; // Unused

  asciichat_error_t result = ASCIICHAT_OK;
  bool snapshot_mode = GET_OPTION(snapshot_mode);

role_dispatch:
  result = discovery_session_apply_handoff(g_discovery);
  if (result != ASCIICHAT_OK)
    return result;

  // Wait for session to become active (host negotiation complete)
  // This processes ACDS events until we have a determined role
  // Snapshot capture requires negotiation to finish before its exit condition is honored.
  // The snapshot delay will be honored once we transition to active state and start capturing
  while (true) {
    if (should_exit() && !snapshot_mode) {
      return ASCIICHAT_OK;
    }
    result = discovery_session_process(g_discovery, 50 * NS_PER_MS_INT);
    if (result != ASCIICHAT_OK && result != ERROR_NETWORK_TIMEOUT) {
      log_error("Discovery session process failed: %d", result);
      return result;
    }

    if (g_discovery->handoff_pending)
      goto role_dispatch;
    if (discovery_session_is_active(g_discovery)) {
      break; // Session is active, role is determined
    }
    platform_sleep_ns(NS_PER_MS_INT);
  }

  // In snapshot mode, proceed to role handling even if should_exit() is true
  // We'll check for exit conditions during the actual frame rendering phase
  if (should_exit() && !snapshot_mode) {
    log_info("Shutdown requested during discovery negotiation");
    return ASCIICHAT_OK;
  }

  // Session is active - run based on our role
  bool we_are_host = discovery_session_is_host(g_discovery);

  if (we_are_host) {
    // HOST ROLE: Capture own media, manage participants, mix and broadcast
    log_info("Hosting session - capturing and broadcasting");

    // Keep terminal logging enabled until a peer connects and we have video to render.
    // This keeps the splash/log UI visible while waiting for peers instead of a blank screen.

    // Get the host context already created and started during discovery negotiation
    session_host_t *host = discovery_session_get_host(g_discovery);
    if (!host) {
      log_fatal("Failed to get session host from discovery");
      return ERROR_INVALID_STATE;
    }

    // Set display context so host renders frames locally
    asciichat_error_t display_result = session_host_set_display(host, display);
    if (display_result != ASCIICHAT_OK) {
      log_error("Failed to set display context on host: %d", display_result);
      // Non-fatal - host can still render frames for broadcasting, just not locally
    } else {
      log_info("Display context set on host for local frame rendering");
    }

    // The passed capture context is set up for network mode (participant receiving frames).
    // For host role, we need local media capture. Reuse the existing capture context
    // which should have test pattern, webcam, or file configured.
    // Note: session_client_like should have initialized this with the media source.

    // Add memory participant for host's own media
    uint32_t host_participant_id = session_host_add_memory_participant(host);
    if (host_participant_id == 0) {
      log_error("Failed to add memory participant for host");
      // Host context is owned by discovery session - don't destroy
      return ERROR_INVALID_STATE;
    }

    log_info("Host participating with ID %u", host_participant_id);

    // Start the render thread (handles video mixing and ASCII rendering for display)
    result = session_host_start_render(host);
    if (result != ASCIICHAT_OK) {
      log_error("Failed to start render thread: %d", result);
      // Host context is owned by discovery session - don't destroy
      return result;
    }

    // Main loop: capture own media and keep discovery responsive
    while (discovery_session_is_active(g_discovery)) {
      // Exit conditions:
      // 1. Non-snapshot mode: check should_exit() (Ctrl+C, SIGTERM, any exit signal)
      // 2. Snapshot mode: exit when should_exit() is true AND we've rendered at least one frame
      //    (to allow the full snapshot_delay to elapse while ignoring the snapshot timeout in should_exit)
      // 3. Discovery session ended: always exit

      if (should_exit()) {
        // In snapshot mode, if we haven't rendered any frames yet, don't exit yet
        // Wait until at least one frame has been displayed
        if (!snapshot_mode || g_snapshot_first_frame_rendered) {
          log_debug("Exit condition met (snapshot_mode=%d, first_frame_rendered=%d)", snapshot_mode,
                    g_snapshot_first_frame_rendered ? 1 : 0);
          break;
        } else {
          log_debug_every(5 * NS_PER_SEC_INT,
                          "Waiting for first frame (snapshot_mode=true, first_frame_rendered=false)");
        }
      }

      keyboard_key_t key = ui_input_read_key(UI_SCREEN_MEDIA);
      if (key != KEY_NONE)
        session_handle_keyboard_input(capture, display, key);
      // Capture frame from local media (webcam, test pattern, file, etc.)
      // The capture context is set up during session_client_like_run() and handles all media types
      asciichat_errno_scope_t frame_scope = asciichat_errno_checkpoint();
      image_t *frame = session_capture_read_frame(capture);
      asciichat_error_context_t capture_failure;
      if (!frame && asciichat_errno_peek_since(frame_scope, &capture_failure)) {
        result = capture_failure.code;
        break;
      }
      if (frame) {
        log_debug_every(5 * NS_PER_SEC_INT, "Captured frame, injecting into host");
        // Inject host's frame into mixer for broadcasting
        result = session_host_inject_frame(host, host_participant_id, frame);
        if (result != ASCIICHAT_OK) {
          LOG_ERRNO_IF_SET("Failed to inject host frame");
          break;
        }
      } else {
        log_debug_every(5 * NS_PER_SEC_INT, "No frame captured");
      }

      // Keep discovery session responsive (NAT negotiations, migrations)
      asciichat_errno_scope_t process_scope = asciichat_errno_scope_begin();
      result = discovery_session_process(g_discovery, 10 * NS_PER_MS_INT);
      if (result != ASCIICHAT_OK && result != ERROR_NETWORK_TIMEOUT) {
        log_error("Discovery session process failed: %d", result);
        break;
      }

      if (result == ASCIICHAT_OK)
        ASSERT_NO_ERRNO_SINCE(process_scope);
      asciichat_errno_scope_end(process_scope, ASCIICHAT_ERRNO_HANDLED);
      result = ASCIICHAT_OK;

      // Frame rate limiting (60 FPS)
      session_capture_sleep_for_fps(capture);
    }

    log_debug("Host role main loop exited (snapshot_mode=%d, first_frame_rendered=%d, session_active=%d)",
              snapshot_mode, g_snapshot_first_frame_rendered ? 1 : 0, discovery_session_is_active(g_discovery) ? 1 : 0);

    // Stop render thread before returning (display will be destroyed by caller)
    session_host_stop_render(host);

    if (result != ASCIICHAT_OK)
      return result;

    if (should_exit()) {
      return ASCIICHAT_OK;
    }

    // If we reach here, discovery session is no longer active (role change)
    if (!discovery_session_is_active(g_discovery)) {
      log_info("Session ended or role changed");
      return ASCIICHAT_OK;
    }
  } else {
    session_participant_t *participant = discovery_session_get_participant(g_discovery);
    acip_transport_t *transport = session_participant_get_transport(participant);
    if (transport && acip_transport_get_type(transport) == ACIP_TRANSPORT_WEBRTC) {
      bool enable_audio = GET_OPTION(audio_enabled);
      log_info("Discovery WebRTC audio: %s", enable_audio ? "enabled" : "disabled");
      result =
          acip_send_client_join(transport, CLIENT_CAP_VIDEO | CLIENT_CAP_COLOR | (enable_audio ? CLIENT_CAP_AUDIO : 0));
      if (result != ASCIICHAT_OK)
        return result;
      terminal_capabilities_t caps = detect_terminal_capabilities();
      terminal_capabilities_packet_t packet = {0};
      packet.capabilities = HOST_TO_NET_U32(caps.capabilities);
      packet.color_level = HOST_TO_NET_U32(caps.color_level);
      packet.color_count = HOST_TO_NET_U32(caps.color_count);
      packet.render_mode = HOST_TO_NET_U32(caps.render_mode);
      packet.width = HOST_TO_NET_U16(GET_OPTION(width) > 0 ? GET_OPTION(width) : 80);
      packet.height = HOST_TO_NET_U16(GET_OPTION(height) > 0 ? GET_OPTION(height) : 24);
      packet.palette_type = HOST_TO_NET_U32(GET_OPTION(palette_type));
      packet.utf8_support = caps.utf8_support ? 1 : 0;
      int desired_fps = GET_OPTION(fps) > 0 ? GET_OPTION(fps) : caps.desired_fps;
      if (desired_fps <= 0) {
        desired_fps = DEFAULT_MAX_FPS;
      }
      packet.desired_fps = (uint8_t)(desired_fps > 144 ? 144 : desired_fps);
      packet.wants_padding = caps.wants_padding ? 1 : 0;
      packet.detection_reliable = caps.detection_reliable;
      SAFE_STRNCPY(packet.term_type, caps.term_type, sizeof(packet.term_type));
      SAFE_STRNCPY(packet.colorterm, caps.colorterm, sizeof(packet.colorterm));
      result = acip_send_capabilities(transport, &packet, sizeof(packet));
      if (result != ASCIICHAT_OK)
        return result;
      result = acip_send_stream_start(transport, STREAM_TYPE_VIDEO | (enable_audio ? STREAM_TYPE_AUDIO : 0));
      if (result != ASCIICHAT_OK)
        return result;
      discovery_video_receiver_t receiver = {
          .transport = transport, .display = display, .running = {0}, .result = ASCIICHAT_OK};
      audio_context_t audio = {0};
      if (enable_audio) {
        result = audio_init(&audio);
        if (result != ASCIICHAT_OK)
          return result;
        media_source_t *local_source = (media_source_t *)session_capture_get_media_source(capture);
        bool has_media_audio = media_source_has_audio(local_source);
        audio.capture_media_source = local_source;
        audio.playback_only = !audio_should_enable_microphone(GET_OPTION(audio_capture_source), has_media_audio);
        log_info("Discovery audio input: media=%d, microphone=%d", has_media_audio,
                 audio_should_enable_microphone(GET_OPTION(audio_capture_source), has_media_audio));
        client_audio_pipeline_config_t config = client_audio_pipeline_config_for_source(has_media_audio);
        config.flags.jitter_buffer = false;
        receiver.audio_pipeline = client_audio_pipeline_create(&config);
        if (!receiver.audio_pipeline) {
          audio_destroy(&audio);
          return SET_ERRNO(ERROR_AUDIO, "Failed to create discovery audio pipeline");
        }
        audio_set_pipeline(&audio, receiver.audio_pipeline);
        receiver.audio = &audio;
        result = audio_start_duplex(&audio);
        if (result != ASCIICHAT_OK) {
          audio_destroy(&audio);
          client_audio_pipeline_destroy(receiver.audio_pipeline);
          return result;
        }
      }
      asciichat_thread_t receiver_thread;
      asciichat_thread_t audio_thread;
      bool audio_thread_started = false;
      atomic_store_bool(&receiver.running, true);
      result = asciichat_thread_create(&receiver_thread, "discovery_video_receive", discovery_video_receive_thread,
                                       &receiver);
      if (result != ASCIICHAT_OK) {
        if (enable_audio) {
          audio_destroy(&audio);
          client_audio_pipeline_destroy(receiver.audio_pipeline);
        }
        return result;
      }
      if (enable_audio) {
        result = asciichat_thread_create(&audio_thread, "discovery_audio_send", discovery_audio_send_thread, &receiver);
        audio_thread_started = result == ASCIICHAT_OK;
        if (!audio_thread_started)
          atomic_store_bool(&receiver.running, false);
      }
      while (!should_exit() && discovery_session_is_active(g_discovery) && acip_transport_is_connected(transport) &&
             atomic_load_bool(&receiver.running)) {
        keyboard_key_t key = ui_input_read_key(UI_SCREEN_MEDIA);
        if (key != KEY_NONE)
          session_handle_keyboard_input(capture, display, key);
        uint64_t iteration_start = time_get_ns();
        if (snapshot_mode && g_snapshot_first_frame_rendered_ns > 0 &&
            time_ns_to_s(time_elapsed_ns(g_snapshot_first_frame_rendered_ns, iteration_start)) >=
                GET_OPTION(snapshot_delay)) {
          signal_exit();
          break;
        }
        uint64_t capture_start = time_get_ns();
        asciichat_errno_scope_t frame_scope = asciichat_errno_checkpoint();
        image_t *frame = session_capture_read_frame(capture);
        asciichat_error_context_t capture_failure;
        if (!frame && asciichat_errno_peek_since(frame_scope, &capture_failure)) {
          result = capture_failure.code;
          break;
        }
        uint64_t capture_end = time_get_ns();
        uint64_t processing_start = capture_end;
        uint64_t processing_end = processing_start;
        uint64_t send_start = processing_start;
        uint64_t send_end = send_start;
        if (frame) {
          image_t *processed = session_capture_process_for_transmission(capture, frame);
          if (processed) {
            processing_end = time_get_ns();
            send_start = processing_end;
            result = acip_send_image_frame(transport, processed->pixels, processed->w, processed->h, PIXEL_FORMAT_RGB);
            send_end = time_get_ns();
            image_destroy(processed);
            if (result != ASCIICHAT_OK)
              break;
          }
        }
        if (processing_end == processing_start)
          processing_end = time_get_ns();
        uint64_t signaling_start = send_end;
        result = discovery_session_process(g_discovery, 10 * NS_PER_MS_INT);
        uint64_t signaling_end = time_get_ns();
        if (result != ASCIICHAT_OK && result != ERROR_NETWORK_TIMEOUT)
          break;
        uint64_t event_start = time_get_ns();
        APP_CALLBACK_VOID(platform_pump_events);
        uint64_t event_end = time_get_ns();
        uint64_t interval = NS_PER_SEC_INT / (GET_OPTION(fps) > 0 ? GET_OPTION(fps) : 30);
        uint64_t elapsed = time_get_ns() - iteration_start;
        if (elapsed > 50 * NS_PER_MS_INT) {
          log_warn_every(US_PER_SEC_INT,
                         "Discovery media loop took %.1fms (capture=%.1fms process=%.1fms send=%.1fms signaling=%.1fms "
                         "events=%.1fms)",
                         (double)elapsed / 1e6, (double)(capture_end - capture_start) / 1e6,
                         (double)(processing_end - processing_start) / 1e6, (double)(send_end - send_start) / 1e6,
                         (double)(signaling_end - signaling_start) / 1e6, (double)(event_end - event_start) / 1e6);
        }
        if (elapsed < interval)
          platform_sleep_ns(interval - elapsed);
      }
      atomic_store_bool(&receiver.running, false);
      asciichat_thread_join(&receiver_thread, NULL);
      if (audio_thread_started)
        asciichat_thread_join(&audio_thread, NULL);
      if (enable_audio) {
        audio_destroy(&audio);
        client_audio_pipeline_destroy(receiver.audio_pipeline);
      }
      if (!should_exit() && g_discovery->session_type == SESSION_TYPE_WEBRTC) {
        if (!g_discovery->handoff_pending) {
          g_discovery->state = DISCOVERY_STATE_MIGRATING;
          g_discovery->migration.detection_time_ms = time_get_ns() / NS_PER_MS_INT;
        }
        goto role_dispatch;
      }
      if (receiver.result != ASCIICHAT_OK)
        return receiver.result;
      if (result != ASCIICHAT_OK && result != ERROR_NETWORK_TIMEOUT)
        return result;
      return ASCIICHAT_OK;
    }
    // PARTICIPANT ROLE: Just wait for host connection
    // Don't use capture/display for participant discovery mode
    (void)capture; // Not used

    splash_intro_done();
    splash_wait_for_animation();

    // For participants, destroy the display context to reset terminal state
    // and prevent the discovery framework from rendering anything
    if (display) {
      log_info("Participant mode - cleaning up display context");
      session_display_destroy(display);
      // Also clear the global display context to prevent signal handlers from using stale pointer
      session_display_set_global_context_public(NULL);
    }

    // Session is active and we're a participant. In discovery mode, participants
    // don't render anything - they just wait for the host. Return early to skip
    // any display rendering that would happen after discovery_run returns.
    return ASCIICHAT_OK;
  }

  return result;
}

static asciichat_error_t discovery_prepare(void *user_data) {
  (void)user_data;
  return discovery_session_start(g_discovery);
}

int discovery_main(void) {
  log_debug("discovery_main() starting");

  // Discovery-specific setup: initialize ACDS connection and session negotiation
  // Note: Shared setup (keepawake, splash, terminal, capture, display, audio)
  // is handled by session_client_like_run()

  // Get session string from options (command-line argument)
  const char *session_string = GET_OPTION(session_string);
  bool is_initiator = (session_string == NULL || session_string[0] == '\0');

  int port_int = GET_OPTION(port);

  log_debug("Discovery: is_initiator=%d, port=%d", is_initiator, port_int);

  // Validate mutually exclusive options: discovery_service_url vs discovery_port
  const char *service_url = GET_OPTION(discovery_service_url);
  if (service_url && service_url[0] != '\0') {
    int discovery_port = GET_OPTION(discovery_port);
    if (discovery_port != ACIP_DISCOVERY_DEFAULT_PORT) {
      log_fatal("--discovery-service-url and --discovery-service-port are mutually exclusive");
      return ERROR_USAGE;
    }
  }

  discovery_ui_state_t ui = {0};
  asciichat_error_t ui_result = mutex_init(&ui.mutex, "discovery_ui");
  if (ui_result != ASCIICHAT_OK)
    return ui_result;

  // Create discovery session configuration
  discovery_config_t discovery_config = {
      .acds_address = GET_OPTION(discovery_server),
      .acds_port = (uint16_t)GET_OPTION(discovery_port),
      .acds_url = service_url,
      .session_string = is_initiator ? NULL : session_string,
      .password = GET_OPTION(password),
      .local_port = (uint16_t)port_int,
      .on_state_change = on_discovery_state_change,
      .on_session_ready = on_session_ready,
      .on_error = on_discovery_error,
      .callback_user_data = &ui,
      .should_exit_callback = discovery_capture_should_exit_adapter,
      .exit_callback_data = NULL,
  };

  // Create discovery session (stored in global for discovery_run() to access)
  g_discovery = discovery_session_create(&discovery_config);
  if (!g_discovery) {
    mutex_destroy(&ui.mutex);
    log_fatal("Failed to create discovery session");
    return ERROR_MEMORY;
  }

  splash_set_discovery_session(session_string, !is_initiator);

  // No network interrupt callback needed - discovery session handles its own shutdown
  set_interrupt_callback(NULL);

  /* ========================================================================
   * Configure and Run Shared Client-Like Session Framework
   * ========================================================================
   * session_client_like_run() handles all shared initialization:
   * - Terminal output management
   * - Keepawake system
   * - Splash screen lifecycle
   * - Media source selection
   * - FPS probing
   * - Audio initialization
   * - Display context creation
   * - Proper cleanup ordering
   *
   * Discovery mode provides:
   * - discovery_run() callback: NAT negotiation, role determination, media handling
   * - discovery_keyboard_handler: interactive controls for participant role
   */

  session_client_like_config_t config = {
      .run_fn = discovery_run,
      .prepare_fn = discovery_prepare,
      .run_user_data = NULL,
      .kind = SESSION_CLIENT_LIKE_KIND_DISCOVERY,
      .discovery = (void *)g_discovery, // Opaque pointer to discovery session
      .custom_should_exit = NULL,
      .exit_user_data = NULL,
      .keyboard_handler = discovery_keyboard_handler,
      .max_reconnect_attempts = 0, // Discovery doesn't retry - role is determined once
      .should_reconnect_callback = NULL,
      .reconnect_user_data = NULL,
      .reconnect_delay_ms = 0,
      .print_newline_on_tty_exit = false, // Server/participant manages cursor
  };

  log_debug("Discovery: calling session_client_like_run()");
  asciichat_error_t session_result = session_client_like_run(&config);
  log_debug("Discovery: session_client_like_run() returned %d", session_result);

  // Cleanup discovery session
  log_debug("Discovery: cleaning up");

  if (g_discovery) {
    discovery_session_stop(g_discovery);
    discovery_session_destroy(g_discovery);
    g_discovery = NULL;
  }

  splash_clear_discovery_session();
  char discovery_error[sizeof(ui.error)];
  mutex_lock(&ui.mutex);
  SAFE_STRNCPY(discovery_error, ui.error, sizeof(discovery_error));
  asciichat_error_t discovery_error_code = ui.error_code;
  mutex_unlock(&ui.mutex);

  if (session_result != ASCIICHAT_OK || discovery_error[0]) {
    log_set_terminal_output(true);
    NOTICE(WARNING, "DISCOVERY FAILED", "Discovery failed: %s",
           discovery_error[0] ? discovery_error : asciichat_error_string(session_result));
    if (session_result == ASCIICHAT_OK)
      session_result = discovery_error_code;
  }
  mutex_destroy(&ui.mutex);
  return (session_result == ASCIICHAT_OK) ? 0 : (int)session_result;
}

void nat_quality_init(nat_quality_t *quality) {
  if (!quality)
    return;
  memset(quality, 0, sizeof(nat_quality_t));
  quality->nat_type = ACIP_NAT_TYPE_SYMMETRIC; // Assume worst case
}

int nat_compute_tier(const nat_quality_t *quality) {
  if (!quality)
    return 4;

  if (quality->lan_reachable)
    return 0; // LAN - best
  if (quality->has_public_ip)
    return 1; // Public IP
  if (quality->upnp_available)
    return 2; // UPnP mapping
  if (quality->nat_type <= ACIP_NAT_TYPE_RESTRICTED)
    return 3; // STUN hole-punchable
  return 4;   // TURN relay required
}

int nat_compare_quality(const nat_quality_t *ours, const nat_quality_t *theirs, bool we_are_initiator) {
  if (!ours || !theirs) {
    return we_are_initiator ? -1 : 1;
  }

  int our_tier = nat_compute_tier(ours);
  int their_tier = nat_compute_tier(theirs);

  // Check for bandwidth override: massive bandwidth advantage can override NAT tier
  if (ours->upload_kbps > 0 && theirs->upload_kbps > 0) {
    if (ours->upload_kbps >= theirs->upload_kbps * BANDWIDTH_OVERRIDE_RATIO) {
      log_debug("NAT compare: we win by bandwidth override (%u vs %u kbps)", ours->upload_kbps, theirs->upload_kbps);
      return -1;
    }
    if (theirs->upload_kbps >= ours->upload_kbps * BANDWIDTH_OVERRIDE_RATIO) {
      log_debug("NAT compare: they win by bandwidth override (%u vs %u kbps)", theirs->upload_kbps, ours->upload_kbps);
      return 1;
    }
  }

  // Compare NAT tiers (lower = better)
  if (our_tier < their_tier) {
    log_debug("NAT compare: we win by tier (%d vs %d)", our_tier, their_tier);
    return -1;
  }
  if (our_tier > their_tier) {
    log_debug("NAT compare: they win by tier (%d vs %d)", our_tier, their_tier);
    return 1;
  }

  // Same tier - bandwidth is tiebreaker
  if (ours->upload_kbps > theirs->upload_kbps) {
    log_debug("NAT compare: we win by bandwidth (%u vs %u kbps)", ours->upload_kbps, theirs->upload_kbps);
    return -1;
  }
  if (ours->upload_kbps < theirs->upload_kbps) {
    log_debug("NAT compare: they win by bandwidth (%u vs %u kbps)", theirs->upload_kbps, ours->upload_kbps);
    return 1;
  }

  // Same bandwidth - latency is tiebreaker
  if (ours->rtt_to_acds_ns < theirs->rtt_to_acds_ns) {
    log_debug("NAT compare: we win by latency (%lu ns vs %lu ns)", ours->rtt_to_acds_ns, theirs->rtt_to_acds_ns);
    return -1;
  }
  if (ours->rtt_to_acds_ns > theirs->rtt_to_acds_ns) {
    log_debug("NAT compare: they win by latency (%lu ns vs %lu ns)", theirs->rtt_to_acds_ns, ours->rtt_to_acds_ns);
    return 1;
  }

  // Everything equal - initiator hosts
  log_debug("NAT compare: equal quality, initiator wins (we_are_initiator=%d)", we_are_initiator);
  return we_are_initiator ? -1 : 1;
}

static asciichat_error_t nat_parse_stun_response(const uint8_t *response, size_t response_len, char *reflexive_addr,
                                                 uint16_t *reflexive_port) {
  if (!response || response_len < 20 || !reflexive_addr || !reflexive_port) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid STUN response parameters");
  }

  // STUN packets have a 20-byte header followed by attributes
  // Attributes are TLV (Type-Length-Value) format
  // Look for XOR_MAPPED_ADDRESS (0x0020) or MAPPED_ADDRESS (0x0001)

  const uint8_t *current = response + 20;
  const uint8_t *end = response + response_len;

  while (current + 4 <= end) {
    uint16_t attr_type = (current[0] << 8) | current[1];
    uint16_t attr_len = (current[2] << 8) | current[3];

    if (current + 4 + attr_len > end) {
      break;
    }

    // Look for MAPPED_ADDRESS (0x0001)
    if (attr_type == 0x0001 && attr_len >= 8) {
      // Format: reserved byte, family (1=IPv4, 2=IPv6), port (2 bytes), address
      uint8_t family = current[5];
      if (family == 1) { // IPv4
        uint16_t port = ((uint16_t)current[6] << 8) | current[7];
        uint32_t addr =
            ((uint32_t)current[8] << 24) | ((uint32_t)current[9] << 16) | ((uint32_t)current[10] << 8) | current[11];

        // Convert to dotted quad notation
        safe_snprintf(reflexive_addr, 64, "%u.%u.%u.%u", (addr >> 24) & 0xFF, (addr >> 16) & 0xFF, (addr >> 8) & 0xFF,
                      addr & 0xFF);
        *reflexive_port = port;
        return ASCIICHAT_OK;
      }
    }

    // Move to next attribute (with 4-byte alignment padding)
    uint16_t padded_len = (attr_len + 3) & ~3;
    current += 4 + padded_len;
  }

  return SET_ERRNO(ERROR_FORMAT, "STUN response missing MAPPED_ADDRESS");
}

static asciichat_error_t nat_stun_probe(nat_quality_t *quality, const char *stun_server, uint16_t local_port) {
  if (!quality || !stun_server || !stun_server[0]) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters for STUN probe");
  }

  log_debug("Starting STUN probe to %s (local_port=%u)", stun_server, local_port);

  // Parse stun_server for hostname and port
  char host_buf[BUFFER_SIZE_SMALL] = {0};
  uint16_t stun_port = STUN_DEFAULT_PORT;

  SAFE_STRNCPY(host_buf, stun_server, sizeof(host_buf));

  char *colon = strchr(host_buf, ':');
  if (colon) {
    *colon = '\0';
    char *endptr;
    errno = 0;
    long port_val = strtol(colon + 1, &endptr, 10);
    if (*endptr == '\0' && errno == 0 && port_val > 0 && port_val <= 65535) {
      stun_port = (uint16_t)port_val;
    } else {
      log_error("nat_probe_via_stun: Invalid STUN port: %s", colon + 1);
    }
  }

  // Detect address family from STUN server hostname (IPv4 vs IPv6)
  int stun_family = is_valid_ipv6(host_buf) ? AF_INET6 : AF_INET;

  // Create UDP socket for STUN probe
  const char *socket_name = stun_family == AF_INET6 ? "probe_ipv6" : "probe_ipv4";
  socket_t sock = socket_create(socket_name, stun_family, SOCK_DGRAM, 0);
  if (sock == INVALID_SOCKET_VALUE) {
    log_warn("Failed to create UDP socket for STUN probe");
    return SET_ERRNO(ERROR_NETWORK, "Cannot create UDP socket");
  }

  // Set timeout on socket
  socket_set_timeout(sock, 5000 * NS_PER_MS_INT); // 5 second timeout

  // Resolve STUN server hostname
  struct addrinfo hints = {0};
  hints.ai_family = stun_family;
  hints.ai_socktype = SOCK_DGRAM;

  struct addrinfo *result = NULL;
  char port_str[16];
  safe_snprintf(port_str, sizeof(port_str), "%u", stun_port);

  int ret = getaddrinfo(host_buf, port_str, &hints, &result);
  if (ret != 0) {
    log_warn("Failed to resolve STUN server %s: %s", host_buf, gai_strerror(ret));
    socket_close(sock);
    return SET_ERRNO(ERROR_NETWORK_CONNECT, "Cannot resolve STUN server hostname");
  }

  // Build minimal STUN binding request (RFC 5389)
  // Header: Magic (0x2112A442) + Transaction ID (96 bits)
  uint8_t stun_request[20];
  stun_request[0] = 0x00; // Message type: Binding Request (0x0001), bits split
  stun_request[1] = 0x01;
  stun_request[2] = 0x00; // Message length: 0 (no attributes for simple probe)
  stun_request[3] = 0x00;

  // Magic cookie (STUN magic number)
  stun_request[4] = 0x21;
  stun_request[5] = 0x12;
  stun_request[6] = 0xa4;
  stun_request[7] = 0x42;

  // Transaction ID (96 bits) - use simple pattern for MVP
  memset(stun_request + 8, 0xAA, 12);

  // Send STUN binding request
  uint64_t start_time = time_get_ns();
  ssize_t sent = socket_sendto(sock, stun_request, sizeof(stun_request), 0, result->ai_addr, result->ai_addrlen);

  if (sent < 0) {
    log_warn("Failed to send STUN request");
    freeaddrinfo(result);
    socket_close(sock);
    return SET_ERRNO(ERROR_NETWORK, "Cannot send STUN request");
  }

  // Receive STUN response
  uint8_t stun_response[512];
  struct sockaddr_in peer_addr;
  socklen_t peer_addr_len = sizeof(peer_addr);

  ssize_t recv_len =
      socket_recvfrom(sock, stun_response, sizeof(stun_response), 0, (struct sockaddr *)&peer_addr, &peer_addr_len);

  uint64_t end_time = time_get_ns();
  uint32_t rtt_ms = (uint32_t)(time_ns_to_ms(end_time - start_time));

  freeaddrinfo(result);
  socket_close(sock);

  if (recv_len < 20) {
    log_warn("STUN response too short or timeout");
    return SET_ERRNO(ERROR_NETWORK_TIMEOUT, "STUN server did not respond");
  }

  // Parse STUN response to extract reflexive address
  char reflexive_addr[64] = {0};
  uint16_t reflexive_port = 0;
  asciichat_error_t parse_result =
      nat_parse_stun_response(stun_response, (size_t)recv_len, reflexive_addr, &reflexive_port);

  if (parse_result != ASCIICHAT_OK) {
    log_warn("Failed to parse STUN response");
    return parse_result;
  }

  SAFE_STRNCPY(quality->public_address, reflexive_addr, sizeof(quality->public_address));
  quality->public_port = reflexive_port;
  quality->stun_latency_ns = (uint64_t)rtt_ms * NS_PER_MS_INT;

  log_info("STUN probe successful: reflexive_address=%s:%u, rtt=%u ms", reflexive_addr, reflexive_port, rtt_ms);

  return ASCIICHAT_OK;
}

asciichat_error_t nat_detect_quality(nat_quality_t *quality, const char *stun_server, uint16_t local_port) {
  if (!quality) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "quality is NULL");
  }

  nat_quality_init(quality);
  log_info("Starting NAT quality detection (local_port=%u)", local_port);

  // Quality probes run before a listener exists (often with port zero).
  // Only the listening server lifecycle may create, renew, and remove mappings.

  // Probe STUN when configured.
  if (stun_server && stun_server[0]) {
    asciichat_error_t stun_result = nat_stun_probe(quality, stun_server, local_port);
    if (stun_result == ASCIICHAT_OK) {
      // Successfully got reflexive address via STUN
      quality->has_srflx_candidates = true;

      // A server-reflexive address demonstrates STUN reachability, not a public
      // interface or NAT classification. Those require separate observations.
      quality->has_public_ip = false;

    } else {
      log_debug("STUN probe failed, falling back to symmetric NAT assumption");
    }
  }

  // Set ICE candidate flags based on what we found
  quality->has_host_candidates = true; // We always have local IP
  quality->has_srflx_candidates = quality->upnp_available || quality->has_public_ip || quality->has_srflx_candidates;

  // Check if TURN relay servers are available (configured via options or ACDS)
  const options_t *opts = options_get();
  const char *turn_servers = opts ? opts->turn_servers : NULL;
  quality->has_relay_candidates = (turn_servers && turn_servers[0] != '\0');
  if (quality->has_relay_candidates) {
    log_debug("TURN relay servers configured: %s", turn_servers);
  }

  quality->detection_complete = true;
  log_info("NAT detection complete: tier=%d, upnp=%d, has_public_ip=%d, nat_type=%s", nat_compute_tier(quality),
           quality->upnp_available, quality->has_public_ip, nat_type_to_string(quality->nat_type));

  return ASCIICHAT_OK;
}

asciichat_error_t nat_measure_bandwidth(nat_quality_t *quality, socket_t acds_socket) {
  if (!quality) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "quality is NULL");
  }
  if (acds_socket == INVALID_SOCKET_VALUE) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "invalid socket");
  }

  // Prepare bandwidth test packet
  acip_bandwidth_test_t test_msg = {0};
  memset(test_msg.session_id, 0, sizeof(test_msg.session_id)); // Anonymous test
  memset(test_msg.participant_id, 0, sizeof(test_msg.participant_id));
  test_msg.test_size_bytes = 65536; // 64KB test payload
  test_msg.client_send_time_ns = time_get_ns();

  // Send BANDWIDTH_TEST packet
  asciichat_error_t result = packet_send(acds_socket, PACKET_TYPE_ACIP_BANDWIDTH_TEST, &test_msg, sizeof(test_msg));
  if (result != ASCIICHAT_OK) {
    log_warn("Failed to send bandwidth test packet");
    return result;
  }

  // Send test payload (64KB of data)
  uint8_t *test_data = SAFE_MALLOC(test_msg.test_size_bytes, uint8_t *);
  if (!test_data) {
    return SET_ERRNO(ERROR_MEMORY, "Failed to allocate bandwidth test payload");
  }
  memset(test_data, 0xAA, test_msg.test_size_bytes); // Fill with pattern

  ssize_t sent = send(acds_socket, (const char *)test_data, test_msg.test_size_bytes, 0);
  SAFE_FREE(test_data);

  if (sent != (ssize_t)test_msg.test_size_bytes) {
    log_warn("Failed to send bandwidth test payload: sent=%zd, expected=%u", sent, test_msg.test_size_bytes);
    return SET_ERRNO(ERROR_NETWORK, "Bandwidth test payload send failed");
  }

  log_debug("Sent bandwidth test with %u bytes", test_msg.test_size_bytes);

  // Set socket timeout for response (5 seconds)
  if (socket_set_timeout(acds_socket, 5 * NS_PER_SEC_INT) != 0) {
    log_warn("Failed to set socket timeout for bandwidth test");
    return SET_ERRNO(ERROR_NETWORK, "Failed to set socket timeout");
  }

  // Wait for BANDWIDTH_RESULT response
  packet_type_t response_type;
  void *response_data = NULL;
  size_t response_len = 0;

  result = packet_receive(acds_socket, &response_type, &response_data, &response_len);

  if (result != ASCIICHAT_OK) {
    log_warn("Bandwidth test timeout or receive failed");
    return SET_ERRNO(ERROR_NETWORK_TIMEOUT, "No bandwidth test response from ACDS");
  }

  if (response_type != PACKET_TYPE_ACIP_BANDWIDTH_RESULT) {
    buffer_release(response_data);
    log_warn("Unexpected packet type %d (expected BANDWIDTH_RESULT)", response_type);
    return SET_ERRNO(ERROR_NETWORK_PROTOCOL, "Wrong packet type in bandwidth test response");
  }

  if (response_len != sizeof(acip_bandwidth_result_t)) {
    buffer_release(response_data);
    return SET_ERRNO(ERROR_NETWORK_PROTOCOL, "Invalid bandwidth result size");
  }

  // Parse results
  acip_bandwidth_result_t *results = (acip_bandwidth_result_t *)response_data;
  quality->upload_kbps = results->measured_upload_kbps;
  quality->download_kbps = results->measured_download_kbps;
  quality->rtt_to_acds_ns = results->rtt_ns;
  quality->jitter_ns = results->jitter_ns;
  quality->packet_loss_pct = results->packet_loss_pct;

  buffer_release(response_data);

  log_debug("Bandwidth measurement: upload=%u kbps, download=%u kbps, rtt=%lu ns", quality->upload_kbps,
            quality->download_kbps, quality->rtt_to_acds_ns);

  return ASCIICHAT_OK;
}

void nat_quality_to_acip(const nat_quality_t *quality, const uint8_t session_id[16], const uint8_t participant_id[16],
                         acip_nat_quality_t *out) {
  if (!quality || !out)
    return;

  memset(out, 0, sizeof(acip_nat_quality_t));

  if (session_id)
    memcpy(out->session_id, session_id, 16);
  if (participant_id)
    memcpy(out->participant_id, participant_id, 16);

  out->has_public_ip = quality->has_public_ip ? 1 : 0;
  out->upnp_available = quality->upnp_available ? 1 : 0;
  out->upnp_mapped_port[0] = (uint8_t)(quality->upnp_mapped_port >> 8);
  out->upnp_mapped_port[1] = (uint8_t)(quality->upnp_mapped_port & 0xFF);
  out->stun_nat_type = (uint8_t)quality->nat_type;
  out->lan_reachable = quality->lan_reachable ? 1 : 0;
  out->stun_latency_ns = quality->stun_latency_ns;

  out->upload_kbps = quality->upload_kbps;
  out->download_kbps = quality->download_kbps;
  out->rtt_to_acds_ns = quality->rtt_to_acds_ns;
  out->jitter_ns = quality->jitter_ns;
  out->packet_loss_pct = quality->packet_loss_pct;

  SAFE_STRNCPY(out->public_address, quality->public_address, sizeof(out->public_address));
  out->public_port = quality->public_port;

  out->ice_candidate_types = 0;
  if (quality->has_host_candidates)
    out->ice_candidate_types |= 1;
  if (quality->has_srflx_candidates)
    out->ice_candidate_types |= 2;
  if (quality->has_relay_candidates)
    out->ice_candidate_types |= 4;
}

void nat_quality_from_acip(const acip_nat_quality_t *acip, nat_quality_t *out) {
  if (!acip || !out)
    return;

  nat_quality_init(out);

  out->has_public_ip = acip->has_public_ip != 0;
  out->upnp_available = acip->upnp_available != 0;
  out->upnp_mapped_port = ((uint16_t)acip->upnp_mapped_port[0] << 8) | acip->upnp_mapped_port[1];
  out->nat_type = (acip_nat_type_t)acip->stun_nat_type;
  out->lan_reachable = acip->lan_reachable != 0;
  out->stun_latency_ns = acip->stun_latency_ns;

  out->upload_kbps = acip->upload_kbps;
  out->download_kbps = acip->download_kbps;
  out->rtt_to_acds_ns = acip->rtt_to_acds_ns;
  out->jitter_ns = acip->jitter_ns;
  out->packet_loss_pct = acip->packet_loss_pct;

  SAFE_STRNCPY(out->public_address, acip->public_address, sizeof(out->public_address));
  out->public_port = acip->public_port;

  out->has_host_candidates = (acip->ice_candidate_types & 1) != 0;
  out->has_srflx_candidates = (acip->ice_candidate_types & 2) != 0;
  out->has_relay_candidates = (acip->ice_candidate_types & 4) != 0;

  out->detection_complete = true;
}

const char *nat_type_to_string(acip_nat_type_t type) {
  switch (type) {
  case ACIP_NAT_TYPE_OPEN:
    return "Open (Public IP)";
  case ACIP_NAT_TYPE_FULL_CONE:
    return "Full Cone";
  case ACIP_NAT_TYPE_RESTRICTED:
    return "Restricted Cone";
  case ACIP_NAT_TYPE_PORT_RESTRICTED:
    return "Port Restricted";
  case ACIP_NAT_TYPE_SYMMETRIC:
    return "Symmetric";
  default:
    return "Unknown";
  }
}

