static void acip_server_on_error(const error_packet_t *header, const char *message, void *client_ctx, void *app_ctx) {
  (void)app_ctx;
  client_info_t *client = (client_info_t *)client_ctx;

  // Reconstruct full packet for existing handler
  size_t msg_len = strlen(message);
  size_t total_len = sizeof(*header) + msg_len;
  uint8_t *full_packet = SAFE_MALLOC(total_len, uint8_t *);
  if (!full_packet) {
    log_error("Failed to allocate buffer for ERROR_MESSAGE reconstruction");
    return;
  }

  memcpy(full_packet, header, sizeof(*header));
  // NOLINTNEXTLINE(bugprone-not-null-terminated-result) - binary packet data, not string
  memcpy(full_packet + sizeof(*header), message, msg_len);

  handle_client_error_packet(client, full_packet, total_len);
  SAFE_FREE(full_packet);
}

static void acip_server_on_remote_log(const remote_log_packet_t *header, const char *message, void *client_ctx,
                                      void *app_ctx) {
  (void)app_ctx;
  client_info_t *client = (client_info_t *)client_ctx;

  // Reconstruct full packet for existing handler
  size_t msg_len = strlen(message);
  size_t total_len = sizeof(*header) + msg_len;
  uint8_t *full_packet = SAFE_MALLOC(total_len, uint8_t *);
  if (!full_packet) {
    log_error("Failed to allocate buffer for REMOTE_LOG reconstruction");
    return;
  }

  memcpy(full_packet, header, sizeof(*header));
  // NOLINTNEXTLINE(bugprone-not-null-terminated-result) - binary packet data, not string
  memcpy(full_packet + sizeof(*header), message, msg_len);

  handle_remote_log_packet_from_client(client, full_packet, total_len);
  SAFE_FREE(full_packet);
}

static void acip_server_on_crypto_rekey_request(const void *payload, size_t payload_len, void *client_ctx,
                                                void *app_ctx) {
  (void)app_ctx;
  client_info_t *client = (client_info_t *)client_ctx;

  log_debug("Received REKEY_REQUEST from client %s", client->client_id);

  // Process the client's rekey request
  mutex_lock(&client->client_state_mutex);
  asciichat_error_t crypto_result =
      crypto_handshake_process_rekey_request(&client->crypto_handshake_ctx, (void *)payload, payload_len);
  mutex_unlock(&client->client_state_mutex);

  if (crypto_result != ASCIICHAT_OK) {
    log_error("Failed to process REKEY_REQUEST from client %s: %d", client->client_id, crypto_result);
    return;
  }

  // Send REKEY_RESPONSE
  mutex_lock(&client->client_state_mutex);
  // Get transport reference briefly to avoid deadlock on transport buffers
  mutex_lock(&client->send_mutex);
  if (atomic_load_bool(&client->shutting_down) || !client->transport) {
    mutex_unlock(&client->send_mutex);
    mutex_unlock(&client->client_state_mutex);
    return; // Client is shutting down
  }
  acip_transport_t *rekey_transport = client->transport;
  mutex_unlock(&client->send_mutex);

  // Network I/O happens OUTSIDE the send_mutex (client_state_mutex still held for crypto state)
  crypto_result = crypto_handshake_rekey_response(&client->crypto_handshake_ctx, rekey_transport);
  mutex_unlock(&client->client_state_mutex);

  if (crypto_result != ASCIICHAT_OK) {
    log_error("Failed to send REKEY_RESPONSE to client %s: %d", client->client_id, crypto_result);
  } else {
    log_debug("Sent REKEY_RESPONSE to client %s", client->client_id);
  }
}

static void acip_server_on_crypto_rekey_response(const void *payload, size_t payload_len, void *client_ctx,
                                                 void *app_ctx) {
  (void)app_ctx;
  client_info_t *client = (client_info_t *)client_ctx;

  log_debug("Received REKEY_RESPONSE from client %s", client->client_id);

  // Process the client's rekey response
  mutex_lock(&client->client_state_mutex);
  asciichat_error_t crypto_result =
      crypto_handshake_process_rekey_response(&client->crypto_handshake_ctx, (void *)payload, payload_len);
  mutex_unlock(&client->client_state_mutex);

  if (crypto_result != ASCIICHAT_OK) {
    log_error("Failed to process REKEY_RESPONSE from client %s: %d", client->client_id, crypto_result);
    return;
  }

  // Send REKEY_COMPLETE to confirm and activate new key
  mutex_lock(&client->client_state_mutex);
  // Get transport reference briefly to avoid deadlock on transport buffers
  mutex_lock(&client->send_mutex);
  if (atomic_load_bool(&client->shutting_down) || !client->transport) {
    mutex_unlock(&client->send_mutex);
    mutex_unlock(&client->client_state_mutex);
    return; // Client is shutting down
  }
  acip_transport_t *complete_transport = client->transport;
  mutex_unlock(&client->send_mutex);

  // Network I/O happens OUTSIDE the send_mutex (client_state_mutex still held for crypto state)
  crypto_result = crypto_handshake_rekey_complete(&client->crypto_handshake_ctx, complete_transport);
  mutex_unlock(&client->client_state_mutex);

  if (crypto_result != ASCIICHAT_OK) {
    log_error("Failed to send REKEY_COMPLETE to client %s: %d", client->client_id, crypto_result);
  } else {
    log_debug("Sent REKEY_COMPLETE to client %s - session rekeying complete", client->client_id);
  }
}

static void acip_server_on_crypto_rekey_complete(const void *payload, size_t payload_len, void *client_ctx,
                                                 void *app_ctx) {
  (void)app_ctx;
  client_info_t *client = (client_info_t *)client_ctx;

  log_debug("Received REKEY_COMPLETE from client %s", client->client_id);

  // Process and commit to new key
  mutex_lock(&client->client_state_mutex);
  asciichat_error_t crypto_result =
      crypto_handshake_process_rekey_complete(&client->crypto_handshake_ctx, (void *)payload, payload_len);
  mutex_unlock(&client->client_state_mutex);

  if (crypto_result != ASCIICHAT_OK) {
    log_error("Failed to process REKEY_COMPLETE from client %s: %d", client->client_id, crypto_result);
  } else {
    log_debug("Session rekeying completed successfully with client %s", client->client_id);
    // Notify client that rekeying is complete (new keys now active on both sides)
    log_info_client(client, "Session rekey complete - new encryption keys active");
  }
}

static void acip_server_on_crypto_key_exchange_resp(packet_type_t type, const void *payload, size_t payload_len,
                                                    void *client_ctx, void *app_ctx) {
  (void)app_ctx;
  client_info_t *client = (client_info_t *)client_ctx;

  log_debug("Received CRYPTO_KEY_EXCHANGE_RESP from client %s", client->client_id);

  // Call refactored handshake function from Phase 2
  asciichat_error_t result = crypto_handshake_server_auth_challenge(&client->crypto_handshake_ctx, client->transport,
                                                                    type, payload, payload_len);

  if (result != ASCIICHAT_OK) {
    log_error("Crypto handshake auth challenge failed for client %s", client->client_id);
    disconnect_client_for_bad_data(client, "Crypto handshake auth challenge failed");
  } else {
    // Check if handshake completed (no-auth flow) or if AUTH_CHALLENGE was sent (with-auth flow)
    if (client->crypto_handshake_ctx.state == CRYPTO_HANDSHAKE_READY) {
      // No-auth flow: handshake complete, HANDSHAKE_COMPLETE was sent
      log_info("Crypto handshake completed successfully for client %s (no authentication)", client->client_id);
      client->crypto_initialized = true;
      client->transport->crypto_ctx = &client->crypto_handshake_ctx.crypto_ctx;
    } else {
      // With-auth flow: AUTH_CHALLENGE was sent, waiting for AUTH_RESPONSE
      log_debug("Sent AUTH_CHALLENGE to client %s", client->client_id);
    }
  }
}

static void acip_server_on_crypto_auth_response(packet_type_t type, const void *payload, size_t payload_len,
                                                void *client_ctx, void *app_ctx) {
  (void)app_ctx;
  client_info_t *client = (client_info_t *)client_ctx;

  log_debug("Received CRYPTO_AUTH_RESPONSE from client %s", client->client_id);

  // Call refactored handshake function from Phase 2
  asciichat_error_t result =
      crypto_handshake_server_complete(&client->crypto_handshake_ctx, client->transport, type, payload, payload_len);

  if (result != ASCIICHAT_OK) {
    log_error("Crypto handshake complete failed for client %s", client->client_id);
    disconnect_client_for_bad_data(client, "Crypto handshake complete failed");
  } else {
    log_info("Crypto handshake completed successfully for client %s", client->client_id);
    log_error("[CRYPTO_SETUP] Setting crypto context for client %s: transport=%p, crypto_ctx=%p", client->client_id,
              (void *)client->transport, (void *)&client->crypto_handshake_ctx.crypto_ctx);
    client->crypto_initialized = true;
    client->transport->crypto_ctx = &client->crypto_handshake_ctx.crypto_ctx;
    log_error("[CRYPTO_SETUP] Crypto context SET: transport->crypto_ctx=%p", (void *)client->transport->crypto_ctx);
  }
}

static void acip_server_on_crypto_no_encryption(packet_type_t type, const void *payload, size_t payload_len,
                                                void *client_ctx, void *app_ctx) {
  (void)app_ctx;
  (void)type;
  (void)payload;
  (void)payload_len;
  client_info_t *client = (client_info_t *)client_ctx;

  log_error("Client %s sent NO_ENCRYPTION - encryption mode mismatch", client->client_id);
  disconnect_client_for_bad_data(client, "Encryption mode mismatch - server requires encryption");
}

void process_decrypted_packet(client_info_t *client, packet_type_t type, void *data, size_t len) {
  if (type == 5000) { // CLIENT_CAPABILITIES
    log_debug("CLIENT: client_id=%s, data=%p, len=%zu", client->client_id, data, len);
  }

  // Rate limiting: Check and record packet-specific rate limits
  if (g_rate_limiter) {
    bool allowed = false;
    asciichat_errno_scope_t limit_scope = asciichat_errno_scope_begin();
    asciichat_error_t result = check_and_record_packet_rate_limit(g_rate_limiter, client->client_ip, type, &allowed);
    if (result != ASCIICHAT_OK || !allowed) {
      if (result == ASCIICHAT_OK)
        SET_ERRNO(ERROR_RATE_LIMITED, "Packet quota exceeded");
      LOG_ERRNO_IF_SET("Packet rate-limit enforcement rejected client");
      asciichat_errno_scope_t notify_scope = asciichat_errno_scope_begin();
      mutex_lock(&client->send_mutex);
      asciichat_error_t sent =
          acip_send_error(client->transport, result == ASCIICHAT_OK ? ERROR_RATE_LIMITED : ERROR_INTERNAL, NULL);
      mutex_unlock(&client->send_mutex);
      if (sent != ASCIICHAT_OK)
        LOG_ERRNO_IF_SET("Could not notify client about rate-limit decision");
      asciichat_errno_scope_end(notify_scope, ASCIICHAT_ERRNO_HANDLED);
      if (result == ASCIICHAT_OK)
        asciichat_errno_scope_end(limit_scope, ASCIICHAT_ERRNO_HANDLED);
      atomic_store_bool(&client->active, false);
      return;
    }
    ASSERT_NO_ERRNO_SINCE(limit_scope);
    asciichat_errno_scope_end(limit_scope, ASCIICHAT_ERRNO_HANDLED);
  }

  // O(1) dispatch via hash table lookup
  int idx = client_dispatch_hash_lookup(g_client_dispatch_hash, type);
  if (type == 5000 || type == 3001) {
    log_error("DISPATCH_LOOKUP: type=%d, idx=%d (len=%zu)", type, idx, len);
  }
  if (idx < 0) {
    disconnect_client_for_bad_data(client, "Unknown packet type: %d (len=%zu)", type, len);
    return;
  }

  if (type == 5000 || type == 3001) {
    log_error("DISPATCH_HANDLER: type=%d, calling handler[%d]...", type, idx);
  }
  g_client_dispatch_handlers[idx](client, data, len);
  if (type == 5000 || type == 3001) {
    log_error("DISPATCH_HANDLER: type=%d, handler returned", type);
  }
}

int server_crypto_init(void) {
  // Only skip handshake if BOTH encryption and authentication are disabled
  bool no_encrypt = GET_OPTION(no_encrypt);
  bool no_auth = GET_OPTION(no_auth);

  if (no_encrypt && no_auth) {
    log_info("ACIP handshake disabled (both encryption and authentication disabled)");
    return 0;
  }

  log_debug("Server crypto system initialized (per-client contexts will be created on demand)");
  return 0;
}

asciichat_error_t server_crypto_event(client_info_t *client, unsigned *step, packet_type_t type, const void *payload,
                                      size_t length, bool *ready) {
  *ready = false;
  crypto_handshake_context_t *ctx = &client->crypto_handshake_ctx;
  acip_transport_t *transport = client->transport;
  asciichat_error_t result = ASCIICHAT_OK;
  if (*step == 0) {
    if (type != PACKET_TYPE_PROTOCOL_VERSION || length != sizeof(protocol_version_packet_t))
      return SET_ERRNO(ERROR_NETWORK_PROTOCOL, "Expected protocol version before application traffic");
    protocol_version_packet_t version;
    memcpy(&version, payload, sizeof(version));
    uint8_t mode = version.supports_encryption;
    if (mode > ACIP_CRYPTO_FULL || NET_TO_HOST_U16(version.protocol_version) != 1)
      return SET_ERRNO(ERROR_CRYPTO, "Unsupported crypto mode or protocol version");
    bool requires_auth = GET_OPTION(password)[0] || g_num_whitelisted_clients || GET_OPTION(require_server_verify);
    if (requires_auth && !ACIP_CRYPTO_HAS_AUTH(mode))
      return SET_ERRNO(ERROR_CRYPTO_AUTH, "Server requires authentication");
    if ((GET_OPTION(encrypt_enabled) && !ACIP_CRYPTO_HAS_ENCRYPT(mode)) ||
        (GET_OPTION(no_encrypt) && ACIP_CRYPTO_HAS_ENCRYPT(mode)))
      return SET_ERRNO(ERROR_CRYPTO, "Requested encryption conflicts with server policy");
    if (!client->transport_encrypted && !GET_OPTION(no_encrypt) && !ACIP_CRYPTO_HAS_ENCRYPT(mode))
      return SET_ERRNO(ERROR_CRYPTO, "Plain transports require encryption unless --no-encrypt is explicit");
    if (mode == ACIP_CRYPTO_NONE) {
      result = packet_send_via_transport(transport, PACKET_TYPE_PROTOCOL_VERSION, &version, sizeof(version), 0);
      client->security_ready = result == ASCIICHAT_OK;
      *ready = client->security_ready;
      *step = 5;
      return result;
    }
    const options_t *opts = options_get();
    const char *password = opts ? opts->password : "";
    result = password[0] ? crypto_handshake_init_with_password("server_async", ctx, true, password)
                         : crypto_handshake_init("server_async", ctx, true);
    if (result != ASCIICHAT_OK)
      return result;
    client->encrypt_data = ACIP_CRYPTO_HAS_ENCRYPT(version.supports_encryption);
    if (g_server_encryption_enabled && g_server_private_key.type == KEY_TYPE_ED25519) {
      ctx->server_private_key = g_server_private_key;
      ctx->server_public_key.type = KEY_TYPE_ED25519;
      memcpy(ctx->server_public_key.key, g_server_private_key.public_key, sizeof(g_server_private_key.public_key));
    }
    ctx->require_client_auth = g_num_whitelisted_clients > 0 || GET_OPTION(require_server_verify);
    ctx->client_whitelist = g_client_whitelist;
    ctx->num_whitelisted_clients = g_num_whitelisted_clients;
    version.protocol_version = HOST_TO_NET_U16(1);
    version.protocol_revision = 0;
    version.compression_algorithms = 0;
    version.compression_threshold = 0;
    version.feature_flags = HOST_TO_NET_U16(PROTOCOL_FEATURE_RECOVERABLE_ERRORS);
    result = packet_send_via_transport(transport, PACKET_TYPE_PROTOCOL_VERSION, &version, sizeof(version), 0);
    *step = 1;
    return result;
  }
  if (*step == 1) {
    if (type != PACKET_TYPE_CRYPTO_CAPABILITIES || length != sizeof(crypto_capabilities_packet_t))
      return SET_ERRNO(ERROR_NETWORK_PROTOCOL, "Expected crypto capabilities");
    crypto_capabilities_packet_t capabilities;
    memcpy(&capabilities, payload, sizeof(capabilities));
    crypto_parameters_packet_t parameters = {0};
    parameters.selected_kex = KEX_ALGO_X25519;
    parameters.selected_cipher = client->encrypt_data ? CIPHER_ALGO_XSALSA20_POLY1305 : CIPHER_ALGO_NONE;
    parameters.selected_auth = g_server_encryption_enabled && g_server_private_key.type == KEY_TYPE_ED25519
                                   ? AUTH_ALGO_ED25519
                                   : AUTH_ALGO_NONE;
    parameters.verification_enabled = g_num_whitelisted_clients > 0;
    parameters.kex_public_key_size = CRYPTO_PUBLIC_KEY_SIZE;
    parameters.shared_secret_size = CRYPTO_PUBLIC_KEY_SIZE;
    parameters.nonce_size = CRYPTO_NONCE_SIZE;
    parameters.mac_size = CRYPTO_MAC_SIZE;
    parameters.hmac_size = CRYPTO_HMAC_SIZE;
    if (parameters.selected_auth == AUTH_ALGO_ED25519) {
      parameters.auth_public_key_size = ED25519_PUBLIC_KEY_SIZE;
      parameters.signature_size = ED25519_SIGNATURE_SIZE;
    }
    result = crypto_handshake_set_parameters(ctx, &parameters);
    if (result != ASCIICHAT_OK)
      return result;
    parameters.kex_public_key_size = HOST_TO_NET_U16(parameters.kex_public_key_size);
    parameters.auth_public_key_size = HOST_TO_NET_U16(parameters.auth_public_key_size);
    parameters.signature_size = HOST_TO_NET_U16(parameters.signature_size);
    parameters.shared_secret_size = HOST_TO_NET_U16(parameters.shared_secret_size);
    result = packet_send_via_transport(transport, PACKET_TYPE_CRYPTO_PARAMETERS, &parameters, sizeof(parameters), 0);
    if (result != ASCIICHAT_OK)
      return result;
    if (g_num_server_identity_keys > 0 && capabilities.requires_verification) {
      *step = 2;
      return ASCIICHAT_OK;
    }
    *step = 3;
    return crypto_handshake_server_start(ctx, transport);
  }
  if (*step == 2) {
    if (type != PACKET_TYPE_CRYPTO_CLIENT_HELLO) {
      if (g_num_server_identity_keys != 1 || type != PACKET_TYPE_CRYPTO_KEY_EXCHANGE_RESP)
        return SET_ERRNO(ERROR_CRYPTO, "Expected pinned server identity");
      // Keep this packet for the key-exchange step after sending the default key.
      ctx->server_private_key = g_server_identity_keys[0];
      ctx->server_public_key.type = KEY_TYPE_ED25519;
      memcpy(ctx->server_public_key.key, g_server_identity_keys[0].public_key,
             sizeof(g_server_identity_keys[0].public_key));
      result = crypto_handshake_server_start(ctx, transport);
      if (result != ASCIICHAT_OK)
        return result;
      *step = 3;
    } else {
      if (length != ED25519_PUBLIC_KEY_SIZE)
        return SET_ERRNO(ERROR_CRYPTO, "Expected pinned server identity");
      bool found = false;
      for (size_t i = 0; i < g_num_server_identity_keys; ++i) {
        if (sodium_memcmp(payload, g_server_identity_keys[i].public_key, ED25519_PUBLIC_KEY_SIZE) == 0) {
          ctx->server_private_key = g_server_identity_keys[i];
          ctx->server_public_key.type = KEY_TYPE_ED25519;
          memcpy(ctx->server_public_key.key, g_server_identity_keys[i].public_key,
                 sizeof(g_server_identity_keys[i].public_key));
          found = true;
          break;
        }
      }
      if (!found)
        return SET_ERRNO(ERROR_CRYPTO, "Unknown pinned server identity");
      *step = 3;
      return crypto_handshake_server_start(ctx, transport);
    }
  }
  if (*step == 3) {
    result = crypto_handshake_server_auth_challenge(ctx, transport, type, payload, length);
    *step = 4;
  } else if (*step == 4) {
    result = crypto_handshake_server_complete(ctx, transport, type, payload, length);
  } else {
    return SET_ERRNO(ERROR_INVALID_STATE, "Unexpected server handshake step");
  }
  if (result == ASCIICHAT_OK && ctx->state == CRYPTO_HANDSHAKE_READY) {
    client->crypto_initialized = true;
    client->security_ready = true;
    ctx->crypto_ctx.encrypt_data = client->encrypt_data;
    transport->crypto_ctx = (crypto_context_t *)crypto_handshake_get_context(ctx);
    *ready = true;
    *step = 5;
  }
  return result;
}

bool crypto_server_is_ready(const char *client_id) {
  client_info_t *client = find_client_by_id(client_id);
  if (!client) {
    return false;
  }

  if (!client->crypto_initialized) {
    return false;
  }

  bool ready = crypto_handshake_is_ready(&client->crypto_handshake_ctx);
  return ready;
}

const crypto_context_t *crypto_server_get_context(const char *client_id) {
  if (!crypto_server_is_ready(client_id)) {
    return NULL;
  }

  client_info_t *client = find_client_by_id(client_id);
  if (!client) {
    return NULL;
  }

  return crypto_handshake_get_context(&client->crypto_handshake_ctx);
}

int crypto_server_encrypt_packet(const char *client_id, const uint8_t *plaintext, size_t plaintext_len,
                                 uint8_t *ciphertext, size_t ciphertext_size, size_t *ciphertext_len) {
  client_info_t *client = find_client_by_id(client_id);
  if (!client) {
    return -1;
  }

  return crypto_encrypt_packet_or_passthrough(&client->crypto_handshake_ctx, crypto_server_is_ready(client_id),
                                              plaintext, plaintext_len, ciphertext, ciphertext_size, ciphertext_len);
}

int crypto_server_decrypt_packet(const char *client_id, const uint8_t *ciphertext, size_t ciphertext_len,
                                 uint8_t *plaintext, size_t plaintext_size, size_t *plaintext_len) {
  client_info_t *client = find_client_by_id(client_id);
  if (!client) {
    return -1;
  }

  return crypto_decrypt_packet_or_passthrough(&client->crypto_handshake_ctx, crypto_server_is_ready(client_id),
                                              ciphertext, ciphertext_len, plaintext, plaintext_size, plaintext_len);
}

void crypto_server_cleanup_client(const char *client_id) {
  client_info_t *client = find_client_by_id(client_id);
  if (!client) {
    return;
  }

  if (client->crypto_initialized) {
    crypto_handshake_destroy(&client->crypto_handshake_ctx);
    client->crypto_initialized = false;
    log_debug("Crypto handshake cleaned up for client %s", client_id);
  }
}

static asciichat_error_t check_connection(server_event_connection_t *connection) {
  rate_limiter_t *limiter = connection->server->rate_limiter;
  if (limiter) {
    bool allowed = false;
    asciichat_error_t result = rate_limiter_check(limiter, connection->ip, RATE_EVENT_CONNECTION, NULL, &allowed);
    if (result != ASCIICHAT_OK)
      return result;
    if (!allowed)
      return SET_ERRNO(ERROR_RATE_LIMITED, "Connection rate limit exceeded");
    result = rate_limiter_record(limiter, connection->ip, RATE_EVENT_CONNECTION);
    if (result != ASCIICHAT_OK)
      return result;
  }
  return ASCIICHAT_OK;
}

static void admit_connection(void *arg) {
  server_event_connection_t *connection = arg;
  connection->result = check_connection(connection);
}

static asciichat_error_t consume_packet(const void *data, size_t length, void *arg) {
  server_event_connection_t *connection = arg;
  if (!connection->client) {
    connection->client = add_transport_client(connection->server, connection->transport, connection->ip, false);
    if (!connection->client)
      return SET_ERRNO(ERROR_SESSION_FULL, "Cannot admit event client");
  }
  client_info_t *client = connection->client;
  packet_header_t header;
  memcpy(&header, data, sizeof(header));
  packet_type_t type = NET_TO_HOST_U16(header.type);
  const void *payload = (const uint8_t *)data + sizeof(header);
  size_t size = length - sizeof(header);
  connection->packet_received = true;
  if (!connection->ready) {
    asciichat_error_t result =
        server_crypto_event(client, &connection->handshake_step, type, payload, size, &connection->ready);
    if (result != ASCIICHAT_OK || type != PACKET_TYPE_CLIENT_CAPABILITIES)
      return result;
  }
  packet_envelope_t envelope = {.type = type, .data = (void *)payload, .len = size};
  asciichat_error_t result = ASCIICHAT_OK;
  mutex_lock(&client->client_state_mutex);
  if (type == PACKET_TYPE_ENCRYPTED) {
    envelope.allocated_buffer = buffer_alloc(NULL, length);
    envelope.allocated_size = length;
    if (!envelope.allocated_buffer) {
      mutex_unlock(&client->client_state_mutex);
      return SET_ERRNO(ERROR_MEMORY, "Cannot allocate received packet");
    }
    memcpy(envelope.allocated_buffer, data, length);
    envelope.data = (uint8_t *)envelope.allocated_buffer + sizeof(header);
    result = packet_decrypt_envelope(&envelope, client->transport->crypto_ctx);
    if (result == ASCIICHAT_OK) {
      packet_header_t inner;
      memcpy(&inner, envelope.allocated_buffer, sizeof(inner));
      if (NET_TO_HOST_U64(inner.magic) != PACKET_MAGIC ||
          (envelope.len && asciichat_crc32(envelope.data, envelope.len) != NET_TO_HOST_U32(inner.crc32)))
        result = SET_ERRNO(ERROR_NETWORK_PROTOCOL, "Invalid decrypted packet");
    }
  } else if (client->encrypt_data && !packet_is_handshake_type(type)) {
    result = SET_ERRNO(ERROR_CRYPTO, "Plaintext application packet on encrypted connection");
  }
  mutex_unlock(&client->client_state_mutex);
  if (result == ASCIICHAT_OK && !connection->capabilities) {
    if (envelope.type != PACKET_TYPE_CLIENT_CAPABILITIES) {
      result = SET_ERRNO(ERROR_NETWORK_PROTOCOL, "Expected initial client capabilities");
    } else {
      handle_client_capabilities_packet(client, envelope.data, envelope.len);
      connection->capabilities = true;
      if (start_transport_client_threads(connection->server, client->client_id) != 0)
        result = SET_ERRNO(ERROR_THREAD, "Cannot start client rendering");
    }
  } else if (result == ASCIICHAT_OK) {
    result = server_event_dispatch(client, envelope.type, envelope.data, envelope.len);
  }
  if (envelope.allocated_buffer)
    buffer_release(envelope.allocated_buffer);
  return result;
}

static void process_input(void *arg) {
  server_event_connection_t *connection = arg;
  connection->packet_received = false;
  connection->result =
      packet_decoder_feed(&connection->decoder, connection->input, connection->length, consume_packet, connection);
}

static void input_done(platform_event_stream_t *stream, void *arg, bool closing) {
  server_event_connection_t *connection = arg;
  if (closing)
    return;
  if (connection->result != ASCIICHAT_OK) {
    platform_event_stream_close(stream, connection->result);
    return;
  }
  if (connection->capabilities) {
    if (packet_decoder_pending(&connection->decoder)) {
      if (!connection->partial_since || connection->packet_received)
        connection->partial_since = time_get_ns();
      uint64_t elapsed = time_get_ns() - connection->partial_since;
      if (elapsed >= 30 * NS_PER_SEC_INT) {
        platform_event_stream_close(stream, ERROR_NETWORK_TIMEOUT);
        return;
      }
      platform_event_stream_deadline(stream, (30 * NS_PER_SEC_INT - elapsed) / NS_PER_MS_INT + 1);
    } else {
      connection->partial_since = 0;
      platform_event_stream_deadline(stream, 0);
    }
  }
  if (platform_event_stream_resume(stream) != ASCIICHAT_OK)
    platform_event_stream_close(stream, ERROR_NETWORK);
}

static void read_input(platform_event_stream_t *stream, const void *data, size_t length, void *arg) {
  server_event_connection_t *connection = arg;
  connection->input = data;
  connection->length = length;
  asciichat_error_t result = platform_event_stream_work(stream, process_input, input_done, connection);
  if (result != ASCIICHAT_OK)
    platform_event_stream_close(stream, result);
}

static void cleanup_connection(void *arg) {
  server_event_connection_t *connection = arg;
  if (connection->client) {
    atomic_store_bool(&connection->client->event_cleanup, true);
    remove_client(connection->server, connection->client->client_id);
  } else {
    acip_transport_destroy(connection->transport);
  }
  packet_decoder_reset(&connection->decoder);
}

static void free_connection(void *arg) {
  server_event_connection_t *connection = arg;
  SAFE_FREE(connection);
}

static void connection_closed(void *arg, asciichat_error_t reason) {
  (void)reason;
  server_event_connection_t *connection = arg;
  acip_async_tcp_transport_detach(connection->transport);
  if (platform_event_loop_work(connection->server->tcp_server->event_loop, cleanup_connection, free_connection,
                               connection) != ASCIICHAT_OK) {
    cleanup_connection(connection);
    free_connection(connection);
  }
}

void server_event_accept(platform_event_stream_t *stream, void *arg) {
  server_event_connection_t *connection = SAFE_CALLOC(1, sizeof(*connection), server_event_connection_t *);
  connection->server = arg;
  connection->stream = stream;
  struct sockaddr_storage peer;
  socklen_t length = sizeof(peer);
  if (platform_event_stream_peer(stream, &peer, &length) == ASCIICHAT_OK)
    format_ip_address(peer.ss_family, (struct sockaddr *)&peer, connection->ip, sizeof(connection->ip));
  connection->transport = acip_async_tcp_transport_create(stream, NULL);
  if (!connection->transport) {
    SAFE_FREE(connection);
    platform_event_stream_close(stream, ERROR_MEMORY);
    return;
  }
  asciichat_error_t result = platform_event_stream_start(stream, read_input, connection_closed, connection);
  if (result == ASCIICHAT_OK)
    result = platform_event_stream_deadline(stream, 30000);
  if (result == ASCIICHAT_OK)
    result = platform_event_stream_work(stream, admit_connection, input_done, connection);
  if (result != ASCIICHAT_OK)
    platform_event_stream_close(stream, result);
}

void server_event_video(client_info_t *client, acip_frame_workspace_t *workspace, const char *data, size_t length,
                        uint32_t width, uint32_t height, int sources) {
  mutex_lock(&client->client_state_mutex);
  mutex_lock(&client->send_mutex);
  acip_transport_t *transport = client->transport;
  if (transport && !atomic_load_bool(&client->shutting_down) && atomic_load_bool(&client->event_ready)) {
    // ASCII frames are independent. Skip an unencrypted, unqueued frame when
    // the peer already has a frame pending; retain room for control and audio.
    if (acip_async_tcp_transport_queued(transport) < 256 * 1024) {
      if (client->crypto_initialized && crypto_handshake_should_rekey(&client->crypto_handshake_ctx))
        crypto_handshake_rekey_request(&client->crypto_handshake_ctx, transport);
      if (sources > 0 && atomic_load_u64(&client->last_sent_grid_sources) != (uint64_t)sources) {
        acip_send_clear_console(transport);
        atomic_store_u64(&client->last_sent_grid_sources, (uint64_t)sources);
      }
      if (acip_send_ascii_frame(transport, workspace, data, length, width, height, client->client_id) == ASCIICHAT_OK)
        atomic_fetch_add_u64(&client->frames_sent_count, 1);
    }
  }
  mutex_unlock(&client->send_mutex);
  mutex_unlock(&client->client_state_mutex);
}

asciichat_error_t server_event_audio(client_info_t *client, const void *data, size_t length) {
  mutex_lock(&client->client_state_mutex);
  mutex_lock(&client->send_mutex);
  asciichat_error_t result = ASCIICHAT_OK;
  if (client->transport && !atomic_load_bool(&client->shutting_down) && atomic_load_bool(&client->event_ready) &&
      acip_async_tcp_transport_queued(client->transport) < 512 * 1024)
    result = packet_send_via_transport(client->transport, PACKET_TYPE_AUDIO_OPUS_BATCH, data, length,
                                       fnv1a_hash_string(client->client_id));
  mutex_unlock(&client->send_mutex);
  mutex_unlock(&client->client_state_mutex);
  return result;
}

