}

static void server_init_session_host(tcp_server_t *tcp, int port) {
  // Session Host Creation (for discovery mode support)
  // Create session_host to track clients in a transport-agnostic way.
  if (!atomic_load_bool(&g_should_exit)) {
    const char *ipv4_address = tcp->config.ipv4_address;
    const char *ipv6_address = tcp->config.ipv6_address;

    session_host_config_t host_config = {
        .port = port,
        .ipv4_address = ipv4_address,
        .ipv6_address = ipv6_address,
        .max_clients = GET_OPTION(max_clients),
        .encryption_enabled = g_server_encryption_enabled,
        .key_path = GET_OPTION(encrypt_key),
        .password = GET_OPTION(password),
        .callbacks = {0}, // No callbacks for now
        .user_data = NULL,
    };

    g_server_ctx.session_host = session_host_create(&host_config);
    if (!g_server_ctx.session_host) {
      // Non-fatal: session_host is optional, server can work without it
      log_warn("Failed to create session_host (discovery mode support disabled)");
    } else {
      log_debug("Session host created for discovery mode support");
    }
  }
}

static bool server_allow_discovery(server_discovery_policy_t *policy) {
  if (policy->has_password || policy->has_identity) {
    // Auto-enable privacy: IP revealed only after verification
    policy->expose_ip = false;
    log_plain("ACDS privacy enabled: IP disclosed only after %s verification",
              policy->has_password ? "password" : "identity");
  } else if (policy->explicit_expose) {
    // Explicit opt-in to public IP disclosure
    // Only prompt if running interactively (can prompt user)
    // When non-interactive (automated/scripted), treat explicit flag as confirmation
    bool is_interactive = terminal_can_prompt_user();

    if (is_interactive) {
      if (!ui_notice_confirm(UI_NOTICE_DANGER,
                             "PUBLIC IP DISCLOSURE\nAnyone with the session string will be able to see your IP "
                             "address.\n\nDo you want to proceed",
                             30)) {
        log_info("IP disclosure not confirmed. Server will run WITHOUT discovery service.");
        return false;
      }
    }

    // User confirmed (or running non-interactively with explicit flag) - proceed with public IP disclosure
    policy->expose_ip = true;
    NOTICE(DANGER, "PUBLIC IP DISCLOSURE ENABLED",
           "Public IP disclosure CONFIRMED.\n"
           "Your IP address will be visible to anyone with the session string");
  } else {
    // Security violation: No password, no identity, no explicit opt-in
    NOTICE(DANGER, "DISCOVERY DISABLED: SECURITY REQUIRED",
           "Cannot create ACDS session: No security configured!\n"
           "You must either:\n"
           "1. Set a password: --password \"your-secret\"\n"
           "2. Use identity key: --key ~/.ssh/id_ed25519\n"
           "3. Explicitly allow public IP: --acds-expose-ip (NOT RECOMMENDED)\n"
           "\n"
           "Server will run WITHOUT discovery service.");
    return false;
  }

  return true;
}

static void server_prepare_discovery_request(acds_session_create_params_t *params,
                                             const server_discovery_policy_t *policy, int port,
                                             nat_upnp_context_t *upnp_ctx, bool upnp_succeeded) {
  // Use server's Ed25519 identity public key if available
  if (g_server_encryption_enabled && policy->has_identity) {
    memcpy(params->identity_pubkey, g_server_private_key.public_key, 32);
    memcpy(params->identity_seckey, g_server_private_key.key.ed25519, sizeof(params->identity_seckey));
    log_debug("Using server identity key for ACDS session");
  } else {
    // No identity key available - use zero key
    // ACDS will accept this if identity verification is not required
    memset(params->identity_pubkey, 0, 32);
    log_debug("No server identity key - using zero key for ACDS session");
  }

  params->capabilities = 0x03; // Video + Audio
  params->max_participants = GET_OPTION(max_clients);
  log_debug("ACDS: max_clients option value = %d", GET_OPTION(max_clients));

  // Set password if configured
  params->has_password = policy->has_password;
  if (policy->has_password) {
    // TODO: Hash password with Argon2id
    SAFE_STRNCPY(params->password, policy->password, sizeof(params->password));
  }

  // Set IP disclosure policy (determined above)
  params->acds_expose_ip = policy->expose_ip;
  log_debug("DEBUG: Server setting acds_expose_ip=%d (explicit_expose=%d, has_password=%d, has_identity=%d)",
           params->acds_expose_ip, policy->explicit_expose, policy->has_password, policy->has_identity);

  // Set session type (Direct TCP or WebRTC)
  // Auto-detect: Use WebRTC if UPnP failed OR if explicitly requested via --webrtc
  // Exception: If bind address is 0.0.0.0, server is on public IP - use Direct TCP
  const char *bind_addr = GET_OPTION(address);
  bool bind_all_interfaces = (strcmp(bind_addr, "0.0.0.0") == 0);

  // Determine session type: prefer WebRTC by default (unless explicitly disabled)
  // Priority: explicit --webrtc flag > connection type detection > UPnP > default
  if (GET_OPTION(webrtc)) {
    // Explicit WebRTC request
    params->session_type = SESSION_TYPE_WEBRTC;
    log_info("ACDS session type: WebRTC (explicitly requested via --webrtc)");
  } else if (bind_all_interfaces) {
    // Bind to 0.0.0.0: use WebRTC as default (better NAT compatibility)
    params->session_type = SESSION_TYPE_WEBRTC;
    log_info("ACDS session type: WebRTC (default for 0.0.0.0 binding, provides NAT-agnostic connections)");
  } else if (upnp_succeeded) {
    // UPnP port mapping worked - can use direct TCP
    params->session_type = SESSION_TYPE_DIRECT_TCP;
    log_info("ACDS session type: Direct TCP (router mapping created; external reachability unverified)");
  } else {
    // UPnP failed and not on public IP - use WebRTC for NAT traversal
    params->session_type = SESSION_TYPE_WEBRTC;
    log_info("ACDS session type: WebRTC (no router mapping or direct connection type selected)");
  }

  // Server connection information (where clients should connect)
  // If bind address is 0.0.0.0, leave server_address empty for ACDS to auto-detect public IP
  if (bind_all_interfaces) {
    params->server_address[0] = '\0'; // Empty - ACDS will use connection source IP
    log_debug("Bind address is 0.0.0.0, ACDS will auto-detect public IP from connection");
  } else {
    SAFE_STRNCPY(params->server_address, bind_addr, sizeof(params->server_address));
  }
  params->server_port = port;
  if (params->session_type == SESSION_TYPE_DIRECT_TCP) {
    if (nat_upnp_get_endpoint(upnp_ctx, params->server_address, sizeof(params->server_address), &params->server_port) !=
        ASCIICHAT_OK) {
      params->session_type = SESSION_TYPE_WEBRTC;
      log_info("ACDS session type: WebRTC (router mapping expired before registration)");
    }
  }

  // DEBUG: Log what we're sending to ACDS
  log_debug("DEBUG: Before SESSION_CREATE - expose_ip_publicly=%d, server_address='%s' port=%u, session_type=%u",
           params->acds_expose_ip, params->server_address, params->server_port, params->session_type);
}

static void server_join_discovery_session(const acds_session_create_params_t *params,
                                          acds_session_create_result_t *result, const char *session_string,
                                          const server_discovery_policy_t *policy) {
  // Server must join its own session so ACDS can route signaling messages
  log_debug("Server joining session as first participant for WebRTC signaling...");
  acds_session_join_params_t join_params = {0};
  join_params.session_string = session_string;

  // Use same identity key as session creation
  memcpy(join_params.identity_pubkey, params->identity_pubkey, 32);
  memcpy(join_params.identity_seckey, params->identity_seckey, sizeof(join_params.identity_seckey));

  // Include password if session is password-protected
  if (policy->has_password) {
    join_params.has_password = true;
    SAFE_STRNCPY(join_params.password, policy->password, sizeof(join_params.password));
  }

  acds_session_join_result_t join_result = {0};
  asciichat_error_t join_err = acds_session_join(g_acds_client, &join_params, &join_result);
  if (join_err != ASCIICHAT_OK || !join_result.success) {
    log_error("Failed to join own session: %s (error: %s)", asciichat_error_string(join_err),
              join_result.error_message[0] ? join_result.error_message : "unknown");
    // Continue anyway - this is not fatal for Direct TCP sessions
  } else {
    log_debug("Server joined session successfully (participant_id: %02x%02x...)", join_result.participant_id[0],
              join_result.participant_id[1]);
    // Store participant ID for WebRTC signaling (needed to identify server in SDP/ICE messages)
    memcpy(g_server_participant_id, join_result.participant_id, 16);
    log_debug("Stored server participant_id for signaling: %02x%02x...", g_server_participant_id[0],
              g_server_participant_id[1]);
    memcpy(result->session_id, join_result.session_id, 16);
  }
}

static void server_start_discovery_keepalive(void) {
  // Keep ACDS connection alive for WebRTC signaling relay
  log_debug("Server staying connected to ACDS for signaling relay");

  // Create ACDS transport wrapper for sending signaling packets
  g_acds_transport =
      acip_tcp_transport_create("transport_acds_server", g_acds_client->socket, g_acds_client->transport->crypto_ctx);
  if (!g_acds_transport) {
    log_error("Failed to create ACDS transport wrapper");
  } else {
    log_debug("ACDS transport wrapper created for signaling");

    // Start ACDS ping thread to keep connection alive (for ALL session types)
    int ping_thread_result = asciichat_thread_create(&g_acds_ping_thread, "acds_ping", acds_ping_thread, NULL);
    if (ping_thread_result != 0) {
      log_error("Failed to create ACDS ping thread: %d", ping_thread_result);
    } else {
      log_debug("ACDS ping thread started to keep connection alive");
      g_acds_ping_thread_started = true;
    }
  }
}

static int server_configure_stun(stun_server_t stun_servers[4]) {
  static lifecycle_t g_stun_lc = LIFECYCLE_INIT;
  static int stun_count = 0; // Store actual count separately

  if (lifecycle_init(&g_stun_lc, "stun")) {
    log_debug("Parsing STUN servers from options: '%s'", GET_OPTION(stun_servers));
    int count = stun_servers_parse(GET_OPTION(stun_servers), OPT_ENDPOINT_STUN_SERVERS_DEFAULT, stun_servers, 4);
    if (count > 0) {
      stun_count = count;
      log_debug("Parsed %d STUN servers", count);
      for (int i = 0; i < count; i++) {
        log_debug("  STUN[%d]: '%s' (len=%d)", i, stun_servers[i].host, stun_servers[i].host_len);
      }
    } else {
      log_warn("Failed to parse STUN servers, using defaults");
      stun_count =
          stun_servers_parse(OPT_ENDPOINT_STUN_SERVERS_DEFAULT, OPT_ENDPOINT_STUN_SERVERS_DEFAULT, stun_servers, 4);
      log_debug("Using default STUN servers, count=%d", stun_count);
      for (int i = 0; i < stun_count; i++) {
        log_debug("  STUN[%d]: '%s' (len=%d)", i, stun_servers[i].host, stun_servers[i].host_len);
      }
    }
  }

  return stun_count;
}

static size_t server_configure_turn(turn_server_t turn_servers[4], const char *turn_username,
                                    const char *turn_credential) {
  size_t turn_count = 0;
  if (turn_username[0] && turn_credential[0]) {
    char urls[OPTIONS_BUFF_SIZE];
    SAFE_STRNCPY(urls, GET_OPTION(turn_servers), sizeof(urls));
    char *saveptr = NULL;
    char *url = platform_strtok_r(urls, ",", &saveptr);
    while (url && turn_count < 4) {
      while (*url == ' ' || *url == '\t')
        url++;
      size_t len = strlen(url);
      while (len && (url[len - 1] == ' ' || url[len - 1] == '\t'))
        url[--len] = '\0';
      if (len && len < sizeof(turn_servers[0].url)) {
        turn_server_t *turn = &turn_servers[turn_count++];
        SAFE_STRNCPY(turn->url, url, sizeof(turn->url));
        SAFE_STRNCPY(turn->username, turn_username, sizeof(turn->username));
        SAFE_STRNCPY(turn->credential, turn_credential, sizeof(turn->credential));
        turn->url_len = (uint8_t)len;
        turn->username_len = (uint8_t)strlen(turn->username);
        turn->credential_len = (uint8_t)strlen(turn->credential);
      }
      url = platform_strtok_r(NULL, ",", &saveptr);
    }
  }

  return turn_count;
}

static void server_init_webrtc(void) {
  log_debug("Initializing WebRTC library and peer manager for session (role=CREATOR)...");

  // Initialize WebRTC library (libdatachannel)
  asciichat_error_t webrtc_init_result = webrtc_init();
  if (webrtc_init_result != ASCIICHAT_OK) {
    log_error("Failed to initialize WebRTC library: %s", asciichat_error_string(webrtc_init_result));
    g_webrtc_peer_manager = NULL;
  } else {
    log_debug("WebRTC library initialized successfully");

    // Configure STUN servers for ICE gathering (static to persist for peer_manager lifetime)
    static stun_server_t stun_servers[4] = {0};
    int stun_count = server_configure_stun(stun_servers);

    static turn_server_t turn_servers[4];
    static char turn_auth_username[128];
    static char turn_auth_credential[128];
    size_t turn_count = 0;
    const char *turn_username = GET_OPTION(turn_username);
    const char *turn_credential = GET_OPTION(turn_credential);
    SAFE_STRNCPY(turn_auth_username, turn_username, sizeof(turn_auth_username));
    SAFE_STRNCPY(turn_auth_credential, turn_credential, sizeof(turn_auth_credential));
    turn_count = server_configure_turn(turn_servers, turn_username, turn_credential);

    // Configure peer_manager
    const char *server_address = GET_OPTION(address);
    bool bind_webrtc_to_server_address = server_address && server_address[0] &&
                                         strcmp(server_address, "0.0.0.0") != 0 && strcmp(server_address, "::") != 0;
    webrtc_peer_manager_config_t pm_config = {
        .role = WEBRTC_ROLE_CREATOR, // Server accepts offers, generates answers
        // Honor an explicitly selected server interface for ICE. With a
        // wildcard bind, let libdatachannel gather candidates on all interfaces.
        .bind_address = bind_webrtc_to_server_address ? server_address : NULL,
        .stun_servers = stun_servers,
        .stun_count = stun_count,
        .turn_servers = turn_servers,
        .turn_count = turn_count,
        .relay_only = GET_OPTION(webrtc_relay_only),
        .turn_username = turn_auth_username,
        .turn_credential = turn_auth_credential,
        .on_transport_ready = on_webrtc_transport_ready,
        .user_data = &g_server_ctx
    };

    // Configure signaling callbacks for relaying SDP/ICE via ACDS
    webrtc_signaling_callbacks_t signaling_callbacks = {
        .send_sdp = server_send_sdp, .send_ice = server_send_ice, .user_data = NULL};

    // Create peer_manager
    asciichat_error_t pm_result = webrtc_peer_manager_create(&pm_config, &signaling_callbacks, &g_webrtc_peer_manager);
    if (pm_result != ASCIICHAT_OK) {
      log_error("Failed to create WebRTC peer_manager: %s", asciichat_error_string(pm_result));
      g_webrtc_peer_manager = NULL;
    } else {
      log_debug("WebRTC peer_manager initialized successfully");

      // Start ACDS receive thread for WebRTC signaling relay
      int thread_result = asciichat_thread_create(&g_acds_receive_thread, "acds_recv", acds_receive_thread, NULL);
      if (thread_result != 0) {
        log_error("Failed to create ACDS receive thread: %d", thread_result);
        // Cleanup peer_manager since signaling won't work
        webrtc_peer_manager_destroy(g_webrtc_peer_manager);
        g_webrtc_peer_manager = NULL;
      } else {
        log_debug("ACDS receive thread started for WebRTC signaling relay");
        g_acds_receive_thread_started = true;
      }
    }
  }
}

static void server_register_discovery(server_discovery_startup_t *startup, int port, nat_upnp_context_t *upnp_ctx,
                                      bool upnp_succeeded) {
  if (!GET_OPTION(discovery)) {
    log_info("ACDS registration disabled (use --acds to enable)");
    return;
  }
  const char *password = GET_OPTION(password);
  const char *encrypt_key = GET_OPTION(encrypt_key);
  server_discovery_policy_t policy = {
      .password = password,
      .has_password = password && strlen(password) > 0,
      .has_identity = encrypt_key && strlen(encrypt_key) > 0,
      .explicit_expose = GET_OPTION(discovery_expose_ip) != 0,
  };
  if (!server_allow_discovery(&policy)) {
    return;
  }
  // Security is configured, proceed with ACDS connection
  const char *acds_server = GET_OPTION(discovery_server);
  uint16_t acds_port = (uint16_t)GET_OPTION(discovery_port);

  log_info("Attempting to create session on ACDS server at %s:%d...", acds_server, acds_port);

  acds_client_config_t acds_config;
  acds_client_config_init_defaults(&acds_config);
  SAFE_STRNCPY(acds_config.server_address, acds_server, sizeof(acds_config.server_address));
  acds_config.server_port = acds_port;
  acds_config.timeout_ms = 5 * MS_PER_SEC_INT;
  acds_config.identity_key = GET_OPTION(encrypt_key);

  // Allocate ACDS client on heap for server lifecycle
  g_acds_client = SAFE_MALLOC(sizeof(acds_client_t), acds_client_t *);
  if (!g_acds_client) {
    log_error("Failed to allocate ACDS client");
    return;
  }

  asciichat_error_t acds_connect_result = acds_client_connect(g_acds_client, &acds_config);
  if (acds_connect_result != ASCIICHAT_OK) {
    log_error("Failed to connect to ACDS server at %s:%d: %s", acds_server, acds_port,
              asciichat_error_string(acds_connect_result));
    return;
  }
  acds_session_create_params_t create_params = {0};
  server_prepare_discovery_request(&create_params, &policy, port, upnp_ctx, upnp_succeeded);
  acds_session_create_result_t create_result;
  asciichat_error_t result = acds_session_create(g_acds_client, &create_params, &create_result);
  if (result != ASCIICHAT_OK) {
    log_warn("Failed to create session on ACDS server (server will run without discovery)");
    if (g_acds_client) {
      acds_client_disconnect(g_acds_client);
      SAFE_FREE(g_acds_client);
      g_acds_client = NULL;
    }
    return;
  }
  SAFE_STRNCPY(startup->session_string, create_result.session_string, sizeof(startup->session_string));
  SAFE_STRNCPY(g_session_string, create_result.session_string, sizeof(g_session_string));
  startup->mdns_only = false;
  log_info("Session created: %s", startup->session_string);
  server_join_discovery_session(&create_params, &create_result, startup->session_string, &policy);
  server_start_discovery_keepalive();
  if (create_params.session_type == SESSION_TYPE_WEBRTC) {
    server_init_webrtc();
  } else {
    log_debug("Session type is DIRECT_TCP, skipping WebRTC peer_manager initialization");
  }
  advertise_mdns_with_session(startup->session_string, (uint16_t)port);
}

static asciichat_error_t server_announce_session(server_discovery_startup_t *startup, int port) {
  // Fallback: If no session string was set by ACDS (either disabled or failed),
  // generate a random session string for mDNS discovery only
  if (startup->session_string[0] == '\0' && session_server_like_get_mdns_ctx()) {
    log_debug("No ACDS session string available, generating random session for mDNS");

    // Use the proper session string generation from discovery module
    // This generates adjective-noun-noun format using the full wordlists
    if (acds_string_generate(startup->session_string, sizeof(startup->session_string)) != ASCIICHAT_OK) {
      log_error("Failed to generate session string for mDNS");
      return SET_ERRNO(ERROR_INVALID_STATE, "Failed to generate session string for mDNS");
    }

    log_debug("Generated random session string for mDNS: '%s'", startup->session_string);

    // Mark that this session is mDNS-only (not globally discoverable via ACDS)
    startup->mdns_only = true;

    // Advertise mDNS with random session string
    advertise_mdns_with_session(startup->session_string, (uint16_t)port);
  }

  if (startup->session_string[0] != '\0') {
    if (startup->mdns_only) {
      NOTICE_ANNOUNCE("SESSION READY",
                      "Session String: %s (LAN only via "
                      "mDNS)\nShare with others on your LAN to join:\n   ascii-chat "
                      "%s",
                      startup->session_string, startup->session_string);
    } else {
      NOTICE_ANNOUNCE("SESSION READY",
                      "Session String: %s\nShare this "
                      "globally to join:\n   ascii-chat %s",
                      startup->session_string, startup->session_string);
    }
  }

  return ASCIICHAT_OK;
}

static asciichat_error_t server_init_fn(void *user_data) {
  (void)user_data;
  int port = GET_OPTION(port);

  // Get TCP server from server_like (it's already initialized at this point)
  tcp_server_t *tcp = session_server_like_get_tcp_server();
  if (!tcp) {
    return SET_ERRNO(ERROR_INVALID_STATE, "TCP server not available from server_like");
  }

  // Point server context at the server_like-owned TCP server
  g_server_ctx.tcp_server = tcp;

  // A local mapping behind upstream NAT must not suppress WebRTC discovery.
  nat_upnp_context_t *upnp_ctx = session_server_like_get_upnp_ctx();
  bool upnp_succeeded =
      nat_upnp_is_active(upnp_ctx) && !upnp_ctx->external_is_private && is_internet_ipv4(upnp_ctx->external_ip);

  asciichat_error_t result = server_init_client_manager_lock();
  if (result != ASCIICHAT_OK) {
    return result;
  }
  // Check if SIGINT/SIGTERM was received during initialization
  if (atomic_load_bool(&g_should_exit)) {
    log_info("Shutdown signal received during initialization, skipping server startup");
    return ASCIICHAT_OK;
  }

  // NOTE: g_client_manager is already zero-initialized in client.c with = {0}
  // We only need to initialize the mutex
  mutex_init(&g_client_manager.mutex, "client_manager");

  // Initialize uthash head pointer for O(1) lookup (uthash requires NULL initialization)
  g_client_manager.clients_by_id = NULL;

  result = server_init_rate_limiter();
  if (result != ASCIICHAT_OK) {
    return result;
  }
  result = server_init_audio_mixer();
  if (result != ASCIICHAT_OK) {
    return result;
  }
  result = server_init_h265();
  if (result != ASCIICHAT_OK) {
    return result;
  }
  server_init_session_host(tcp, port);

  // Update server context fields that depend on init results
  g_server_ctx.rate_limiter = g_rate_limiter;
  g_server_ctx.audio_mixer = g_audio_mixer;
  g_server_ctx.h265_server = g_h265_server; // Sync H.265 context created in this function

  server_discovery_startup_t startup = {0};
  server_register_discovery(&startup, port, upnp_ctx, upnp_succeeded);
  result = server_announce_session(&startup, port);
  if (result != ASCIICHAT_OK) {
    return result;
  }

  // Copy session info to globals for status screen display
  SAFE_STRNCPY(g_session_string, startup.session_string, sizeof(g_session_string));
  g_session_is_mdns_only = startup.mdns_only;

  // Initialize status screen timestamps
  g_server_start_time = time(NULL);
  g_last_status_update = platform_get_monotonic_time_us();

  stats_runtime_set_provider(server_stats_provider, NULL);
  log_debug("Server init_fn complete");
  return ASCIICHAT_OK;
}

static void server_close_client_sockets(void) {
  // Close all client sockets immediately to unblock receive threads.
  // Only do this if initialization succeeded and created the rwlock.
  log_debug("Closing all client sockets to unblock receive threads...");
  if (g_client_manager_rwlock_initialized) {
    rwlock_wrlock(&g_client_manager_rwlock);
    for (int i = 0; i < MAX_CLIENTS; i++) {
      client_info_t *client = &g_client_manager.clients[i];
      if (client->client_id[0] != '\0' && client->socket != INVALID_SOCKET_VALUE) {
        socket_close(client->socket);
        client->socket = INVALID_SOCKET_VALUE;
      }
    }
    rwlock_wrunlock(&g_client_manager_rwlock);
  }
}

static void server_stop_workers(void) {
  // Stop and destroy server worker thread pool (stats logger, etc.)
  if (g_server_worker_pool) {
    thread_pool_destroy(g_server_worker_pool);
    g_server_worker_pool = NULL;
    log_debug("Server worker thread pool stopped");
  }

  // Destroy rate limiter
  if (g_rate_limiter) {
    rate_limiter_destroy(g_rate_limiter);
    g_rate_limiter = NULL;
  }
}

static void server_wait_for_clients(void) {
  // Wait for all client handler threads to exit (only if rwlock was initialized)
  if (g_client_manager_rwlock_initialized) {
    int retry_count = 0;
    while (retry_count < 50) { // Max 500ms wait
      rwlock_rdlock(&g_client_manager_rwlock);
      bool all_cleaned = true;
      for (int i = 0; i < MAX_CLIENTS; i++) {
        if (g_client_manager.clients[i].client_id[0] != '\0') {
          all_cleaned = false;
          break;
        }
      }
      rwlock_rdunlock(&g_client_manager_rwlock);

      if (all_cleaned)
        break;
      platform_sleep_us(10 * US_PER_MS_INT); // 10ms
      retry_count++;
    }
    log_debug("Client handler threads cleaned up");
  }
}

static void server_remove_remaining_clients(void) {
  // Clean up all connected clients (only if rwlock was initialized)
  log_debug("Cleaning up connected clients...");
  char clients_to_remove[MAX_CLIENTS][MAX_CLIENT_ID_LEN];
  int client_count = 0;

  if (g_client_manager_rwlock_initialized) {
    rwlock_rdlock(&g_client_manager_rwlock);
    for (int i = 0; i < MAX_CLIENTS; i++) {
      client_info_t *client = &g_client_manager.clients[i];
      if (client->client_id[0] == '\0') {
        continue;
      }
      SAFE_STRNCPY(clients_to_remove[client_count], client->client_id, MAX_CLIENT_ID_LEN - 1);
      client_count++;
    }
    rwlock_rdunlock(&g_client_manager_rwlock);
  }

  for (int i = 0; i < client_count; i++) {
    if (remove_client(&g_server_ctx, clients_to_remove[i]) != 0) {
      log_error("Failed to remove client %s during shutdown", clients_to_remove[i]);
    }
  }

  // Clean up hash table
  while (g_client_manager.clients_by_id) {
    client_info_t *current_client = g_client_manager.clients_by_id;
    HASH_DELETE(hh, g_client_manager.clients_by_id, current_client);
  }
}

static void server_destroy_media(void) {
  // Clean up audio mixer
  if (g_audio_mixer) {
    mixer_t *mixer_to_destroy = g_audio_mixer;
    g_audio_mixer = NULL;
    mixer_destroy(mixer_to_destroy);
  }

  // Clean up H.265 codec server context
  if (g_h265_server) {
    h265_server_context_t *h265_to_destroy = g_h265_server;
    g_h265_server = NULL;
    g_server_ctx.h265_server = NULL;
    h265_server_context_destroy(h265_to_destroy);
    log_debug("H.265 codec server context shut down");
  }
}

static void server_destroy_session_host(void) {
  // Destroy session host
  if (g_server_ctx.session_host) {
    log_debug("Destroying session host");
    session_host_destroy(g_server_ctx.session_host);
    g_server_ctx.session_host = NULL;
  }

  // Destroy H.265 server codec context from server_ctx
  if (g_server_ctx.h265_server) {
    log_debug("Destroying H.265 server context");
    h265_server_context_destroy(g_server_ctx.h265_server);
    g_server_ctx.h265_server = NULL;
  }
}

static void server_stop_discovery(void) {
  // Join ACDS threads (if started)
  if (g_acds_ping_thread_started) {
    log_debug("Joining ACDS ping thread");
    asciichat_thread_join(&g_acds_ping_thread, NULL);
    g_acds_ping_thread_started = false;
    log_debug("ACDS ping thread joined");
  }

  if (g_acds_receive_thread_started) {
    log_debug("Joining ACDS receive thread");
    asciichat_thread_join(&g_acds_receive_thread, NULL);
    g_acds_receive_thread_started = false;
    log_debug("ACDS receive thread joined");
  }

  // Clean up WebRTC peer manager
  if (g_webrtc_peer_manager) {
    log_debug("Destroying WebRTC peer manager");
    webrtc_peer_manager_destroy(g_webrtc_peer_manager);
    g_webrtc_peer_manager = NULL;
  }

  // Clean up ACDS transport wrapper
  if (g_acds_transport) {
    log_debug("Destroying ACDS transport wrapper");
    acip_transport_destroy(g_acds_transport);
    g_acds_transport = NULL;
  }

  // Disconnect from ACDS server
  if (g_acds_client) {
    log_debug("Disconnecting from ACDS server");
    acds_client_disconnect(g_acds_client);
    SAFE_FREE(g_acds_client);
    g_acds_client = NULL;
  }
}

static void server_cleanup_fn(void *user_data) {
  stats_runtime_set_provider(NULL, NULL);
  (void)user_data;

  log_debug("Server shutting down...");
  memset(g_session_string, 0, sizeof(g_session_string)); // Clear session string for status screen

  // Wake up any threads that might be blocked on condition variables
  // (like packet queues) to ensure responsive shutdown
  static_cond_broadcast(&g_shutdown_cond);

  server_close_client_sockets();

  log_debug("Signaling all clients to stop (sockets closed, g_should_exit set)...");

  server_stop_workers();

  server_wait_for_clients();

  // Cleanup debug sync BEFORE destroying websocket_server
#ifndef NDEBUG
  debug_sync_destroy();
  debug_errno_destroy();
  debug_stats_destroy();
#endif

  server_remove_remaining_clients();

  server_destroy_media();

  // Clean up synchronization primitives (only if they were initialized)
  if (g_client_manager_rwlock_initialized) {
    rwlock_destroy(&g_client_manager_rwlock);
    g_client_manager_rwlock_initialized = false;
  }
  mutex_destroy(&g_client_manager.mutex);

#ifndef NDEBUG
  stats_cleanup();
#endif

  server_destroy_session_host();

  // TCP server, WebSocket server, mDNS, UPnP are destroyed by server_like.

  server_stop_discovery();

  // Clean up platform-specific resources
  socket_cleanup();

  log_info("Server shutdown complete");
  asciichat_error_stats_print();
}

int server_main(void) {
  // Common initialization (options, logging, lock debugging) now happens in main.c before dispatch

  // Register atomic for debug tracking
  ATOMIC_REGISTER_AUTO(g_should_exit, NULL);

  // Register shutdown check callback for library code
  shutdown_register_callback(check_shutdown);

  // Initialize crypto after logging is ready
  log_debug("Initializing crypto...");
  if (init_server_crypto() != 0) {
    LOG_ERRNO_IF_SET("Crypto initialization failed");
    FATAL(ERROR_CRYPTO, "Crypto initialization failed");
  }
  log_debug("Crypto initialized successfully");

  log_info("ascii-chat server starting...");

  int port = GET_OPTION(port);
  if (port < 1 || port > 65535) {
    log_error("Invalid port configuration: %d", port);
    FATAL(ERROR_CONFIG, "Invalid port configuration: %d", port);
  }

  ascii_simd_init();
  precalc_rgb_palettes(weight_red, weight_green, weight_blue);

#ifndef NDEBUG
  if (stats_init() != 0) {
    FATAL(ERROR_THREAD, "Statistics system initialization failed");
  }
#endif

  // Create background worker thread pool for server operations
  g_server_worker_pool = thread_pool_create("server_workers");
  if (!g_server_worker_pool) {
    LOG_ERRNO_IF_SET("Failed to create server worker thread pool");
    FATAL(ERROR_MEMORY, "Failed to create server worker thread pool");
  }

  // Spawn statistics logging thread in worker pool
  if (thread_pool_spawn(g_server_worker_pool, stats_logger_thread, NULL, 0, "stats_logger") != ASCIICHAT_OK) {
    LOG_ERRNO_IF_SET("Statistics logger thread creation failed");
  } else {
    log_debug("Statistics logger thread started");
  }

  // Initialize static server context (populated further in server_init_fn)
  // H.265 context is initialized in server_init_fn, not here
  g_server_ctx = (server_context_t){
      .tcp_server = NULL, // Set in server_init_fn after TCP server is ready
      .rate_limiter = g_rate_limiter,
      .client_manager = &g_client_manager,
      .client_manager_rwlock = &g_client_manager_rwlock,
      .server_should_exit = &g_should_exit,
      .audio_mixer = g_audio_mixer,
      .stats = &g_stats,
      .stats_mutex = &g_stats_mutex,
      .encryption_enabled = g_server_encryption_enabled,
      .server_private_key = &g_server_private_key,
      .client_whitelist = g_client_whitelist,
      .num_whitelisted_clients = g_num_whitelisted_clients,
      .session_host = NULL,
      .h265_server = NULL, // Initialized in server_init_fn
  };

  session_server_like_config_t config = {
      .init_fn = server_init_fn,
      .init_user_data = NULL,
      .interrupt_fn = server_handle_sigint,
      .cleanup_fn = server_cleanup_fn,
      .cleanup_user_data = NULL,
      .status_fn = server_status_fn,
      .status_user_data = NULL,
      .tcp_event_handler = server_event_accept,
      .tcp_user_data = &g_server_ctx,
      .websocket =
          {
              .enabled = true,
              .handler = websocket_client_handler,
              .user_data = &g_server_ctx,
          },
      .mdns =
          {
              .enabled = !GET_OPTION(no_mdns_advertise),
              .service_name = NULL, // Deferred: advertised after ACDS or mDNS session string is ready
              .service_type = "_ascii-chat._tcp",
          },
      .upnp =
          {
              .enabled = GET_OPTION(enable_upnp),
              .description = "ascii-chat Server",
          },
      // Raise FD limit for high-client-count scenarios (matches discovery-service policy)
      // Server accepts MAX_CLIENTS connections plus WebSocket, TCP, UPnP, mDNS, etc.
      // Each client may use multiple FDs (socket, media buffers, file handles)
      // Raising to 65536 ensures we don't hit system limits under load
      .raise_fd_limit = true,
      .fd_limit_target = 65536,
  };

  asciichat_error_t result = session_server_like_run(&config);
  return (result == ASCIICHAT_OK) ? 0 : 1;
}

static void protocol_cleanup_thread_locals(void) {
  // Placeholder for thread-local resources owned by the receive thread.
  // Add cleanup logic here if future protocol changes introduce
  // thread-local allocations that must be released before disconnecting.
}

void disconnect_client_for_bad_data(client_info_t *client, const char *format, ...) {
  if (!client) {
    return;
  }

  protocol_cleanup_thread_locals();

  // Atomically set the disconnect flag and get the old value
  // This ensures only one thread proceeds to disconnect (the first one)
  bool already_requested = atomic_exchange_bool(&client->protocol_disconnect_requested, true);
  if (already_requested) {
    return; // Already disconnecting, don't do it again
  }

  char reason[BUFFER_SIZE_SMALL] = {0};
  if (format) {
    va_list args;
    va_start(args, format);
    safe_vsnprintf(reason, sizeof(reason), format, args);
    va_end(args);
  } else {
    SAFE_STRNCPY(reason, "Protocol violation", sizeof(reason));
  }

  const char *reason_str = reason[0] != '\0' ? reason : "Protocol violation";
  const char *client_id = client->client_id;

  socket_t socket_snapshot = INVALID_SOCKET_VALUE;
  const crypto_context_t *crypto_ctx = NULL;
  acip_transport_t *transport_snapshot = NULL;

  mutex_lock(&client->client_state_mutex);
  if (client->socket != INVALID_SOCKET_VALUE) {
    socket_snapshot = client->socket;
    if (client->crypto_initialized) {
      crypto_ctx = crypto_handshake_get_context(&client->crypto_handshake_ctx);
    }
  }
  mutex_unlock(&client->client_state_mutex);

  // Get transport reference for WebSocket clients
  mutex_lock(&client->send_mutex);
  transport_snapshot = client->transport;
  mutex_unlock(&client->send_mutex);

  // NOTE: Disconnecting a client due to the client's own bad behavior isn't an
  // error for us, it's desired behavior for us, so we simply warn and do not
  // have a need for asciichat_errno here.
  log_warn("Disconnecting client %s due to protocol violation: %s", client_id, reason_str);

  if (socket_snapshot != INVALID_SOCKET_VALUE) {
    // Protect socket writes with send_mutex to prevent race with send_thread.
    // This receive_thread and send_thread both write to same socket.
    mutex_lock(&client->send_mutex);

    asciichat_error_t log_result =
        log_network_message(socket_snapshot, (const struct crypto_context_t *)crypto_ctx, LOG_ERROR,
                            REMOTE_LOG_DIRECTION_SERVER_TO_CLIENT, "Protocol violation: %s", reason_str);
    if (log_result != ASCIICHAT_OK) {
      log_warn("Failed to send remote log to client %s: %s", client_id, asciichat_error_string(log_result));
    }

    asciichat_error_t send_result = packet_send_error(socket_snapshot, crypto_ctx, ERROR_NETWORK_PROTOCOL, reason_str);
    if (send_result != ASCIICHAT_OK) {
      log_warn("Failed to send error packet to client %s: %s", client_id, asciichat_error_string(send_result));
    }

    mutex_unlock(&client->send_mutex);
  } else if (transport_snapshot) {
    // For WebSocket clients, try to send error via transport
    log_debug("Sending error to WebSocket client %s via transport", client_id);
    acip_send_error(transport_snapshot, ERROR_NETWORK_PROTOCOL, reason_str);
  }

  APP_CALLBACK_VOID(platform_pump_events);
  platform_sleep_ms(500);

  log_debug("Setting active=false in disconnect_client_for_bad_data (client_id=%s, reason=%s)", client_id, reason_str);
  atomic_store_bool(&client->active, false);
  atomic_store_bool(&client->shutting_down, true);
  atomic_store_bool(&client->send_thread_running, false);
  atomic_store_bool(&client->video_render_thread_running, false);
  atomic_store_bool(&client->audio_render_thread_running, false);

  if (client->audio_queue) {
    packet_queue_stop(client->audio_queue);
  }

  mutex_lock(&client->client_state_mutex);
  if (client->socket != INVALID_SOCKET_VALUE) {
    socket_shutdown(client->socket, 2);
    socket_close(client->socket);
    client->socket = INVALID_SOCKET_VALUE;
  }
  mutex_unlock(&client->client_state_mutex);
}

void handle_client_join_packet(client_info_t *client, const void *data, size_t len) {
  VALIDATE_PACKET_SIZE(client, data, len, sizeof(client_info_packet_t), "CLIENT_JOIN");

  const client_info_packet_t *join_info = (const client_info_packet_t *)data;

  // Validate display name is present and not just whitespace
  if (join_info->display_name[0] == '\0') {
    disconnect_client_for_bad_data(client, "CLIENT_JOIN display_name cannot be empty");
    return;
  }

  uint32_t capabilities = NET_TO_HOST_U32(join_info->capabilities);

  // Validate at least one capability flag is set
  const uint32_t VALID_CAP_MASK = CLIENT_CAP_VIDEO | CLIENT_CAP_AUDIO | CLIENT_CAP_COLOR | CLIENT_CAP_STRETCH;
  VALIDATE_CAPABILITY_FLAGS(client, capabilities, VALID_CAP_MASK, "CLIENT_JOIN");

  // Validate no unknown capability bits are set
  VALIDATE_FLAGS_MASK(client, capabilities, VALID_CAP_MASK, "CLIENT_JOIN");

  SAFE_STRNCPY(client->display_name, join_info->display_name, MAX_DISPLAY_NAME_LEN - 1);

  client->can_send_video = (capabilities & CLIENT_CAP_VIDEO) != 0;
  client->can_send_audio = (capabilities & CLIENT_CAP_AUDIO) != 0;
  client->wants_stretch = (capabilities & CLIENT_CAP_STRETCH) != 0;

  log_info("Client %s joined: %s (video=%d, audio=%d, stretch=%d)", client->client_id, client->display_name,
           client->can_send_video, client->can_send_audio, client->wants_stretch);

  // Notify client of successful join (encrypted channel)
  if (client->socket != INVALID_SOCKET_VALUE) {
    log_info_client(client, "Joined as '%s' (video=%s, audio=%s)", client->display_name,
                    client->can_send_video ? "yes" : "no", client->can_send_audio ? "yes" : "no");
  }
}

void handle_protocol_version_packet(client_info_t *client, const void *data, size_t len) {
  if (!data) {
    disconnect_client_for_bad_data(client, "PROTOCOL_VERSION payload missing");
    return;
  }

  if (len != sizeof(protocol_version_packet_t)) {
    disconnect_client_for_bad_data(client, "PROTOCOL_VERSION invalid size: %zu (expected %zu)", len,
                                   sizeof(protocol_version_packet_t));
    return;
  }

  const protocol_version_packet_t *version = (const protocol_version_packet_t *)data;
  uint16_t client_major = NET_TO_HOST_U16(version->protocol_version);
  uint16_t client_minor = NET_TO_HOST_U16(version->protocol_revision);

  // Validate major version match (minor version can differ for backward compat)
  if (client_major != PROTOCOL_VERSION_MAJOR) {
    log_warn("Client %s protocol version mismatch: client=%u.%u, server=%u.%u", client->client_id, client_major,
             client_minor, PROTOCOL_VERSION_MAJOR, PROTOCOL_VERSION_MINOR);
    // Note: We don't disconnect on version mismatch for backward compatibility
    // Clients may be older or newer than server
  } else if (client_minor != PROTOCOL_VERSION_MINOR) {
    log_info("Client %s has different protocol revision: client=%u.%u, server=%u.%u", client->client_id, client_major,
             client_minor, PROTOCOL_VERSION_MAJOR, PROTOCOL_VERSION_MINOR);
  }

  // Validate reserved bytes are zero
  for (size_t i = 0; i < sizeof(version->reserved); i++) {
    if (version->reserved[i] != 0) {
      log_warn("Client %s sent non-zero reserved bytes in PROTOCOL_VERSION packet", client->client_id);
      // Don't disconnect - reserved bytes may be used in future versions
      break;
    }
  }

  // Log supported features
  if (ACIP_CRYPTO_HAS_ENCRYPT(version->supports_encryption)) {
    log_debug("Client %s supports encryption", client->client_id);
  }
  if (version->compression_algorithms != 0) {
    log_debug("Client %s supports compression: 0x%02x", client->client_id, version->compression_algorithms);
  }
  if (version->feature_flags != 0) {
    uint16_t feature_flags = NET_TO_HOST_U16(version->feature_flags);
    atomic_store_bool(&client->supports_recoverable_errors, (feature_flags & PROTOCOL_FEATURE_RECOVERABLE_ERRORS) != 0);
    log_debug("Client %s supports features: 0x%04x", client->client_id, feature_flags);
  }
}

void handle_client_leave_packet(client_info_t *client, const void *data, size_t len) {
  if (!client) {
    return;
  }

  const char *client_id = client->client_id;

  if (len == 0) {
    // Empty reason - client disconnecting without explanation
    log_info("Client %s sent leave notification (no reason)", client_id);
  } else if (len <= 256) {
    // Reason provided - extract and log it
    if (!data) {
      SET_ERRNO(ERROR_INVALID_STATE, "Client %s sent leave notification with non-zero length but NULL data", client_id);
      return;
    }

    char reason[257] = {0};
    memcpy(reason, data, len);
    reason[len] = '\0';

    // Validate reason is printable (handle potential non-UTF8 gracefully)
    bool all_printable = true;
    for (size_t i = 0; i < len; i++) {
      uint8_t c = (uint8_t)reason[i];
      if (c < 32 && c != '\t' && c != '\n') {
        all_printable = false;
        break;
      }
    }

    if (all_printable) {
      log_info("Client %s sent leave notification: %s", client_id, reason);
    } else {
      log_info("Client %s sent leave notification (reason contains non-printable characters)", client_id);
    }
  } else {
    // Oversized reason - shouldn't happen with validation.h checks
    log_warn("Client %s sent oversized leave reason (%zu bytes, max 256)", client_id, len);
  }

  // Deactivate client to stop processing packets
  // Sets client->active = false immediately - triggers client cleanup procedures
  log_debug("Setting active=false in handle_client_leave_packet (client_id=%s)", client_id);
  atomic_store_bool(&client->active, false);

  // Note: We don't disconnect the client here - that happens when socket closes
  // This is just a clean notification before disconnect
}

void handle_stream_start_packet(client_info_t *client, const void *data, size_t len) {
  VALIDATE_PACKET_SIZE(client, data, len, sizeof(uint32_t), "STREAM_START");

  uint32_t stream_type;
  memcpy(&stream_type, data, sizeof(uint32_t));
  stream_type = NET_TO_HOST_U32(stream_type);

  /* Older browser/WASM packet serializers emitted this control payload in
   * host order while the enclosing ACIP header remained in network order.
   * Accept that unambiguous two-bit form so a connected browser is not
   * disconnected before it can send its first frame. */
  const uint32_t VALID_STREAM_MASK = STREAM_TYPE_VIDEO | STREAM_TYPE_AUDIO;
  if ((stream_type & VALID_STREAM_MASK) == 0) {
    uint32_t host_order_stream_type = HOST_TO_NET_U32(stream_type);
    if ((host_order_stream_type & ~VALID_STREAM_MASK) == 0 && host_order_stream_type != 0) {
      log_debug("Normalizing legacy host-order STREAM_START flags 0x%x", stream_type);
      stream_type = host_order_stream_type;
    }
  }

  // Validate at least one stream type flag is set
  VALIDATE_CAPABILITY_FLAGS(client, stream_type, VALID_STREAM_MASK, "STREAM_START");

  // Validate no unknown stream type bits are set
  VALIDATE_FLAGS_MASK(client, stream_type, VALID_STREAM_MASK, "STREAM_START");

  if (stream_type & STREAM_TYPE_VIDEO) {
    atomic_store_bool(&client->is_sending_video, true);
  }
  if (stream_type & STREAM_TYPE_AUDIO) {
    atomic_store_bool(&client->is_sending_audio, true);

    // Create Opus decoder for this client if not already created
    if (!client->opus_decoder) {
      client->opus_decoder = opus_codec_create_decoder(48000);
      if (client->opus_decoder) {
        log_info("Client %s: Opus decoder created (48kHz)", client->client_id);
      } else {
        log_error("Client %s: Failed to create Opus decoder", client->client_id);
      }
    }
  }

  if (stream_type & STREAM_TYPE_VIDEO) {
    log_info("Client %s announced video stream (waiting for first frame)", client->client_id);
  }
  if (stream_type & STREAM_TYPE_AUDIO) {
    log_info("Client %s started audio stream", client->client_id);
  }

  // Notify client of stream start acknowledgment
  const char *streams = (stream_type & STREAM_TYPE_VIDEO) && (stream_type & STREAM_TYPE_AUDIO)
                            ? "video+audio"
                            : ((stream_type & STREAM_TYPE_VIDEO) ? "video" : "audio");
  // Only send remote log to TCP clients (WebSocket clients have invalid socket)
  if (client->socket != INVALID_SOCKET_VALUE) {
    log_info_client(client, "Stream started: %s", streams);
  }
}

void handle_stream_stop_packet(client_info_t *client, const void *data, size_t len) {
  VALIDATE_PACKET_SIZE(client, data, len, sizeof(uint32_t), "STREAM_STOP");

  uint32_t stream_type;
  memcpy(&stream_type, data, sizeof(uint32_t));
  stream_type = NET_TO_HOST_U32(stream_type);

  // Validate at least one stream type flag is set
  const uint32_t VALID_STREAM_MASK = STREAM_TYPE_VIDEO | STREAM_TYPE_AUDIO;
  VALIDATE_CAPABILITY_FLAGS(client, stream_type, VALID_STREAM_MASK, "STREAM_STOP");

  // Validate no unknown stream type bits are set
  VALIDATE_FLAGS_MASK(client, stream_type, VALID_STREAM_MASK, "STREAM_STOP");

  if (stream_type & STREAM_TYPE_VIDEO) {
    atomic_store_bool(&client->is_sending_video, false);
  }
  if (stream_type & STREAM_TYPE_AUDIO) {
    atomic_store_bool(&client->is_sending_audio, false);
  }

  if (stream_type & STREAM_TYPE_VIDEO) {
    log_info("Client %s stopped video stream", client->client_id);
  }
  if (stream_type & STREAM_TYPE_AUDIO) {
    log_info("Client %s stopped audio stream", client->client_id);
  }

  // Notify client of stream stop acknowledgment
  const char *streams = (stream_type & STREAM_TYPE_VIDEO) && (stream_type & STREAM_TYPE_AUDIO)
                            ? "video+audio"
                            : ((stream_type & STREAM_TYPE_VIDEO) ? "video" : "audio");
  // Only send remote log to TCP clients (WebSocket clients have invalid socket)
  if (client->socket != INVALID_SOCKET_VALUE) {
    log_info_client(client, "Stream stopped: %s", streams);
  }
}

void handle_ping_packet(client_info_t *client, const void *data, size_t len) {
  (void)data;
  (void)len;

  // Serialize the complete PONG write with the sender. TCP packets cannot be
  // sent concurrently without risking byte-stream interleaving.
  mutex_lock(&client->send_mutex);
  if (atomic_load_bool(&client->shutting_down) || !client->transport) {
    mutex_unlock(&client->send_mutex);
    return;
  }
  acip_transport_t *pong_transport = client->transport;
  asciichat_error_t pong_result = acip_send_pong(pong_transport);
  mutex_unlock(&client->send_mutex);
  if (pong_result != ASCIICHAT_OK) {
    SET_ERRNO(ERROR_NETWORK, "Failed to send PONG response to client %s: %s", client->client_id,
              asciichat_error_string(pong_result));
  }
}

void handle_pong_packet(client_info_t *client, const void *data, size_t len) {
  (void)client;
  (void)data;
  (void)len;
  // No action needed - client acknowledged our PING
}

void handle_image_frame_packet(client_info_t *client, void *data, size_t len) {
  // Handle incoming image data from client
  // New format: [width:4][height:4][compressed_flag:4][data_size:4][rgb_data:data_size]
  // Old format: [width:4][height:4][rgb_data:w*h*3] (for backward compatibility)
  // Use atomic compare-and-swap to avoid race condition - ensures thread-safe auto-enabling of video stream

  log_debug_every(US_PER_SEC_INT, "RECV_IMAGE_FRAME: client_id=%s, len=%zu", client->client_id, len);

  // Validate codec capability for RGBA frames
  if (!VIDEO_CODEC_SUPPORTED(client->codec_capabilities_video, VIDEO_CODEC_RGBA)) {
    log_error("Client %s sent RGBA frame but does not support VIDEO_CODEC_RGBA (capabilities=0x%x)", client->client_id,
              client->codec_capabilities_video);
    disconnect_client_for_bad_data(client, "VIDEO_CODEC_RGBA not supported by client (capabilities=0x%x)",
                                   client->codec_capabilities_video);
    return;
  }

  if (!data || len < sizeof(uint32_t) * 2) {
    disconnect_client_for_bad_data(client, "IMAGE_FRAME payload too small: %zu bytes", len);
    return;
  }
  bool was_sending_video = atomic_load_bool(&client->is_sending_video);
  if (!was_sending_video) {
    // Try to atomically enable video sending
    // Use atomic_compare_exchange_strong to avoid spurious failures
    if (atomic_cas_bool(&client->is_sending_video, &was_sending_video, true)) {
      log_info("Client %s auto-enabled video stream (received IMAGE_FRAME)", client->client_id);
      // Notify client that their first video frame was received
      if (client->socket != INVALID_SOCKET_VALUE) {
        log_info_client(client, "First video frame received - streaming active");
      }
    }
  } else {
    // Log periodically to confirm we're receiving frames
    // Use per-client counter protected by client_state_mutex to avoid race conditions
    mutex_lock(&client->client_state_mutex);
    client->frames_received_logged++;
    if (client->frames_received_logged % 25000 == 0) {
      char pretty[64];
      format_bytes_pretty(len, pretty, sizeof(pretty));
      log_debug("Client %s has sent %u IMAGE_FRAME packets (%s)", client->client_id, client->frames_received_logged,
                pretty);
    }
    mutex_unlock(&client->client_state_mutex);
  }

  // Parse image dimensions (use memcpy to avoid unaligned access)
  uint32_t img_width_net, img_height_net;
  memcpy(&img_width_net, data, sizeof(uint32_t));
  memcpy(&img_height_net, (char *)data + sizeof(uint32_t), sizeof(uint32_t));
  uint32_t img_width = NET_TO_HOST_U32(img_width_net);
  uint32_t img_height = NET_TO_HOST_U32(img_height_net);

  log_debug_every(US_PER_SEC_INT, "IMAGE_FRAME packet: width=%u, height=%u, payload_len=%zu", img_width, img_height, len);

  // Validate dimensions using image utility functions
  if (image_validate_dimensions((size_t)img_width, (size_t)img_height) != ASCIICHAT_OK) {
    log_error("IMAGE_FRAME validation failed for dimensions: %u x %u", img_width, img_height);
    disconnect_client_for_bad_data(client, "IMAGE_FRAME invalid dimensions");
    return;
  }

  // Calculate RGB buffer size with overflow checking
  size_t rgb_size = 0;
  if (image_calc_rgb_size((size_t)img_width, (size_t)img_height, &rgb_size) != ASCIICHAT_OK) {
    disconnect_client_for_bad_data(client, "IMAGE_FRAME buffer size calculation failed");
    return;
  }

  // Validate final buffer size against maximum
  if (image_validate_buffer_size(rgb_size) != ASCIICHAT_OK) {
    disconnect_client_for_bad_data(client, "IMAGE_FRAME buffer size exceeds maximum");
    return;
  }

  // Only support legacy format: [width:4][height:4][rgb_data:w*h*3]
  if (rgb_size > SIZE_MAX - FRAME_HEADER_SIZE_LEGACY) {
    char size_str[32];
    format_bytes_pretty(rgb_size, size_str, sizeof(size_str));
    disconnect_client_for_bad_data(client, "IMAGE_FRAME legacy packet size overflow: %s", size_str);
    return;
  }
  size_t expected_size = FRAME_HEADER_SIZE_LEGACY + rgb_size;

  if (len != expected_size) {
    disconnect_client_for_bad_data(client, "IMAGE_FRAME size mismatch: expected %zu bytes got %zu", expected_size, len);
    return;
  }

  // Validate legacy format
  asciichat_error_t validate_result = frame_validate_legacy(len, rgb_size);
  if (validate_result != ASCIICHAT_OK) {
    disconnect_client_for_bad_data(client, "IMAGE_FRAME legacy validation failed");
    return;
  }

  void *rgb_data = (char *)data + FRAME_HEADER_SIZE_LEGACY;
  size_t rgb_data_size = rgb_size;
  bool needs_free = false;

  if (client->incoming_video_buffer) {
    // Get the write buffer
    video_frame_t *frame = video_frame_begin_write(client->incoming_video_buffer);

    if (frame && frame->data) {
      // Build the packet in the old format for internal storage: [width:4][height:4][rgb_data:w*h*3]
      // Use frame_check_size_overflow to validate overflow before repacking
      asciichat_error_t overflow_check = frame_check_size_overflow(FRAME_HEADER_SIZE_LEGACY, rgb_data_size);
      if (overflow_check != ASCIICHAT_OK) {
        if (needs_free && rgb_data) {
          SAFE_FREE(rgb_data);
        }
        disconnect_client_for_bad_data(client, "IMAGE_FRAME size overflow while repacking");
        return;
      }
      size_t old_packet_size = FRAME_HEADER_SIZE_LEGACY + rgb_data_size;

      if (old_packet_size <= MAX_FRAME_BUFFER_SIZE) { // Max frame buffer size
        uint32_t width_net = HOST_TO_NET_U32(img_width);
        uint32_t height_net = HOST_TO_NET_U32(img_height);

        // Pack in old format for internal consistency
        memcpy(frame->data, &width_net, sizeof(uint32_t));
        memcpy((char *)frame->data + sizeof(uint32_t), &height_net, sizeof(uint32_t));
        memcpy((char *)frame->data + sizeof(uint32_t) * 2, rgb_data, rgb_data_size);

        frame->size = old_packet_size;
        frame->width = img_width;
        frame->height = img_height;
        frame->capture_timestamp_ns = (uint64_t)time(NULL) * NS_PER_SEC_INT;
        frame->sequence_number = ++client->frames_received;

        // DEBUG: Compute hash of incoming RGB data to detect duplicates
        uint32_t incoming_rgb_hash = 0;
        for (size_t i = 0; i < rgb_data_size && i < 1000; i++) {
          incoming_rgb_hash = (uint32_t)((uint64_t)incoming_rgb_hash * 31 + ((unsigned char *)rgb_data)[i]);
        }

        // Per-client hash tracking (not static!) to avoid cross-client interference
        const char *client_id = client->client_id;
        bool is_new_frame = (incoming_rgb_hash != client->last_received_frame_hash);

        if (is_new_frame) {
          log_debug_every(US_PER_SEC_INT, "RECV_FRAME #%u NEW: Client %s size=%zu dims=%ux%u hash=0x%08x (prev=0x%08x)",
                   client->frames_received, client_id, rgb_data_size, img_width, img_height, incoming_rgb_hash,
                   client->last_received_frame_hash);
          client->last_received_frame_hash = incoming_rgb_hash;
        } else {
          log_debug_every(US_PER_SEC_INT, "RECV_FRAME #%u DUP: Client %s size=%zu dims=%ux%u hash=0x%08x",
                          client->frames_received, client_id, rgb_data_size, img_width, img_height, incoming_rgb_hash);
        }

        video_frame_commit(client->incoming_video_buffer);
      } else {
        if (needs_free && rgb_data) {
          SAFE_FREE(rgb_data);
        }
        disconnect_client_for_bad_data(client, "IMAGE_FRAME repacked frame too large (%zu bytes)", old_packet_size);
        return;
      }
    } else {
      log_warn("Failed to get write buffer for client %s (frame=%p, frame->data=%p)", client->client_id, (void *)frame,
               frame ? frame->data : NULL);
    }
  } else {
    // During shutdown, this is expected - don't spam error logs
    if (!atomic_load_bool(&g_should_exit)) {
      SET_ERRNO(ERROR_INVALID_STATE, "Client %s has no incoming video buffer!", client->client_id);
    } else {
      log_debug("Client %s: ignoring video packet during shutdown", client->client_id);
    }
  }

  // Clean up decompressed data if allocated
  if (needs_free && rgb_data) {
    SAFE_FREE(rgb_data);
  }
}

void handle_image_frame_h265_packet(client_info_t *client, const void *data, size_t len) {
  // Validate codec capability for H.265 frames
  if (!VIDEO_CODEC_SUPPORTED(client->codec_capabilities_video, VIDEO_CODEC_H265)) {
    log_error("Client %s sent H.265 frame but does not support VIDEO_CODEC_H265 (capabilities=0x%x)", client->client_id,
              client->codec_capabilities_video);
    disconnect_client_for_bad_data(client, "VIDEO_CODEC_H265 not supported by client (capabilities=0x%x)",
                                   client->codec_capabilities_video);
    return;
  }

  if (!data || len < 5) {
    disconnect_client_for_bad_data(client, "H265_FRAME payload too small: %zu bytes (min 5)", len);
    return;
  }

  // Auto-enable video stream if not already enabled
  // Use atomic_exchange to atomically set flag and check old value
  bool was_sending_video = atomic_exchange_bool(&client->is_sending_video, true);
  if (!was_sending_video) {
    log_info("Client %s auto-enabled H.265 video stream (received IMAGE_FRAME_H265)", client->client_id);
    if (client->socket != INVALID_SOCKET_VALUE) {
      log_info_client(client, "First H.265 video frame received - streaming active");
    }
  }

  uint8_t flags = *(const uint8_t *)data;
  bool is_keyframe = (flags & 0x01) != 0;
  bool size_changed = (flags & 0x02) != 0;

  log_debug_every(US_PER_SEC_INT, "H265_FRAME: flags=0x%02x, keyframe=%s, size_change=%s, len=%zu", flags,
                  is_keyframe ? "yes" : "no", size_changed ? "yes" : "no", len);

  if (!client->incoming_video_buffer) {
    log_error("Client %s has no incoming video buffer for H.265 frames", client->client_id);
    return;
  }

  // Get H.265 server context (may be NULL during shutdown)
  h265_server_context_t *h265_ctx = g_h265_server;
  if (!h265_ctx) {
    if (!atomic_load_bool(&g_should_exit)) {
      log_error("H.265 codec server context not initialized");
    }
    return;
  }

  // Get or create decoder for this client
  uint32_t client_id_num = 0;
  char *end = NULL;
  unsigned long parsed = strtoul(client->client_id, &end, 10);
  if (end != client->client_id && *end == '\0') {
    client_id_num = (uint32_t)parsed;
  } else {
    // Fallback to string hash if can't parse as number
    client_id_num = 0;
    for (int i = 0; client->client_id[i]; i++) {
      client_id_num = (client_id_num * 31 + (unsigned char)client->client_id[i]) & 0xFFFFFFFF;
    }
  }

  h265_server_client_t *client_decoder = h265_server_get_client_decoder(h265_ctx, client_id_num);
  if (!client_decoder) {
    log_error("Failed to get H.265 decoder for client %s", client->client_id);
    disconnect_client_for_bad_data(client, "Failed to initialize H.265 decoder");
    return;
  }

  // Allocate temporary RGBA buffer for decoding
  // H.265 frames from client are sent as [flags:u8][width:u16][height:u16][h265_data...]
  // Max frame is (256x256 = 65536 pixels) * 4 bytes/pixel = 262KB
  uint8_t *rgba_buf = SAFE_MALLOC(512 * 512 * 4, uint8_t *);
  if (!rgba_buf) {
    log_error("Failed to allocate RGBA buffer for H.265 decoding");
    disconnect_client_for_bad_data(client, "Out of memory for H.265 frame decoding");
    return;
  }

  uint16_t frame_width = 0;
  uint16_t frame_height = 0;
  size_t rgba_size = 512 * 512 * 4;

  // Decode H.265 packet to RGBA
  asciichat_error_t decode_result = h265_server_decode_and_convert(client_decoder, (const uint8_t *)data, len, rgba_buf,
                                                                   &frame_width, &frame_height, &rgba_size);

  if (decode_result != ASCIICHAT_OK) {
    log_error("H.265 decoding failed for client %s: %s", client->client_id, asciichat_error_string(decode_result));
    SAFE_FREE(rgba_buf);
    disconnect_client_for_bad_data(client, "H.265 frame decode error");
    return;
  }

  // Write decoded frame to video buffer
  video_frame_t *frame = video_frame_begin_write(client->incoming_video_buffer);
  if (frame && frame->data) {
    memcpy(frame->data, rgba_buf, rgba_size);
    frame->size = rgba_size;
    frame->width = frame_width;
    frame->height = frame_height;
    frame->is_keyframe = is_keyframe;

    // Update frame metadata
    frame->receive_timestamp_ns = time_get_realtime_ns();
    frame->sequence_number = client->frames_received++;

    log_debug_every(US_PER_SEC_INT, "RECV_H265 #%lu: client_id=%s size=%zu dims=%ux%u keyframe=%s",
                    frame->sequence_number, client->client_id, rgba_size, frame_width, frame_height,
                    is_keyframe ? "yes" : "no");

    video_frame_commit(client->incoming_video_buffer);
  } else {
    log_warn("Failed to get write buffer for client %s (frame=%p, frame->data=%p)", client->client_id, (void *)frame,
             frame ? frame->data : NULL);
  }

  SAFE_FREE(rgba_buf);
}

void handle_audio_packet(client_info_t *client, const void *data, size_t len) {
  VALIDATE_NOTNULL_DATA(client, data, "AUDIO");
  VALIDATE_AUDIO_ALIGNMENT(client, len, sizeof(float), "AUDIO");
  VALIDATE_AUDIO_STREAM_ENABLED(client, "AUDIO");

  int num_samples = (int)(len / sizeof(float));
  VALIDATE_AUDIO_SAMPLE_COUNT(client, num_samples, AUDIO_SAMPLES_PER_PACKET, "AUDIO");
  VALIDATE_RESOURCE_INITIALIZED(client, client->incoming_audio_buffer, "audio buffer");

  const float *samples = (const float *)data;
  asciichat_error_t result = audio_ring_buffer_write(client->incoming_audio_buffer, samples, num_samples);
  if (result != ASCIICHAT_OK) {
    log_error("Failed to write audio samples to buffer: %s", asciichat_error_string(result));
  }
}

void handle_remote_log_packet_from_client(client_info_t *client, const void *data, size_t len) {
  if (!client) {
    return;
  }

  log_level_t remote_level = LOG_INFO;
  remote_log_direction_t direction = REMOTE_LOG_DIRECTION_UNKNOWN;
  uint16_t flags = 0;
  char message[MAX_REMOTE_LOG_MESSAGE_LENGTH + 1] = {0};

  asciichat_error_t parse_result =
      packet_parse_remote_log(data, len, &remote_level, &direction, &flags, message, sizeof(message), NULL);
  if (parse_result != ASCIICHAT_OK) {
    disconnect_client_for_bad_data(client, "Invalid REMOTE_LOG packet: %s", asciichat_error_string(parse_result));
    return;
  }

  if (direction != REMOTE_LOG_DIRECTION_CLIENT_TO_SERVER) {
    disconnect_client_for_bad_data(client, "REMOTE_LOG direction mismatch: %u", direction);
    return;
  }

  const bool truncated = (flags & REMOTE_LOG_FLAG_TRUNCATED) != 0;
  const char *display_name = client->display_name[0] ? client->display_name : "(unnamed)";
  const char *client_id = client->client_id;

  if (truncated) {
    log_msg(remote_level, __FILE__, __LINE__, __func__, "[REMOTE CLIENT %s \"%s\"] %s [message truncated]", client_id,
            display_name, message);
  } else {
    log_msg(remote_level, __FILE__, __LINE__, __func__, "[REMOTE CLIENT %s \"%s\"] %s", client_id, display_name,
            message);
  }
}

void handle_audio_batch_packet(client_info_t *client, const void *data, size_t len) {
  // Log every audio batch packet reception
  log_debug_every(LOG_RATE_DEFAULT, "Received audio batch packet from client %s (len=%zu, is_sending_audio=%d)",
                  client->client_id, len, atomic_load_bool(&client->is_sending_audio));

  VALIDATE_NOTNULL_DATA(client, data, "AUDIO_BATCH");
  VALIDATE_MIN_SIZE(client, len, sizeof(audio_batch_packet_t), "AUDIO_BATCH");
  VALIDATE_AUDIO_STREAM_ENABLED(client, "AUDIO_BATCH");

  // Parse batch header using utility function
  audio_batch_info_t batch_info;
  asciichat_error_t parse_result = audio_parse_batch_header(data, len, &batch_info);
  if (parse_result != ASCIICHAT_OK) {
    disconnect_client_for_bad_data(client, "Failed to parse audio batch header");
    return;
  }

  uint32_t packet_batch_count = batch_info.batch_count;
  uint32_t total_samples = batch_info.total_samples;
  uint32_t sample_rate = batch_info.sample_rate;

  (void)packet_batch_count;
  (void)sample_rate;

  VALIDATE_NONZERO(client, packet_batch_count, "batch_count", "AUDIO_BATCH");
  VALIDATE_NONZERO(client, total_samples, "total_samples", "AUDIO_BATCH");

  size_t samples_bytes = 0;
  if (safe_size_mul(total_samples, sizeof(uint32_t), &samples_bytes)) {
    disconnect_client_for_bad_data(client, "AUDIO_BATCH sample size overflow (samples=%u)", total_samples);
    return;
  }

  size_t expected_size = sizeof(audio_batch_packet_t) + samples_bytes;
  if (len != expected_size) {
    disconnect_client_for_bad_data(client, "AUDIO_BATCH length mismatch: got %zu expected %zu", len, expected_size);
    return;
  }

  // Bounds check to prevent integer overflow on allocation
  // Maximum allowed samples: AUDIO_BATCH_SAMPLES * 2 (2048 samples)
  // This prevents total_samples * sizeof(float) from exceeding 8KB
  const uint32_t MAX_AUDIO_SAMPLES = AUDIO_BATCH_SAMPLES * 2;
  if (total_samples > MAX_AUDIO_SAMPLES) {
    disconnect_client_for_bad_data(client, "AUDIO_BATCH too many samples: %u (max: %u)", total_samples,
                                   MAX_AUDIO_SAMPLES);
    return;
  }

  const uint8_t *samples_ptr = (const uint8_t *)data + sizeof(audio_batch_packet_t);

  // Safe allocation: total_samples is bounded above, so multiplication won't overflow
  size_t alloc_size = (size_t)total_samples * sizeof(float);
  float *samples = SAFE_MALLOC(alloc_size, float *);
  if (!samples) {
    SET_ERRNO(ERROR_MEMORY, "Failed to allocate memory for audio sample conversion");
    return;
  }

  // Use helper function to dequantize samples
  asciichat_error_t dq_result = audio_dequantize_samples(samples_ptr, total_samples, samples);
  if (dq_result != ASCIICHAT_OK) {
    SAFE_FREE(samples);
    return;
  }

#ifndef NDEBUG
  static int recv_count = 0;
  recv_count++;
  if (recv_count % 100 == 0) {
    uint32_t raw0 = bytes_read_u32_unaligned(samples_ptr + 0 * sizeof(uint32_t));
    uint32_t raw1 = bytes_read_u32_unaligned(samples_ptr + 1 * sizeof(uint32_t));
    uint32_t raw2 = bytes_read_u32_unaligned(samples_ptr + 2 * sizeof(uint32_t));
    int32_t scaled0 = (int32_t)NET_TO_HOST_U32(raw0);
    int32_t scaled1 = (int32_t)NET_TO_HOST_U32(raw1);
    int32_t scaled2 = (int32_t)NET_TO_HOST_U32(raw2);
    log_debug_every(US_PER_SEC_INT, "RECV: network[0]=0x%08x, network[1]=0x%08x, network[2]=0x%08x", raw0, raw1, raw2);
    log_debug_every(US_PER_SEC_INT, "RECV: scaled[0]=%d, scaled[1]=%d, scaled[2]=%d", scaled0, scaled1, scaled2);
    log_debug_every(US_PER_SEC_INT, "RECV: samples[0]=%.6f, samples[1]=%.6f, samples[2]=%.6f", samples[0], samples[1],
                    samples[2]);
  }
#endif

  if (client->incoming_audio_buffer) {
    asciichat_error_t write_result = audio_ring_buffer_write(client->incoming_audio_buffer, samples, total_samples);
    if (write_result != ASCIICHAT_OK) {
      log_error("Failed to write decoded audio batch to buffer: %s", asciichat_error_string(write_result));
    }
  }

  SAFE_FREE(samples);
}

void handle_audio_opus_batch_packet(client_info_t *client, const void *data, size_t len) {
  log_debug_every(LOG_RATE_SLOW, "Received Opus audio batch from client %s (len=%zu)", client->client_id, len);

  VALIDATE_NOTNULL_DATA(client, data, "AUDIO_OPUS_BATCH");
  VALIDATE_AUDIO_STREAM_ENABLED(client, "AUDIO_OPUS_BATCH");
  VALIDATE_RESOURCE_INITIALIZED(client, client->opus_decoder, "Opus decoder");

  // Parse Opus batch packet
  const uint8_t *opus_data = NULL;
  size_t opus_size = 0;
  const uint16_t *frame_sizes = NULL;
  int sample_rate = 0;
  int frame_duration = 0;
  int frame_count = 0;

  asciichat_error_t result = packet_parse_opus_batch(data, len, &opus_data, &opus_size, &frame_sizes, &sample_rate,
                                                     &frame_duration, &frame_count);

  if (result != ASCIICHAT_OK) {
    disconnect_client_for_bad_data(client, "Failed to parse AUDIO_OPUS_BATCH packet");
    return;
  }

  VALIDATE_NONZERO(client, frame_count, "frame_count", "AUDIO_OPUS_BATCH");
  VALIDATE_NONZERO(client, opus_size, "opus_size", "AUDIO_OPUS_BATCH");

  // Calculate samples per frame (20ms @ 48kHz = 960 samples)
  int samples_per_frame = (sample_rate * frame_duration) / 1000;
  VALIDATE_RANGE(client, samples_per_frame, 1, 4096, "samples_per_frame", "AUDIO_OPUS_BATCH");

  // Use static buffer for common case to avoid malloc in hot path
  // Typical batches: 1-32 frames of 960 samples = up to 30,720 samples
  // Static buffer holds 32 frames @ 48kHz 20ms = 30,720 samples (120KB)
#define OPUS_DECODE_STATIC_MAX_SAMPLES (32 * 960)
  // Each client receive thread decodes independently. Sharing this scratch
  // buffer lets concurrent clients overwrite one another's PCM before it is
  // written to their source rings.
  static _Thread_local float static_decode_buffer[OPUS_DECODE_STATIC_MAX_SAMPLES];

  size_t total_samples = (size_t)samples_per_frame * (size_t)frame_count;
  float *decoded_samples;
  bool used_malloc = false;

  if (total_samples <= OPUS_DECODE_STATIC_MAX_SAMPLES) {
    decoded_samples = static_decode_buffer;
  } else {
    // Unusual large batch - fall back to malloc
    log_warn("Client %s: Large audio batch requires malloc (%zu samples)", client->client_id, total_samples);
    decoded_samples = SAFE_MALLOC(total_samples * sizeof(float), float *);
    if (!decoded_samples) {
      SET_ERRNO(ERROR_MEMORY, "Failed to allocate buffer for Opus decoded samples");
      return;
    }
    used_malloc = true;
  }

  // Decode each Opus frame using frame_sizes array
  int total_decoded = 0;
  size_t opus_offset = 0;

  for (int i = 0; i < frame_count; i++) {
    // Get exact frame size from frame_sizes array (convert from network byte order)
    size_t frame_size = (size_t)NET_TO_HOST_U16(frame_sizes[i]);

    // DEBUG: Log the actual bytes of each Opus frame
    if (frame_size > 0) {
      log_debug_every(LOG_RATE_DEFAULT, "Client %s: Opus frame %d: size=%zu, first_bytes=[0x%02x,0x%02x,0x%02x,0x%02x]",
                      client->client_id, i, frame_size, opus_data[opus_offset] & 0xFF,
                      frame_size > 1 ? (opus_data[opus_offset + 1] & 0xFF) : 0,
                      frame_size > 2 ? (opus_data[opus_offset + 2] & 0xFF) : 0,
                      frame_size > 3 ? (opus_data[opus_offset + 3] & 0xFF) : 0);
    }

    if (opus_offset + frame_size > opus_size) {
      log_error("Client %s: Frame %d size overflow (offset=%zu, frame_size=%zu, total=%zu)", client->client_id, i + 1,
                opus_offset, frame_size, opus_size);
      if (used_malloc) {
        SAFE_FREE(decoded_samples);
      }
      return;
    }

    // SECURITY: Bounds check before writing decoded samples to prevent buffer overflow
    // An attacker could send malicious Opus frames that decode to more samples than expected
    if ((size_t)total_decoded + (size_t)samples_per_frame > total_samples) {
      log_error("Client %s: Opus decode would overflow buffer (decoded=%d, frame_samples=%d, max=%zu)",
                client->client_id, total_decoded, samples_per_frame, total_samples);
      if (used_malloc) {
        SAFE_FREE(decoded_samples);
      }
      return;
    }

    int decoded_count = opus_codec_decode((opus_codec_t *)client->opus_decoder, &opus_data[opus_offset], frame_size,
                                          &decoded_samples[total_decoded], samples_per_frame);

    if (decoded_count < 0) {
      log_error("Client %s: Opus decoding failed for frame %d/%d (size=%zu)", client->client_id, i + 1, frame_count,
                frame_size);
      if (used_malloc) {
        SAFE_FREE(decoded_samples);
      }
      return;
    }

    total_decoded += decoded_count;
    opus_offset += frame_size;
  }

  log_debug_every(LOG_RATE_DEFAULT, "Client %s: Decoded %d Opus frames -> %d samples", client->client_id, frame_count,
                  total_decoded);

  // DEBUG: Log sample values to detect all-zero issue
  static _Thread_local int server_decode_count = 0;
  server_decode_count++;
  if (total_decoded > 0 && (server_decode_count <= 10 || server_decode_count % 100 == 0)) {
    float peak = 0.0f, rms = 0.0f;
    for (int i = 0; i < total_decoded && i < 100; i++) {
      float abs_val = fabsf(decoded_samples[i]);
      if (abs_val > peak)
        peak = abs_val;
      rms += decoded_samples[i] * decoded_samples[i];
    }
    rms = sqrtf(rms / (total_decoded > 100 ? 100 : total_decoded));
    // Log first 4 bytes of Opus data to compare with client encode
    log_debug_every(
        US_PER_SEC_INT,
        "SERVER OPUS DECODE #%d from client %s: decoded_rms=%.6f, opus_first4=[0x%02x,0x%02x,0x%02x,0x%02x]",
        server_decode_count, client->client_id, rms, opus_size > 0 ? opus_data[0] : 0, opus_size > 1 ? opus_data[1] : 0,
        opus_size > 2 ? opus_data[2] : 0, opus_size > 3 ? opus_data[3] : 0);
  }

  // Write decoded samples to client's incoming audio buffer
  // Note: audio_ring_buffer_write returns error code, not sample count
  // Buffer overflow warnings are logged inside audio_ring_buffer_write if buffer is full
  if (client->incoming_audio_buffer && total_decoded > 0) {
    asciichat_error_t result = audio_ring_buffer_write(client->incoming_audio_buffer, decoded_samples, total_decoded);
    if (result != ASCIICHAT_OK) {
      log_error("Client %s: Failed to write decoded audio to buffer: %d", client->client_id, result);
    }
  }

  if (used_malloc) {
    SAFE_FREE(decoded_samples);
  }
}

void handle_audio_opus_packet(client_info_t *client, const void *data, size_t len) {
  log_debug_every(LOG_RATE_DEFAULT, "Received Opus audio from client %s (len=%zu)", client->client_id, len);

  if (VALIDATE_PACKET_NOT_NULL(client, data, "AUDIO_OPUS")) {
    return;
  }

  // Minimum size: 16-byte header + at least 1 byte of Opus data
  if (len < 17) {
    disconnect_client_for_bad_data(client, "AUDIO_OPUS packet too small: %zu bytes", len);
    return;
  }

  if (!atomic_load_bool(&client->is_sending_audio)) {
    disconnect_client_for_bad_data(client, "AUDIO_OPUS received before audio stream enabled");
    return;
  }

  if (!client->opus_decoder) {
    disconnect_client_for_bad_data(client, "Opus decoder not initialized");
    return;
  }

  // Parse header (16 bytes) - convert from network byte order
  const uint8_t *buf = (const uint8_t *)data;
  uint32_t sample_rate_net, frame_duration_net;
  memcpy(&sample_rate_net, buf, 4);
  memcpy(&frame_duration_net, buf + 4, 4);
  uint32_t sample_rate = NET_TO_HOST_U32(sample_rate_net);
  uint32_t frame_duration = NET_TO_HOST_U32(frame_duration_net);

  // Extract Opus data (after 16-byte header)
  const uint8_t *opus_data = buf + 16;
  size_t opus_size = len - 16;

  // Validate parameters
  if (sample_rate == 0 || sample_rate > 192000) {
    disconnect_client_for_bad_data(client, "AUDIO_OPUS invalid sample_rate: %u", sample_rate);
    return;
  }

  if (frame_duration == 0 || frame_duration > 120) {
    disconnect_client_for_bad_data(client, "AUDIO_OPUS invalid frame_duration: %u ms", frame_duration);
    return;
  }

  // Calculate expected samples per frame
  int samples_per_frame = (int)((sample_rate * frame_duration) / 1000);
  if (samples_per_frame <= 0 || samples_per_frame > 5760) { // Max 120ms @ 48kHz
    disconnect_client_for_bad_data(client, "AUDIO_OPUS invalid samples_per_frame: %d", samples_per_frame);
    return;
  }

  // Decode Opus frame
  float decoded_samples[5760]; // Max Opus frame size (120ms @ 48kHz)
  int decoded_count =
      opus_codec_decode((opus_codec_t *)client->opus_decoder, opus_data, opus_size, decoded_samples, samples_per_frame);

  if (decoded_count < 0) {
    log_error("Client %s: Opus decoding failed (size=%zu)", client->client_id, opus_size);
    return;
  }

  log_debug_every(LOG_RATE_VERY_FAST, "Client %s: Decoded Opus frame -> %d samples", client->client_id, decoded_count);

  // Write decoded samples to client's incoming audio buffer
  if (client->incoming_audio_buffer && decoded_count > 0) {
    asciichat_error_t write_result =
        audio_ring_buffer_write(client->incoming_audio_buffer, decoded_samples, decoded_count);
    if (write_result != ASCIICHAT_OK) {
      log_error("Failed to write decoded Opus samples to buffer: %s", asciichat_error_string(write_result));
    }
  }
}

void handle_client_capabilities_packet(client_info_t *client, const void *data, size_t len) {
  const char *client_id = client->client_id;
  log_debug("[CAPS_HANDLER] 🟢 CAPS_RECEIVED: client_id=%s, data_ptr=%p, len=%zu bytes", client_id, data, len);

  log_debug("[CAPS_HANDLER] Step 1: Validating packet size (expected=%zu, actual=%zu)",
            sizeof(terminal_capabilities_packet_t), len);
  VALIDATE_PACKET_SIZE(client, data, len, sizeof(terminal_capabilities_packet_t), "CLIENT_CAPABILITIES");
  log_debug("[CAPS_HANDLER] ✅ Size validation passed");

  const terminal_capabilities_packet_t *caps = (const terminal_capabilities_packet_t *)data;

  // Extract and validate dimensions
  uint16_t width = NET_TO_HOST_U16(caps->width);
  uint16_t height = NET_TO_HOST_U16(caps->height);
  log_debug("[CAPS_HANDLER] 📐 DIMENSIONS: width=%u, height=%u", width, height);

  log_debug("[CAPS_HANDLER] Step 2: Validating width (value=%u, must be nonzero)", width);
  VALIDATE_NONZERO(client, width, "width", "CLIENT_CAPABILITIES");
  log_debug("[CAPS_HANDLER] ✅ Width nonzero check passed");

  log_debug("[CAPS_HANDLER] Step 3: Validating height (value=%u, must be nonzero)", height);
  VALIDATE_NONZERO(client, height, "height", "CLIENT_CAPABILITIES");
  log_debug("[CAPS_HANDLER] ✅ Height nonzero check passed");

  log_debug("[CAPS_HANDLER] Step 4: Validating width range (value=%u, range=1-4096)", width);
  VALIDATE_RANGE(client, width, 1, 4096, "width", "CLIENT_CAPABILITIES");
  log_debug("[CAPS_HANDLER] ✅ Width range check passed");

  log_debug("[CAPS_HANDLER] Step 5: Validating height range (value=%u, range=1-4096)", height);
  VALIDATE_RANGE(client, height, 1, 4096, "height", "CLIENT_CAPABILITIES");
  log_debug("[CAPS_HANDLER] ✅ Height range check passed");

  // Extract and validate color level (0=none, 1=16, 2=256, 3=truecolor)
  uint32_t color_level = NET_TO_HOST_U32(caps->color_level);
  log_debug("[CAPS_HANDLER] Step 6: Validating color_level (value=%u, range=0-3)", color_level);
  VALIDATE_RANGE(client, color_level, 0, 3, "color_level", "CLIENT_CAPABILITIES");
  log_debug("[CAPS_HANDLER] ✅ Color level check passed");

  // Extract and validate render mode (0=foreground, 1=background, 2=half-block)
  uint32_t render_mode = NET_TO_HOST_U32(caps->render_mode);
  log_debug("[CAPS_HANDLER] Step 7: Validating render_mode (value=%u, range=0-2)", render_mode);
  VALIDATE_RANGE(client, render_mode, 0, 2, "render_mode", "CLIENT_CAPABILITIES");
  log_debug("[CAPS_HANDLER] ✅ Render mode check passed");

  // Extract and validate palette type (0-5 are valid, 5=PALETTE_CUSTOM)
  uint32_t palette_type = NET_TO_HOST_U32(caps->palette_type);
  log_debug("[CAPS_HANDLER] Step 8: Validating palette_type (value=%u, range=0-5)", palette_type);
  VALIDATE_RANGE(client, palette_type, 0, 5, "palette_type", "CLIENT_CAPABILITIES");
  log_debug("[CAPS_HANDLER] ✅ Palette type check passed");

  // Validate desired FPS (1-144)
  log_debug("[CAPS_HANDLER] Step 9: Validating desired_fps (value=%u, range=1-144)", caps->desired_fps);
  VALIDATE_RANGE(client, caps->desired_fps, 1, 144, "desired_fps", "CLIENT_CAPABILITIES");
  log_debug("[CAPS_HANDLER] ✅ FPS check passed");

  mutex_lock(&client->client_state_mutex);

  client->width = width;
  client->height = height;

  log_debug("Client %s dimensions: %ux%u, desired_fps=%u", client->client_id, client->width, client->height,
            caps->desired_fps);

  client->terminal_caps.capabilities = NET_TO_HOST_U32(caps->capabilities);
  client->terminal_caps.color_level = color_level;
  client->terminal_caps.color_count = NET_TO_HOST_U32(caps->color_count);
  client->terminal_caps.render_mode = render_mode;
  client->terminal_caps.detection_reliable = caps->detection_reliable;
  client->terminal_caps.wants_background = (render_mode == RENDER_MODE_BACKGROUND);

  SAFE_STRNCPY(client->terminal_caps.term_type, caps->term_type, sizeof(client->terminal_caps.term_type));
  SAFE_STRNCPY(client->terminal_caps.colorterm, caps->colorterm, sizeof(client->terminal_caps.colorterm));

  client->terminal_caps.utf8_support = NET_TO_HOST_U32(caps->utf8_support);
  client->terminal_caps.palette_type = palette_type;
  SAFE_STRNCPY(client->terminal_caps.palette_custom, caps->palette_custom,
               sizeof(client->terminal_caps.palette_custom));

  client->terminal_caps.desired_fps = caps->desired_fps;
  client->terminal_caps.color_filter = (color_filter_t)caps->color_filter;

  // Extract wants_padding flag (1=padding enabled, 0=no padding for snapshot/piped modes)
  client->terminal_caps.wants_padding = (caps->wants_padding != 0);

  const char *custom_chars =
      (client->terminal_caps.palette_type == PALETTE_CUSTOM && client->terminal_caps.palette_custom[0])
          ? client->terminal_caps.palette_custom
          : NULL;

  if (initialize_client_palette((palette_type_t)client->terminal_caps.palette_type, custom_chars,
                                client->client_palette_chars, &client->client_palette_len,
                                client->client_luminance_palette) == 0) {
    client->client_palette_type = (palette_type_t)client->terminal_caps.palette_type;
    client->client_palette_initialized = true;
    log_info("Client %s palette initialized: type=%u, %zu chars, utf8=%u", client->client_id,
             client->terminal_caps.palette_type, client->client_palette_len, client->terminal_caps.utf8_support);
  } else {
    SET_ERRNO(ERROR_INVALID_STATE, "Failed to initialize palette for client %s", client->client_id);
    client->client_palette_initialized = false;
  }

  // Extract and store codec capabilities
  client->codec_capabilities_video = NET_TO_HOST_U32(caps->codec_capabilities_video);
  client->codec_capabilities_audio = NET_TO_HOST_U32(caps->codec_capabilities_audio);
  log_info("Client %s codec capabilities: video=0x%x audio=0x%x", client->client_id, client->codec_capabilities_video,
           client->codec_capabilities_audio);

  client->has_terminal_caps = true;

  log_info("Client %s capabilities: %ux%u, color_level=%s (%u colors), caps=0x%x, term=%s, colorterm=%s, "
           "render_mode=%s, reliable=%s, fps=%u, wants_padding=%d",
           client->client_id, client->width, client->height,
           terminal_color_level_name(client->terminal_caps.color_level), client->terminal_caps.color_count,
           client->terminal_caps.capabilities, client->terminal_caps.term_type, client->terminal_caps.colorterm,
           (client->terminal_caps.render_mode == RENDER_MODE_HALF_BLOCK
                ? "half-block"
                : (client->terminal_caps.render_mode == RENDER_MODE_BACKGROUND ? "background" : "foreground")),
           client->terminal_caps.detection_reliable ? "yes" : "no", client->terminal_caps.desired_fps,
           client->terminal_caps.wants_padding);

  // Send capabilities acknowledgment to client
  if (client->socket != INVALID_SOCKET_VALUE) {
    log_info_client(client, "Terminal configured: %ux%u, %s, %s mode, %u fps", client->width, client->height,
                    terminal_color_level_name(client->terminal_caps.color_level),
                    (client->terminal_caps.render_mode == RENDER_MODE_HALF_BLOCK
                         ? "half-block"
                         : (client->terminal_caps.render_mode == RENDER_MODE_BACKGROUND ? "background" : "foreground")),
                    client->terminal_caps.desired_fps);
  }

  mutex_unlock(&client->client_state_mutex);

  log_debug("[CAPS_HANDLER] ✅ CAPS_COMPLETE: client_id=%s - all validations passed, capabilities stored",
           client->client_id);
}

void handle_size_packet(client_info_t *client, const void *data, size_t len) {
  VALIDATE_PACKET_SIZE(client, data, len, sizeof(size_packet_t), "SIZE");

  const size_packet_t *size_pkt = (const size_packet_t *)data;

  // Extract and validate new dimensions
  uint16_t width = NET_TO_HOST_U16(size_pkt->width);
  uint16_t height = NET_TO_HOST_U16(size_pkt->height);

  VALIDATE_NONZERO(client, width, "width", "SIZE");
  VALIDATE_NONZERO(client, height, "height", "SIZE");
  VALIDATE_RANGE(client, width, 1, 4096, "width", "SIZE");
  VALIDATE_RANGE(client, height, 1, 4096, "height", "SIZE");

  mutex_lock(&client->client_state_mutex);
  client->width = width;
  client->height = height;
  mutex_unlock(&client->client_state_mutex);

  log_info("Client %s updated terminal size: %ux%u", client->client_id, width, height);
}

int send_server_state_to_client(client_info_t *client) {
  if (!client) {
    return -1;
  }

  // Count active clients - LOCK OPTIMIZATION: Use atomic reads, no rwlock needed
  int active_count = 0;
  for (int i = 0; i < MAX_CLIENTS; i++) {
    if (atomic_load_bool(&g_client_manager.clients[i].active)) {
      active_count++;
    }
  }

  // Prepare server state packet
  server_state_packet_t state;
  state.connected_client_count = active_count;
  state.active_client_count = active_count; // For now, all connected are active
  memset(state.reserved, 0, sizeof(state.reserved));

  // Convert to network byte order
  server_state_packet_t net_state;
  net_state.connected_client_count = HOST_TO_NET_U32(state.connected_client_count);
  net_state.active_client_count = HOST_TO_NET_U32(state.active_client_count);
  memset(net_state.reserved, 0, sizeof(net_state.reserved));

  // Send server state via ACIP transport
  // Protect socket writes with send_mutex to prevent race with send_thread.
  mutex_lock(&client->send_mutex);
  asciichat_error_t result = acip_send_server_state(client->transport, &net_state);
  mutex_unlock(&client->send_mutex);

  if (result != ASCIICHAT_OK) {
    SET_ERRNO(ERROR_NETWORK, "Failed to send server state to client %s: %s", client->client_id,
              asciichat_error_string(result));
    return -1;
  }

  log_debug("Sent server state to client %s: %u connected, %u active", client->client_id, state.connected_client_count,
            state.active_client_count);
  return 0;
}

void broadcast_clear_console_to_all_clients(void) {
  SET_ERRNO(ERROR_INVALID_STATE, "broadcast_clear_console_to_all_clients() called - unexpected usage");
  log_warn("CLEAR_CONSOLE is now sent from render threads, not broadcast");
}

void *client_video_render_thread(void *arg) {
  acip_frame_workspace_t event_workspace = {0};
  client_info_t *client = (client_info_t *)arg;
  if (!client) {
    log_error("NULL client pointer in video render thread");
    return NULL;
  }

  // Take snapshot of client ID and socket at start to avoid race conditions
  char thread_client_id[MAX_CLIENT_ID_LEN];
  SAFE_STRNCPY(thread_client_id, client->client_id, sizeof(thread_client_id) - 1);
  socket_t thread_socket = client->socket;
  bool is_webrtc = (thread_socket == INVALID_SOCKET_VALUE);
  (void)is_webrtc; // May be unused in release builds

  log_debug("Video render thread: client_id=%s, webrtc=%d", thread_client_id, is_webrtc);

  log_debug("[VIDEO_RENDER_THREAD_START] ★★★ LOCK STATE at thread entry for client %s", thread_client_id);
  // debug_sync_print_state();  // Disabled: causes AddressSanitizer stack-use-after-return crash

  // Wait for client to send terminal capabilities before rendering
  // Without capabilities, convert_composite_to_ascii() will fail
  int timeout_ms = 5000;
  int waited_ms = 0;
  while (!client->has_terminal_caps && !atomic_load_bool(&g_should_exit) && !atomic_load_bool(&client->shutting_down)) {
    if (waited_ms == 0) {
      log_debug("Waiting for terminal capabilities from client %s...", thread_client_id);
    }
    APP_CALLBACK_VOID(platform_pump_events);
    platform_sleep_ms(10);
    waited_ms += 10;
    if (waited_ms >= timeout_ms) {
      log_debug("Still waiting for terminal capabilities from client %s", thread_client_id);
      waited_ms = 0;
    }
  }
  if (client->has_terminal_caps) {
    log_debug("Received terminal capabilities for client %s after %dms", thread_client_id, waited_ms);
  }

  // Get client's desired FPS from capabilities or use default
  int client_fps = VIDEO_RENDER_FPS; // Default to 60 FPS
  // Use snapshot pattern to avoid mutex in render thread
  bool has_caps = client->has_terminal_caps;
  int desired_fps = has_caps ? client->terminal_caps.desired_fps : 0;
  if (has_caps && desired_fps > 0) {
    client_fps = desired_fps;
    log_debug("Client %s requested FPS: %d (has_caps=%d, desired_fps=%d)", thread_client_id, client_fps, has_caps,
              desired_fps);
  } else {
    log_debug("Client %s using default FPS: %d (has_caps=%d, desired_fps=%d)", thread_client_id, client_fps, has_caps,
              desired_fps);
  }

  int base_frame_interval_ms = 1000 / client_fps;
  log_debug("Client %s render interval: %dms (%d FPS)", thread_client_id, base_frame_interval_ms, client_fps);

  // FPS tracking for video render thread
  fps_t video_fps_tracker = {0};
  fps_init(&video_fps_tracker, client_fps, "SERVER VIDEO");

  const uint64_t frame_interval_ns = NS_PER_SEC_INT / client_fps;
  uint64_t next_frame_ns = time_get_ns() + frame_interval_ns;
  bool last_has_sources = false;
  uint32_t frame_gen_count = 0;
  uint64_t frame_gen_start_time = 0;
  uint32_t last_frame_hash = UINT32_MAX;
  uint32_t commits_count = 0;
  uint64_t commits_start_time = 0;
  uint64_t render_rate_window_start_ns = time_get_ns();
  uint64_t rendered_frames_in_window = 0;
  uint64_t missed_deadlines_in_window = 0;

  log_debug("Video render loop STARTING for client %s", thread_client_id);

  bool should_continue = true;
  while (should_continue && !atomic_load_bool(&g_should_exit) && !atomic_load_bool(&client->shutting_down)) {
    START_TIMER("render_iteration");
    log_dev_every(10 * NS_PER_MS_INT, "Video render loop iteration for client %s", thread_client_id);

    // Check for immediate shutdown
    if (atomic_load_bool(&g_should_exit)) {
      log_debug("Video render thread stopping for client %s (g_should_exit)", thread_client_id);
      break;
    }

    bool video_running = atomic_load_bool(&client->video_render_thread_running);
    bool active = atomic_load_bool(&client->active);
    bool shutting_down = atomic_load_bool(&client->shutting_down);

    should_continue = video_running && active && !shutting_down;

    if (!should_continue) {
      log_debug("Video render thread stopping for client %s (should_continue=false: video_running=%d, active=%d, "
                "shutting_down=%d)",
                thread_client_id, video_running, active, shutting_down);
      break;
    }

    // Processing consumes part of the frame interval. Sleep only until the
    // scheduled deadline, and skip missed deadlines without a catch-up burst.
    uint64_t iter_start_ns = time_get_ns();
    START_TIMER("render_frame_sleep");
    if (iter_start_ns < next_frame_ns) {
      platform_sleep_ns(next_frame_ns - iter_start_ns);
    }
    STOP_TIMER_AND_LOG(dev, 0, "render_frame_sleep", "frame deadline sleep completed");
    uint64_t after_sleep_ns = time_get_ns();
    uint64_t elapsed_intervals =
        after_sleep_ns >= next_frame_ns ? (after_sleep_ns - next_frame_ns) / frame_interval_ns + 1 : 1;
    if (elapsed_intervals > 1) {
      missed_deadlines_in_window += elapsed_intervals - 1;
    }
    next_frame_ns += elapsed_intervals * frame_interval_ns;

    // Capture timestamp for FPS tracking and frame timestamps
    uint64_t current_time_ns = time_get_ns();

    // Check thread state again before acquiring locks (client might have been destroyed during sleep).
    should_continue = atomic_load_bool(&client->video_render_thread_running) && atomic_load_bool(&client->active) &&
                      !atomic_load_bool(&client->shutting_down);
    if (!should_continue) {
      break;
    }

    // Optimization: No mutex needed - all fields are atomic or stable.
    // client_id: stable string pointer
    // width/height: stable uint16_t values (set once, never modified)
    // active: atomic_t - use atomic_load for thread safety
    const char *client_id_snapshot = client->client_id;       // Stable read
    unsigned short width_snapshot = client->width;            // Stable uint16_t
    unsigned short height_snapshot = client->height;          // Stable uint16_t
    bool active_snapshot = atomic_load_bool(&client->active); // Atomic read

    // Check if client is still active after getting snapshot
    if (!active_snapshot) {
      break;
    }

    // Phase 2 IMPLEMENTED: Generate frame specifically for THIS client using snapshot data
    size_t frame_size = 0;

    // Check if any clients are sending video
    bool has_video_sources = any_clients_sending_video();

    // DIAGNOSTIC: Track when video sources become available
    if (has_video_sources != last_has_sources) {
      log_debug("Client %s video sources: %s", thread_client_id, has_video_sources ? "AVAILABLE" : "UNAVAILABLE");
      last_has_sources = has_video_sources;
    }

    log_debug_every(5 * NS_PER_MS_INT,
                    "Video render iteration for client %s: has_video_sources=%d, width=%u, height=%u", thread_client_id,
                    has_video_sources, width_snapshot, height_snapshot);

    // Use default dimensions if client dimensions not received
    if (width_snapshot == 0 || height_snapshot == 0) {
      log_dev_every(5 * NS_PER_MS_INT, "Using default dimensions for client %s (client reported: width=%u, height=%u)",
                    thread_client_id, width_snapshot, height_snapshot);
      // Use 80x25 as standard terminal size fallback for snapshot/test clients
      width_snapshot = 80;
      height_snapshot = 25;
    }

    // Generate frames for all clients with valid dimensions, regardless of whether other clients are sending video.
    // This ensures WebSocket snapshot clients (receive-only mode) receive frames even when no other clients are
    // sending video.
    int sources_count = 0; // Track number of video sources in this frame

    // DIAGNOSTIC: Track every frame generation attempt
    frame_gen_count++;
    if (frame_gen_count == 1) {
      frame_gen_start_time = current_time_ns;
    }

    // Log every 120 attempts (should be ~2 seconds at 60 Hz)
    if (frame_gen_count % 120 == 0) {
      uint64_t elapsed_ns = current_time_ns - frame_gen_start_time;
      double gen_fps = (120.0 / (elapsed_ns / (double)NS_PER_SEC_INT));
      log_dev("render loop: client=%s fps=%.1f", thread_client_id, gen_fps);
    }

    log_dev_every(5 * NS_PER_MS_INT, "About to call create_mixed_ascii_frame_for_client for client %s with dims %ux%u",
                  thread_client_id, width_snapshot, height_snapshot);

    // debug_sync_print_state() is too expensive to call every frame (kills FPS)

    uint64_t frame_create_start_ns = time_get_ns();
    START_TIMER("render_create_frame");
    char *ascii_frame = create_mixed_ascii_frame_for_client(client_id_snapshot, width_snapshot, height_snapshot, false,
                                                            &frame_size, NULL, &sources_count);
    STOP_TIMER_AND_LOG(dev, 0, "render_create_frame", "create_mixed_ascii_frame completed");
    uint64_t frame_create_end_ns = time_get_ns();
    if (sources_count > 0) {
      stats_duration_record(stats_runtime_scope(), STATS_DURATION_ASCII_CONVERT,
                            frame_create_end_ns - frame_create_start_ns);
      stats_counter_add(stats_runtime_scope(),
                        ascii_frame ? STATS_COUNTER_FRAMES_CONVERTED : STATS_COUNTER_FRAMES_DROPPED, 1);
    }

    if (frame_gen_count % 120 == 0) {
      char sleep_str[32], create_str[32];
      time_pretty((uint64_t)(after_sleep_ns - iter_start_ns), -1, sleep_str, sizeof(sleep_str));
      time_pretty((uint64_t)(frame_create_end_ns - frame_create_start_ns), -1, create_str, sizeof(create_str));
      log_dev("render timing: adaptive_sleep=%s frame_create=%s", sleep_str, create_str);
    }

    // Always send frames at configured FPS, even if no external video sources yet
    // This ensures single-client mode (like testing) still gets continuous frames
    // The frame data (animated background or test pattern) is still valid content

    // DEBUG: Log frame generation details
    uint32_t current_frame_hash = 0;
    if (ascii_frame && frame_size > 0) {
      if (client->event_driven)
        server_event_video(client, &event_workspace, ascii_frame, frame_size, width_snapshot, height_snapshot,
                           sources_count);
      for (size_t i = 0; i < frame_size && i < 1000; i++) {
        current_frame_hash = (uint32_t)((uint64_t)current_frame_hash * 31 + ((unsigned char *)ascii_frame)[i]);
      }
      if (current_frame_hash != last_frame_hash) {
        log_dev_every(US_PER_SEC_INT, "RENDER_FRAME CHANGE: Client %s frame #%zu sources=%d hash=0x%08x (prev=0x%08x)",
                      thread_client_id, frame_size, sources_count, current_frame_hash, last_frame_hash);
        last_frame_hash = current_frame_hash;
      } else {
        log_dev_every(25000, "RENDER_FRAME DUPLICATE: Client %s frame #%zu sources=%d hash=0x%08x (no change)",
                      thread_client_id, frame_size, sources_count, current_frame_hash);
      }
    }

    log_dev_every(5 * NS_PER_MS_INT,
                  "create_mixed_ascii_frame_for_client returned: ascii_frame=%p, frame_size=%zu, sources_count=%d",
                  (void *)ascii_frame, frame_size, sources_count);

    // Phase 2 IMPLEMENTED: Write frame to double buffer (never drops!)
    if (ascii_frame && frame_size > 0) {
      log_debug_every(5 * NS_PER_MS_INT, "Buffering frame for client %s (size=%zu)", thread_client_id, frame_size);
      // GRID LAYOUT CHANGE DETECTION: Store source count with frame
      // Send thread will compare this with last sent count to detect grid changes
      atomic_store_u64(&client->last_rendered_grid_sources, (uint64_t)sources_count);

      // Use double-buffer system which has its own internal swap_mutex
      // No external locking needed - the double-buffer is thread-safe by design
      video_frame_buffer_t *vfb_snapshot = client->outgoing_video_buffer;

      if (vfb_snapshot) {
        video_frame_t *write_frame = video_frame_begin_write(vfb_snapshot);
        if (write_frame) {
          // Copy ASCII frame data to the back buffer (NOT holding rwlock - just double-buffer's internal lock)
          if (write_frame->data && frame_size <= vfb_snapshot->allocated_buffer_size) {
            memcpy(write_frame->data, ascii_frame, frame_size);
            write_frame->size = frame_size;
            write_frame->width = width_snapshot;
            write_frame->height = height_snapshot;
            write_frame->capture_timestamp_ns = current_time_ns;

            // Commit at the configured cadence enforced by the frame deadline.
            // Never skip frames based on content changes.
            {
              uint64_t commit_start_ns = time_get_ns();
              // Commit the frame (swaps buffers atomically using vfb->swap_mutex, NOT rwlock)
              START_TIMER("render_video_frame_commit");
              video_frame_commit(vfb_snapshot);
              STOP_TIMER_AND_LOG(dev, 0, "render_video_frame_commit", "video_frame_commit completed");
              uint64_t commit_end_ns = time_get_ns();
              char commit_duration_str[32];
              time_pretty((uint64_t)(commit_end_ns - commit_start_ns), -1, commit_duration_str,
                          sizeof(commit_duration_str));

              commits_count++;
              if (commits_count == 1) {
                commits_start_time = commit_end_ns;
              }
              if (commits_count % 10 == 0) {
                uint64_t elapsed_ns = commit_end_ns - commits_start_time;
                double commit_fps = (10.0 / (elapsed_ns / (double)NS_PER_SEC_INT));
                log_dev("render commit rate: client=%s fps=%.1f", thread_client_id, commit_fps);
              }

              log_dev_every(US_PER_SEC_INT, "FRAME_COMMIT: Client %s took %s (hash=0x%08x)", thread_client_id,
                            commit_duration_str, current_frame_hash);

              // ARCHITECTURE: Frame transmission is handled EXCLUSIVELY by the send thread
              // The send thread reads from this buffer and applies proper 60 FPS rate limiting
              // Do NOT send from render thread - it bypasses rate limiting and causes network congestion
              // Render thread responsibility: Generate frame → Write to buffer → Done
              // Send thread responsibility: Read from buffer → Apply 60 FPS pacing → Transmit
            }

          } else {
            log_warn_every(US_PER_SEC_INT, "Frame too large for buffer: %zu > %zu", frame_size,
                           vfb_snapshot->allocated_buffer_size);
          }

          // FPS tracking - frame successfully generated (handles lag detection and periodic reporting)
          fps_frame_ns(&video_fps_tracker, current_time_ns, "frame rendered");
          rendered_frames_in_window++;
          uint64_t render_rate_now_ns = time_get_ns();
          uint64_t render_rate_elapsed_ns = render_rate_now_ns - render_rate_window_start_ns;
          if (render_rate_elapsed_ns >= NS_PER_SEC_INT) {
            double render_fps = (double)rendered_frames_in_window * NS_PER_SEC_INT / (double)render_rate_elapsed_ns;
            if (render_fps < (double)client_fps * 0.9 || missed_deadlines_in_window > 0) {
              log_warn("Server video render lagging client=%s fps=%.1f target=%d missed_deadlines=%llu",
                       thread_client_id, render_fps, client_fps, (unsigned long long)missed_deadlines_in_window);
            } else {
              log_debug("Server video render client=%s fps=%.1f target=%d missed_deadlines=0", thread_client_id,
                       render_fps, client_fps);
            }
            render_rate_window_start_ns = render_rate_now_ns;
            rendered_frames_in_window = 0;
            missed_deadlines_in_window = 0;
          }
        }
      }

      SAFE_FREE(ascii_frame);
    } else {
      // No frame generated (probably no video sources) - this is normal, no error logging needed
      log_dev_every(10 * NS_PER_MS_INT, "Per-client render: No video sources available for client %s",
                    client_id_snapshot);
    }

    uint64_t iter_end_ns = time_get_ns();
    if (frame_gen_count % 120 == 0) {
      char total_str[32];
      time_pretty((uint64_t)(iter_end_ns - iter_start_ns), -1, total_str, sizeof(total_str));
      log_warn_every(US_PER_SEC_INT, "  TIMING: TOTAL_ITERATION=%s", total_str);
    }
    STOP_TIMER_AND_LOG(dev, 0, "render_iteration", "render_iteration completed (total)");
  }

#ifdef DEBUG_THREADS
  log_debug("Video render thread stopped for client %s", thread_client_id);
#endif
  acip_frame_workspace_destroy(&event_workspace);

  // Clean up thread-local error context before exit

  return NULL;
}

void *client_audio_render_thread(void *arg) {
  client_info_t *client = (client_info_t *)arg;

  if (!client) {
    log_error("Invalid client info in audio render thread");
    return NULL;
  }

  // Take snapshot of client ID and display name at start to avoid race conditions
  char thread_client_id[MAX_CLIENT_ID_LEN];
  SAFE_STRNCPY(thread_client_id, client->client_id, sizeof(thread_client_id) - 1);
  char thread_display_name[64];
  bool is_webrtc = (client->socket == INVALID_SOCKET_VALUE);
  (void)is_webrtc; // May be unused in release builds

  // LOCK OPTIMIZATION: Only need client_state_mutex, not global rwlock
  // We already have a stable client pointer
  mutex_lock(&client->client_state_mutex);
  SAFE_STRNCPY(thread_display_name, client->display_name, sizeof(thread_display_name));
  mutex_unlock(&client->client_state_mutex);

#ifdef DEBUG_THREADS
  log_debug("Audio render thread started for client %s (%s), webrtc=%d", thread_client_id, thread_display_name,
            is_webrtc);
#endif

  // Mix buffer: up to 960 samples for adaptive reading
  // Normal: 480 samples = 10ms @ 48kHz
  // Catchup: 960 samples = 20ms when buffers are filling up
  float mix_buffer[960];

// Opus frame accumulation buffer (960 samples = 20ms @ 48kHz)
// Opus requires minimum 480 samples, 960 is optimal for 20ms frames
#define OPUS_FRAME_SAMPLES 960
  float opus_frame_buffer[OPUS_FRAME_SAMPLES];
  int opus_frame_accumulated = 0;

  // Create Opus encoder for this client's audio stream (48kHz, mono, 128kbps, AUDIO mode for music quality)
  opus_codec_t *opus_encoder = opus_codec_create_encoder(OPUS_APPLICATION_AUDIO, 48000, 128000);
  if (!opus_encoder) {
    log_error("Failed to create Opus encoder for audio render thread (client %s)", thread_client_id);
    return NULL;
  }

  // FPS tracking for audio render thread
  fps_t audio_fps_tracker = {0};
  fps_init(&audio_fps_tracker, AUDIO_PACKET_FPS, "SERVER AUDIO");

  // Per-thread counters (NOT static - each thread instance gets its own)
  int server_audio_frame_count = 0;

  bool should_continue = true;
  uint64_t audio_deadline = time_get_ns();
  while (should_continue && !atomic_load_bool(&g_should_exit) && !atomic_load_bool(&client->shutting_down)) {
    log_debug_every(LOG_RATE_SLOW, "Audio render loop iteration for client %s", thread_client_id);

    // Check for immediate shutdown
    if (atomic_load_bool(&g_should_exit)) {
      log_debug("Audio render thread stopping for client %s (g_should_exit)", thread_client_id);
      break;
    }

    // Check thread state before acquiring any locks to prevent use-after-destroy.
    // If we acquire locks after client is being destroyed, we'll crash with SIGSEGV
    should_continue = (((int)atomic_load_bool(&client->audio_render_thread_running) != 0) &&
                       ((int)atomic_load_bool(&client->active) != 0) && !atomic_load_bool(&client->shutting_down));

    if (!should_continue) {
      log_debug("Audio render thread stopping for client %s (should_continue=false)", thread_client_id);
      break;
    }

    if (!g_audio_mixer) {
      log_dev_every(10 * NS_PER_MS_INT, "Audio render waiting for mixer (client %s)", thread_client_id);
      // Check shutdown flag while waiting
      if (atomic_load_bool(&g_should_exit))
        break;
      platform_sleep_ns(10 * NS_PER_MS_INT);
      continue;
    }

    // Optimization: No mutex needed - all fields are atomic or stable.
    // client_id: atomic_t - use atomic_load for thread safety
    // active: atomic_t - use atomic_load
    // audio_queue: Assigned once at init and never changes
    const char *client_id_snapshot = client->client_id;         // Atomic read
    bool active_snapshot = atomic_load_bool(&client->active);   // Atomic read
    packet_queue_t *audio_queue_snapshot = client->audio_queue; // Stable after init

    // Check if client is still active after getting snapshot
    if (!active_snapshot || !audio_queue_snapshot) {
      break;
    }

    // Create mix excluding THIS client's audio using snapshot data
    START_TIMER("mix_%s", client_id_snapshot);

    // ADAPTIVE READING: Read more samples when we're behind to catch up
    // Normal: 480 samples per 10ms iteration
    // When behind: read up to 960 samples to catch up faster
    // Check source buffer levels to decide
    int samples_to_read = 480; // Default: 10ms worth

    // Log latency at each stage in the server pipeline
    // NOTE: Skipping mixer source latency logging due to potential use-after-free
    // when source IDs are freed during concurrent client cleanup
    if (g_audio_mixer) {
      // Log outgoing queue latency
      size_t queue_depth = packet_queue_size(audio_queue_snapshot);
      float queue_latency_ms = (float)queue_depth * 20.0f; // ~20ms per Opus packet
      log_dev_every(5 * NS_PER_MS_INT, "LATENCY: Server send queue for client %s: %.1fms (%zu packets)",
                    client_id_snapshot, queue_latency_ms, queue_depth);
    }

    int samples_mixed = 0;
    uint32_t client_id_hash = fnv1a_hash_string(client_id_snapshot);
    uint64_t stats_mix_start = time_get_ns();
    samples_mixed = mixer_process_excluding_source(g_audio_mixer, mix_buffer, samples_to_read, client_id_hash);
    stats_duration_record(stats_runtime_scope(), STATS_DURATION_AUDIO_MIX, time_get_ns() - stats_mix_start);

    STOP_TIMER_AND_LOG_EVERY(dev, NS_PER_SEC_INT, 5 * NS_PER_MS_INT, "mix_%s", "Mixer for client %s: took",
                             client_id_snapshot);

    log_debug_every(LOG_RATE_SLOW, "Audio render for client %s: samples_mixed=%d", client_id_snapshot, samples_mixed);

    // Accumulate all samples (including 0 or partial) until we have a full Opus frame
    // This maintains continuous stream without silence padding
    START_TIMER("accum_%s", client_id_snapshot);

    int space_available = OPUS_FRAME_SAMPLES - opus_frame_accumulated;
    int samples_to_copy = (samples_mixed <= space_available) ? samples_mixed : space_available;

    // Only copy if we have samples, otherwise just wait for next frame
    if (samples_to_copy > 0) {
      SAFE_MEMCPY(opus_frame_buffer + opus_frame_accumulated,
                  (OPUS_FRAME_SAMPLES - opus_frame_accumulated) * sizeof(float), mix_buffer,
                  samples_to_copy * sizeof(float));
      opus_frame_accumulated += samples_to_copy;
    }

    STOP_TIMER_AND_LOG_EVERY(dev, NS_PER_SEC_INT, 2 * NS_PER_MS_INT, "accum_%s", "Accumulate for client %s: took",
                             client_id_snapshot);

    // Only encode and send when we have accumulated a full Opus frame
    if (opus_frame_accumulated >= OPUS_FRAME_SAMPLES) {
      // A completed Opus frame is only 20 ms, while the outgoing audio queue
      // is the same ordered path that precedes video. Enforce the bound for
      // every frame: checking only once per 100 iterations lets a 200 ms
      // backlog grow past a second before the producer reacts.
      size_t queue_depth = packet_queue_size(audio_queue_snapshot);
      bool apply_backpressure = queue_depth >= 10;
      if (apply_backpressure) {
        log_warn_every(4500 * US_PER_MS_INT,
                       "Audio backpressure for client %s: queue depth %zu packets (%.1fms buffered)",
                       client_id_snapshot, queue_depth, (float)queue_depth / 50.0f * 1000.0f);
      }

      if (apply_backpressure) {
        // Skip this packet to let the queue drain
        // Reset accumulation buffer so fresh samples can be captured on next iteration.
        // Without this reset, we'd loop forever with stale audio and no space for new samples
        opus_frame_accumulated = 0;
        // Reduced sleep from 5.8ms to 1ms to minimize audio gaps on localhost
        platform_sleep_ns(1 * NS_PER_MS_INT);
        continue;
      }

      // Encode accumulated Opus frame (960 samples = 20ms @ 48kHz)
      uint8_t opus_buffer[1024]; // Max Opus frame size

      START_TIMER("opus_encode_%s", client_id_snapshot);

      int opus_size =
          opus_codec_encode(opus_encoder, opus_frame_buffer, OPUS_FRAME_SAMPLES, opus_buffer, sizeof(opus_buffer));

      STOP_TIMER_AND_LOG_EVERY(dev, NS_PER_SEC_INT, 10 * NS_PER_MS_INT, "opus_encode_%s",
                               "Opus encode for client %s: took", client_id_snapshot);

      // DEBUG: Log mix buffer and encoding results to see audio levels being sent
      {
        float peak = 0.0f, rms = 0.0f;
        for (int i = 0; i < OPUS_FRAME_SAMPLES; i++) {
          float abs_val = fabsf(opus_frame_buffer[i]);
          if (abs_val > peak)
            peak = abs_val;
          rms += opus_frame_buffer[i] * opus_frame_buffer[i];
        }
        rms = sqrtf(rms / OPUS_FRAME_SAMPLES);
        // NOTE: server_audio_frame_count is now per-thread (not static), so each client thread has its own counter
        server_audio_frame_count++;
        if (server_audio_frame_count <= 5 || server_audio_frame_count % 20 == 0) {
          // Log first 4 samples to verify they look like valid audio (not NaN/Inf/garbage)
          log_dev_every(4500 * US_PER_MS_INT,
                        "Server audio frame #%d for client %s: samples_mixed=%d, Peak=%.6f, RMS=%.6f, opus_size=%d, "
                        "first4=[%.4f,%.4f,%.4f,%.4f]",
                        server_audio_frame_count, client_id_snapshot, samples_mixed, peak, rms, opus_size,
                        opus_frame_buffer[0], opus_frame_buffer[1], opus_frame_buffer[2], opus_frame_buffer[3]);
        }
      }

      // Always reset accumulation buffer after attempting to encode - we've consumed these samples
      // If we don't reset, new audio samples would be dropped while stale data sits in the buffer
      opus_frame_accumulated = 0;

      if (opus_size <= 0) {
        log_error_every(US_PER_SEC_INT, "Failed to encode audio to Opus for client %s: opus_size=%d",
                        client_id_snapshot, opus_size);
      } else {
        // Wrap Opus data in proper batch packet format for client parsing:
        // Header: sample_rate (4B) + frame_duration (4B) + frame_count (4B)
        // Frame sizes: frame_count * 2B (one uint16 per frame with Opus data size)
        // Opus data: raw encoded audio

        // Fixed values for Opus encoding (standard 48kHz, 960 samples per frame = 20ms)
        const uint32_t sample_rate = 48000;
        const uint32_t frame_duration = 20; // milliseconds (960 samples / 48kHz = 20ms)
        const uint32_t frame_count = 1;     // one Opus frame per packet
        const uint16_t frame_size = (uint16_t)opus_size;

        // Calculate total packet size: 16-byte header + frame_sizes + opus data
        const size_t header_size = 16; // 4 uint32s (sample_rate, frame_duration, frame_count, reserved)
        const size_t frame_sizes_size = (size_t)frame_count * sizeof(uint16_t);
        const size_t total_packet_size = header_size + frame_sizes_size + (size_t)opus_size;

        // Allocate buffer for the complete packet
        uint8_t *packet_buffer = SAFE_MALLOC(total_packet_size, uint8_t *);
        if (!packet_buffer) {
          log_error("Failed to allocate Opus batch packet buffer for client %s (size=%zu)", client_id_snapshot,
                    total_packet_size);
        } else {
          // Build header in network byte order
          uint8_t *ptr = packet_buffer;

          // Write sample_rate (4 bytes, network byte order)
          uint32_t sr_net = htonl(sample_rate);
          memcpy(ptr, &sr_net, 4);
          ptr += 4;

          // Write frame_duration (4 bytes, network byte order)
          uint32_t fd_net = htonl(frame_duration);
          memcpy(ptr, &fd_net, 4);
          ptr += 4;

          // Write frame_count (4 bytes, network byte order)
          uint32_t fc_net = htonl(frame_count);
          memcpy(ptr, &fc_net, 4);
          ptr += 4;

          // Write reserved field (4 bytes, all zeros)
          uint32_t reserved = 0;
          memcpy(ptr, &reserved, 4);
          ptr += 4;

          // Write frame sizes (2 bytes per frame, network byte order)
          for (uint32_t i = 0; i < frame_count; i++) {
            uint16_t fs_net = htons(frame_size);
            memcpy(ptr, &fs_net, 2);
            ptr += 2;
          }

          // Copy Opus data
          memcpy(ptr, opus_buffer, (size_t)opus_size);

          // Queue the properly formatted packet
          START_TIMER("audio_queue_%s", client_id_snapshot);

          asciichat_error_t result = client->event_driven
                                         ? server_event_audio(client, packet_buffer, total_packet_size)
                                         : packet_queue_push_copy(audio_queue_snapshot, PACKET_TYPE_AUDIO_OPUS_BATCH,
                                                                  packet_buffer, total_packet_size, 0);

          STOP_TIMER_AND_LOG_EVERY(dev, NS_PER_SEC_INT, 1 * NS_PER_MS_INT, "audio_queue_%s",
                                   "Audio queue for client %s: took", client_id_snapshot);

          if (result != ASCIICHAT_OK) {
            log_debug_every(US_PER_SEC_INT, "Failed to queue Opus audio for client %s", client_id_snapshot);
          } else {
            // FPS tracking - audio packet successfully queued (handles lag detection and periodic reporting)
            fps_frame_ns(&audio_fps_tracker, time_get_ns(), "audio packet queued");
          }

          // Free the allocated packet buffer after queuing (packet_queue_push_copy copies data)
          SAFE_FREE(packet_buffer);
        }
      }
      // NOTE: opus_frame_accumulated is already reset at line 928 after encode attempt
    }

    // Audio mixing rate limiting using adaptive sleep system
    // Target: 10ms intervals (100 FPS) for 480 samples @ 48kHz
    // Use queue_depth=0 and target_depth=0 for constant-rate audio processing
    audio_deadline += 10 * NS_PER_MS_INT;
    uint64_t now = time_get_ns();
    if (audio_deadline > now)
      platform_sleep_ns(audio_deadline - now);
    else if (now - audio_deadline > 100 * NS_PER_MS_INT)
      audio_deadline = now;
  }

#ifdef DEBUG_THREADS
  log_debug("Audio render thread stopped for client %s", thread_client_id);
#endif

  // Clean up Opus encoder
  if (opus_encoder) {
    opus_codec_destroy(opus_encoder);
  }

  // Clean up thread-local error context before exit

  return NULL;
}

int create_client_render_threads(server_context_t *server_ctx, client_info_t *client) {
  log_debug("★★★ create_client_render_threads() CALLED for client_id=%s", client ? client->client_id : "NULL");

  if (!server_ctx || !client) {
    log_error("Cannot create render threads: NULL %s", !server_ctx ? "server_ctx" : "client");
    return -1;
  }

#ifdef DEBUG_THREADS
  log_debug("Creating render threads for client %s", client->client_id);
#endif

  // NOTE: Mutexes are already initialized in add_client() before any threads start
  // This prevents race conditions where receive thread tries to use uninitialized mutexes

  // Initialize render thread control flags
  // IMPORTANT: Set to true BEFORE creating thread to avoid race condition
  // where thread starts and immediately exits because flag is false
  atomic_store_bool(&client->video_render_thread_running, true);
  atomic_store_bool(&client->audio_render_thread_running, true);

  // Create video rendering thread (stop_id=2, stop after receive thread)
  char thread_name[64];
  safe_snprintf(thread_name, sizeof(thread_name), "video_render_%s", client->client_id);
  asciichat_error_t video_result;

  video_result = asciichat_thread_create(&client->video_render_thread, thread_name, client_video_render_thread, client);

  if (video_result != ASCIICHAT_OK) {
    // Reset flag since thread creation failed
    atomic_store_bool(&client->video_render_thread_running, false);
    // Mutexes will be destroyed by remove_client() which called us
    return -1;
  }

  // Create audio rendering thread (stop_id=2, same priority as video)
  safe_snprintf(thread_name, sizeof(thread_name), "audio_render_%s", client->client_id);
  asciichat_error_t audio_result;

  audio_result = asciichat_thread_create(&client->audio_render_thread, thread_name, client_audio_render_thread, client);
  if (audio_result != ASCIICHAT_OK) {
    // Clean up video thread (atomic operation, no mutex needed)
    atomic_store_bool(&client->video_render_thread_running, false);
    // Reset audio flag since thread creation failed
    atomic_store_bool(&client->audio_render_thread_running, false);
    // stop_client_render_threads() will be called by remove_client()
    // to clean up the video thread we just created
    // Mutexes will be destroyed by remove_client() which called us
    return -1;
  }

#ifdef DEBUG_THREADS
  log_debug("Created render threads for client %s", client->client_id);
#endif

  return 0;
}

void stop_client_render_threads(client_info_t *client) {
  if (!client) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Client is NULL");
    return;
  }

  log_debug("Stopping render threads for client %s", client->client_id);

  // Signal threads to stop (atomic operations, no mutex needed)
  atomic_store_bool(&client->video_render_thread_running, false);
  atomic_store_bool(&client->audio_render_thread_running, false);

  // Wait for threads to finish (deterministic cleanup)
  // During shutdown, don't wait forever for threads to join
  bool is_shutting_down = atomic_load_bool(&g_should_exit);

  if (asciichat_thread_is_initialized(&client->video_render_thread)) {
    log_debug("Joining video render thread for client %s", client->client_id);
    int result;
    if (is_shutting_down) {
      // During shutdown, don't timeout - wait for thread to exit
      // Timeouts mask the real problem: threads that are still running
      log_debug("Shutdown mode: joining video render thread for client %s (no timeout)", client->client_id);
      result = asciichat_thread_join(&client->video_render_thread, NULL);
      if (result != 0) {
        log_warn("Video render thread for client %s failed to join during shutdown: %s", client->client_id,
                 SAFE_STRERROR(result));
      }
    } else {
      log_debug("Calling asciichat_thread_join for video thread of client %s", client->client_id);
      result = asciichat_thread_join(&client->video_render_thread, NULL);
      log_debug("asciichat_thread_join returned %d for video thread of client %s", result, client->client_id);
    }

    if (result == 0) {
#ifdef DEBUG_THREADS
      log_debug("Video render thread joined for client %s", client->client_id);
#endif
    } else if (result != -2) { // Don't log timeout errors again
      if (is_shutting_down) {
        log_warn("Failed to join video render thread for client %s during shutdown (continuing): %s", client->client_id,
                 SAFE_STRERROR(result));
      } else {
        log_error("Failed to join video render thread for client %s: %s", client->client_id, SAFE_STRERROR(result));
      }
    }
    if (result == 0) {
      asciichat_thread_init(&client->video_render_thread);
    }
  }

  if (asciichat_thread_is_initialized(&client->audio_render_thread)) {
    int result;
    if (is_shutting_down) {
      // During shutdown, don't timeout - wait for thread to exit
      // Timeouts mask the real problem: threads that are still running
      log_debug("Shutdown mode: joining audio render thread for client %s (no timeout)", client->client_id);
      result = asciichat_thread_join(&client->audio_render_thread, NULL);
      if (result != 0) {
        log_warn("Audio render thread for client %s failed to join during shutdown: %s", client->client_id,
                 SAFE_STRERROR(result));
      }
    } else {
      result = asciichat_thread_join(&client->audio_render_thread, NULL);
    }

    if (result == 0) {
#ifdef DEBUG_THREADS
      log_debug("Audio render thread joined for client %s", client->client_id);
#endif
    } else if (result != -2) { // Don't log timeout errors again
      if (is_shutting_down) {
        log_warn("Failed to join audio render thread for client %s during shutdown (continuing): %s", client->client_id,
                 SAFE_STRERROR(result));
      } else {
        log_error("Failed to join audio render thread for client %s: %s", client->client_id, SAFE_STRERROR(result));
      }
    }
    if (result == 0) {
      asciichat_thread_init(&client->audio_render_thread);
    }
  }

  // DO NOT destroy the mutex here - client.c will handle it
  // mutex_destroy(&client->client_state_mutex);

#ifdef DEBUG_THREADS
  log_debug("Successfully destroyed render threads for client %s", client->client_id);
#endif
}

int stats_init(void) {
  if (!lifecycle_init(&g_stats_lc, "stats")) {
    return 0; // Already initialized
  }
  return 0;
}

void stats_cleanup(void) {
  lifecycle_shutdown(&g_stats_lc);
}

void *stats_logger_thread(void *arg) {
  (void)arg;

  while (!atomic_load_bool(&g_should_exit)) {
    // Log buffer domain statistics every 10 seconds with fast exit checking (10ms intervals)
    for (int i = 0; i < 1000 && !atomic_load_bool(&g_should_exit); i++) {
      platform_sleep_us(10 * US_PER_MS_INT); // 10ms sleep
    }

    // Check exit condition before proceeding with statistics logging
    // Check multiple times to avoid accessing freed resources during shutdown.
    if (atomic_load_bool(&g_should_exit)) {
      break;
    }

    buffer_domain_log_stats(buffer_default_domain(), "media");
    buffer_domain_log_stats(buffer_control_domain(), "control");
    buffer_domain_trim(buffer_default_domain());
    buffer_domain_trim(buffer_control_domain());

    // Collect all statistics data first
#ifndef NDEBUG
    char lock_debug_info[BUFFER_SIZE_MEDIUM] = {0};
    // Check exit condition again before accessing lock_debug.
    // lock_debug might be destroyed during shutdown
    if (!atomic_load_bool(&g_should_exit) && debug_sync_is_initialized()) {
      uint64_t total_acquired = 0, total_released = 0;
      uint32_t currently_held = 0;
      debug_sync_get_stats(&total_acquired, &total_released, &currently_held);

      safe_snprintf(lock_debug_info, sizeof(lock_debug_info),
                    "Historical Mutex/RWLock Statistics:\n"
                    "  Total locks acquired: %llu\n"
                    "  Total locks released: %llu\n"
                    "  Currently held: %u\n"
                    "  Net locks (acquired - released): %lld",
                    (unsigned long long)total_acquired, (unsigned long long)total_released, currently_held,
                    (long long)total_acquired - (long long)total_released);
    }
#endif

    // Collect client statistics
    // Check exit condition again before accessing rwlock.
    // rwlock might be destroyed during shutdown.
    if (atomic_load_bool(&g_should_exit)) {
      break;
    }

    rwlock_rdlock(&g_client_manager_rwlock);
    int active_clients = 0;
    int clients_with_audio = 0;
    int clients_with_video = 0;
    char client_details[BUFFER_SIZE_XLARGE] = {0};
    int client_details_len = 0;

    for (int i = 0; i < MAX_CLIENTS; i++) {
      if (atomic_load_bool(&g_client_manager.clients[i].active)) {
        active_clients++;
        if (g_client_manager.clients[i].audio_queue) {
          clients_with_audio++;
        }
        if (g_client_manager.clients[i].outgoing_video_buffer) {
          clients_with_video++;
        }
      }
    }

    // Collect per-client details
    for (int i = 0; i < MAX_CLIENTS; i++) {
      client_info_t *client = &g_client_manager.clients[i];
      bool is_active = atomic_load_bool(&client->active);
      const char *client_id_snapshot = client->client_id;

      if (is_active && client_id_snapshot != 0) {
        // Check audio queue stats
        if (client->audio_queue) {
          uint64_t enqueued, dequeued, dropped;
          packet_queue_get_stats(client->audio_queue, &enqueued, &dequeued, &dropped);
          if (enqueued > 0 || dequeued > 0 || dropped > 0) {
            int len =
                safe_snprintf(client_details + client_details_len, sizeof(client_details) - client_details_len,
                              "  Client %u audio queue: %llu enqueued, %llu dequeued, %llu dropped", client_id_snapshot,
                              (unsigned long long)enqueued, (unsigned long long)dequeued, (unsigned long long)dropped);
            if (len > 0 && client_details_len + len < (int)sizeof(client_details)) {
              client_details_len += len;
            }
          }
        }
        // Check video buffer stats
        if (client->outgoing_video_buffer) {
          video_frame_stats_t stats;
          video_frame_get_stats(client->outgoing_video_buffer, &stats);
          if (stats.total_frames > 0) {
            int len = safe_snprintf(client_details + client_details_len, sizeof(client_details) - client_details_len,
                                    "  Client %u video buffer: %llu frames, %llu dropped (%.1f%% drop rate)",
                                    client_id_snapshot, (unsigned long long)stats.total_frames,
                                    (unsigned long long)stats.dropped_frames, stats.drop_rate * 100.0f);
            if (len > 0 && client_details_len + len < (int)sizeof(client_details)) {
              client_details_len += len;
            }
          }
        }
      }
    }
    rwlock_rdunlock(&g_client_manager_rwlock);

    // Single comprehensive log statement
    if (client_details_len > 0) {
      log_info("Stats: Clients: %d, Audio: %d, Video: %d\n%s", active_clients, clients_with_audio, clients_with_video,
               client_details);
    }
  }

  log_server_stats();

  asciichat_error_stats_print();

  // Clean up thread-local error context before exit

  return NULL;
}

void update_server_stats(void) {
  stats_snapshot_t snapshot;
  if (!lifecycle_is_initialized(&g_stats_lc) || stats_scope_snapshot(stats_runtime_scope(), &snapshot) != ASCIICHAT_OK)
    return;
  mutex_lock(&g_stats_mutex);
  g_stats.frames_captured = snapshot.counters[STATS_COUNTER_FRAMES_RECEIVED];
  g_stats.frames_sent = snapshot.counters[STATS_COUNTER_FRAMES_SENT];
  g_stats.frames_dropped = snapshot.counters[STATS_COUNTER_FRAMES_DROPPED];
  double seconds = (double)(snapshot.sampled_ns - snapshot.started_ns) / 1e9;
  g_stats.avg_capture_fps = seconds > 0 ? (double)g_stats.frames_captured / seconds : 0;
  g_stats.avg_send_fps = seconds > 0 ? (double)g_stats.frames_sent / seconds : 0;
  mutex_unlock(&g_stats_mutex);
}

void log_server_stats(void) {
  // Check if stats mutex is initialized (safe in debug builds where stats_init() may not be called)
  if (!lifecycle_is_initialized(&g_stats_lc)) {
    return; // Mutex not initialized, skip logging
  }

  // Now safe to use the mutex
  mutex_lock(&g_stats_mutex);
  log_info("Server Statistics:\n"
           "  frames_captured=%llu\n"
           "  frames_sent=%llu\n"
           "  frames_dropped=%llu\n"
           "  Average FPS: capture=%.2f, send=%.2f",
           (unsigned long long)g_stats.frames_captured, (unsigned long long)g_stats.frames_sent,
           (unsigned long long)g_stats.frames_dropped, g_stats.avg_capture_fps, g_stats.avg_send_fps);
  mutex_unlock(&g_stats_mutex);
}

static int collect_video_sources(image_source_t *sources, int max_sources) {
  int source_count = 0;

  // Check for shutdown before acquiring locks to prevent lock corruption
  if (atomic_load_bool(&g_should_exit)) {
    return 0;
  }

  // Keep client slots and their incoming frame buffers alive until every
  // active source has been copied out of its double buffer. remove_client()
  // frees those buffers under the manager write lock after stopping only that
  // client's own workers; the other clients' render workers also read them.
  bool manager_lock_held = g_client_manager_rwlock_initialized;
  if (manager_lock_held) {
    rwlock_rdlock(&g_client_manager_rwlock);
  }

  // Snapshot fields while holding the manager read lock so removal cannot
  // invalidate a frame-buffer pointer between this scan and its copy.
  typedef struct {
    char client_id[MAX_CLIENT_ID_LEN];
    bool is_active;
    bool is_sending_video;
    video_frame_buffer_t *video_buffer;
  } client_snapshot_t;

  client_snapshot_t client_snapshots[MAX_CLIENTS];
  int snapshot_count = 0;

  // The manager read lock protects slot identity and buffer lifetime; stream
  // flags are atomic because receive callbacks update them independently.
  for (int i = 0; i < MAX_CLIENTS; i++) {
    client_info_t *client = &g_client_manager.clients[i];

    if (client->client_id[0] == '\0') {
      continue; // Skip uninitialized clients
    }

    // Snapshot all needed client state (all atomic reads or stable pointers)
    SAFE_STRNCPY(client_snapshots[snapshot_count].client_id, client->client_id,
                 sizeof(client_snapshots[snapshot_count].client_id) - 1);
    client_snapshots[snapshot_count].is_active = atomic_load_bool(&client->active);
    client_snapshots[snapshot_count].is_sending_video = atomic_load_bool(&client->is_sending_video);
    client_snapshots[snapshot_count].video_buffer = client->incoming_video_buffer; // Stable pointer
    snapshot_count++;
  }

  // Process frames (expensive operations)
  log_dev_every(5 * NS_PER_MS_INT, "collect_video_sources: Processing %d snapshots", snapshot_count);
  for (int i = 0; i < snapshot_count && source_count < max_sources; i++) {
    client_snapshot_t *snap = &client_snapshots[i];

    if (!snap->is_active) {
      log_dev_every(5 * NS_PER_MS_INT, "collect_video_sources: Skipping inactive client %s", snap->client_id);
      continue;
    }

    log_dev_every(5 * NS_PER_MS_INT, "collect_video_sources: Client %s: is_sending_video=%d", snap->client_id,
                  snap->is_sending_video);

    SAFE_STRNCPY(sources[source_count].client_id, snap->client_id, sizeof(sources[source_count].client_id) - 1);
    sources[source_count].image = NULL; // Will be set if video is available
    sources[source_count].has_video = false;

    // Declare these outside the if block so they're accessible later
    multi_source_frame_t current_frame = {0};
    bool got_new_frame = false;

    // Always try to get the last available video frame for consistent ASCII generation.
    // Keep the swap mutex held until the front-buffer bytes have been copied:
    // after the next commit, this frame becomes the writer's back buffer and
    // can be overwritten while the compositor is still reading it.
    if (snap->is_sending_video && snap->video_buffer) {
      video_frame_buffer_t *video_buffer = snap->video_buffer;
      mutex_lock(&video_buffer->swap_mutex);
      const video_frame_t *frame = video_buffer->front_buffer;
      if (!frame || !frame->data || frame->size < sizeof(uint32_t) * 2 ||
          frame->size > video_buffer->allocated_buffer_size) {
        mutex_unlock(&video_buffer->swap_mutex);
        continue;
      }

      size_t frame_size_val = frame->size;

      if (frame_size_val >= (sizeof(uint32_t) * 2 + 3)) {
        // PARSE AND VALIDATE DIMENSIONS BEFORE COPYING
        // Don't trust frame->size - calculate correct size from dimensions
        uint32_t peek_width = NET_TO_HOST_U32(read_u32_unaligned(frame->data));
        uint32_t peek_height = NET_TO_HOST_U32(read_u32_unaligned(frame->data + sizeof(uint32_t)));

        // Reject obviously corrupted dimensions
        if (peek_width == 0 || peek_height == 0 || peek_width > 4096 || peek_height > 2160) {
          log_debug("Per-client %s: rejected dimensions %ux%u as corrupted", snap->client_id, peek_width, peek_height);
          mutex_unlock(&video_buffer->swap_mutex);
          continue;
        }

        // Validate dimensions
        if (image_validate_dimensions((size_t)peek_width, (size_t)peek_height) != ASCIICHAT_OK) {
          mutex_unlock(&video_buffer->swap_mutex);
          continue;
        }

        // Calculate CORRECT frame size based on dimensions (don't trust frame->size)
        size_t correct_frame_size = sizeof(uint32_t) * 2;
        {
          size_t rgb_size = 0;
          if (image_calc_rgb_size((size_t)peek_width, (size_t)peek_height, &rgb_size) != ASCIICHAT_OK) {
            log_debug("Per-client: rgb_size calc failed for %ux%u", peek_width, peek_height);
            mutex_unlock(&video_buffer->swap_mutex);
            continue;
          }
          correct_frame_size += rgb_size;
        }

        log_debug_every(NS_PER_MS_INT, "Per-client: frame dimensions=%ux%u, frame_size=%zu, correct_size=%zu",
                        peek_width, peek_height, frame_size_val, correct_frame_size);

        // Verify frame is at least large enough for the correct size
        if (frame_size_val < correct_frame_size) {
          log_debug("Per-client: frame too small: got %zu, need %zu", frame_size_val, correct_frame_size);
          mutex_unlock(&video_buffer->swap_mutex);
          continue;
        }

        // We have frame data - copy ONLY the correct amount based on dimensions
        current_frame.data = buffer_alloc(NULL, correct_frame_size);

        if (current_frame.data) {
          memcpy(current_frame.data, frame->data, correct_frame_size);
          current_frame.size = correct_frame_size;
          SAFE_STRNCPY(current_frame.source_client_id, snap->client_id, sizeof(current_frame.source_client_id) - 1);
          current_frame.timestamp = (uint32_t)(frame->capture_timestamp_ns / NS_PER_SEC_INT);
          got_new_frame = true;
          // Keep the frame for reuse, but mark it consumed before the next swap.
          atomic_store_bool(&video_buffer->new_frame_available, false);
        }
        mutex_unlock(&video_buffer->swap_mutex);
      } else {
        mutex_unlock(&video_buffer->swap_mutex);
      }
    }

    multi_source_frame_t *frame_to_use = got_new_frame ? &current_frame : NULL;

    if (frame_to_use && frame_to_use->data && frame_to_use->size > sizeof(uint32_t) * 2) {
      // Parse the image data
      // Format: [width:4][height:4][rgb_data:w*h*3]
      // Use unaligned read helpers - frame data may not be aligned
      uint32_t img_width = NET_TO_HOST_U32(read_u32_unaligned(frame_to_use->data));
      uint32_t img_height = NET_TO_HOST_U32(read_u32_unaligned(frame_to_use->data + sizeof(uint32_t)));

      // Debug logging to understand the data
      if (img_width == 0xBEBEBEBE || img_height == 0xBEBEBEBE) {
        SET_ERRNO(ERROR_INVALID_STATE, "Uninitialized frame dimensions from client %s: 0x%08x x 0x%08x",
                  snap->client_id, img_width, img_height);
      }

      // Validate dimensions using image utility function
      if (image_validate_dimensions((size_t)img_width, (size_t)img_height) != ASCIICHAT_OK) {
        SET_ERRNO(ERROR_INVALID_STATE,
                  "Per-client: Invalid image dimensions from client %s: %ux%u (data may be corrupted)", snap->client_id,
                  img_width, img_height);
        if (got_new_frame) {
          buffer_release(current_frame.data);
        }
        source_count++;
        continue;
      }

      // Calculate expected frame size with overflow checking
      size_t expected_size = sizeof(uint32_t) * 2;
      {
        size_t rgb_size = 0;
        if (image_calc_rgb_size((size_t)img_width, (size_t)img_height, &rgb_size) != ASCIICHAT_OK) {
          SET_ERRNO(ERROR_INVALID_STATE, "Per-client: RGB size calculation failed for client %s: %ux%u",
                    snap->client_id, img_width, img_height);
          if (got_new_frame) {
            buffer_release(current_frame.data);
          }
          source_count++;
          continue;
        }
        expected_size += rgb_size;
      }
      if (frame_to_use->size != expected_size) {
        SET_ERRNO(ERROR_INVALID_STATE,
                  "Per-client: Frame size mismatch from client %s: got %zu, expected %zu for %ux%u image",
                  snap->client_id, frame_to_use->size, expected_size, img_width, img_height);
        if (got_new_frame) {
          buffer_release(current_frame.data);
        }
        source_count++;
        continue;
      }

      // Extract pixel data pointer
      rgb_pixel_t *pixels = (rgb_pixel_t *)(frame_to_use->data + (sizeof(uint32_t) * 2));

      // Create image from buffer domain for consistent video pipeline management
      image_t *img = image_new(img_width, img_height);
      if (!img) {
        log_error("Per-client: image_new failed for %ux%u", img_width, img_height);
        if (got_new_frame) {
          buffer_release(current_frame.data);
        }
        continue;
      }
      memcpy(img->pixels, pixels, (size_t)img_width * (size_t)img_height * sizeof(rgb_pixel_t));
      sources[source_count].image = img;
      sources[source_count].has_video = true;

      // Free temporary frame buffer - image has its own pixel data now
      if (got_new_frame) {
        buffer_release(current_frame.data);
      }
    } else {
      // frame_to_use check failed - clean up allocated frame data
      if (got_new_frame && current_frame.data) {
        buffer_release(current_frame.data);
      }
    }

    // Increment source count for this active client (with or without video)
    source_count++;
  }

  if (manager_lock_held) {
    rwlock_rdunlock(&g_client_manager_rwlock);
  }
  return source_count;
}

static image_t *create_single_source_composite(image_source_t *sources, int source_count,
                                               const char *target_client_id __attribute__((unused)),
                                               unsigned short width __attribute__((unused)),
                                               unsigned short height __attribute__((unused))) {
  // Find the single source with video
  image_t *single_source = NULL;
  for (int i = 0; i < source_count; i++) {
    if (sources[i].has_video && sources[i].image) {
      single_source = sources[i].image;
      break;
    }
  }

  if (!single_source) {
    SET_ERRNO(ERROR_INVALID_STATE, "Logic error: sources_with_video=1 but no source found");
    return NULL;
  }

  // For single source, don't pre-fit the image. Let ascii_convert_with_capabilities handle
  // all aspect ratio fitting with proper CHAR_ASPECT correction. This avoids double-correction
  // that was happening when the image was pre-fitted in pixel space and then aspect_ratio()
  // was called again with CHAR_ASPECT=2.0.
  // Just return the source image as-is; ascii_convert_with_capabilities will fit it properly.
  return single_source;
}

static void calculate_optimal_grid_layout(image_source_t *sources, int source_count, int sources_with_video,
                                          int terminal_width, int terminal_height, int *out_cols, int *out_rows) {
  // Special cases
  if (sources_with_video == 0) {
    *out_cols = 0;
    *out_rows = 0;
    return;
  }

  if (sources_with_video == 1) {
    *out_cols = 1;
    *out_rows = 1;
    return;
  }

  // ASCII character aspect ratio: characters are ~2x taller than wide
  // So we need to adjust terminal dimensions to visual space
  const float CHAR_ASPECT = 2.0f; // Character height / width ratio

  // Calculate average aspect ratio of all video sources
  float avg_aspect = 0.0f;
  int aspect_count = 0;
  for (int i = 0; i < source_count; i++) {
    if (sources[i].has_video && sources[i].image) {
      float aspect = (float)sources[i].image->w / (float)sources[i].image->h;
      avg_aspect += aspect;
      aspect_count++;
    }
  }
  if (aspect_count > 0) {
    avg_aspect /= aspect_count;
  } else {
    avg_aspect = 1.6f; // Default aspect ratio
  }

  // Try all reasonable grid configurations
  int best_cols = 1;
  int best_rows = sources_with_video;
  float best_utilization = 0.0f;

  // Try grid configurations from 1x1 up to reasonable limits
  for (int cols = 1; cols <= sources_with_video; cols++) {
    int rows = (sources_with_video + cols - 1) / cols; // Ceiling division

    // Skip configurations with too many empty cells (more than one row worth)
    int total_cells = cols * rows;
    int empty_cells = total_cells - sources_with_video;
    if (empty_cells > cols) {
      continue;
    }

    // Calculate cell dimensions for this configuration
    int cell_width = terminal_width / cols;
    int cell_height = terminal_height / rows;

    // Skip if cells would be too small
    if (cell_width < 20 || cell_height < 10) {
      continue;
    }

    // Calculate total area utilized by all videos in this configuration
    // For each video, calculate how much space it would use in a cell
    // IMPORTANT: Account for character aspect ratio (chars are 2x taller than wide)
    float total_area_used = 0.0f;
    int cell_area = cell_width * cell_height;

    for (int i = 0; i < sources_with_video; i++) {
      // Use average aspect ratio for calculation
      float video_aspect = avg_aspect;

      // Calculate VISUAL cell aspect ratio (accounting for character shape)
      // A cell that is cell_width chars wide and cell_height chars tall
      // has visual aspect = cell_width / (cell_height * CHAR_ASPECT)
      float cell_visual_aspect = (float)cell_width / ((float)cell_height * CHAR_ASPECT);

      // Calculate fitted dimensions while preserving aspect ratio
      int fitted_width, fitted_height;

      if (video_aspect > cell_visual_aspect) {
        // Video is wider than cell - fit to width
        fitted_width = cell_width;
        // Visual height needed: cell_width / video_aspect
        // Character height: visual_height / CHAR_ASPECT
        fitted_height = (int)((cell_width / video_aspect) / CHAR_ASPECT);
      } else {
        // Video is taller than cell - fit to height
        fitted_height = cell_height;
        // Visual width needed: cell_height * CHAR_ASPECT * video_aspect
        fitted_width = (int)(cell_height * CHAR_ASPECT * video_aspect);
      }

      // Clamp to cell bounds
      if (fitted_width > cell_width) {
        fitted_width = cell_width;
      }
      if (fitted_height > cell_height) {
        fitted_height = cell_height;
      }

      // Add area used by this video
      total_area_used += fitted_width * fitted_height;
    }

    // Calculate utilization percentage
    float total_available_area = (float)(cell_area * sources_with_video);
    float utilization = total_area_used / total_available_area;

    float test_cell_visual_aspect = (float)cell_width / ((float)cell_height * CHAR_ASPECT);
    log_dev_every(LOG_RATE_NORMAL, "  Testing %dx%d: cell=%dx%d (visual aspect %.2f), utilization=%.1f%%", cols, rows,
                  cell_width, cell_height, test_cell_visual_aspect, utilization * 100.0f);

    // Prefer configurations with better utilization
    if (utilization > best_utilization) {
      best_utilization = utilization;
      best_cols = cols;
      best_rows = rows;
    }
  }

  *out_cols = best_cols;
  *out_rows = best_rows;

  float terminal_visual_aspect = (float)terminal_width / ((float)terminal_height * CHAR_ASPECT);
  log_dev_every(LOG_RATE_NORMAL,
                "Grid layout: %d clients -> %dx%d grid (%.1f%% utilization) | terminal=%dx%d (char aspect %.2f, VISUAL "
                "aspect %.2f), video aspect: %.2f",
                sources_with_video, best_cols, best_rows, best_utilization * 100.0f, terminal_width, terminal_height,
                (float)terminal_width / (float)terminal_height, terminal_visual_aspect, avg_aspect);
}

static image_t *create_multi_source_composite(image_source_t *sources, int source_count, int sources_with_video,
                                              const char *target_client_id, unsigned short width,
                                              unsigned short height) {
  (void)target_client_id; // Unused - composite is same for all clients now

  // Calculate optimal grid layout using space-maximizing algorithm
  int grid_cols, grid_rows;
  calculate_optimal_grid_layout(sources, source_count, sources_with_video, width, height, &grid_cols, &grid_rows);

  // Calculate composite dimensions in PIXELS for half-block mode
  // Terminal dimensions are in CHARACTERS, need to convert to pixels:
  // - Width: 1 char = 1 horizontal pixel
  // - Height: 1 char = 2 vertical pixels (half-block = 2 pixels per char)
  const int PIXELS_PER_CHAR_HEIGHT = 2;
  int composite_width_px = width;                            // chars = pixels horizontally
  int composite_height_px = height * PIXELS_PER_CHAR_HEIGHT; // chars * 2 = pixels vertically

  // Create composite with final dimensions - no recreation needed
  image_t *composite = image_new(composite_width_px, composite_height_px);
  image_clear(composite);

  // Place each source in the grid
  int video_source_index = 0;                                        // Track only sources with video
  for (int i = 0; i < source_count && video_source_index < 9; i++) { // Max 9 sources in 3x3 grid
    if (!sources[i].image)
      continue;

    int row = video_source_index / grid_cols;
    int col = video_source_index % grid_cols;
    video_source_index++;

    // Use actual composite dimensions for cell calculations
    // Composite is now in PIXELS (already converted from terminal characters)
    int cell_width_px = composite->w / grid_cols;
    int cell_height_px = composite->h / grid_rows;

    // Calculate aspect ratios
    float src_aspect = (float)sources[i].image->w / (float)sources[i].image->h;
    float cell_visual_aspect = (float)cell_width_px / (float)cell_height_px;

    int target_width_px, target_height_px;

    // CONTAIN strategy: Fill one dimension completely, let other scale down (never overflow)
    // Compare aspects to decide which dimension to fill
    if (src_aspect > cell_visual_aspect) {
      // Video is WIDER than cell → fill WIDTH (height will be smaller)
      target_width_px = cell_width_px;
      target_height_px = (int)((cell_width_px / src_aspect) + 0.5f);
    } else {
      // Video is TALLER than cell → fill HEIGHT (width will be smaller)
      target_height_px = cell_height_px;
      target_width_px = (int)((cell_height_px * src_aspect) + 0.5f);
    }

    log_dev_every(LOG_RATE_NORMAL, "Cell %d: %dx%d px, video %.1f, cell %.2f → target %dx%d px (fill %s)",
                  video_source_index - 1, cell_width_px, cell_height_px, src_aspect, cell_visual_aspect,
                  target_width_px, target_height_px, (src_aspect > cell_visual_aspect) ? "WIDTH" : "HEIGHT");

    // Create resized image with standard allocation
    image_t *resized = image_new(target_width_px, target_height_px);
    image_resize(sources[i].image, resized);

    // Calculate cell position in pixels (after any composite recreation)
    int cell_x_offset_px = col * cell_width_px;
    int cell_y_offset_px = row * cell_height_px;

    // Grid centering strategy:
    // - Multi-client: Apply padding ONLY to edge cells to center the grid as a whole
    //   (left column gets left padding, right column gets right padding)
    //   (top row gets top padding, bottom row gets bottom padding)
    //   This keeps cells edge-to-edge while centering the entire grid
    // - Single client: Center the image within the cell
    int x_padding_px, y_padding_px;

    // Center images within their cells for all layouts
    // This prevents gaps/stripes between clients
    x_padding_px = (cell_width_px - target_width_px) / 2;
    y_padding_px = (cell_height_px - target_height_px) / 2;

    // Define cell boundaries for clipping (prevents bleeding into adjacent cells)
    int cell_x_min = cell_x_offset_px;
    int cell_x_max = cell_x_offset_px + cell_width_px - 1;
    int cell_y_min = cell_y_offset_px;
    int cell_y_max = cell_y_offset_px + cell_height_px - 1;

    // Copy resized image to composite with cell boundary clipping
    // This allows images to fill cells completely while preventing overlap

    for (int y = 0; y < resized->h; y++) {
      for (int x = 0; x < resized->w; x++) {
        // Calculate destination position
        int dst_x = cell_x_offset_px + x_padding_px + x;
        int dst_y = cell_y_offset_px + y_padding_px + y;

        // Clip to cell boundaries (prevents bleeding into adjacent cells)
        if (dst_x < cell_x_min || dst_x > cell_x_max || dst_y < cell_y_min || dst_y > cell_y_max) {
          continue; // Skip pixels outside cell boundaries
        }

        // Additional composite boundary check
        if (dst_x < 0 || dst_x >= composite->w || dst_y < 0 || dst_y >= composite->h) {
          continue; // Skip pixels outside composite
        }

        // Copy pixel
        int src_idx = (y * resized->w) + x;
        int dst_idx = (dst_y * composite->w) + dst_x;
        composite->pixels[dst_idx] = resized->pixels[src_idx];
      }
    }

    image_destroy(resized);
  }

  return composite;
}

static char *convert_composite_to_ascii(image_t *composite, const char *target_client_id, unsigned short width,
                                        unsigned short height) {
  // LOCK OPTIMIZATION: Don't call find_client_by_id() - it would acquire rwlock unnecessarily
  // Instead, the render thread already has snapshot of client state, so we just need palette data
  // which is stable after initialization

  // We need to find the client to access palette data, but we can do this without locking
  // since palette is initialized once and never changes
  client_info_t *render_client = NULL;

  // Find client without locking - client_id is stable once set
  for (int i = 0; i < MAX_CLIENTS; i++) {
    client_info_t *client = &g_client_manager.clients[i];
    if (strcmp(client->client_id, target_client_id) == 0) {
      render_client = client;
      break;
    }
  }

  if (!render_client) {
    SET_ERRNO(ERROR_INVALID_STATE, "Per-client %s: Target client not found", target_client_id);
    return NULL;
  }

  // Snapshot terminal capabilities WITHOUT holding rwlock
  // Terminal caps are set once during handshake and never change, so this is safe
  bool has_terminal_caps_snapshot = render_client->has_terminal_caps;
  if (!has_terminal_caps_snapshot) {
    SET_ERRNO(ERROR_INVALID_STATE, "Per-client %s: Terminal capabilities not received", target_client_id);
    return NULL;
  }

  terminal_capabilities_t caps_snapshot = render_client->terminal_caps;

  if (!render_client->client_palette_initialized) {
    SET_ERRNO(ERROR_TERMINAL, "Client %s palette not initialized - cannot render frame", target_client_id);
    return NULL;
  }

  // Render with client's custom palette using enhanced capabilities
  // Palette data is stable after initialization, so no locking needed
  const int h = caps_snapshot.render_mode == RENDER_MODE_HALF_BLOCK ? height * 2 : height;

  // DEBUG: Log dimensions being used for ASCII conversion
  log_dev_every(LOG_RATE_SLOW, "convert_composite_to_ascii: composite=%dx%d, terminal=%dx%d, h=%d (mode=%d)",
                composite->w, composite->h, width, height, h, caps_snapshot.render_mode);

  // Pass full terminal dimensions so ascii_convert_with_capabilities can fit the image correctly
  // with proper CHAR_ASPECT correction. The composite may have been pre-fitted in pixel space,
  // but ascii_convert will handle terminal character aspect ratio properly when aspect_ratio=true.
  uint64_t convert_start_ns = time_get_ns();
  char *ascii_frame = ascii_convert_with_capabilities(composite, width, h, &caps_snapshot, true, false,
                                                      render_client->client_palette_chars);
  uint64_t convert_end_ns = time_get_ns();
  uint64_t convert_duration_ns = convert_end_ns - convert_start_ns;

  if (convert_duration_ns > 5 * NS_PER_MS_INT) { // Log if > 5ms
    char duration_str[32];
    time_pretty((uint64_t)((double)convert_duration_ns), -1, duration_str, sizeof(duration_str));
    log_warn_every(US_PER_SEC_INT, "SLOW_ASCII_CONVERT: Client %s took %s to convert %dx%d image to ASCII",
                   target_client_id, duration_str, composite->w, composite->h);
  }

  const bool matrix_rain = (caps_snapshot.capabilities & TERM_CAP_MATRIX_RAIN) != 0;
  if (matrix_rain && ascii_frame) {
    if (!render_client->digital_rain || render_client->digital_rain->num_columns != width ||
        render_client->digital_rain->num_rows != h) {
      if (render_client->digital_rain) {
        digital_rain_destroy(render_client->digital_rain);
      }
      render_client->digital_rain = digital_rain_init(width, h);
      render_client->digital_rain_last_update_time = (double)time_get_ns() / (double)NS_PER_SEC_INT;
    }

    if (render_client->digital_rain) {
      const double now = (double)time_get_ns() / (double)NS_PER_SEC_INT;
      const float elapsed = (float)(now - render_client->digital_rain_last_update_time);
      render_client->digital_rain_last_update_time = now;
      digital_rain_set_color_from_filter(render_client->digital_rain, caps_snapshot.color_filter);
      char *rain_frame = digital_rain_apply(render_client->digital_rain, ascii_frame, elapsed);
      if (rain_frame) {
        SAFE_FREE(ascii_frame);
        ascii_frame = rain_frame;
      }
    }
  } else if (render_client->digital_rain) {
    digital_rain_destroy(render_client->digital_rain);
    render_client->digital_rain = NULL;
  }

  return ascii_frame;
}

char *create_mixed_ascii_frame_for_client(const char *target_client_id, unsigned short width, unsigned short height,
                                          bool wants_stretch, size_t *out_size, bool *out_grid_changed,
                                          int *out_sources_count) {
  (void)wants_stretch; // Unused - we always handle aspect ratio ourselves

  // Register the stream counter once even when per-client render workers enter
  // this function concurrently.
  static _Atomic bool stream_atomics_registered = false;
  if (!atomic_exchange_explicit(&stream_atomics_registered, true, memory_order_acq_rel)) {
    NAMED_REGISTER_ATOMIC(&g_previous_active_video_count, "server_video_source_count_for_layout_detection", NULL);
  }

  uint64_t frame_gen_start_ns = time_get_ns();

  // Initialize output parameters
  if (out_grid_changed) {
    *out_grid_changed = false;
  }
  if (out_sources_count) {
    *out_sources_count = 0;
  }

  if (!out_size || width == 0 || height == 0) {
    SET_ERRNO(ERROR_INVALID_PARAM,
              "Invalid parameters for create_mixed_ascii_frame_for_client: width=%u, height=%u, out_size=%p", width,
              height, out_size);
    return NULL;
  }

  // Collect all active clients and their image sources
  image_source_t sources[MAX_CLIENTS];
  uint64_t collect_start_ns = time_get_ns();
  int source_count = collect_video_sources(sources, MAX_CLIENTS);
  uint64_t collect_end_ns = time_get_ns();

  // Count sources that actually have video data
  int sources_with_video = 0;
  for (int i = 0; i < source_count; i++) {
    if (sources[i].has_video && sources[i].image) {
      sources_with_video++;
    }
  }

  log_dev_every(333 * NS_PER_MS_INT, "FRAME_GEN_START: target_client=%s sources=%d collect=%.1fms", target_client_id,
                sources_with_video, (collect_end_ns - collect_start_ns) / NS_PER_MS);

  // Return the source count for debugging/tracking
  if (out_sources_count) {
    *out_sources_count = sources_with_video;
  }

  // GRID LAYOUT CHANGE DETECTION:
  // Check if the number of active video sources has changed
  // NOTE: We only UPDATE the count and SIGNAL the change via out parameter
  // Broadcasting CLEAR_CONSOLE must happen AFTER the new frames are written to buffers
  // to prevent race condition where CLEAR arrives before new frame is ready
  uint64_t previous_count = atomic_load_u64(&g_previous_active_video_count);
  if (sources_with_video != (int)previous_count) {
    // Use compare-and-swap to ensure only ONE thread detects the change
    if (atomic_cas_u64(&g_previous_active_video_count, &previous_count, (uint64_t)sources_with_video)) {
      log_dev_every(
          LOG_RATE_DEFAULT,
          "Grid layout changing: %d -> %d active video sources - caller will broadcast clear AFTER buffering frame",
          previous_count, sources_with_video);
      if (out_grid_changed) {
        *out_grid_changed = true; // Signal to caller
      }
    }
  }

  // No active video sources - don't generate placeholder frames
  image_t *composite = NULL;

  if (sources_with_video == 0) {
    *out_size = 0;
    // No active video sources for client - this isn't an error.
    // Return NULL to indicate no frame should be sent
    return NULL;
  }

  START_TIMER("composite_create");
  if (sources_with_video == 1) {
    // Single source handling - create composite and convert to ASCII
    // Note: create_single_source_composite returns a reference to sources[i].image
    // which could be modified by other threads. Make a copy to prevent concurrent
    // modification during ascii_convert_with_capabilities.
    image_t *single_source = create_single_source_composite(sources, source_count, target_client_id, width, height);
    if (single_source) {
      composite = image_new_copy(single_source);
      if (!composite) {
        SET_ERRNO(ERROR_MEMORY, "Failed to copy single source composite");
        *out_size = 0;
        return NULL;
      }
    }
  } else {
    // Multiple sources - create grid layout
    composite =
        create_multi_source_composite(sources, source_count, sources_with_video, target_client_id, width, height);
  }
  STOP_TIMER_AND_LOG(dev, 500000, "composite_create", "Composite creation (single/multi)");

  char *out = NULL;

  if (!composite) {
    SET_ERRNO(ERROR_INVALID_STATE, "Per-client %s: Failed to create composite image", target_client_id);
    *out_size = 0;
    return NULL;
  }

  // Convert composite to ASCII using client capabilities
  // Pass terminal dimensions so the frame can be padded to full width
  START_TIMER("ascii_convert");
  char *ascii_frame = convert_composite_to_ascii(composite, target_client_id, width, height);
  STOP_TIMER_AND_LOG(dev, 500000, "ascii_convert", "ASCII conversion (composite to ASCII)");

  if (ascii_frame) {
    // The frame should have been null-terminated by the padding functions.
    // Use strlen() which is optimized and reliable
    size_t ascii_len = strlen(ascii_frame);

    // Safety check: don't accept unreasonably large frames (10MB limit)
    if (ascii_len > 10 * 1024 * 1024) {
      log_error("Frame size exceeds 10MB safety limit (possible buffer overflow)");
      SET_ERRNO(ERROR_INVALID_PARAM, "Frame size exceeds 10MB");
      SAFE_FREE(ascii_frame);
      image_destroy(composite);
      *out_size = 0;
      return NULL;
    }

    // Ensure frame ends with a reset sequence to avoid garbage at terminal
    // This prevents color codes from leaking into uninitialized memory
    const char reset_seq[] = "\033[0m";
    const size_t reset_len = 4;

    if (ascii_len >= reset_len) {
      // Check if frame already ends with reset
      const char *frame_end = ascii_frame + ascii_len - reset_len;
      if (strncmp(frame_end, reset_seq, reset_len) == 0) {
        // Frame properly ends with reset, use full length
        *out_size = ascii_len;
      } else {
        // Frame doesn't end with reset - this is the REAL bug!
        // Truncate to the last occurrence of reset sequence
        const char *last_reset = NULL;
        for (const char *p = ascii_frame + ascii_len - reset_len; p >= ascii_frame; p--) {
          if (strncmp(p, reset_seq, reset_len) == 0) {
            last_reset = p;
            break;
          }
        }

        if (last_reset) {
          // Include the reset sequence and truncate after it
          *out_size = (size_t)(last_reset - ascii_frame) + reset_len;
          ascii_frame[*out_size] = '\0'; // Ensure null termination
          log_warn("Frame was missing reset at end (had garbage), truncated from %zu to %zu bytes", ascii_len,
                   *out_size);
        } else {
          // No reset found, use full length as fallback
          *out_size = ascii_len;
          log_dev_every(LOG_RATE_SLOW, "Frame has no reset sequences, sending full %zu bytes", ascii_len);
        }
      }
    } else {
      // Frame too short to have a reset, use as-is
      *out_size = ascii_len;
    }

    log_dev_every(LOG_RATE_SLOW, "create_mixed_ascii_frame_for_client: Final frame size=%zu bytes for client %s",
                  *out_size, target_client_id);

    // Debug: Log the last 50 bytes of the frame to see what's really there
    if (*out_size >= 50) {
      char hex_buf[300] = {0};
      size_t hex_len = 0;
      const uint8_t *last_bytes = (const uint8_t *)ascii_frame + (*out_size - 50);
      for (int i = 0; i < 50 && hex_len < sizeof(hex_buf) - 5; i++) {
        hex_len += snprintf(hex_buf + hex_len, sizeof(hex_buf) - hex_len, "%02X ", last_bytes[i]);
      }
      log_dev_every(4500 * US_PER_MS_INT, "FRAME_LAST_50_BYTES (hex): %s", hex_buf);

      // Also log as ASCII for readability
      char ascii_buf[100] = {0};
      for (int i = 0; i < 50 && i < (int)sizeof(ascii_buf) - 1; i++) {
        if (last_bytes[i] >= 32 && last_bytes[i] < 127) {
          ascii_buf[i] = (char)last_bytes[i];
        } else if (last_bytes[i] == '\n') {
          ascii_buf[i] = 'N';
        } else if (last_bytes[i] == '\0') {
          ascii_buf[i] = '0';
        } else {
          ascii_buf[i] = '.';
        }
      }
      log_dev_every(4500 * US_PER_MS_INT, "FRAME_LAST_50_ASCII: %s", ascii_buf);
    }

    out = ascii_frame;
  } else {
    SET_ERRNO(ERROR_TERMINAL, "Per-client %s: Failed to convert image to ASCII", target_client_id);
    *out_size = 0;
  }

  START_TIMER("image_cleanup");
  if (composite) {
    image_destroy(composite);
  }
  for (int i = 0; i < source_count; i++) {
    if (sources[i].image) {
      image_destroy(sources[i].image);
    }
  }
  STOP_TIMER_AND_LOG(dev, 500000, "image_cleanup", "Image cleanup (composite + sources)");

  uint64_t frame_gen_end_ns = time_get_ns();
  uint64_t frame_gen_duration_ns = frame_gen_end_ns - frame_gen_start_ns;
  if (frame_gen_duration_ns > 10 * NS_PER_MS_INT) { // Log if > 10ms
    char duration_str[32];
    time_pretty((uint64_t)((double)frame_gen_duration_ns), -1, duration_str, sizeof(duration_str));
    log_warn_every(LOG_RATE_DEFAULT, "SLOW_FRAME_GENERATION: Client %s full frame gen took %s", target_client_id,
                   duration_str);
  }

  return out;
}

int queue_audio_for_client(client_info_t *client, const void *audio_data, size_t data_size) {
  if (!client || !client->audio_queue || !audio_data || data_size == 0) {
    return -1;
  }

  return packet_queue_push_copy(client->audio_queue, PACKET_TYPE_AUDIO_BATCH, audio_data, data_size, 0) == ASCIICHAT_OK
             ? 0
             : -1;
}

bool any_clients_sending_video(void) {
  // LOCK OPTIMIZATION: Don't acquire rwlock - all fields we access are atomic
  // client_id, active, is_sending_video are all atomic variables

  // Iterate through all client slots
  for (int i = 0; i < MAX_CLIENTS; i++) {
    client_info_t *client = &g_client_manager.clients[i];

    // Skip uninitialized clients (atomic read)
    if (client->client_id[0] == '\0') {
      continue;
    }

    // Check if client is active and sending video (both atomic reads)
    bool is_active = atomic_load_bool(&client->active);
    bool is_sending = atomic_load_bool(&client->is_sending_video);

    if (is_active && is_sending) {
      return true;
    }
  }

  return false;
}

int main(int argc, char *argv[]) {
  long long count = 1;
  int dump_adjectives = 0;
  int dump_nouns = 0;

  static struct option long_options[] = {{"count", required_argument, 0, 'n'},
                                         {"dump-adjectives", no_argument, 0, 'a'},
                                         {"dump-nouns", no_argument, 0, 'o'},
                                         {"help", no_argument, 0, 'h'},
                                         {0, 0, 0, 0}};

  int opt;
  while ((opt = getopt_long(argc, argv, "n:aoh", long_options, NULL)) != -1) {
    switch (opt) {
    case 'n':
      count = strtoll(optarg, NULL, 10);
      break;
    case 'a':
      dump_adjectives = 1;
      break;
    case 'o':
      dump_nouns = 1;
      break;
    case 'h':
      printf("Usage: ascii-chat-strings [OPTIONS]\n");
      printf("Generate memorable session strings (adjective-noun-noun format)\n");
      printf("\nOptions:\n");
      printf("  -n, --count COUNT        Generate COUNT session strings (default: 1)\n");
      printf("  -a, --dump-adjectives    Dump adjectives list as JavaScript\n");
      printf("  -o, --dump-nouns         Dump nouns list as JavaScript\n");
      printf("  -h, --help               Show this help message\n");
      return 0;
    default:
      return ERROR_USAGE;
    }
  }

  // Handle dump modes
  if (dump_adjectives) {
    printf("export const adjectives = [\n");
    for (size_t i = 0; i < adjectives_count; i++) {
      printf("  \"%s\"%s\n", adjectives[i], (i < adjectives_count - 1) ? "," : "");
    }
    printf("];\n");
    printf("export const adjectives_count = %zu;\n", adjectives_count);
    return 0;
  }

  if (dump_nouns) {
    printf("export const nouns = [\n");
    for (size_t i = 0; i < nouns_count; i++) {
      printf("  \"%s\"%s\n", nouns[i], (i < nouns_count - 1) ? "," : "");
    }
    printf("];\n");
    printf("export const nouns_count = %zu;\n", nouns_count);
    return 0;
  }

  // Normal session string generation
  if (count <= 0 || (long long)count > ACDS_MAX_UNIQUE_SESSIONS) {
    return ERROR_USAGE;
  }

  // Generate session strings
  for (long long i = 0; i < count; i++) {
    uint32_t adj_idx = randombytes_uniform((uint32_t)adjectives_count);
    uint32_t noun1_idx = randombytes_uniform((uint32_t)nouns_count);
    uint32_t noun2_idx = randombytes_uniform((uint32_t)nouns_count);

    printf("%s-%s-%s\n", adjectives[adj_idx], nouns[noun1_idx], nouns[noun2_idx]);
  }

  return 0;
}

