int wasm_parse_args(const char *args_str, char **argv, int max_args, char **out_args_copy) {
  if (!args_str || !argv || !out_args_copy || max_args < 1) {
    return -1;
  }

  *out_args_copy = NULL;
  char *args_copy = strdup(args_str);
  if (!args_copy) {
    return -1;
  }

  *out_args_copy = args_copy;

  // Compact each parsed argument in place so quoted values can contain spaces.
  int argc = 0;
  char *read = args_copy;
  char *write = args_copy;
  while (*read != '\0') {
    while (*read == ' ' || *read == '\t' || *read == '\n' || *read == '\r')
      read++;
    if (*read == '\0')
      break;
    if (argc >= max_args - 1) {
      free(args_copy);
      *out_args_copy = NULL;
      return -1;
    }

    argv[argc++] = write;
    char quote = '\0';
    while (*read != '\0') {
      char current = *read++;
      if (current == '\\' && *read != '\0') {
        *write++ = *read++;
        continue;
      }
      if (quote != '\0') {
        if (current == quote)
          quote = '\0';
        else
          *write++ = current;
        continue;
      }
      if (current == '\'' || current == '"') {
        quote = current;
      } else if (current == ' ' || current == '\t' || current == '\n' || current == '\r') {
        break;
      } else {
        *write++ = current;
      }
    }
    if (quote != '\0') {
      free(args_copy);
      *out_args_copy = NULL;
      return -1;
    }
    *write++ = '\0';
  }
  argv[argc] = NULL;

  return argc;
}

