const char *get_known_hosts_path(void) {
  // Return cached path if already determined
  if (!g_known_hosts_path_cache) {
    char *config_dir = get_config_dir();
    if (!config_dir) {
      log_error("Failed to determine configuration directory for known_hosts");
      return NULL;
    }

    // Build path: config_dir + "known_hosts"
    size_t config_len = strlen(config_dir);
    size_t total_len = config_len + strlen("known_hosts") + 1;
    char *path = SAFE_MALLOC(total_len, char *);
    if (!path) {
      SAFE_FREE(config_dir);
      log_error("Failed to allocate memory for known_hosts path");
      return NULL;
    }

    safe_snprintf(path, total_len, "%sknown_hosts", config_dir);
    SAFE_FREE(config_dir);

    g_known_hosts_path_cache = path;
    log_debug("KNOWN_HOSTS: Using path %s", g_known_hosts_path_cache);
  }
  return g_known_hosts_path_cache;
}

asciichat_error_t check_known_host(const char *server_ip, uint16_t port, const uint8_t server_key[32]) {
  return check_known_host_with_key(server_ip, port, server_key, NULL, NULL);
}

asciichat_error_t check_known_host_with_key(const char *server_ip, uint16_t port, const uint8_t server_key[32],
                                            uint8_t expected_key[32], bool *has_expected_key) {
  if (has_expected_key)
    *has_expected_key = false;
  // Validate parameters first
  if (!server_ip || !server_key) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters: server_ip=%p, server_key=%p", server_ip, server_key);
  }

  // Format IP:port with proper bracket notation for IPv6
  char ip_with_port[BUFFER_SIZE_MEDIUM];
  if (format_ip_with_port(server_ip, port, ip_with_port, sizeof(ip_with_port)) != ASCIICHAT_OK) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid IP format: %s", server_ip);
  }

  // Add space after IP:port for prefix matching
  char expected_prefix[BUFFER_SIZE_MEDIUM];
  safe_snprintf(expected_prefix, sizeof(expected_prefix), "%s ", ip_with_port);

  // Use platform abstraction to find all known_hosts files across standard locations
  // Append semantics: search ALL files for matching entries (user + system)
  config_file_list_t known_hosts_files = {0};
  asciichat_error_t search_result = platform_find_config_file("known_hosts", &known_hosts_files);

  if (search_result != ASCIICHAT_OK) {
    // Platform search failed - non-fatal, treat as unknown host
    log_debug("KNOWN_HOSTS: Failed to search for known_hosts files: %d", search_result);
    return ASCIICHAT_OK;
  }

  // If no files found, this is an unknown host (first connection)
  if (known_hosts_files.count == 0) {
    return ASCIICHAT_OK;
  }

  // Search through ALL known_hosts files for matching entry (append semantics)
  bool found_entries = false;
  for (size_t file_idx = 0; file_idx < known_hosts_files.count; file_idx++) {
    const char *path = known_hosts_files.files[file_idx].path;

    int fd = platform_open("known_hosts_file", path, PLATFORM_O_RDONLY, FILE_PERM_PRIVATE);
    if (fd < 0) {
      log_debug("KNOWN_HOSTS: Cannot open file: %s", path);
      continue; // Skip files that can't be opened
    }

    FILE *f = platform_fdopen("known_hosts_stream", fd, "r");
    if (!f) {
      platform_close(fd);
      log_debug("KNOWN_HOSTS: Failed to fdopen: %s", path);
      continue;
    }

    char line[BUFFER_SIZE_XLARGE];

    // Search this file for matching IP:port entries
    while (fgets(line, sizeof(line), f)) {
      if (line[0] == '#')
        continue; // Comment

      // Use regex to parse and extract known_hosts line components
      char *parsed_ip_port = NULL, *parsed_key_type = NULL, *parsed_hex_key = NULL, *parsed_comment = NULL;
      if (!crypto_regex_match_known_hosts(line, &parsed_ip_port, &parsed_key_type, &parsed_hex_key, &parsed_comment)) {
        continue; // Line doesn't match known_hosts format
      }

      // Check if IP:port matches what we're looking for (with IPv6 normalization)
      if (!compare_ip_port_strings(parsed_ip_port, ip_with_port)) {
        SAFE_FREE(parsed_ip_port);
        SAFE_FREE(parsed_key_type);
        SAFE_FREE(parsed_hex_key);
        SAFE_FREE(parsed_comment);
        continue; // Different IP:port
      }

      found_entries = true;

      if (strcmp(parsed_key_type, NO_IDENTITY_MARKER) == 0) {
        // No-identity entry but server has identity - continue searching
        log_debug("SECURITY_DEBUG: Found no-identity entry, but server has identity key");
        SAFE_FREE(parsed_ip_port);
        SAFE_FREE(parsed_key_type);
        SAFE_FREE(parsed_hex_key);
        SAFE_FREE(parsed_comment);
        continue;
      }

      // Parse identity key from hex string
      if (!parsed_hex_key) {
        // No hex key found - invalid entry
        SAFE_FREE(parsed_ip_port);
        SAFE_FREE(parsed_key_type);
        SAFE_FREE(parsed_comment);
        continue;
      }

      public_key_t stored_key;
      if (parse_public_key(parsed_hex_key, &stored_key) != 0) {
