void debug_stats_set_main_thread_id(void) {
  g_debug_stats_main_thread = asciichat_thread_current_id();
}

uint64_t debug_stats_get_main_thread_id(void) {
  return g_debug_stats_main_thread;
}

asciichat_error_t debug_stats_init(void) {
  if (g_debug_stats_initialized)
    return ASCIICHAT_OK;
  if (mutex_init(&g_debug_stats_mutex, "debug_stats") != 0)
    return SET_ERRNO(ERROR_THREAD, "Cannot initialize diagnostics mutex");
  if (cond_init(&g_debug_stats_condition, "debug_stats") != 0) {
    mutex_destroy(&g_debug_stats_mutex);
    return SET_ERRNO(ERROR_THREAD, "Cannot initialize diagnostics condition");
  }
  g_debug_stats_initialized = true;
  atomic_store_bool_impl(&g_debug_stats_cleaning, false);
  return ASCIICHAT_OK;
}

void debug_stats_print(void) {
  log_info("Diagnostic statistics:");
  asciichat_error_stats_print();
}

void debug_stats_set_memory_report_interval(uint64_t interval) {
  if (!g_debug_stats_initialized)
    return;
  mutex_lock(&g_debug_stats_mutex);
  g_debug_stats_memory_interval = interval;
  g_debug_stats_memory_deadline = interval ? debug_report_deadline_after(time_get_ns(), interval) : 0;
  cond_signal(&g_debug_stats_condition);
  mutex_unlock(&g_debug_stats_mutex);
}

void debug_stats_trigger_print(void) {
  // Do not signal a condition variable or invoke diagnostic hooks in a signal
  // handler. The worker checks this flag at most 100ms after its next wakeup.
  atomic_store_bool_impl(&g_debug_stats_signal, true);
}

bool debug_stats_is_cleanup_in_progress(void) {
  return atomic_load_bool_impl(&g_debug_stats_cleaning);
}

void debug_stats_poll(void) {
  if (!g_debug_stats_initialized)
    return;
  uint64_t now = time_get_ns();
  bool all = atomic_exchange_bool_impl(&g_debug_stats_signal, false);
  mutex_lock(&g_debug_stats_mutex);
  bool memory = g_debug_stats_memory_deadline && now >= g_debug_stats_memory_deadline;
  if (memory)
    g_debug_stats_memory_deadline = debug_report_deadline_after(now, g_debug_stats_memory_interval);
  mutex_unlock(&g_debug_stats_mutex);
  if (all)
    debug_stats_print();
#if defined(DEBUG_MEMORY) && !defined(NDEBUG)
  if (memory)
    debug_memory_report();
#else
  (void)memory;
#endif
}

static void *debug_stats_worker(void *unused) {
  (void)unused;
  while (!atomic_load_bool_impl(&g_debug_stats_exiting)) {
    debug_stats_poll();
    mutex_lock(&g_debug_stats_mutex);
    uint64_t now = time_get_ns();
    uint64_t wait = 100 * NS_PER_MS_INT;
    uint64_t deadlines[] = {g_debug_stats_memory_deadline};
    for (size_t i = 0; i < sizeof(deadlines) / sizeof(deadlines[0]); ++i)
      if (deadlines[i]) {
        uint64_t remaining = deadlines[i] > now ? deadlines[i] - now : 1;
        if (remaining < wait)
          wait = remaining;
      }
    if (!atomic_load_bool_impl(&g_debug_stats_exiting))
      cond_timedwait(&g_debug_stats_condition, &g_debug_stats_mutex, wait);
    mutex_unlock(&g_debug_stats_mutex);
  }
  return NULL;
}

asciichat_error_t debug_stats_start_thread(void) {
  if (g_debug_stats_started)
    return ASCIICHAT_OK;
  asciichat_error_t result = debug_stats_init();
  if (result != ASCIICHAT_OK)
    return result;
  atomic_store_bool_impl(&g_debug_stats_exiting, false);
  atomic_store_bool_impl(&g_debug_stats_cleaning, false);
  options_t *opts = options_get();
  if (opts) {
    if (opts->debug_memory_report_interval > 0)
      debug_stats_set_memory_report_interval((uint64_t)(opts->debug_memory_report_interval * NS_PER_SEC_INT));
  }
#ifndef EMSCRIPTEN_BUILD
  if (asciichat_thread_create(&g_debug_stats_thread, "debug_stats", debug_stats_worker, NULL) != 0)
    return SET_ERRNO(ERROR_THREAD, "Cannot start diagnostics worker");
#endif
  g_debug_stats_started = true;
  return ASCIICHAT_OK;
}

void debug_stats_cleanup_thread(void) {
  if (!g_debug_stats_started)
    return;
  atomic_store_bool_impl(&g_debug_stats_cleaning, true);
  mutex_lock(&g_debug_stats_mutex);
  atomic_store_bool_impl(&g_debug_stats_exiting, true);
  cond_signal(&g_debug_stats_condition);
  mutex_unlock(&g_debug_stats_mutex);
#ifndef EMSCRIPTEN_BUILD
  // Join fully: diagnostic data must not be destroyed while a reader is alive.
  if (asciichat_thread_join(&g_debug_stats_thread, NULL) != 0)
    FATAL(ERROR_THREAD, "Cannot join diagnostics worker");
#endif
  g_debug_stats_started = false;
}

void debug_stats_destroy(void) {
  debug_stats_cleanup_thread();
  if (g_debug_stats_initialized) {
    cond_destroy(&g_debug_stats_condition);
    mutex_destroy(&g_debug_stats_mutex);
    g_debug_stats_initialized = false;
    atomic_store_bool_impl(&g_debug_stats_signal, false);
    g_debug_stats_memory_deadline = g_debug_stats_memory_interval = 0;
  }
}

