  if (!noun) {
    return -1;
  }

  // Just return the noun, no counter or transport info
  int written = snprintf(buffer, buffer_size, "%s", noun);
  if (written < 0 || (size_t)written >= buffer_size) {
    return -1; // Buffer too small
  }

  return 0;
}

int generate_client_name(char *buffer, size_t buffer_size, void *existing_clients_hash, int port, bool is_tcp) {
  if (!buffer || buffer_size < 1 || !nouns_count) {
    return -1;
  }

  // Select a random noun
  uint32_t noun_idx = randombytes_uniform((uint32_t)nouns_count);
  const char *noun = nouns[noun_idx];

  if (!noun) {
    return -1;
  }

  const char *transport_name = is_tcp ? "tcp" : "webrtc";

  // Try to generate a unique name by appending a counter
  // Format: "noun.0 (tcp:48036)", "noun.1 (webrtc:52441)", etc.
  for (int counter = 0; counter < 100; counter++) {
    int written = snprintf(buffer, buffer_size, "%s.%d (%s:%d)", noun, counter, transport_name, port);
    if (written < 0 || (size_t)written >= buffer_size) {
      return -1; // Buffer too small
    }

    // Check if this name already exists in the clients hash
    client_info_t *client, *tmp;
    int found = 0;

    HASH_ITER(hh, (client_info_t *)existing_clients_hash, client, tmp) {
      if (strcmp(client->display_name, buffer) == 0) {
        found = 1;
        break;
      }
    }

    if (!found) {
      // Name is unique, return it
      return 0;
    }
  }

  // Couldn't find a unique name after 100 tries
  // Fall back to numeric-only name as last resort
  snprintf(buffer, buffer_size, "client_%u (%s:%d)", randombytes_uniform(10000U), transport_name, port);
  return 0;
}

void session_entry_destroy(session_entry_t *entry) {
  if (!entry) {
    return;
  }

  // Free all participants
  for (size_t i = 0; i < PARTICIPANT_LIMIT; i++) {
    if (entry->participants[i]) {
      SAFE_FREE(entry->participants[i]);
    }
  }

  // Free the entry itself
  SAFE_FREE(entry);
}

