static void log_terminal_printf(int fd, const char *format, ...) {
  if (ui_controller_is_presenting() && (ui_controller_is_owner() || platform_isatty(fd)))
    return;
  char buffer[16384];
  va_list args;
  va_start(args, format);
  int length = vsnprintf(buffer, sizeof(buffer), format, args);
  va_end(args);
  if (length > 0) {
    size_t bytes = (size_t)length < sizeof(buffer) ? (size_t)length : sizeof(buffer) - 1;
    ui_controller_write(fd, buffer, bytes);
  }
}

const char *get_level_string_padded(log_level_t level) {
  const char *result;
  switch (level) {
  case LOG_INFO:
    result = "INFO "; // 5 chars: INFO + 1 space
    break;
  case LOG_WARN:
    result = "WARN "; // 5 chars: WARN + 1 space
    break;
  case LOG_DEV:
    result = "DEV  "; // 5 chars: DEV + 2 spaces
    break;
  case LOG_DEBUG:
    result = "DEBUG"; // 5 chars: DEBUG (no padding needed)
    break;
  case LOG_ERROR:
    result = "ERROR"; // 5 chars: ERROR (no padding needed)
    break;
  case LOG_FATAL:
    result = "FATAL"; // 5 chars: FATAL (no padding needed)
    break;
  default:
    result = "?????"; // Invalid level - return 5 question marks
  }
  // Verify length
  if (strlen(result) != 5) {
    log_terminal_printf(STDERR_FILENO, "ERROR: get_level_string_padded() returned non-5-char string: '%s' (len=%zu)\n",
                         result, strlen(result));
  }
  return result;
}

size_t get_current_time_formatted(char *time_buf) {
  /* Get wall-clock time in nanoseconds */
  uint64_t ts_ns = time_get_realtime_ns();
  // Extract seconds and nanoseconds from total nanoseconds
  time_t seconds = (time_t)(ts_ns / NS_PER_SEC_INT);
  long nanoseconds = (long)(ts_ns % NS_PER_SEC_INT);
  struct tm tm_info;
  platform_localtime(&seconds, &tm_info);
  // Format the time part first
  // strftime returns 0 on error, not negative (and len is size_t/unsigned)
  size_t len = strftime(time_buf, 32, "%H:%M:%S", &tm_info);
  if (len == 0 || len >= 32) {
    LOGGING_INTERNAL_ERROR(ERROR_INVALID_STATE, "Failed to format time");
    return 0;
  }

  // Add microseconds manually (convert nanoseconds to microseconds for display)
  long microseconds = nanoseconds / 1000;
  if (microseconds < 0)
    microseconds = 0;
  if (microseconds > 999999)
    microseconds = 999999;

  int result = safe_snprintf(time_buf + len, 32 - len, ".%06ld", microseconds);
  if (result < 0 || result >= (int)(32 - len)) {
    LOGGING_INTERNAL_ERROR(ERROR_INVALID_STATE, "Failed to format microseconds");
    return 0;
  }

  return len + (size_t)result;
}

char *format_message(const char *format, va_list args) {
  if (!format) {
    return NULL;
  }

  // First, determine the size needed
  va_list args_copy;
  va_copy(args_copy, args);
  int size = safe_vsnprintf(NULL, 0, format, args_copy);
  va_end(args_copy);

  if (size < 0) {
    LOGGING_INTERNAL_ERROR(ERROR_INVALID_STATE, "Failed to format context message");
    return NULL;
  }

  // Allocate and format the message
  char *message = SAFE_MALLOC(size + 1, char *);
  int result = safe_vsnprintf(message, (size_t)size + 1, format, args);
  if (result < 0) {
    SAFE_FREE(message);
    LOGGING_INTERNAL_ERROR(ERROR_INVALID_STATE, "Failed to format context message");
    return NULL;
  }

  return message;
}

static int truncate_at_whole_line(char *buffer, int current_len, size_t max_len) {
  if (current_len < 0 || (size_t)current_len <= max_len) {
    return current_len; // No truncation needed
  }

  // Search backwards from max_len position for last newline
  int truncate_pos = (int)max_len - 1;
  while (truncate_pos > 0 && buffer[truncate_pos] != '\n') {
    truncate_pos--;
  }

  // If we found a newline, truncate after it
  if (truncate_pos > 0 && buffer[truncate_pos] == '\n') {
    truncate_pos++; // Include the newline
    // NOLINTNEXTLINE(clang-analyzer-security.ArrayBound) - truncate_pos validated by max_len
    buffer[truncate_pos] = '\0';
    return truncate_pos;
  }

  // No newline found, truncate at max_len to be safe
  truncate_pos = (int)max_len - 1;
  buffer[truncate_pos] = '\0';
  return truncate_pos;
}

static void validate_log_message_utf8(const char *message, const char *source) {
  if (!message || !source) {
    return;
  }

  if (!utf8_is_valid(message)) {
    // Use fprintf instead of log_warn to avoid infinite recursion
    // (this function is called from log_msg, which would create a loop)
    log_terminal_printf(STDERR_FILENO, "[WARN] Invalid UTF-8 detected in %s\n", source);
    log_terminal_printf(STDERR_FILENO, "[DEBUG] Invalid UTF-8 data: %s\n", message);
  }
}

static log_level_t parse_log_level_from_env(void) {
  const char *env_level = SAFE_GETENV("LOG_LEVEL");
  if (!env_level) {
    return DEFAULT_LOG_LEVEL; // Default level based on build type
  }

  // Case-insensitive comparison
  if (platform_strcasecmp(env_level, "DEV") == 0 || strcmp(env_level, "0") == 0) {
    return LOG_DEV;
  }
  if (platform_strcasecmp(env_level, "DEBUG") == 0 || strcmp(env_level, "1") == 0) {
    return LOG_DEBUG;
  }
  if (platform_strcasecmp(env_level, "INFO") == 0 || strcmp(env_level, "2") == 0) {
    return LOG_INFO;
  }
  if (platform_strcasecmp(env_level, "WARN") == 0 || strcmp(env_level, "3") == 0) {
    return LOG_WARN;
  }
  if (platform_strcasecmp(env_level, "ERROR") == 0 || strcmp(env_level, "4") == 0) {
    return LOG_ERROR;
  }
  if (platform_strcasecmp(env_level, "FATAL") == 0 || strcmp(env_level, "5") == 0) {
    return LOG_FATAL;
  }

  // Invalid value - return default
  log_warn("Invalid LOG_LEVEL: %s", env_level);
  return DEFAULT_LOG_LEVEL;
}

static void rotate_log_locked(void) {
  int file = atomic_load_int(&g_log.file);
  size_t current_size = atomic_load_u64(&g_log.current_size);

  if (file < 0 || file == STDERR_FILENO || strlen(g_log.filename) == 0) {
    return;
  }

  if (current_size < MAX_LOG_SIZE) {
    return;
  }

  platform_close(file);
  atomic_store_int(&g_log.file, -1);

  /* Open file for reading to get the tail */
  int read_file = platform_open("log_file_read", g_log.filename, O_RDONLY, 0);
  if (read_file < 0) {
    log_error("Failed to open file descriptor for log rotation: fd=%d, path=%s", read_file, g_log.filename);
    /* Fall back to regular truncation */
    int fd = platform_open("log_file_write", g_log.filename, O_CREAT | O_RDWR | O_TRUNC, FILE_PERM_PRIVATE);
    atomic_store_int(&g_log.file, fd);
    atomic_store_u64(&g_log.current_size, 0);
    return;
  }

  /* Seek to position where we want to start keeping data (keep last 2MB) */
  size_t keep_size = MAX_LOG_SIZE * 2 / 3; /* Keep last 2MB of 3MB file */
  if (current_size < keep_size) {
    platform_close(read_file);
    /* Fall back to truncation since we don't have enough data to rotate */
    int fd = platform_open("log_file_write", g_log.filename, O_CREAT | O_RDWR | O_TRUNC, FILE_PERM_PRIVATE);
    atomic_store_int(&g_log.file, fd);
    atomic_store_u64(&g_log.current_size, 0);
    return;
  }
  if (lseek(read_file, (off_t)(current_size - keep_size), SEEK_SET) == (off_t)-1) {
    platform_close(read_file);
    /* Fall back to truncation */
    int fd = platform_open("log_file_write", g_log.filename, O_CREAT | O_RDWR | O_TRUNC, FILE_PERM_PRIVATE);
    atomic_store_int(&g_log.file, fd);
    atomic_store_u64(&g_log.current_size, 0);
    return;
  }

  /* Skip to next line boundary to avoid partial lines */
  char c;
  while (platform_read(read_file, &c, 1) > 0 && c != '\n') {
    /* Skip characters until newline */
  }

  /* Read the tail into a temporary file */
  char temp_filename[PLATFORM_MAX_PATH_LENGTH];
  int result = safe_snprintf(temp_filename, sizeof(temp_filename), "%s.tmp", g_log.filename);
  if (result <= 0 || result >= (int)sizeof(temp_filename)) {
    LOGGING_INTERNAL_ERROR(ERROR_INVALID_STATE, "Failed to format temp filename");
    platform_close(read_file);
    int fd = platform_open("log_file_append", g_log.filename, O_CREAT | O_RDWR | O_APPEND, FILE_PERM_PRIVATE);
    atomic_store_int(&g_log.file, fd);
    return;
  }

  int temp_file = platform_open("log_file_temp", temp_filename, O_CREAT | O_WRONLY | O_TRUNC, FILE_PERM_PRIVATE);
  if (temp_file < 0) {
    log_warn("Failed to open temporary file descriptor for log rotation: fd=%d, path=%s", temp_file, temp_filename);
    platform_close(read_file);
    /* Fall back to truncation */
    int fd = platform_open("log_file_write", g_log.filename, O_CREAT | O_RDWR | O_TRUNC, FILE_PERM_PRIVATE);
    atomic_store_int(&g_log.file, fd);
    atomic_store_u64(&g_log.current_size, 0);
    return;
  }

  /* Copy tail to temp file */
  char buffer[8192];
  ssize_t bytes_read;
  size_t new_size = 0;
  while ((bytes_read = platform_read(read_file, buffer, sizeof(buffer))) > 0) {
    ssize_t written = platform_write(temp_file, buffer, (size_t)bytes_read);
    if (written != bytes_read) {
      platform_close(read_file);
      platform_close(temp_file);
      unlink(temp_filename);
      /* Fall back to truncation */
      int fd = platform_open("log_file_write", g_log.filename, O_CREAT | O_RDWR | O_TRUNC, FILE_PERM_PRIVATE);
      atomic_store_int(&g_log.file, fd);
      atomic_store_u64(&g_log.current_size, 0);
      return;
    }
    new_size += (size_t)bytes_read;
  }

  platform_close(read_file);
  platform_close(temp_file);

  /* Replace original with temp file */
  if (rename(temp_filename, g_log.filename) != 0) {
    unlink(temp_filename); /* Clean up temp file */
    /* Fall back to truncation */
    int fd = platform_open("log_file_write", g_log.filename, O_CREAT | O_RDWR | O_TRUNC, FILE_PERM_PRIVATE);
    atomic_store_int(&g_log.file, fd);
    atomic_store_u64(&g_log.current_size, 0);
    return;
  }

  /* Reopen for appending */
  int new_fd = platform_open("log_file_append", g_log.filename, O_CREAT | O_RDWR | O_APPEND, FILE_PERM_PRIVATE);
  if (new_fd < 0) {
    LOGGING_INTERNAL_ERROR(ERROR_INVALID_STATE, "Failed to reopen rotated log file: %s", g_log.filename);
    atomic_store_int(&g_log.file, STDERR_FILENO);
    g_log.filename[0] = '\0';
    atomic_store_u64(&g_log.current_size, 0);
    return;
  }
  atomic_store_int(&g_log.file, new_fd);
  atomic_store_u64(&g_log.current_size, new_size);

  char time_buf[LOG_TIMESTAMP_BUFFER_SIZE];
  get_current_time_formatted(time_buf);

  char log_msg[256];
  int log_msg_len =
      safe_snprintf(log_msg, sizeof(log_msg), "[%s] [INFO] Log tail-rotated (kept %zu bytes)\n", time_buf, new_size);
  if (log_msg_len > 0 && log_msg_len < (int)sizeof(log_msg)) {
    (void)platform_write(new_fd, log_msg, (size_t)log_msg_len);
  }
}

static void maybe_rotate_log(void) {
  /* Rotation mutex not initialized - skip rotation */
  if (!lifecycle_is_initialized(&g_log.rotation_mutex_lifecycle)) {
    return;
  }

  /* Check mmap path first */
  if (log_mmap_is_active()) {
    size_t used = 0, capacity = 0;
    if (log_mmap_get_usage(&used, &capacity) && capacity > 0) {
      /* Rotate when 90% full to leave room for writes */
      if (used > capacity * 9 / 10) {
        mutex_lock(&g_log.rotation_mutex);
        log_mmap_rotate();
        mutex_unlock(&g_log.rotation_mutex);
      }
    }
    return;
  }

  /* File path: quick atomic check - avoid mutex if not needed */
  size_t current_size = atomic_load_u64(&g_log.current_size);
  if (current_size < MAX_LOG_SIZE) {
    return;
  }

  /* Size exceeded - acquire mutex and rotate */
  mutex_lock(&g_log.rotation_mutex);
  rotate_log_locked();
  mutex_unlock(&g_log.rotation_mutex);
}

session_log_buffer_t *log_get_history_buffer(void) {
  return g_history;
}

void log_init(const char *filename, log_level_t level, bool force_stderr, bool use_mmap) {

  if (!g_history)
    g_history = session_log_buffer_create();

  // Initialize rotation mutex (only operation that uses a mutex)
  g_log.rotation_mutex_lifecycle.sync_type = LIFECYCLE_SYNC_MUTEX;
  g_log.rotation_mutex_lifecycle.sync.mutex = &g_log.rotation_mutex;
  lifecycle_init(&g_log.rotation_mutex_lifecycle, "log_rotation");

  // Set basic config using atomic stores
  atomic_store_u64(&g_log.force_stderr, force_stderr);
  bool preserve_terminal_output = atomic_load_u64(&g_log.terminal_output_enabled);

  // Force logs to stderr if stdout is piped/redirected
  // This prevents logs from contaminating piped/redirected output in snapshot/batch modes
  // Per terminal.h: "force stderr when piped to prevent data corruption"
  if (terminal_is_piped_output()) {
    atomic_store_bool(&g_log.force_stderr, true);
  }

  // Close any existing file (atomic load/store)
  int old_file = atomic_load_int(&g_log.file);
  if (lifecycle_is_initialized(&g_log.lifecycle) && old_file >= 0 && old_file != STDERR_FILENO) {
    platform_close(old_file);
    atomic_store_int(&g_log.file, -1);
  }

  // Check LOG_LEVEL environment variable
  const char *env_level_str = SAFE_GETENV("LOG_LEVEL");
  if (env_level_str) {
    atomic_store_u64(&g_log.level, (int)parse_log_level_from_env());
  } else {
    atomic_store_u64(&g_log.level, (int)level);
  }

  atomic_store_bool(&g_log.level_manually_set, false);
  atomic_store_u64(&g_log.current_size, 0);

  if (filename) {
    SAFE_STRNCPY(g_log.filename, filename, sizeof(g_log.filename) - 1);

    if (use_mmap) {
      // Lock-free mmap path - writes go to mmap'd file
      asciichat_error_t mmap_result = log_mmap_init_simple(filename, 0);
      if (mmap_result == ASCIICHAT_OK) {
        atomic_store_int(&g_log.file, -1); // No regular fd - using mmap for file output
      } else {
        // Mmap failed - use stderr only (atomic writes, lock-free)
        if (preserve_terminal_output) {
          log_terminal_printf(STDERR_FILENO, "Mmap logging failed for %s, using stderr only (lock-free)\n", filename);
        }
        atomic_store_int(&g_log.file, STDERR_FILENO);
        g_log.filename[0] = '\0';
      }
    } else {
      // Lock-free file I/O path - uses atomic write() syscalls
      int fd = platform_open("log_file", filename, O_CREAT | O_RDWR | O_TRUNC, FILE_PERM_PRIVATE);
      atomic_store_int(&g_log.file, (fd >= 0) ? fd : STDERR_FILENO);
      if (fd < 0) {
        if (preserve_terminal_output) {
          log_terminal_printf(STDERR_FILENO, "Failed to open log file: %s\n", filename);
        }
        g_log.filename[0] = '\0';
      }
    }
  } else {
    atomic_store_int(&g_log.file, STDERR_FILENO);
    g_log.filename[0] = '\0';
  }

  /* Initialize default log format (NULL means use mode-specific default) */
  log_set_format(NULL, false);

  /* Mark logging system as initialized (state machine transition) */
  if (!lifecycle_is_initialized(&g_log.lifecycle)) {
    lifecycle_init(&g_log.lifecycle, "logging");
  }

  atomic_store_u64(&g_log.terminal_output_enabled, preserve_terminal_output);

  // Reset terminal detection if needed
  if (g_log.terminal_caps_initialized && !g_log.terminal_caps.detection_reliable) {
    g_log.terminal_caps_initialized = false;
  }

  // Detect terminal capabilities
  log_redetect_terminal_capabilities();

  // NOTE: Color initialization happens separately via log_set_color_scheme()
  // after options are parsed. Logging works without colors until then.
  // NOTE: Grep filter initialization happens in main.c after options_init() completes.
}

void log_destroy(void) {
  // Destroy mmap logging first (if active)
  if (log_mmap_is_active()) {
    log_mmap_destroy();
  }

  // Cleanup grep filter
  grep_destroy();

  /* Mark logging system as shutdown FIRST (state machine transition)
   * This signals worker threads to stop logging immediately before we free memory.
   * This prevents TOCTOU race where a worker thread could see non-NULL format pointer
   * after we've freed it but before lifecycle_shutdown() is called. */
  lifecycle_shutdown(&g_log.lifecycle);

  // Cleanup custom format structures: All worker threads have been signaled to stop by this point.
  // Safe to free templates now without use-after-free concerns.
  if (g_log.format) {
    log_template_free(g_log.format);
    g_log.format = NULL;
  }
  if (g_log.format_console_only) {
    log_template_free(g_log.format_console_only);
    g_log.format_console_only = NULL;
  }
  atomic_store_bool(&g_log.has_custom_format, false);

  // Lock-free cleanup using atomic operations
  int old_file = atomic_load_int(&g_log.file);
  if (old_file >= 0 && old_file != STDERR_FILENO) {
    platform_close(old_file);
  }
  atomic_store_int(&g_log.file, -1);

  // Destroy rotation mutex
  lifecycle_shutdown(&g_log.rotation_mutex_lifecycle);
}

void log_system_init(void) {

  // Detect terminal capabilities if not already done
  log_redetect_terminal_capabilities();

  // Initialize color scheme based on terminal capabilities
  log_init_colors();
}

void log_system_destroy(void) {
  // Unregister session log buffer if registered
  log_clear_session_log_buffer();
  log_search_destroy();
  session_log_buffer_destroy(g_history);
  g_history = NULL;
}

void log_set_level(log_level_t level) {
  atomic_store_u64(&g_log.level, (int)level);
  atomic_store_bool(&g_log.level_manually_set, true);
}

log_level_t log_get_level(void) {
  return (log_level_t)atomic_load_u64(&g_log.level);
}

void log_set_terminal_output(bool enabled) {
  // Respect --quiet flag: if quiet is set, never enable terminal output
  // But allow disabling even if options are unavailable (for shutdown cleanup)

  // Only check quiet flag when ENABLING output to avoid deadlock with
  // concurrent logging from other threads (options_get() can deadlock when
  // called while other threads are actively logging due to RCU synchronization)
  if (enabled) {
    const options_t *opts = options_get();
    if (opts && opts->quiet) {
      return; // Silently ignore attempts to enable terminal output when --quiet is set
    }
  }

  atomic_store_u64(&g_log.terminal_output_enabled, enabled);
}

bool log_get_terminal_output(void) {
  return atomic_load_u64(&g_log.terminal_output_enabled);
}

void log_set_force_stderr(bool enabled) {
  atomic_store_u64(&g_log.force_stderr, enabled);
}

bool log_get_force_stderr(void) {
  return atomic_load_u64(&g_log.force_stderr);
}

void log_set_json_output(int fd) {
  atomic_store_int(&g_log.json_file, fd);
}

void log_disable_file_output(void) {
  /* Close the current file if it's not stderr */
  int old_file = atomic_load_int(&g_log.file);
  if (old_file >= 0 && old_file != STDERR_FILENO) {
    platform_close(old_file);
  }
  /* Redirect file output to stderr */
  atomic_store_int(&g_log.file, STDERR_FILENO);
  g_log.filename[0] = '\0';
}

asciichat_error_t log_set_format(const char *format_str, bool console_only) {
  /* Free old format if it exists */
  if (g_log.format) {
    log_template_free(g_log.format);
    g_log.format = NULL;
  }
  if (g_log.format_console_only) {
    log_template_free(g_log.format_console_only);
    g_log.format_console_only = NULL;
  }

  /* Use default format if NULL or empty string */
  const char *format_to_use = (format_str && format_str[0] != '\0') ? format_str : OPT_LOG_TEMPLATE_DEFAULT;
  bool is_custom = (format_str && format_str[0] != '\0');

  /* Parse the format string (always parse, never skip) */
  log_template_t *parsed_format = log_template_parse(format_to_use, false);

  if (!parsed_format) {
    log_error("Failed to parse log format: %s", format_to_use);
    return SET_ERRNO(ERROR_INVALID_STATE, "Invalid log format string");
  }

  /* If console_only is true, we also need the default format for file output */
  if (console_only && is_custom) {
    log_template_t *default_format = log_template_parse(OPT_LOG_TEMPLATE_DEFAULT, false);

    if (!default_format) {
      log_template_free(parsed_format);
      log_error("Failed to parse default log format");
      return SET_ERRNO(ERROR_INVALID_STATE, "Failed to parse default format");
    }
    g_log.format = default_format;
    g_log.format_console_only = parsed_format;
  } else {
    g_log.format = parsed_format;
    g_log.format_console_only = NULL;
  }

  atomic_store_u64(&g_log.has_custom_format, is_custom);
  return ASCIICHAT_OK;
}

bool log_lock_terminal(void) {
  bool expected = atomic_load_bool(&g_log.terminal_locked);
  while (!atomic_cas_bool(&g_log.terminal_locked, &expected, true)) {
    // Retry if CAS failed
  }
  atomic_store_u64(&g_log.terminal_owner_thread, (uint64_t)asciichat_thread_self());
  return expected;
}

void log_unlock_terminal(bool previous_state) {
  atomic_store_u64(&g_log.terminal_locked, previous_state);
  if (!previous_state) {
    atomic_store_u64(&g_log.terminal_owner_thread, 0);
  }
}

void log_set_flush_delay(unsigned int delay_ms) {
  atomic_store_u64(&g_log.flush_delay_ms, delay_ms);
}

void log_truncate_if_large(void) {
  // Log rotation is inherently racy without locks - best-effort only
  // For reliable rotation, use mmap mode or external logrotate
  int file = atomic_load_int(&g_log.file);
  if (file >= 0 && file != STDERR_FILENO && strlen(g_log.filename) > 0) {
    struct stat st;
    if (fstat(file, &st) == 0 && st.st_size > MAX_LOG_SIZE) {
      atomic_store_u64(&g_log.current_size, (size_t)st.st_size);
    }
  }
}

static void write_to_log_file_atomic(const char *buffer, int length, const char *stripped_buffer) {
  if (length <= 0 || buffer == NULL) {
    return;
  }

  if (length > MAX_LOG_SIZE) {
    return;
  }

  int file = atomic_load_int(&g_log.file);
  if (file < 0 || file == STDERR_FILENO) {
    return;
  }

  // Use pre-stripped buffer if available (already stripped by caller), otherwise use original
  const char *write_buf = stripped_buffer ? stripped_buffer : buffer;
  size_t write_len = stripped_buffer ? strlen(stripped_buffer) : (size_t)length;

  // Single atomic write() call - no locking needed
  ssize_t written = platform_write(file, write_buf, write_len);
  if (written > 0) {
    atomic_fetch_add_u64(&g_log.current_size, (uint64_t)written);
    maybe_rotate_log();
  }
}

static int format_log_header(char *buffer, size_t buffer_size, log_level_t level, const char *timestamp,
                             const char *file, int line, const char *func, bool use_colors, uint64_t time_nanoseconds) {
  const log_template_t *format = g_log.format;
  if (!format) {
    LOGGING_INTERNAL_ERROR(ERROR_INVALID_STATE, "Log format not initialized");
    return -1;
  }

  /* Use log_template_apply() to generate the complete formatted output
   * Safety: reload format immediately before use. Format is never freed to avoid TOCTOU races. */
  const log_template_t *format_check = g_log.format;
  if (!format_check) {
    /* Format not available - return minimal output */
    return -1;
  }

  int written = log_template_apply(format_check, buffer, buffer_size, level, timestamp, file, line, func,
                                   asciichat_thread_current_id(), "", use_colors, time_nanoseconds);
  if (written < 0 || written >= (int)buffer_size) {
    LOGGING_INTERNAL_ERROR(ERROR_INVALID_STATE, "Failed to format log header");
    return -1;
  }

  return written;
}

static void write_to_terminal_atomic(log_level_t level, const char *timestamp, const char *file, int line,
                                     const char *func, const char *fmt, va_list args, uint64_t time_nanoseconds,
                                     bool capture_history) {
  // Prevent logging during shutdown - if logging lifecycle is being destroyed,
  // bail out to avoid use-after-free of the log template
  if (!lifecycle_is_initialized(&g_log.lifecycle)) {
    return; /* Logging is being shut down, skip */
  }

  // Choose output file descriptor using unified routing logic
  int fd = terminal_choose_log_fd(level);
  FILE *output_stream = (fd == STDERR_FILENO) ? stderr : stdout;
  bool use_colors = terminal_should_color_output(fd);

  // Format message first (needed for status screen capture even if terminal output disabled)
  char msg_buffer[LOG_MSG_BUFFER_SIZE];
  va_list args_copy;
  va_copy(args_copy, args);
  int msg_len = safe_vsnprintf(msg_buffer, sizeof(msg_buffer), fmt, args_copy);
  va_end(args_copy);

  // Use message buffer directly as clean message
  // Stack allocation avoids heap corruption during shutdown signal handling
  const char *clean_msg = msg_buffer;

  // Use format system to generate the complete log line
  char colored_log_line[LOG_MSG_BUFFER_SIZE + 512];
  char plain_log_line[LOG_MSG_BUFFER_SIZE + 512];

  /* Apply format without colors first (plain version for grep matching)
   * Load format pointer once to prevent TOCTOU race condition where another
   * thread frees the format between our check and use. */
  const log_template_t *format = g_log.format;
  int plain_len = 0;
  if (format && lifecycle_is_initialized(&g_log.lifecycle)) { /* Double-check lifecycle is still active */
    plain_len = log_template_apply(format, plain_log_line, sizeof(plain_log_line), level, timestamp, file, line, func,
                                   asciichat_thread_current_id(), clean_msg, false, time_nanoseconds);
  }

  /* For colored output, apply format with colors enabled */
  int colored_len = 0;
  if (use_colors && plain_len > 0) {
    const log_template_t *format_check = g_log.format;
    if (format_check && lifecycle_is_initialized(&g_log.lifecycle)) { /* Re-verify lifecycle before use */
      colored_len = log_template_apply(format_check, colored_log_line, sizeof(colored_log_line), level, timestamp, file,
                                       line, func, asciichat_thread_current_id(), clean_msg, true, time_nanoseconds);
    }
    /* If applying with colors failed, fall back to plain text */
    if (colored_len <= 0) {
      // Applying with colors failed - use plain text (no colors)
      colored_len = plain_len;
      if (plain_len > 0 && plain_len < (int)sizeof(colored_log_line)) {
        memcpy(colored_log_line, plain_log_line, (size_t)plain_len + 1);
      }
    }
  } else {
    /* No colors - use plain text */
    colored_len = plain_len;
    if (plain_len > 0 && plain_len < (int)sizeof(colored_log_line)) {
      memcpy(colored_log_line, plain_log_line, (size_t)plain_len + 1);
    }
  }

  if (capture_history)
    session_log_buffer_append(g_history, colored_len > 0 ? colored_log_line : clean_msg);

  // Feed log to registered session log buffer (use colored version if available, otherwise plain)
  atomic_fetch_add_u64_impl(&g_session_log_readers, 1);
  session_log_buffer_t *buf = (session_log_buffer_t *)atomic_ptr_load(&g_log.session_log_buffer);
  if (buf && buf != g_history) {
    if (colored_len > 0 && colored_len < (int)sizeof(colored_log_line)) {
      session_log_buffer_append(buf, colored_log_line);
    } else if (plain_len > 0 && plain_len < (int)sizeof(plain_log_line)) {
      session_log_buffer_append(buf, plain_log_line);
    }
  }

  atomic_fetch_sub_u64_impl(&g_session_log_readers, 1);

  // Check if terminal output is enabled (atomic load)
  bool is_enabled = atomic_load_u64(&g_log.terminal_output_enabled);
  if (!is_enabled) {
    // Terminal output disabled - return (status screen already captured)
    return;
  }

  // Check if terminal is locked by another thread
  if (atomic_load_u64(&g_log.terminal_locked)) {
    uint64_t owner = atomic_load_u64(&g_log.terminal_owner_thread);
    if (owner != (uint64_t)asciichat_thread_self()) {
      // Terminal locked by another thread - return
      return;
    }
  }

  // Handle message formatting errors for terminal output
  if (msg_len <= 0 || msg_len >= (int)sizeof(msg_buffer)) {
    // Message formatting failed - skip filtering and try direct output
    /* A failed format is omitted; args may already have been consumed. */
    log_terminal_printf(output_stream == stdout ? STDOUT_FILENO : STDERR_FILENO, "\n");
    (void)fflush(output_stream);
    return;
  }

  // Handle log formatting errors
  if (colored_len <= 0 || colored_len >= (int)sizeof(colored_log_line) || plain_len <= 0 ||
      plain_len >= (int)sizeof(plain_log_line)) {
    // Formatting failed - try to output something
    log_terminal_printf(output_stream == stdout ? STDOUT_FILENO : STDERR_FILENO, "%s\n", clean_msg);
    (void)fflush(output_stream);
    return;
  }

  // Apply grep filter (terminal output only - file logs are unfiltered)
  // Match against PLAIN text (no ANSI codes) so offsets are correct
  size_t match_start = 0, match_len = 0;
  if (!grep_should_output(plain_log_line, &match_start, &match_len)) {
    return; // No match - suppress terminal output
  }

  // Output with colors
  if (use_colors) {
    const char **colors = log_get_color_array();

    // When grep matches, highlight in the colored line
    if (match_len > 0 && colors != NULL) {
      // Apply highlighting to the full line, respecting existing ANSI codes
      const char *highlighted_line = grep_highlight_colored(colored_log_line, plain_log_line, match_start, match_len);
      log_terminal_printf(output_stream == stdout ? STDOUT_FILENO : STDERR_FILENO, "%s\n", highlighted_line);
    } else {
      // No grep match - output colored line as-is
      log_terminal_printf(output_stream == stdout ? STDOUT_FILENO : STDERR_FILENO, "%s\n", colored_log_line);
    }
  } else {
    // No colors - output plain line
    log_terminal_printf(output_stream == stdout ? STDOUT_FILENO : STDERR_FILENO, "%s\n", plain_log_line);
  }

  (void)fflush(output_stream);
}

static void output_notice(log_level_t level, const char *file, int line, const char *func) {
  if (g_notice_record_only)
    return;
  const char *text = g_notice_text;
  ui_notice_severity_t severity = g_notice_severity;
  g_notice_text = NULL;
  atomic_fetch_add_u64_impl(&g_session_log_readers, 1);
  session_log_buffer_t *buffer = log_get_session_log_buffer();
  session_log_buffer_append(g_history, text);
  if (buffer && buffer != g_history)
    session_log_buffer_append(buffer, text);
  atomic_fetch_sub_u64_impl(&g_session_log_readers, 1);
  // Match the same uncolored template as ordinary terminal logs, including metadata.
  // Keep the complete body for notices that span multiple file-log records.
  size_t capacity = strlen(text) + LOG_MSG_BUFFER_SIZE + 512;
  char *plain_log_line = SAFE_MALLOC(capacity, char *);
  char timestamp[LOG_TIMESTAMP_BUFFER_SIZE];
  uint64_t time_ns = time_get_realtime_ns();
  get_current_time_formatted(timestamp);
  const log_template_t *format = g_log.format;
  int plain_len = format && plain_log_line
                      ? log_template_apply(format, plain_log_line, capacity, level, timestamp, file, line, func,
                                           asciichat_thread_current_id(), text, false, time_ns)
                      : -1;
  size_t start = 0, length = 0;
  if (!GET_OPTION(quiet) &&
      (log_get_terminal_output() || ui_controller_is_presenting() || severity == UI_NOTICE_FATAL) &&
      plain_len > 0 && (size_t)plain_len < capacity && grep_should_output(plain_log_line, &start, &length))
#ifdef EMSCRIPTEN_BUILD
    log_plain("%s", text);
#else
    if (ui_notice_present(severity, text) == ERROR_BUFFER_FULL)
      log_warn_every(US_PER_SEC_INT, "Notice display queue is full; additional notices remain in the log");
#endif
  SAFE_FREE(plain_log_line);
  g_notice_text = text;
}

static void notice_logv(ui_notice_severity_t severity, bool unfiltered, const char *file, int line, const char *func,
                        const char *title, const char *format, va_list args) {
  if (!title || !format || !lifecycle_is_initialized(&g_log.lifecycle))
    return;
  char *body = format_message(format, args);
  if (!body)
    return;
  size_t size = strlen(title) + strlen(body) + 2;
  char *message = SAFE_MALLOC(size, char *);
  if (!message) {
    SAFE_FREE(body);
    return;
  }
  safe_snprintf(message, size, "%s\n%s", title, body);
  const char *previous = g_notice_text;
  ui_notice_severity_t previous_severity = g_notice_severity;
  bool previous_unfiltered = g_notice_unfiltered;
  g_notice_text = message;
  g_notice_severity = severity;
  g_notice_unfiltered = unfiltered;
  log_level_t level = severity == UI_NOTICE_FATAL     ? LOG_FATAL
                      : severity == UI_NOTICE_DANGER  ? LOG_ERROR
                      : severity == UI_NOTICE_WARNING ? LOG_WARN
                                                      : LOG_INFO;
  if (strlen(message) < 3000) {
    log_msg(level, file, line, func, "%s", message);
  } else {
    bool previous_record_only = g_notice_record_only;
    g_notice_record_only = true;
    const char *cursor = message;
    while (*cursor) {
      size_t bytes = strlen(cursor);
      if (bytes > 3000) {
        bytes = 3000;
        while (bytes && ((unsigned char)cursor[bytes] & 0xc0) == 0x80)
          --bytes;
        if (!bytes)
          bytes = 3000; // Malformed UTF-8 must still make progress.
      }
      log_msg(level, file, line, func, "%.*s", (int)bytes, cursor);
      cursor += bytes;
    }
    g_notice_record_only = previous_record_only;
    if ((unfiltered || level >= log_get_level()) && atomic_load_int(&g_log.json_file) < 0)
      output_notice(level, file, line, func);
  }
  g_notice_text = previous;
  g_notice_severity = previous_severity;
  g_notice_unfiltered = previous_unfiltered;
  SAFE_FREE(message);
  SAFE_FREE(body);
}

void ui_notice_log(ui_notice_severity_t severity, const char *file, int line, const char *func, const char *title,
                   const char *format, ...) {
  va_list args;
  va_start(args, format);
  notice_logv(severity, false, file, line, func, title, format, args);
  va_end(args);
}

void ui_notice_announce(const char *file, int line, const char *func, const char *title, const char *format, ...) {
  va_list args;
  va_start(args, format);
  notice_logv(UI_NOTICE_INFO, true, file, line, func, title, format, args);
  va_end(args);
}

void log_msg(log_level_t level, const char *file, int line, const char *func, const char *fmt, ...) {


  // All state access uses atomic operations - fully lock-free
  if (!lifecycle_is_initialized(&g_log.lifecycle)) {
    return;
  }

  // Safety check: if main format template has been freed during shutdown, skip logging
  // This prevents heap-use-after-free when threads call logging after log_destroy() has freed g_log.format
  if (!g_log.format) {
    return;
  }

  uint64_t loaded_level = atomic_load_u64(&g_log.level);

  if (level < (log_level_t)loaded_level && !(g_notice_text && g_notice_unfiltered)) {
    return;
  }
  /* =========================================================================
   * MMAP PATH: When mmap logging is active, writes go to mmap'd file
   * ========================================================================= */
  bool mmap_active = log_mmap_is_active();

  if (mmap_active) {
    maybe_rotate_log();

    va_list args;
    va_start(args, fmt);
    char msg_buffer[LOG_MMAP_MSG_BUFFER_SIZE];
    int msg_len = safe_vsnprintf(msg_buffer, sizeof(msg_buffer), fmt, args);
    va_end(args);

    // Truncate at whole line boundaries to avoid UTF-8 issues
    if (msg_len > 0) {
      msg_len = truncate_at_whole_line(msg_buffer, msg_len, sizeof(msg_buffer));
    }

    // Validate UTF-8 in formatted message
    validate_log_message_utf8(msg_buffer, "mmap log message");

    if (!g_notice_text)
      session_log_buffer_append(g_history, msg_buffer);
    log_mmap_write(level, file, line, func, "%s", msg_buffer);

    if (g_notice_text) {
      output_notice(level, file, line, func);
      return;
    }

    // Terminal output (check with atomic loads)
    if (atomic_load_u64(&g_log.terminal_output_enabled) && !atomic_load_bool(&g_log.terminal_locked)) {
      char time_buf[LOG_TIMESTAMP_BUFFER_SIZE];
      uint64_t time_ns = time_get_realtime_ns();
      get_current_time_formatted(time_buf);

      // Choose output stream using unified routing logic
      int fd = terminal_choose_log_fd(level);
      FILE *output_stream = (fd == STDERR_FILENO) ? stderr : stdout;
      // Check if colors should be used
      // Priority 1: If --color was explicitly passed, force colors
      bool use_colors = true; // Default: enable colors
      if (g_color_flag_passed && !g_color_flag_value) {
        use_colors = false; // --color=false explicitly disables colors
      }
      // Priority 2: If --color NOT explicitly passed, enable colors by default

      char header_buffer[512];
      int header_len = format_log_header(header_buffer, sizeof(header_buffer), level, time_buf, file, line, func,
                                         use_colors, time_ns);

      if (header_len >= 0 && header_len < (int)sizeof(header_buffer)) {
        if (use_colors) {
          const char *colorized_msg = colorize_log_message(msg_buffer);
          const char **colors = log_get_color_array();
          if (colors) {
            log_terminal_printf(output_stream == stdout ? STDOUT_FILENO : STDERR_FILENO, "%s%s%s%s\n", header_buffer,
                                 colors[LOG_COLOR_RESET], colorized_msg, colors[LOG_COLOR_RESET]);
          } else {
            log_terminal_printf(output_stream == stdout ? STDOUT_FILENO : STDERR_FILENO, "%s%s\n", header_buffer,
                                 colorized_msg);
          }
        } else {
          log_terminal_printf(output_stream == stdout ? STDOUT_FILENO : STDERR_FILENO, "%s%s\n", header_buffer,
                               msg_buffer);
        }
        (void)fflush(output_stream);
      }
    } else {
    }
    return;
  }
  /* =========================================================================
   * FILE I/O PATH: Lock-free using atomic write() syscalls
   * ========================================================================= */
  char time_buf[LOG_TIMESTAMP_BUFFER_SIZE];
  uint64_t time_ns = time_get_realtime_ns();
  get_current_time_formatted(time_buf);
  // Format message for file output
  char log_buffer[LOG_MSG_BUFFER_SIZE];
  va_list args;
  va_start(args, fmt);
  int header_len = format_log_header(log_buffer, sizeof(log_buffer), level, time_buf, file, line, func, false, time_ns);
  if (header_len < 0 || header_len >= (int)sizeof(log_buffer)) {
    LOGGING_INTERNAL_ERROR(ERROR_INVALID_STATE, "Failed to format log header");
    va_end(args);
    return;
  }
  int msg_len = header_len;
  int formatted_len = safe_vsnprintf(log_buffer + header_len, sizeof(log_buffer) - (size_t)header_len, fmt, args);
  if (formatted_len < 0) {
    LOGGING_INTERNAL_ERROR(ERROR_INVALID_STATE, "Failed to format log message");
    va_end(args);
    return;
  }

  msg_len += formatted_len;
  // Truncate at whole line boundaries to avoid UTF-8 issues
  msg_len = truncate_at_whole_line(log_buffer, msg_len, sizeof(log_buffer));
  // Add newline if there's room and message doesn't already end with one
  if (msg_len > 0 && msg_len < (int)sizeof(log_buffer) - 1) {
    if (log_buffer[msg_len - 1] != '\n') {
      log_buffer[msg_len++] = '\n';
      log_buffer[msg_len] = '\0';
    }
  }
  va_end(args);
  // Validate UTF-8 in formatted message
  validate_log_message_utf8(log_buffer, "leveled log message");

  // Extract the user message part (without header) for JSON logging
  const char *user_message = log_buffer + header_len;

  // For JSON output: strip automatic trailing newline (keep explicit ones)
  char json_message_buf[LOG_MSG_BUFFER_SIZE];
  const char *json_message = user_message;
  size_t user_msg_len = strlen(user_message);

  // If message ends with newline and it was added automatically (not in original message)
  if (user_msg_len > 0 && user_message[user_msg_len - 1] == '\n') {
    // The newline was added automatically if the message part didn't end with one
    // before we added it on line 1067. We can check this by looking at msg_len - 1
    // If msg_len >= header_len + 2, then msg_len - 2 would be the char before the newline
    int msg_content_len = msg_len - header_len;
    // NOLINTNEXTLINE(clang-analyzer-security.ArrayBound) - msg_content_len > 1 bounds check above
    if (msg_content_len > 1 && log_buffer[msg_len - 2] != '\n') {
      // Newline was added automatically - strip it for JSON
      if (user_msg_len - 1 < sizeof(json_message_buf)) {
        memcpy(json_message_buf, user_message, user_msg_len - 1);
        json_message_buf[user_msg_len - 1] = '\0';
        json_message = json_message_buf;
      }
    }
  }

  // Check if JSON format is enabled
  int json_fd = atomic_load_int(&g_log.json_file);
  bool json_format_enabled = (json_fd >= 0);

  // If JSON format is enabled, output ONLY JSON (skip text output)
  if (json_format_enabled) {
    session_log_buffer_append(g_history, log_buffer);
    // Output JSON to the JSON file descriptor
    log_json_write(json_fd, level, time_ns, file, line, func, json_message);
    // Also output JSON to console using unified routing logic, respecting quiet flag
    if (atomic_load_u64(&g_log.terminal_output_enabled)) {
      int console_fd = terminal_choose_log_fd(level);
      log_json_write(console_fd, level, time_ns, file, line, func, json_message);
    }
  } else {
    // Text format: output to file and terminal
    // No heap allocation - use log_buffer directly
    // Write to file (atomic write syscall) - use original buffer (with ANSI codes)
    int file_fd = (int)atomic_load_u64(&g_log.file);
    if (file_fd >= 0 && file_fd != STDERR_FILENO) {
      write_to_log_file_atomic(log_buffer, msg_len, NULL);
    }

    if (g_notice_text) {
      output_notice(level, file, line, func);
      return;
    }

    // Write to terminal (atomic state checks)
    va_list args_terminal;
    va_start(args_terminal, fmt);
    write_to_terminal_atomic(level, time_buf, file, line, func, fmt, args_terminal, time_ns, true);
    va_end(args_terminal);
  }
}

void log_terminal_msg(log_level_t level, const char *file, int line, const char *func, const char *fmt, ...) {
  // Lock-free: only uses atomic loads, no mutex
  if (!lifecycle_is_initialized(&g_log.lifecycle)) {
    return;
  }

  if (level < (log_level_t)atomic_load_u64(&g_log.level)) {
    return;
  }

  // Terminal output only - no file/mmap writing
  char time_buf[LOG_TIMESTAMP_BUFFER_SIZE];
  uint64_t time_ns = time_get_realtime_ns();
  get_current_time_formatted(time_buf);

  va_list args;
  va_start(args, fmt);
  write_to_terminal_atomic(level, time_buf, file, line, func, fmt, args, time_ns, true);
  va_end(args);
}

void log_plain_msg(const char *fmt, ...) {
  if (!lifecycle_is_initialized(&g_log.lifecycle)) {
    return;
  }

  char log_buffer[LOG_MSG_BUFFER_SIZE];
  va_list args;
  va_start(args, fmt);
  int msg_len = safe_vsnprintf(log_buffer, sizeof(log_buffer), fmt, args);
  va_end(args);

  if (msg_len <= 0) {
    return;
  }

  // Truncate at whole line boundaries to avoid UTF-8 issues
  msg_len = truncate_at_whole_line(log_buffer, msg_len, sizeof(log_buffer));

  // Validate UTF-8 in formatted message
  validate_log_message_utf8(log_buffer, "plain text log");

  session_log_buffer_append(g_history, log_buffer);

  // Write to mmap if active
  if (log_mmap_is_active()) {
    log_mmap_write(LOG_INFO, NULL, 0, NULL, "%s", log_buffer);
  } else {
    // Write to file with headers (atomic write syscall)
    int file_fd = atomic_load_u64(&g_log.file);
    if (file_fd >= 0 && file_fd != STDERR_FILENO) {
      // Add header with timestamp and log level to file output
      char time_buf[LOG_TIMESTAMP_BUFFER_SIZE];
      uint64_t time_ns = time_get_realtime_ns();
      get_current_time_formatted(time_buf);

      char header_buffer[512];
      int header_len = format_log_header(header_buffer, sizeof(header_buffer), LOG_INFO, time_buf, "lib/log/logging.c",
                                         0, "log_plain_msg", false, time_ns);

      if (header_len > 0) {
        write_to_log_file_atomic(header_buffer, header_len, NULL);
      }
      write_to_log_file_atomic(log_buffer, msg_len, NULL);
      write_to_log_file_atomic("\n", 1, NULL);
    }
  }

  // Preserve diagnostics in the log file during shutdown without repainting the terminal.
  if (shutdown_is_requested())
    return;

  // Terminal output (atomic state checks)
  if (!atomic_load_u64(&g_log.terminal_output_enabled)) {
    return;
  }
  if (atomic_load_u64(&g_log.terminal_locked)) {
    uint64_t owner = atomic_load_u64(&g_log.terminal_owner_thread);
    if (owner != (uint64_t)asciichat_thread_self()) {
      return;
    }
  }

  // Check if JSON format is enabled
  int json_fd = atomic_load_int(&g_log.json_file);
  bool json_format_enabled = (json_fd >= 0);

  if (json_format_enabled) {
    // Output JSON for plain messages too
    uint64_t time_ns = time_get_realtime_ns();
    int console_fd = terminal_choose_log_fd(LOG_INFO);
    log_json_write(console_fd, LOG_INFO, time_ns, __FILE__, __LINE__, "log_plain_msg", log_buffer);
  } else {
    // Choose output stream using unified routing logic (LOG_INFO level)
    int fd = terminal_choose_log_fd(LOG_INFO);
    FILE *output_stream = (fd == STDERR_FILENO) ? stderr : stdout;

    // Apply colorization for TTY output
    if (terminal_should_color_output(fd)) {
      const char *colorized_msg = colorize_log_message(log_buffer);
      log_terminal_printf(output_stream == stdout ? STDOUT_FILENO : STDERR_FILENO, "%s\n", colorized_msg);
    } else {
      log_terminal_printf(output_stream == stdout ? STDOUT_FILENO : STDERR_FILENO, "%s\n", log_buffer);
    }
    (void)fflush(output_stream);
  }
}

static void log_plain_stderr_internal_atomic(const char *fmt, va_list args, bool add_newline) {
  char log_buffer[LOG_MSG_BUFFER_SIZE];
  int msg_len = safe_vsnprintf(log_buffer, sizeof(log_buffer), fmt, args);

