static crc32_fn crc32_backend(void) {
  static _Thread_local crc32_fn selected;
  if (!selected) {
    selected = asciichat_crc32_sw_update;
#if defined(ARCH_ARM64) || defined(ARCH_X86_64)
    if (platform_cpu_features() & CPU_FEATURE_CRC32) {
