asciichat_error_t platform_dup2(int source_fd, int target_fd) {
#ifdef _WIN32
  int result = _dup2(source_fd, target_fd);
#else
  int result = dup2(source_fd, target_fd);
#endif
  if (result < 0) {
    return SET_ERRNO_SYS(ERROR_FILE_OPERATION, "Failed to redirect descriptor %d to %d", target_fd, source_fd);
  }
  return ASCIICHAT_OK;
}

int safe_snprintf(char *buffer, size_t buffer_size, const char *format, ...) {
  if (!buffer || !format || buffer_size == 0) {
    return -1;
  }

  va_list args;
  va_start(args, format);

  /* Delegate to platform_snprintf for actual formatting */
  int ret = platform_vsnprintf(buffer, buffer_size, format, args);

  va_end(args);
  return ret;
}

int safe_fprintf(FILE *stream, const char *format, ...) {
  if (!stream || !format) {
    return -1;
  }

  va_list args;
  va_start(args, format);
  int ret = vfprintf(stream, format, args);
  va_end(args);

  return ret;
}

int safe_vsnprintf(char *buffer, size_t buffer_size, const char *format, va_list ap) {
  if (!format) {
    return -1;
  }

  // Allow NULL buffer with size 0 for size calculation (standard vsnprintf behavior)
  if (!buffer && buffer_size > 0) {
    return -1; // Non-NULL buffer required when buffer_size > 0
  }

  /* Delegate to platform_vsnprintf for actual formatting */
  return platform_vsnprintf(buffer, buffer_size, format, ap);
}

size_t platform_write_all(int fd, const void *buf, size_t count) {
  if (!buf || count == 0) {
    return 0;
  }

  size_t written_total = 0;
  int attempts = 0;
  const int MAX_ATTEMPTS = 1000;

  while (written_total < count && attempts < MAX_ATTEMPTS) {
    ssize_t result = platform_write(fd, (const char *)buf + written_total, count - written_total);

    if (result > 0) {
      written_total += (size_t)result;
      attempts = 0; // Reset attempt counter on successful write
    } else if (result < 0) {
      int write_errno = errno;
      // Handle EAGAIN (non-blocking would-block) with sleep instead of tight loop
      if (write_errno == EAGAIN || write_errno == EWOULDBLOCK) {
        // Sleep 100us before retrying to avoid busy-waiting and spinning CPU
        platform_sleep_us(100);
      } else if (write_errno != EINTR) {
        // Logging also writes through this function. Reporting a broken output
        // here can recurse into the same failure, and retrying cannot repair it.
        break;
      }
      errno = write_errno;
      attempts++;
    } else {
      // A zero-length write cannot make progress on this buffer.
      break;
    }
  }

  return written_total;
}

