    pcre2_match_data *sep_match = path_match_data_create(separator_regex);
    pcre2_match_data *dot_match = path_match_data_create(dot_regex);

    if (sep_match && dot_match) {
      size_t offset = 0;
      size_t remaining_len = strlen(pos);
