    platform_rmdir_recursive(homedir->path);
    SAFE_FREE(homedir);
    return NULL;
  }

  log_debug("Created temporary GPG homedir: %s", homedir->path);
  return homedir;
}

const char *gpg_homedir_path(const gpg_homedir_t *homedir) {
