  if (!collection || !out_metrics || !out_count) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters to collection_get");
  }

  *out_metrics = collection->metrics;
  *out_count = collection->count;

  return ASCIICHAT_OK;
}

