static void webrtc_release_port(webrtc_peer_connection_t *pc) {
  if (pc->port_reservation != INVALID_SOCKET_VALUE) {
    socket_close(pc->port_reservation);
    pc->port_reservation = INVALID_SOCKET_VALUE;
  }
}

static void *webrtc_mapping_worker(void *arg) {
  webrtc_peer_connection_t *pc = arg;
  while (!atomic_load_bool(&pc->mapping_stop)) {
    if (time_get_ns() >= pc->mapping->refresh_at_ns) {
      asciichat_errno_scope_t renewal_scope = asciichat_errno_scope_begin();
      if (nat_upnp_refresh(pc->mapping) != ASCIICHAT_OK)
        LOG_ERRNO_IF_SET("WebRTC UDP mapping renewal failed");
      asciichat_errno_scope_end(renewal_scope, ASCIICHAT_ERRNO_HANDLED);
    }
    time_sleep_ns(100 * NS_PER_MS_INT);
  }
  return NULL;
}

static void webrtc_mapping_close(webrtc_peer_connection_t *pc) {
  if (pc->mapping_thread_started) {
    atomic_store_bool(&pc->mapping_stop, true);
    asciichat_thread_join(&pc->mapping_thread, NULL);
    pc->mapping_thread_started = false;
  }
  nat_upnp_close(&pc->mapping);
  webrtc_release_port(pc);
}

static void webrtc_mapping_prepare(webrtc_peer_connection_t *pc, rtcConfiguration *rtc_config) {
  if (!pc->config.port_forwarding || pc->config.relay_only) {
    return;
  }
  const char *bind_address = pc->config.bind_address;
  bool specific = bind_address && bind_address[0] && strcmp(bind_address, "0.0.0.0") != 0;
  if (specific && (!is_valid_ipv4(bind_address) || is_localhost_ipv4(bind_address))) {
    log_info("WebRTC UDP mapping skipped for loopback or IPv6-only binding");
    return;
  }
  pc->port_reservation = socket_create("webrtc_mapping_reservation", AF_INET, SOCK_DGRAM, 0);
  if (pc->port_reservation == INVALID_SOCKET_VALUE) {
    return;
  }
  struct sockaddr_in addr = {0};
  addr.sin_family = AF_INET;
  addr.sin_addr.s_addr = htonl(INADDR_ANY);
  socklen_t length = sizeof(addr);
  if (socket_bind(pc->port_reservation, (struct sockaddr *)&addr, sizeof(addr)) != 0 ||
      socket_getsockname(pc->port_reservation, (struct sockaddr *)&addr, &length) != 0) {
    webrtc_release_port(pc);
    return;
  }
  uint16_t port = ntohs(addr.sin_port);
  asciichat_errno_scope_t mapping_scope = asciichat_errno_scope_begin();
  if (nat_upnp_open_protocol(port, "ascii-chat WebRTC", NAT_UPNP_UDP, &pc->mapping) != ASCIICHAT_OK) {
    asciichat_errno_scope_end(mapping_scope, ASCIICHAT_ERRNO_HANDLED);
    log_warn("WebRTC UDP mapping unavailable; continuing with normal ICE/STUN/TURN");
    webrtc_release_port(pc);
    return;
  }
  asciichat_errno_scope_end(mapping_scope, ASCIICHAT_ERRNO_HANDLED);
  if (pc->mapping->is_natpmp) {
    pc->mapping->internal_ip[0] = '\0';
    struct sockaddr_in gateway = {0};
    gateway.sin_family = AF_INET;
    gateway.sin_port = htons(5351);
    gateway.sin_addr.s_addr = pc->mapping->gateway;
    if (socket_connect(pc->port_reservation, (struct sockaddr *)&gateway, sizeof(gateway)) == 0 &&
        socket_getsockname(pc->port_reservation, (struct sockaddr *)&addr, &length) == 0) {
      inet_ntop(AF_INET, &addr.sin_addr, pc->mapping->internal_ip, sizeof(pc->mapping->internal_ip));
    }
  }
  if (!pc->mapping->internal_ip[0] || (specific && strcmp(bind_address, pc->mapping->internal_ip) != 0)) {
    // Do not map a different interface from the one selected by the caller.
    webrtc_mapping_close(pc);
    return;
  }
  atomic_store_bool(&pc->mapping_stop, false);
  if (asciichat_thread_create(&pc->mapping_thread, "webrtc_mapping", webrtc_mapping_worker, pc) != 0) {
    webrtc_mapping_close(pc);
    return;
  }
  pc->mapping_thread_started = true;
  rtc_config->portRangeBegin = port;
  rtc_config->portRangeEnd = port;
  rtc_config->bindAddress = pc->mapping->internal_ip;
  log_info("WebRTC UDP mapping ready before ICE gathering: %s:%u -> %s:%u", pc->mapping->external_ip,
           pc->mapping->mapped_port, pc->mapping->internal_ip, port);
}

static void rtc_log_callback(rtcLogLevel level, const char *message) {
  switch (level) {
  case RTC_LOG_FATAL:
  case RTC_LOG_ERROR:
    log_error("[libdatachannel] %s", message);
    break;
  case RTC_LOG_WARNING:
    log_warn("[libdatachannel] %s", message);
    break;
  case RTC_LOG_INFO:
    log_info("[libdatachannel] %s", message);
    break;
  case RTC_LOG_DEBUG:
  case RTC_LOG_VERBOSE:
    log_debug("[libdatachannel] %s", message);
    break;
  default:
    break;
  }
}

static void on_state_change_adapter(int pc_id, rtcState state, void *user_data) {
  webrtc_peer_connection_t *pc = (webrtc_peer_connection_t *)user_data;
  if (!pc)
    return;

  // Map libdatachannel state to our enum
  webrtc_state_t new_state;
  switch (state) {
  case RTC_NEW:
    new_state = WEBRTC_STATE_NEW;
    break;
  case RTC_CONNECTING:
    new_state = WEBRTC_STATE_CONNECTING;
    break;
  case RTC_CONNECTED:
    new_state = WEBRTC_STATE_CONNECTED;
    char local_candidate[512], remote_candidate[512];
    if (rtcGetSelectedCandidatePair(pc_id, local_candidate, sizeof(local_candidate), remote_candidate,
                                    sizeof(remote_candidate)) >= 0) {
      log_info("WebRTC selected local candidate: %s", local_candidate);
      log_info("WebRTC selected remote candidate: %s", remote_candidate);
    }
    break;
  case RTC_DISCONNECTED:
    new_state = WEBRTC_STATE_DISCONNECTED;
    break;
  case RTC_FAILED:
    new_state = WEBRTC_STATE_FAILED;
    break;
  case RTC_CLOSED:
    new_state = WEBRTC_STATE_CLOSED;
    break;
  default:
    new_state = WEBRTC_STATE_NEW;
    break;
  }

  atomic_store_u64(&pc->state, (uint64_t)new_state);

  if (pc->config.on_state_change) {
    pc->config.on_state_change(pc, new_state, pc->config.user_data);
  }
}

static void on_gathering_state_change_adapter(int pc_id, rtcGatheringState state, void *user_data) {
  (void)pc_id; // Unused - we get peer connection from user_data
  webrtc_peer_connection_t *pc = (webrtc_peer_connection_t *)user_data;
  if (!pc)
    return;

  // Map libdatachannel gathering state to our enum
  webrtc_gathering_state_t new_state;
  switch (state) {
  case RTC_GATHERING_NEW:
    new_state = WEBRTC_GATHERING_NEW;
    break;
  case RTC_GATHERING_INPROGRESS:
    new_state = WEBRTC_GATHERING_GATHERING;
    // Record start time when gathering begins
    if (atomic_load_u64(&pc->gathering_state) != WEBRTC_GATHERING_GATHERING) {
      uint64_t start_time_ms = platform_get_monotonic_time_us() / 1000;
      atomic_store_u64(&pc->gathering_start_time_ms, start_time_ms);
      log_debug("ICE gathering started at %llu ms", (unsigned long long)start_time_ms);
    }
    break;
  case RTC_GATHERING_COMPLETE:
    new_state = WEBRTC_GATHERING_COMPLETE;
    uint64_t gathering_start_time_ms = atomic_load_u64(&pc->gathering_start_time_ms);
    if (gathering_start_time_ms > 0) {
      uint64_t duration = (platform_get_monotonic_time_us() / 1000) - gathering_start_time_ms;
      log_info("ICE gathering completed in %llu ms", (unsigned long long)duration);
    }
    break;
  default:
    new_state = WEBRTC_GATHERING_NEW;
    break;
  }

  atomic_store_u64(&pc->gathering_state, (uint64_t)new_state);

  if (pc->config.on_gathering_state_change) {
    pc->config.on_gathering_state_change(pc, new_state, pc->config.user_data);
  }
}

static void on_local_description_adapter(int pc_id, const char *sdp, const char *type, void *user_data) {
  (void)pc_id; // Unused - we get peer connection from user_data
  webrtc_peer_connection_t *pc = (webrtc_peer_connection_t *)user_data;
  if (!pc)
    return;

  if (pc->config.on_local_description) {
    pc->config.on_local_description(pc, sdp, type, pc->config.user_data);
  }
}

static void on_local_candidate_adapter(int pc_id, const char *candidate, const char *mid, void *user_data) {
  (void)pc_id; // Unused - we get peer connection from user_data
  webrtc_peer_connection_t *pc = (webrtc_peer_connection_t *)user_data;
  if (!pc)
    return;

  if (pc->config.on_local_candidate) {
    pc->config.on_local_candidate(pc, candidate, mid, pc->config.user_data);
  }
}

static void on_datachannel_adapter(int pc_id, int dc_id, void *user_data) {
  (void)pc_id; // Unused - we get peer connection from user_data
  log_info("on_datachannel_adapter: pc_id=%d, dc_id=%d, user_data=%p", pc_id, dc_id, user_data);

  webrtc_peer_connection_t *pc = (webrtc_peer_connection_t *)user_data;
  if (!pc) {
    log_error("on_datachannel_adapter: peer connection user_data is NULL!");
    return;
  }

  log_info("on_datachannel_adapter: received DataChannel (dc_id=%d) from remote peer", dc_id);

  // Allocate data channel wrapper
  webrtc_data_channel_t *dc = SAFE_CALLOC(1, sizeof(webrtc_data_channel_t), webrtc_data_channel_t *);
  if (!dc) {
    log_error("Failed to allocate data channel wrapper");
    rtcDeleteDataChannel(dc_id);
    return;
  }

  dc->rtc_id = dc_id;
  dc->pc = pc;
  atomic_store_bool(&dc->is_open, false);
  log_debug("Initialized DataChannel wrapper: dc=%p, is_open=false", (void *)dc);

  // Store in peer connection
  pc->dc = dc;

  // Set up data channel callbacks for incoming channel
  rtcSetUserPointer(dc_id, dc);
  rtcSetOpenCallback(dc_id, on_datachannel_open_adapter);
  // Keep libdatachannel's receive queue intact until a consumer is installed.
  // An adapter with no user callback would silently discard early peer hellos.
  if (pc->config.on_datachannel_message)
    rtcSetMessageCallback(dc_id, on_datachannel_message_adapter);
  rtcSetErrorCallback(dc_id, on_datachannel_error_adapter);

  log_info("Set up callbacks for incoming DataChannel (dc_id=%d, dc=%p)", dc_id, (void *)dc);

  // Check if DataChannel is already open (can happen if it opened before callbacks were set)
  // In libdatachannel, negotiated DataChannels may be open immediately when received
  // We manually trigger the open callback if that's the case
  if (rtcIsOpen(dc_id)) {
    log_info("DataChannel was already open when received, manually triggering open callback");
    on_datachannel_open_adapter(dc_id, dc);
  }
}

static void on_datachannel_open_adapter(int dc_id, void *user_data) {
  webrtc_data_channel_t *dc = (webrtc_data_channel_t *)user_data;
  log_info("on_datachannel_open_adapter called: dc_id=%d, dc=%p", dc_id, (void *)dc);
  if (!dc) {
    log_error("on_datachannel_open_adapter: dc is NULL!");
    return;
  }

  atomic_store_bool(&dc->is_open, true);
  log_info("DataChannel opened (id=%d, dc=%p), set is_open=true", dc_id, (void *)dc);

  // Check per-channel callback first, then fall back to peer connection callback
  if (dc->user_on_open) {
    log_debug("Calling per-channel on_open callback");
    dc->user_on_open(dc, dc->user_data);
  } else if (dc->pc && dc->pc->config.on_datachannel_open) {
    log_debug("Calling user on_datachannel_open callback");
    dc->pc->config.on_datachannel_open(dc, dc->pc->config.user_data);
  } else {
    log_warn("No user on_datachannel_open callback registered");
  }
}

static void on_datachannel_closed_adapter(int dc_id, void *user_data) {
  webrtc_data_channel_t *dc = (webrtc_data_channel_t *)user_data;
  log_info("on_datachannel_closed_adapter called: dc_id=%d, dc=%p", dc_id, (void *)dc);
  if (!dc) {
    log_error("on_datachannel_closed_adapter: dc is NULL!");
    return;
  }

  atomic_store_bool(&dc->is_open, false);
  log_info("DataChannel closed (id=%d, dc=%p), set is_open=false", dc_id, (void *)dc);

  // Check per-channel callback first
  if (dc->user_on_close) {
    log_debug("Calling per-channel on_close callback");
    dc->user_on_close(dc, dc->user_data);
  }
}

static void on_datachannel_message_adapter(int dc_id, const char *data, int size, void *user_data) {
  (void)dc_id; // Unused - we get data channel from user_data

  // Log at libdatachannel callback level (debug level for normal operation)
  if (size >= 20 && data) {
    const uint8_t *pkt = (const uint8_t *)data;
    log_dev("★ LIBDATACHANNEL_RX: dc_id=%d, size=%d, first_20_bytes: %02x%02x%02x%02x %02x%02x%02x%02x "
            "%02x%02x%02x%02x %02x%02x%02x%02x %02x%02x%02x%02x",
            dc_id, size, pkt[0], pkt[1], pkt[2], pkt[3], pkt[4], pkt[5], pkt[6], pkt[7], pkt[8], pkt[9], pkt[10],
            pkt[11], pkt[12], pkt[13], pkt[14], pkt[15], pkt[16], pkt[17], pkt[18], pkt[19]);
  } else {
    log_dev("★ LIBDATACHANNEL_RX: dc_id=%d, size=%d (no data or too small)", dc_id, size);
  }

  webrtc_data_channel_t *dc = (webrtc_data_channel_t *)user_data;
  if (!dc) {
    log_debug("★ LIBDATACHANNEL_RX: dc=NULL, dropping message");
    return;
  }

  // Check per-channel callback first, then fall back to peer connection callback
  if (dc->user_on_message) {
    dc->user_on_message(dc, (const uint8_t *)data, (size_t)size, dc->user_data);
  } else if (dc->pc && dc->pc->config.on_datachannel_message) {
    dc->pc->config.on_datachannel_message(dc, (const uint8_t *)data, (size_t)size, dc->pc->config.user_data);
  }
}

static void on_datachannel_error_adapter(int dc_id, const char *error, void *user_data) {
  webrtc_data_channel_t *dc = (webrtc_data_channel_t *)user_data;
  if (!dc)
    return;

  log_error("DataChannel error (id=%d): %s", dc_id, error);

  // Check per-channel callback first, then fall back to peer connection callback
  if (dc->user_on_error) {
    dc->user_on_error(dc, error, dc->user_data);
  } else if (dc->pc && dc->pc->config.on_datachannel_error) {
    dc->pc->config.on_datachannel_error(dc, error, dc->pc->config.user_data);
  }
}

static asciichat_error_t webrtc_ensure_initialized(void) {
  if (!lifecycle_init_once(&g_webrtc_lc)) {
    return ASCIICHAT_OK; // Already initialized
  }

  // First initialization - call library initialization exactly once
  rtcInitLogger(log_get_level() <= LOG_DEV ? RTC_LOG_VERBOSE : RTC_LOG_INFO, rtc_log_callback);
  rtcSctpSettings settings = {.sendBufferSize = ACIP_OUTBOUND_SCTP_RESERVE};
  if (rtcSetSctpSettings(&settings) < 0) {
    lifecycle_init_abort(&g_webrtc_lc);
    return SET_ERRNO(ERROR_NETWORK, "Cannot bound SCTP send buffer");
  }
  rtcPreload();
  lifecycle_init_commit(&g_webrtc_lc);

  log_debug("WebRTC library initialized (libdatachannel)");
  return ASCIICHAT_OK;
}

static void webrtc_release(void) {
  if (lifecycle_shutdown(&g_webrtc_lc)) {
    rtcCleanup();
    log_info("WebRTC library cleaned up");
  }
}

asciichat_error_t webrtc_init(void) {
  return webrtc_ensure_initialized();
}

void webrtc_destroy(void) {
  webrtc_release();
}

static void encode_turn_userinfo(const char *value, char *encoded, size_t size) {
  static const char hex[] = "0123456789ABCDEF";
  size_t out = 0;
  for (size_t i = 0; value[i] && out + 3 < size; i++) {
    unsigned char c = (unsigned char)value[i];
    encoded[out++] = '%';
    encoded[out++] = hex[c >> 4];
    encoded[out++] = hex[c & 15];
  }
  encoded[out] = '\0';
}

asciichat_error_t webrtc_create_peer_connection(const webrtc_config_t *config, webrtc_peer_connection_t **pc_out) {
  if (!config || !pc_out) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid config or output parameter");
  }
  *pc_out = NULL;
  if ((config->stun_count && !config->stun_servers) || (config->turn_count && !config->turn_servers)) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "ICE server counts require server arrays");
  }
  if ((config->turn_username != NULL) != (config->turn_credential != NULL)) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "TURN overrides require both username and credential");
  }

  if (!lifecycle_is_initialized(&g_webrtc_lc)) {
    return SET_ERRNO(ERROR_INIT, "WebRTC library not initialized");
  }
  if (config->relay_only && config->turn_count == 0) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Relay only requires a TURN server with credentials");
  }
  for (size_t i = 0; i < config->turn_count; i++) {
    const turn_server_t *server = &config->turn_servers[i];
    const char *username = config->turn_username ? config->turn_username : server->username;
    const char *credential = config->turn_credential ? config->turn_credential : server->credential;
    if (!username[0] || !credential[0] || strlen(username) > 127 || strlen(credential) > 127) {
      return SET_ERRNO(ERROR_INVALID_PARAM, "TURN server requires both username and credential");
    }
    if (strncmp(server->url, "turn:", 5) != 0 && strncmp(server->url, "turns:", 6) != 0) {
      return SET_ERRNO(ERROR_INVALID_PARAM, "TURN server URL must start with turn: or turns:");
    }
  }

  // Allocate peer connection wrapper
  webrtc_peer_connection_t *pc = SAFE_CALLOC(1, sizeof(webrtc_peer_connection_t), webrtc_peer_connection_t *);
  if (!pc) {
    return SET_ERRNO(ERROR_MEMORY, "Failed to allocate peer connection");
  }

  pc->port_reservation = INVALID_SOCKET_VALUE;
  pc->config = *config; // Copy config
  atomic_store_u64(&pc->state, WEBRTC_STATE_NEW);
  pc->dc = NULL;

  // Build ICE server list for libdatachannel
  const char **ice_servers = NULL;
  size_t ice_count = 0;
  char *turn_urls = NULL;

  if (config->stun_count > 0 || config->turn_count > 0) {
    ice_count = config->stun_count + config->turn_count;
    ice_servers = SAFE_MALLOC(ice_count * sizeof(char *), const char **);
    if (!ice_servers) {
      SAFE_FREE(pc);
      return SET_ERRNO(ERROR_MEMORY, "Failed to allocate ICE server list");
    }

    // Add STUN servers
    for (size_t i = 0; i < config->stun_count; i++) {
      ice_servers[i] = config->stun_servers[i].host;
    }

    // Add TURN servers
    if (config->turn_count > 0) {
      turn_urls = SAFE_CALLOC(config->turn_count, 1024, char *);
      if (!turn_urls) {
        SAFE_FREE(ice_servers);
        SAFE_FREE(pc);
        return SET_ERRNO(ERROR_MEMORY, "Failed to allocate authenticated TURN URLs");
      }
    }
    for (size_t i = 0; i < config->turn_count; i++) {
      const turn_server_t *server = &config->turn_servers[i];
      char username[128 * 3];
      char credential[128 * 3];
      encode_turn_userinfo(config->turn_username ? config->turn_username : server->username, username,
                           sizeof(username));
      encode_turn_userinfo(config->turn_credential ? config->turn_credential : server->credential, credential,
                           sizeof(credential));
      const char *address = strchr(server->url, ':') + 1;
      while (*address == '/')
        address++;
      SAFE_SNPRINTF(turn_urls + i * 1024, 1024, "%.*s%s:%s@%s", (int)(strchr(server->url, ':') - server->url + 1),
                    server->url, username, credential, address);
      ice_servers[config->stun_count + i] = turn_urls + i * 1024;
    }
  }

  // Create libdatachannel configuration
  rtcConfiguration rtc_config;
  memset(&rtc_config, 0, sizeof(rtc_config));
  // libdatachannel raises SO_SNDBUF to at least the local maximum message size.
  // Keep both limits equal so the fixed SCTP reservation covers retained bytes.
  rtc_config.maxMessageSize = ACIP_OUTBOUND_SCTP_RESERVE;
  rtc_config.bindAddress = config->bind_address;
  rtc_config.iceServers = ice_servers;
  rtc_config.iceServersCount = (int)ice_count;
  rtc_config.iceTransportPolicy = config->relay_only ? RTC_TRANSPORT_POLICY_RELAY : RTC_TRANSPORT_POLICY_ALL;
  if (rtc_config.bindAddress && rtc_config.bindAddress[0]) {
    log_info("Binding WebRTC ICE sockets to %s", rtc_config.bindAddress);
  }

  webrtc_mapping_prepare(pc, &rtc_config);

  // Create peer connection
  int pc_id = rtcCreatePeerConnection(&rtc_config);
  SAFE_FREE(turn_urls);

  // Free ICE server list (libdatachannel makes a copy)
  if (ice_servers) {
    SAFE_FREE(ice_servers);
  }

  if (pc_id < 0) {
    webrtc_mapping_close(pc);
    SAFE_FREE(pc);
    return SET_ERRNO(ERROR_NETWORK, "Failed to create peer connection (rtc error %d)", pc_id);
  }

  pc->rtc_id = pc_id;

  // Initialize gathering state
  atomic_store_u64(&pc->gathering_state, WEBRTC_GATHERING_NEW);
  atomic_store_u64(&pc->gathering_start_time_ms, 0);

  // Set up callbacks
  rtcSetUserPointer(pc_id, pc);
  rtcSetStateChangeCallback(pc_id, on_state_change_adapter);
  rtcSetGatheringStateChangeCallback(pc_id, on_gathering_state_change_adapter);
  rtcSetLocalDescriptionCallback(pc_id, on_local_description_adapter);
  rtcSetLocalCandidateCallback(pc_id, on_local_candidate_adapter);
  rtcSetDataChannelCallback(pc_id, on_datachannel_adapter);

  /* Register peer connection with named registry */
  char pc_name[64];
  snprintf(pc_name, sizeof(pc_name), "webrtc_peer_connection:%d", pc_id);
  NAMED_REGISTER(pc, pc_name, "webrtc_peer_connection_t", "0x%tx", NULL);

  *pc_out = pc;
  log_debug("Created WebRTC peer connection (id=%d)", pc_id);
  return ASCIICHAT_OK;
}

void webrtc_close_peer_connection(webrtc_peer_connection_t *pc) {
  if (!pc) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Invalid peer connection");
    return;
  }

  // Close data channel if exists
  if (pc->dc) {
    webrtc_close_datachannel(pc->dc);
    pc->dc = NULL;
  }

  // Close peer connection
  rtcDeletePeerConnection(pc->rtc_id);
  webrtc_mapping_close(pc);
  log_debug("Closed WebRTC peer connection (id=%d)", pc->rtc_id);

  SAFE_FREE(pc);
}

webrtc_state_t webrtc_get_state(webrtc_peer_connection_t *pc) {
  if (!pc) {
    log_warn("Peer connection is NULL");
    return WEBRTC_STATE_CLOSED;
  }
  return (webrtc_state_t)atomic_load_u64(&pc->state);
}

webrtc_gathering_state_t webrtc_get_gathering_state(webrtc_peer_connection_t *pc) {
  if (!pc) {
    log_warn("Peer connection is NULL");
    return WEBRTC_GATHERING_NEW;
  }
  return (webrtc_gathering_state_t)atomic_load_u64(&pc->gathering_state);
}

bool webrtc_is_gathering_timed_out(webrtc_peer_connection_t *pc, uint32_t timeout_ms) {
  if (!pc) {
    return false;
  }

  // Only check timeout if we're actively gathering
  if (atomic_load_u64(&pc->gathering_state) != WEBRTC_GATHERING_GATHERING) {
    return false;
  }

  // If gathering hasn't started yet (start_time == 0), no timeout
  uint64_t gathering_start_time_ms = atomic_load_u64(&pc->gathering_start_time_ms);
  if (gathering_start_time_ms == 0) {
    return false;
  }

  // Check if elapsed time exceeds timeout
  uint64_t current_time_ms = platform_get_monotonic_time_us() / 1000;
  uint64_t elapsed_ms = current_time_ms - gathering_start_time_ms;

  if (elapsed_ms > timeout_ms) {
    return true;
  }

  return false;
}

void *webrtc_get_user_data(webrtc_peer_connection_t *pc) {
  if (!pc) {
    log_warn("Peer connection is NULL");
    return NULL;
  }
  return pc->config.user_data;
}

asciichat_error_t webrtc_create_offer(webrtc_peer_connection_t *pc) {
  if (!pc) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid peer connection");
  }

  // Set local description with NULL type to trigger offer generation
  webrtc_release_port(pc);
  int result = rtcSetLocalDescription(pc->rtc_id, NULL);
  if (result != RTC_ERR_SUCCESS) {
    return SET_ERRNO(ERROR_NETWORK, "Failed to create SDP offer (rtc error %d)", result);
  }

  log_debug("Creating SDP offer (pc_id=%d)", pc->rtc_id);
  return ASCIICHAT_OK;
}

asciichat_error_t webrtc_set_remote_description(webrtc_peer_connection_t *pc, const char *sdp, const char *type) {
  if (!pc || !sdp || !type) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters");
  }

  webrtc_release_port(pc);
  int result = rtcSetRemoteDescription(pc->rtc_id, sdp, type);
  if (result != RTC_ERR_SUCCESS) {
    return SET_ERRNO(ERROR_NETWORK, "Failed to set remote SDP (rtc error %d)", result);
  }

  const char *dcmap = strstr(sdp, "a=dcmap:");
  if (strcmp(type, "offer") == 0) {
    log_debug("Remote WebRTC offer DataChannel map: %s", dcmap ? dcmap : "(none)");
  }
  if (strcmp(type, "offer") == 0 && strstr(sdp, "\na=dcmap:0 label=\"acip\"") && !pc->dc) {
    rtcDataChannelInit init = {0};
    init.negotiated = true;
    init.manualStream = true;
    init.stream = 0;
    int dc_id = rtcCreateDataChannelEx(pc->rtc_id, "acip", &init);
    if (dc_id < 0)
      return SET_ERRNO(ERROR_NETWORK, "Failed to create negotiated ACIP channel");
    on_datachannel_adapter(pc->rtc_id, dc_id, pc);
  }

  log_debug("Set remote SDP description (pc_id=%d, type=%s)", pc->rtc_id, type);
  return ASCIICHAT_OK;
}

asciichat_error_t webrtc_add_remote_candidate(webrtc_peer_connection_t *pc, const char *candidate, const char *mid) {
  if (!pc || !candidate) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters");
  }

  log_debug("  [4] Before libdatachannel - candidate: '%s' (len=%zu)", candidate, strlen(candidate));
  log_debug("  [4] Before libdatachannel - mid: '%s' (len=%zu)", mid ? mid : "(null)", mid ? strlen(mid) : 0);

  int result = rtcAddRemoteCandidate(pc->rtc_id, candidate, mid);
  if (result != RTC_ERR_SUCCESS) {
    return SET_ERRNO(ERROR_NETWORK, "Failed to add remote ICE candidate (rtc error %d)", result);
  }

  log_debug("Added remote ICE candidate (pc_id=%d)", pc->rtc_id);
  return ASCIICHAT_OK;
}

asciichat_error_t webrtc_create_datachannel(webrtc_peer_connection_t *pc, const char *label,
                                            webrtc_data_channel_t **dc_out) {
  if (!pc || !label || !dc_out) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters");
  }

  // Native peers use DCEP. Browser offers advertise the separately negotiated
  // ACIP channel and are handled in webrtc_set_remote_description().
  webrtc_release_port(pc);
  int dc_id = rtcCreateDataChannel(pc->rtc_id, label);
  if (dc_id < 0) {
    return SET_ERRNO(ERROR_NETWORK, "Failed to create data channel (rtc error %d)", dc_id);
  }

  // Allocate wrapper
  webrtc_data_channel_t *dc = SAFE_CALLOC(1, sizeof(webrtc_data_channel_t), webrtc_data_channel_t *);
  if (!dc) {
    rtcDeleteDataChannel(dc_id);
    return SET_ERRNO(ERROR_MEMORY, "Failed to allocate data channel wrapper");
  }

  dc->rtc_id = dc_id;
  dc->pc = pc;
  atomic_store_bool(&dc->is_open, false);

  // Set up callbacks
  rtcSetUserPointer(dc_id, dc);
  rtcSetOpenCallback(dc_id, on_datachannel_open_adapter);
  // Keep libdatachannel's receive queue intact until a consumer is installed.
  // An adapter with no user callback would silently discard early peer hellos.
  if (pc->config.on_datachannel_message)
    rtcSetMessageCallback(dc_id, on_datachannel_message_adapter);
  rtcSetErrorCallback(dc_id, on_datachannel_error_adapter);

  pc->dc = dc;
  *dc_out = dc;

  // Register data channel with debug naming system
  NAMED_REGISTER_DATACHANNEL(dc, label, NULL);

  log_debug("Created DataChannel '%s' (dc_id=%d, pc_id=%d)", label, dc_id, pc->rtc_id);
  return ASCIICHAT_OK;
}

asciichat_error_t webrtc_datachannel_get_buffered_amount(webrtc_data_channel_t *dc, size_t *amount) {
  if (!dc || dc->rtc_id < 0 || !amount)
    return SET_ERRNO(ERROR_INVALID_PARAM, "DataChannel and amount are required");
  int result = rtcGetBufferedAmount(dc->rtc_id);
  if (result < 0)
    return SET_ERRNO(ERROR_NETWORK, "Failed to query DataChannel buffered amount");
  *amount = (size_t)result;
  return ASCIICHAT_OK;
}

asciichat_error_t webrtc_datachannel_get_max_message_size(webrtc_data_channel_t *dc, size_t *size) {
  if (!dc || dc->rtc_id < 0 || !size)
    return SET_ERRNO(ERROR_INVALID_PARAM, "DataChannel and max message size are required");
  int result = rtcMaxMessageSize(dc->rtc_id);
  if (result <= 0)
    return SET_ERRNO(ERROR_NETWORK, "Failed to query DataChannel max message size");
  *size = (size_t)result;
  return ASCIICHAT_OK;
}

asciichat_error_t webrtc_datachannel_send(webrtc_data_channel_t *dc, const uint8_t *data, size_t size) {
  if (!dc || dc->rtc_id < 0 || !data) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters");
  }

  if (!atomic_load_bool(&dc->is_open)) {
    log_error("★ WEBRTC_DATACHANNEL_SEND: Channel not open! size=%zu, dc->rtc_id=%d", size, dc ? dc->rtc_id : -1);
    return SET_ERRNO(ERROR_NETWORK, "DataChannel not open");
  }

  // Log packet details at network layer (debug level for normal operation)
  if (size >= 20) {
    const uint8_t *pkt = (const uint8_t *)data;
    log_dev("★ RTCSENDMESSAGE_BEFORE: dc_id=%d, size=%zu, first_20_bytes: %02x%02x%02x%02x %02x%02x%02x%02x "
            "%02x%02x%02x%02x %02x%02x%02x%02x %02x%02x%02x%02x",
            dc->rtc_id, size, pkt[0], pkt[1], pkt[2], pkt[3], pkt[4], pkt[5], pkt[6], pkt[7], pkt[8], pkt[9], pkt[10],
            pkt[11], pkt[12], pkt[13], pkt[14], pkt[15], pkt[16], pkt[17], pkt[18], pkt[19]);
  } else {
    log_dev("★ RTCSENDMESSAGE_BEFORE: dc_id=%d, size=%zu (too small to log content)", dc->rtc_id, size);
  }

  int result = rtcSendMessage(dc->rtc_id, (const char *)data, (int)size);

  log_dev("★ RTCSENDMESSAGE_AFTER: dc_id=%d, rtcSendMessage returned %d for size=%zu", dc->rtc_id, result, size);

  if (result < 0) {
    log_error("★ WEBRTC_DATACHANNEL_SEND: FAILED with error code %d", result);
    return SET_ERRNO(ERROR_NETWORK, "Failed to send data (rtc error %d)", result);
  }

  log_dev("★ WEBRTC_DATACHANNEL_SEND: SUCCESS - sent %zu bytes", size);
  return ASCIICHAT_OK;
}

bool webrtc_datachannel_is_open(webrtc_data_channel_t *dc) {
  if (!dc) {
    SET_ERRNO(ERROR_INVALID_PARAM, "DataChannel is NULL");
    return false;
  }
  return dc->rtc_id >= 0 && atomic_load_bool(&dc->is_open);
}

void webrtc_datachannel_set_open_state(webrtc_data_channel_t *dc, bool is_open) {
  if (!dc) {
    SET_ERRNO(ERROR_INVALID_PARAM, "DataChannel is NULL");
    return;
  }
  atomic_store_bool(&dc->is_open, is_open);
}

const char *webrtc_datachannel_get_label(webrtc_data_channel_t *dc) {
  if (!dc || dc->rtc_id < 0) {
    SET_ERRNO(ERROR_INVALID_PARAM, "DataChannel is NULL");
    return NULL;
  }

  static char label[256];
  int result = rtcGetDataChannelLabel(dc->rtc_id, label, sizeof(label));
  if (result < 0) {
    return NULL;
  }

  return label;
}

void webrtc_close_datachannel(webrtc_data_channel_t *dc) {
  if (!dc) {
    SET_ERRNO(ERROR_INVALID_PARAM, "DataChannel is NULL");
    return;
  }
  if (dc->rtc_id < 0) {
    atomic_store_bool(&dc->is_open, false);
    return;
  }

  // Save the ID before deleting the native channel.
  int dc_id = dc->rtc_id;

  rtcDeleteDataChannel(dc_id);
  log_debug("Closed DataChannel (dc_id=%d)", dc_id);
  dc->rtc_id = -1;
  atomic_store_bool(&dc->is_open, false);
}

asciichat_error_t webrtc_datachannel_set_callbacks(webrtc_data_channel_t *dc,
                                                   const webrtc_datachannel_callbacks_t *callbacks) {
  if (!dc) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "DataChannel is NULL");
  }

  if (!callbacks) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Callbacks struct is NULL");
  }

  // Store user callbacks in the data channel struct
  dc->user_on_open = callbacks->on_open;
  dc->user_on_close = callbacks->on_close;
  dc->user_on_error = callbacks->on_error;
  dc->user_on_message = callbacks->on_message;
  dc->user_data = callbacks->user_data;

  // Register adapter functions with libdatachannel (adapters use correct signature)
  // The adapters will look up our stored callbacks and invoke them with proper types
  if (callbacks->on_open) {
    rtcSetOpenCallback(dc->rtc_id, on_datachannel_open_adapter);
  }

  if (callbacks->on_close) {
    rtcSetClosedCallback(dc->rtc_id, on_datachannel_closed_adapter);
  }

  if (callbacks->on_error) {
    rtcSetErrorCallback(dc->rtc_id, on_datachannel_error_adapter);
  }

  if (callbacks->on_message) {
    rtcSetMessageCallback(dc->rtc_id, on_datachannel_message_adapter);
  }

  // Set user pointer to the data channel so adapters can retrieve it
  rtcSetUserPointer(dc->rtc_id, dc);

  log_debug("Set DataChannel callbacks (dc_id=%d)", dc->rtc_id);
  return ASCIICHAT_OK;
}

void webrtc_datachannel_destroy(webrtc_data_channel_t *dc) {
  if (!dc) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Invalid null data channel");
    return;
  }

  // Close if still open, then free the wrapper.
  webrtc_close_datachannel(dc);
  SAFE_FREE(dc);
}

void webrtc_peer_connection_close(webrtc_peer_connection_t *pc) {
  if (!pc) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Invalid null peer connectiont");
    return;
  }

  rtcClose(pc->rtc_id);
  webrtc_mapping_close(pc);
  log_debug("Closed peer connection (pc_id=%d)", pc->rtc_id);
}

void webrtc_peer_connection_destroy(webrtc_peer_connection_t *pc) {
  if (!pc) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Invalid null peer connectiont");
    return;
  }

  // Close and delete peer connection
  rtcDeletePeerConnection(pc->rtc_id);
  webrtc_mapping_close(pc);
  log_debug("Destroyed peer connection (pc_id=%d)", pc->rtc_id);

  SAFE_FREE(pc);
}

int webrtc_get_rtc_id(webrtc_peer_connection_t *pc) {
  if (!pc) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Invalid null peer connectiont");
    return -1;
  }
  return pc->rtc_id;
}

