  /* Write binary-level options in grouped format */
  if (binary_opts) {
    zsh_write_combined_args(output, binary_opts, binary_count, true);
  }

  fprintf(output, "}\n\n_ascii_chat() {\n"
                  "  local i mode=''\n"
                  "  for (( i=2; i<CURRENT; ++i )); do\n"
                  "    case $words[i] in\n"
                  "      --) break ;;\n"
                  "      --*=*) continue ;;\n");
