  if (client_opts) {
    zsh_write_combined_args(output, client_opts, client_count, false);
    SAFE_FREE(client_opts);
  }

  fprintf(output, "}\n"
                  "\n"
                  "_ascii_chat_mirror() {\n"
                  "  local curcontext=$curcontext\n"
                  "  local -a context line state_descr args\n"
                  "  local state\n"
