asciichat_error_t manpage_merger_generate_usage(const options_config_t *config, char **out_content, size_t *out_len) {
  if (!out_content || !out_len) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid output parameters for manpage_merger_generate_usage");
  }

  if (!config || config->num_usage_lines == 0) {
    *out_content = SAFE_MALLOC(1, char *);
    (*out_content)[0] = '\0';
    *out_len = 0;
    return ASCIICHAT_OK;
  }

  // Allocate growing buffer for usage section
  size_t buffer_capacity = 4096;
  char *buffer = SAFE_MALLOC(buffer_capacity, char *);
  size_t offset = 0;

  for (size_t i = 0; i < config->num_usage_lines; i++) {
    const usage_descriptor_t *usage = &config->usage_lines[i];

    // Ensure buffer is large enough
    if (offset + 512 >= buffer_capacity) {
      buffer_capacity *= 2;
      buffer = SAFE_REALLOC(buffer, buffer_capacity, char *);
    }

    offset += safe_snprintf(buffer + offset, buffer_capacity - offset, ".TP\n");
    offset += safe_snprintf(buffer + offset, buffer_capacity - offset, ".B ascii-chat");
    if (usage->mode) {
      offset += safe_snprintf(buffer + offset, buffer_capacity - offset, " %s", usage->mode);
    }
    if (usage->positional) {
      offset += safe_snprintf(buffer + offset, buffer_capacity - offset, " %s", usage->positional);
    }
    if (usage->show_options) {
      // Use mode-specific options suffix for mode commands, regular options for binary-level
      if (usage->mode && strcmp(usage->mode, "<mode>") != 0) {
        offset += safe_snprintf(buffer + offset, buffer_capacity - offset, " [mode-options...]");
      } else {
        offset += safe_snprintf(buffer + offset, buffer_capacity - offset, " [options...]");
      }
    }
    offset += safe_snprintf(buffer + offset, buffer_capacity - offset, "\n");

    if (usage->description) {
      offset += safe_snprintf(buffer + offset, buffer_capacity - offset, "%s\n", usage->description);
    }
  }

  offset += safe_snprintf(buffer + offset, buffer_capacity - offset, "\n");

  *out_content = buffer;
  *out_len = offset;

  log_debug("Generated usage section (%zu bytes)", offset);
  return ASCIICHAT_OK;
}

asciichat_error_t manpage_merger_generate_synopsis(const char *mode_name, char **out_content, size_t *out_len) {
  if (!out_content || !out_len) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid output parameters for manpage_merger_generate_synopsis");
  }

  // Allocate buffer for synopsis
  size_t buffer_size = 512;
  char *buffer = SAFE_MALLOC(buffer_size, char *);
  size_t offset = 0;

  // Note: Section header is already in template, don't duplicate it

  if (mode_name) {
    // Mode-specific synopsis
    offset += safe_snprintf(buffer + offset, buffer_size - offset,
                            ".B ascii-chat\n"
                            ".I %s\n"
                            "[\\fIoptions\\fR]\n",
                            mode_name);
  } else {
    // Binary-level synopsis - show main modes
    offset += safe_snprintf(buffer + offset, buffer_size - offset,
                            ".B ascii-chat\n"
                            "[\\fIoptions\\fR]\n"
                            "\n"
                            ".B ascii-chat\n"
                            "[\\fIoptions\\fR] \\fI<session-string>\\fR\n"
                            "\n"
                            ".B ascii-chat\n"
                            "[\\fIoptions\\fR] [\\fBserver\\fR | \\fBclient\\fR | \\fBmirror\\fR | "
                            "\\fBdiscovery-service\\fR] [\\fImode-options\\fR]\n");
  }

  offset += safe_snprintf(buffer + offset, buffer_size - offset, "\n");

  *out_content = buffer;
  *out_len = offset;

  log_debug("Generated synopsis section (%zu bytes)", *out_len);
  return ASCIICHAT_OK;
}

