int getopt(int argc, char *const argv[], const char *optstring) {
  static int sp = 1;
  char *oli;

  if (sp == 1) {
    if (optind >= argc || argv[optind][0] != '-' || argv[optind][1] == '\0') {
      return -1;
    }
    if (strcmp(argv[optind], "--") == 0) {
      optind++;
      return -1;
    }
  }

  optopt = argv[optind][sp];
  oli = strchr(optstring, optopt);

  if (optopt == ':' || oli == NULL) {
    if (opterr && *optstring != ':') {
      (void)fprintf(stderr, "%s: invalid option -- '%c'\n", argv[0], optopt);
    }
    if (argv[optind][++sp] == '\0') {
      optind++;
      sp = 1;
    }
    return '?';
  }

  if (*(++oli) != ':') {
    optarg = NULL;
    if (argv[optind][++sp] == '\0') {
      sp = 1;
      optind++;
    }
  } else {
    if (argv[optind][sp + 1] != '\0') {
      optarg = &argv[optind++][sp + 1];
    } else if (++optind >= argc) {
      if (*optstring == ':') {
        return ':';
      }
      if (opterr) {
        (void)fprintf(stderr, "%s: option requires an argument -- '%c'\n", argv[0], optopt);
      }
      sp = 1;
      return '?';
    } else {
      optarg = argv[optind++];
    }
    sp = 1;
  }

  return optopt;
}

int getopt_long(int argc, char *const argv[], const char *optstring, const struct option *longopts, int *longindex) {
  static int sp = 1;
  char *current_arg;

  // Reset if needed
  if (optind == 0) {
    optind = 1;
    sp = 1;
  }

  optarg = NULL;

  if (optind >= argc) {
    sp = 1; // Reset sp when we're done
    return -1;
  }

  current_arg = argv[optind];

  // Check for end of options
  if (current_arg[0] != '-' || current_arg[1] == '\0') {
    sp = 1; // Reset sp when we're done
    return -1;
  }

  // Handle "--" (end of options)
  if (strcmp(current_arg, "--") == 0) {
    optind++;
    sp = 1; // Reset sp
    return -1;
  }

  // Handle long options
  if (current_arg[0] == '-' && current_arg[1] == '-') {
    const char *name_start = current_arg + 2;
    const char *name_end = strchr(name_start, '=');
    size_t name_len;

    if (name_end) {
      name_len = (size_t)((ptrdiff_t)(name_end - name_start));
    } else {
      name_len = strlen(name_start);
    }

    // Search for matching long option
    if (longopts != NULL) {
      for (int i = 0; longopts[i].name != NULL; i++) {
        if (strncmp(longopts[i].name, name_start, name_len) == 0 && longopts[i].name[name_len] == '\0') {
          // Found a match
          if (longindex != NULL) {
            *longindex = i;
          }

          // Handle argument
          if (longopts[i].has_arg == required_argument) {
            if (name_end) {
              // Cast needed: optarg is char* per getopt API, but name_end is const char*
              optarg = (char *)(name_end + 1); // NOLINT(cppcoreguidelines-pro-type-const-cast)
            } else if (optind + 1 < argc) {
              optarg = argv[++optind];
            } else {
              if (opterr && *optstring != ':') {
                (void)fprintf(stderr, "%s: option '--%s' requires an argument\n", argv[0], longopts[i].name);
              }
              optind++;
              return (*optstring == ':') ? ':' : '?';
            }
          } else if (longopts[i].has_arg == optional_argument) {
            if (name_end) {
              // Cast needed: optarg is char* per getopt API, but name_end is const char*
              optarg = (char *)(name_end + 1); // NOLINT(cppcoreguidelines-pro-type-const-cast)
            }
          } else if (longopts[i].has_arg == no_argument && name_end) {
            if (opterr && *optstring != ':') {
              (void)fprintf(stderr, "%s: option '--%s' doesn't allow an argument\n", argv[0], longopts[i].name);
            }
            optind++;
            return '?';
          }

          optind++;

          if (longopts[i].flag != NULL) {
            *longopts[i].flag = longopts[i].val;
            return 0;
          }

          return longopts[i].val;
        }
      }
    }

    // Unknown long option
    if (opterr && *optstring != ':') {
      (void)fprintf(stderr, "%s: unrecognized option '--%.*s'\n", argv[0], (int)name_len, name_start);
    }
    optind++;
    return '?';
  }

  // Handle short options
  // sp == 1 means we're already positioned at the first option character after '-'
  optopt = (unsigned char)current_arg[sp];
  const char *oli = strchr(optstring, optopt);

  if (optopt == ':' || oli == NULL) {
    if (opterr && *optstring != ':') {
      (void)fprintf(stderr, "%s: invalid option -- '%c'\n", argv[0], optopt);
    }
    if (current_arg[++sp] == '\0') {
      optind++;
      sp = 1;
    }
    return '?';
  }

  // Check what comes after this option in the optstring
  char next_char = *(oli + 1);

  if (next_char == '\0' || next_char != ':') {
    // No argument - next char is either null terminator or not a colon
    optarg = NULL;
    if (current_arg[++sp] == '\0') {
      sp = 1;
      optind++;
    }
    return optopt;
  }
  if (next_char == ':') {
    // Check if it's optional (::) or required (:)
    char after_colon = *(oli + 2);

    if (after_colon == ':') {
      // Optional argument (::)
      if (current_arg[sp + 1] != '\0') {
        optarg = &current_arg[sp + 1];
        sp = 1;
        optind++;
      } else {
        optarg = NULL;
        sp = 1;
        optind++;
      }
      return optopt;
    }
    // Required argument (:)
    if (current_arg[sp + 1] != '\0') {
      // Argument attached to option (-vARG)
      optarg = &current_arg[sp + 1];
      sp = 1;
      optind++;
      return optopt;
    }

    if (optind + 1 >= argc) {
      // No next argument available
      sp = 1;
      if (*optstring == ':') {
        return ':';
      }
      if (opterr) {
        (void)fprintf(stderr, "%s: option requires an argument -- '%c'\n", argv[0], optopt);
      }
      optind++;
      return '?';
    }

    // Get argument from next argv element
    sp = 1;
    optind++;
    optarg = argv[optind++];
    return optopt;
  }

  // Should not reach here
  return '?';
}

