  } else {
    log_error("Cannot answer prompt without an interactive terminal: %s", prompt);
    return false;
  }
  if (_stricmp(response, "yes") == 0 || _stricmp(response, "y") == 0)
    return true;
  if (_stricmp(response, "no") == 0 || _stricmp(response, "n") == 0)
    return false;
  return default_yes;
}

