const char *get_username_env(void) {
  static char username[BUFFER_SIZE_SMALL] = {'\0'};
  if (username[0] != '\0') {
    log_debug("Username already cached: %s", username);
    return username;
  }
  const char *user = platform_getenv("USERNAME");
  if (!user) {
    user = platform_getenv("USER");
  }
  if (user) {
    if (platform_strncpy(username, sizeof(username), user, sizeof(username) - 1) != 0) {
      SET_ERRNO(ERROR_STRING, "Failed to copy username");
      return "unknown";
    }
    return username;
  }
  SET_ERRNO(ERROR_STRING, "Failed to get username");
  return "unknown";
}

asciichat_error_t platform_init(void) {
  // Set binary mode for stdin/stdout to handle raw data
  _setmode(_fileno(stdin), _O_BINARY);
  _setmode(_fileno(stdout), _O_BINARY);
  _setmode(_fileno(stderr), _O_BINARY);

  // Set Windows timer resolution to 1ms for high-precision sleep
  // This is required for multimedia applications that need accurate timing
  // Without this, Sleep(1) can sleep up to 15.6ms (default Windows timer resolution)
  // With timeBeginPeriod(1), Sleep(1) sleeps 1-2ms which is acceptable for 144 FPS capture
  timeBeginPeriod(1);

  // Initialize username cache (only need to call once)
  get_username_env();

  // Install crash handlers for automatic backtrace on crashes
  platform_install_crash_handler();

  if (symbol_cache_init() != ASCIICHAT_OK) {
    return SET_ERRNO_SYS(ERROR_PLATFORM_INIT, "Symbol cache initialization failed");
  }

  // Initialize Winsock (required before getaddrinfo and socket operations)
  if (socket_init() != ASCIICHAT_OK) {
    return SET_ERRNO_SYS(ERROR_PLATFORM_INIT, "Network operation failed");
  }

  return ASCIICHAT_OK;
}

void platform_destroy(void) {
  // Cleanup binary PATH cache
  platform_cleanup_binary_path_cache();

  // Print symbol cache statistics before cleanup
  symbol_cache_print_stats();

  // Clean up symbol cache
  symbol_cache_destroy();

  // Clean up Windows DbgHelp symbol resolution
  cleanup_windows_symbols();

  socket_cleanup();

  // Restore original Windows timer resolution
  timeEndPeriod(1);
}

void platform_sleep_ms(unsigned int ms) {
  Sleep(ms);
}

uint64_t platform_get_monotonic_time_us(void) {
  static LARGE_INTEGER freq = {0};
  static bool freq_initialized = false;

  // Initialize frequency once (thread-safe via Windows guarantee)
  if (!freq_initialized) {
    QueryPerformanceFrequency(&freq);
    freq_initialized = true;
  }

  LARGE_INTEGER counter;
  QueryPerformanceCounter(&counter);

  // Convert to microseconds: (counter * 1,000,000) / freq
  return (uint64_t)((counter.QuadPart * US_PER_SEC_INT) / freq.QuadPart);
}

void platform_sleep_us(unsigned int usec) {
  // Convert microseconds to milliseconds, minimum 1ms
  int timeout_ms = (int)(usec / 1000);
  if (timeout_ms < 1)
    timeout_ms = 1;

  Sleep((DWORD)timeout_ms);
}

void platform_sleep_ns(uint64_t ns) {
  if (ns == 0) {
    return;
  }

  // Sleep() rounds a sub-millisecond remainder up to the next scheduler
  // tick.  Render loops frequently have only 1-3ms left after processing a
  // frame, so that rounding can skip an entire 16.7ms video deadline and
  // produce a stable ~30 FPS cadence.  A high-resolution waitable timer keeps
  // those deadline sleeps precise without busy-spinning a CPU core.
  // A waitable timer is stateful: setting a new deadline cancels the prior
  // deadline.  Each render/audio thread therefore needs its own handle.
  static _Thread_local HANDLE timer = NULL;
  if (!timer) {
    timer = CreateWaitableTimerExW(NULL, NULL, CREATE_WAITABLE_TIMER_HIGH_RESOLUTION, TIMER_ALL_ACCESS);
    if (!timer) {
      timer = CreateWaitableTimerW(NULL, FALSE, NULL);
    }
  }
  if (timer) {
    LARGE_INTEGER due_time;
    // Relative waitable-timer deadlines are measured in 100ns units.
    uint64_t ticks_100ns = (ns + 99) / 100;
    due_time.QuadPart = -(LONGLONG)ticks_100ns;
    if (SetWaitableTimer(timer, &due_time, 0, NULL, NULL, FALSE) && WaitForSingleObject(timer, INFINITE) == WAIT_OBJECT_0) {
      return;
    }
  }

  DWORD timeout_ms = (DWORD)((ns + NS_PER_MS_INT - 1) / NS_PER_MS_INT);
  Sleep(timeout_ms ? timeout_ms : 1);
}

asciichat_error_t platform_localtime(const time_t *timer, struct tm *result) {
  if (!timer || !result) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters for localtime");
  }
  errno_t err = localtime_s(result, timer);
  if (err != 0) {
    return SET_ERRNO_SYS(ERROR_PLATFORM_INIT, "Failed to convert time to local time");
  }
  return ASCIICHAT_OK;
}

asciichat_error_t platform_gtime(const time_t *timer, struct tm *result) {
  if (!timer || !result) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters for gmtime");
  }

  errno_t err = gmtime_s(result, timer);
  if (err != 0) {
    return SET_ERRNO_SYS(ERROR_PLATFORM_INIT, "Failed to convert time to UTC");
  }

  return ASCIICHAT_OK;
}

const char *platform_get_username(void) {
  return get_username_env();
}

signal_handler_t platform_signal(int sig, signal_handler_t handler) {
  return signal(sig, handler);
}

static void windows_sigint_handler(int sig) {
  (void)sig;
  if (g_console_ctrl_handler) {
    g_console_ctrl_handler(CONSOLE_CTRL_C);
  }
}

static BOOL WINAPI windows_console_ctrl_handler(DWORD ctrl_type) {
  if (!g_console_ctrl_handler) {
    return FALSE;
  }

  console_ctrl_event_t event;
  switch (ctrl_type) {
  case CTRL_C_EVENT:
    event = CONSOLE_CTRL_C;
    break;
  case CTRL_BREAK_EVENT:
    event = CONSOLE_CTRL_BREAK;
    break;
  case CTRL_CLOSE_EVENT:
    event = CONSOLE_CLOSE;
    break;
  case CTRL_LOGOFF_EVENT:
    event = CONSOLE_LOGOFF;
    break;
  case CTRL_SHUTDOWN_EVENT:
    event = CONSOLE_SHUTDOWN;
    break;
  default:
    return FALSE;
  }

  // Call the user's handler
  bool handled = g_console_ctrl_handler(event);
  return handled ? TRUE : FALSE;
}

bool platform_set_console_ctrl_handler(console_ctrl_handler_t handler) {
  if (handler != NULL) {
    // Register our handler if not already registered
    if (g_console_ctrl_handler == NULL) {
      if (!SetConsoleCtrlHandler(windows_console_ctrl_handler, TRUE)) {
        return false;
      }
      // Also register SIGINT for Git Bash/mintty compatibility
      signal(SIGINT, windows_sigint_handler);
    }
    g_console_ctrl_handler = handler;
  } else {
    // Unregister handler
    if (g_console_ctrl_handler != NULL) {
      SetConsoleCtrlHandler(windows_console_ctrl_handler, FALSE);
      signal(SIGINT, SIG_DFL);
      g_console_ctrl_handler = NULL;
    }
  }
  return true;
}

const char *platform_getenv(const char *name) {
  if (!name || name[0] == '\0') {
    SET_ERRNO(ERROR_INVALID_PARAM, "Empty environment variable name is invalid");
    return NULL;
  }
  // Use thread-local static buffer to avoid memory leak
  // (callers never free the returned pointer, matching POSIX getenv behavior)
  _Thread_local static char buffer[PLATFORM_MAX_ENV_VALUE_LENGTH];
  size_t required_size = 0;

  errno_t err = getenv_s(&required_size, buffer, sizeof(buffer), name);
  if (err != 0 || required_size == 0) {
    // Variable not found or error
    return NULL;
  }

  // Validate UTF-8 encoding
  if (!utf8_is_valid(buffer)) {
    log_warn("Environment variable '%s' contains invalid UTF-8, ignoring", name);
    return NULL;
  }

  return buffer;
}

int platform_setenv(const char *name, const char *value) {
  return _putenv_s(name, value);
}

int platform_unsetenv(const char *name) {
  return _putenv_s(name, "");
}

void platform_raise_fd_limit(unsigned int limit) {
  // Windows doesn't have a per-process fd limit like POSIX. The CRT default
  // is 8192 handles which is sufficient for most use cases. If needed,
  // _setmaxstdio() can raise the CRT stdio limit (max 8192).
  if (limit > 0 && limit > 512) {
    int current_max = _getmaxstdio();
    if ((int)limit > current_max) {
      int cap = limit > 8192 ? 8192 : (int)limit;
      _setmaxstdio(cap);
    }
  }
}

int platform_format_backtrace_symbols(char *buffer, size_t buffer_size, const char *label, char **symbols, int count,
                                      int skip_frames, int max_frames, backtrace_frame_filter_t filter) {
  if (!buffer || buffer_size == 0 || !symbols || count <= 0) {
    return 0;
  }

  int offset = 0;

  // Header with color
  offset +=
      safe_snprintf(buffer + offset, buffer_size - (size_t)offset, "  %s:\n", colored_string(LOG_COLOR_WARN, label));

  // Calculate frame limits
  int start = skip_frames;
  int end = count;
  if (max_frames > 0 && (start + max_frames) < end) {
    end = start + max_frames;
  }

  // Format backtrace frames with colored frame numbers
  int frame_num = 0;
  for (int i = start; i < end && offset < (int)buffer_size - 128; i++) {
    const char *symbol = symbols[i] ? symbols[i] : "???";

    // Skip frame if filter says to
    if (filter && filter(symbol)) {
      continue;
    }

    // Build colored frame number and manually embed it in buffer
    char frame_buf[16];
    safe_snprintf(frame_buf, sizeof(frame_buf), "%d", frame_num++);
    const char *colored_frame = colored_string(LOG_COLOR_FATAL, frame_buf);
    size_t colored_len = strlen(colored_frame);

    // Append "    ["
    offset += safe_snprintf(buffer + offset, buffer_size - (size_t)offset, "    [");

    // Append colored frame number
    if ((size_t)offset + colored_len < buffer_size) {
      memcpy(buffer + offset, colored_frame, colored_len);
      offset += (int)colored_len;
    }

    // Append "] symbol\n"
    offset += safe_snprintf(buffer + offset, buffer_size - (size_t)offset, "] %s\n", symbol);
  }

  return offset;
}

void platform_print_backtrace(int skip_frames) {
  void *buffer[32];
  int size = platform_backtrace(buffer, 32);

  if (size > 0) {
    char **symbols = platform_backtrace_symbols(buffer, size);
    if (symbols) {
      int start = 1 + skip_frames; // Skip this function + requested frames
      fprintf(stderr, "  Backtrace:\n");
      for (int i = start; i < size; i++) {
        fprintf(stderr, "    #%d %s\n", i - start, symbols[i] ? symbols[i] : "???");
      }
      platform_backtrace_symbols_destroy(symbols);
    }
  }
}

void platform_log_backtrace_frame(int n) {
  if (n < 1) {
    log_debug("Invalid frame number: %d (must be >= 1)", n);
    return;
  }

  const int MAX_FRAMES = 64;
  void *buffer[MAX_FRAMES];

  int size = platform_backtrace(buffer, MAX_FRAMES);
  if (size <= 0) {
    log_debug("Unable to capture backtrace");
    return;
  }

  // Calculate actual frame index (Windows skip is 1 vs 2 on POSIX)
  int frame_idx = 1 + n;
  if (frame_idx >= size) {
    log_debug("Frame %d not available (only %d frames in stack)", n, size - 1);
    return;
  }

  // Resolve the single frame symbol
  char **symbols = platform_backtrace_symbols(buffer + frame_idx, 1);
  if (!symbols || !symbols[0]) {
    log_debug("Unable to resolve frame %d", n);
    if (symbols)
      platform_backtrace_symbols_destroy(symbols);
    return;
  }

  const char *symbol = symbols[0];

  // Format: [frame_num] function_name() (relative/path/file.c:line)
  // Extract repo-relative path from symbol
  const char *file_start = strchr(symbol, '(');
  char frame_buf[16];
  safe_snprintf(frame_buf, sizeof(frame_buf), "%d", n);

  if (file_start) {
    // Symbol contains file path: extract it
    file_start++; // Skip '('
    const char *file_end = strchr(file_start, ')');
    if (file_end) {
      size_t file_len = (size_t)(file_end - file_start);
      char full_path[512];
      safe_snprintf(full_path, sizeof(full_path), "%.*s", (int)file_len, file_start);

      const char *rel_file = extract_project_relative_path(full_path);
      const char *colored_frame = colored_string(LOG_COLOR_FATAL, frame_buf);
      const char *colored_file = colored_string(LOG_COLOR_WARN, rel_file);

      log_debug("[%s] %s", colored_frame, colored_file);
    } else {
      const char *colored_frame = colored_string(LOG_COLOR_FATAL, frame_buf);
      log_debug("[%s] %s", colored_frame, symbol);
    }
  } else {
    // Raw symbol, just color the frame number
    const char *colored_frame = colored_string(LOG_COLOR_FATAL, frame_buf);
    log_debug("[%s] %s", colored_frame, symbol);
  }

  platform_backtrace_symbols_destroy(symbols);
}

static LONG WINAPI crash_handler(EXCEPTION_POINTERS *exception_info) {
  DWORD exception_code = exception_info->ExceptionRecord->ExceptionCode;
  const char *exception_name;

  switch (exception_code) {
  case EXCEPTION_ACCESS_VIOLATION:
    exception_name = "Access Violation (SIGSEGV)";
    break;
  case EXCEPTION_ARRAY_BOUNDS_EXCEEDED:
    exception_name = "Array Bounds Exceeded";
    break;
  case EXCEPTION_DATATYPE_MISALIGNMENT:
    exception_name = "Data Type Misalignment";
    break;
  case EXCEPTION_FLT_DIVIDE_BY_ZERO:
    exception_name = "Floating Point Divide by Zero (SIGFPE)";
    break;
  case EXCEPTION_FLT_INVALID_OPERATION:
    exception_name = "Floating Point Invalid Operation (SIGFPE)";
    break;
  case EXCEPTION_ILLEGAL_INSTRUCTION:
    exception_name = "Illegal Instruction (SIGILL)";
    break;
  case EXCEPTION_INT_DIVIDE_BY_ZERO:
    exception_name = "Integer Divide by Zero (SIGFPE)";
    break;
  case EXCEPTION_STACK_OVERFLOW:
    exception_name = "Stack Overflow";
    break;
  default:
    exception_name = "Unknown";
    break;
  }

  log_error("\n*** CRASH DETECTED ***\n"
            "Exception Code: 0x%08lx\n"
            "Exception: %s",
            exception_code, exception_name);
#ifndef NDEBUG
  // Only capture backtraces in Debug builds
  platform_print_backtrace(0);
#endif

  // Return EXCEPTION_EXECUTE_HANDLER to terminate the program
  return EXCEPTION_EXECUTE_HANDLER;
}

static void windows_signal_handler(int sig) {
  const char *signal_name;
  switch (sig) {
  case SIGABRT:
    signal_name = "SIGABRT (Abort)";
    break;
  case SIGFPE:
    signal_name = "SIGFPE (Floating Point Exception)";
    break;
  case SIGILL:
    signal_name = "SIGILL (Illegal Instruction)";
    break;
  default:
    signal_name = "Unknown";
    break;
  }

#ifndef NDEBUG
  // Only capture backtraces in Debug builds
  log_error("*** CRASH DETECTED ***\nSignal: %d (%s)", sig, signal_name);
  platform_print_backtrace(0);
#else
  log_error("*** CRASH DETECTED ***\nSignal: %d (%s)\nBacktrace disabled in Release builds", sig, signal_name);
#endif

  exit(1);
}

void platform_install_crash_handler(void) {
  // Install structured exception handler
  SetUnhandledExceptionFilter(crash_handler);

  // Also install signal handlers for C runtime exceptions
  platform_signal(SIGABRT, windows_signal_handler);
  platform_signal(SIGFPE, windows_signal_handler);
  platform_signal(SIGILL, windows_signal_handler);
}

int clock_gettime(int clk_id, struct timespec *tp) {
  if (!tp) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid timespec pointer");
  }

  if (clk_id == CLOCK_REALTIME) {
    // Get current wall clock time (Unix epoch time)
    FILETIME ft;
    GetSystemTimeAsFileTime(&ft);

    // Convert to 64-bit value
    ULARGE_INTEGER ull;
    ull.LowPart = ft.dwLowDateTime;
    ull.HighPart = ft.dwHighDateTime;

// Windows file time is 100ns intervals since January 1, 1601
// Unix epoch is January 1, 1970
// The difference is 11644473600 seconds
#define WINDOWS_TICK 10000000ULL
#define SEC_TO_UNIX_EPOCH 11644473600ULL

    tp->tv_sec = (time_t)((ull.QuadPart / WINDOWS_TICK) - SEC_TO_UNIX_EPOCH);
    tp->tv_nsec = (long)((ull.QuadPart % WINDOWS_TICK) * 100);
  } else {
    // For CLOCK_MONOTONIC or other clocks, use QueryPerformanceCounter
    LARGE_INTEGER freq, counter;

    if (!QueryPerformanceFrequency(&freq) || !QueryPerformanceCounter(&counter)) {
      return SET_ERRNO_SYS(ERROR_PLATFORM_INIT, "Platform initialization failed");
    }

    // Convert to seconds and nanoseconds
    tp->tv_sec = (time_t)(counter.QuadPart / freq.QuadPart);
    tp->tv_nsec = (long)((long long)(((counter.QuadPart % freq.QuadPart) * NS_PER_SEC_INT) / freq.QuadPart));
  }

  return 0;
}

