int platform_open(const char *name, const char *pathname, int flags, ...) {
  if (!name) {
    return -1;
  }

  int mode = 0;
  if (flags & _O_CREAT) {
    va_list args;
    va_start(args, flags);
    mode = va_arg(args, int);
    va_end(args);
  }

  // Windows requires _O_BINARY for binary mode
  if (!(flags & _O_TEXT)) {
    flags |= _O_BINARY;
  }

  // Use _sopen_s (secure version) with _SH_DENYNO for compatibility
  int fd = -1;
  errno_t err = _sopen_s(&fd, pathname, flags, _SH_DENYNO, mode);
  if (err != 0) {
    return -1;
  }

  if (fd >= 0) {
    NAMED_REGISTER_FD(fd, name);
    log_dev("Opened file descriptor %d for %s at path %s", fd, name, pathname);
  }

  return fd;
}

FILE *platform_fdopen(const char *name, int fd, const char *mode) {
  if (!name) {
    return NULL;
  }

  FILE *stream = _fdopen(fd, mode);
  if (stream && fd >= 0) {
    NAMED_REGISTER_FD(fd, name);
  }
  return stream;
}

ssize_t platform_read(int fd, void *buf, size_t count) {
  // Windows _read returns int, convert to ssize_t
  return (ssize_t)_read(fd, buf, (unsigned int)count);
}

ssize_t platform_write(int fd, const void *buf, size_t count) {
  // Use Windows WriteFile API to avoid deprecated _write
  HANDLE handle = (HANDLE)_get_osfhandle(fd);
  if (handle == INVALID_HANDLE_VALUE) {
    errno = EBADF;
    return -1;
  }

  DWORD bytes_written = 0;
  if (WriteFile(handle, buf, (DWORD)count, &bytes_written, NULL)) {
    return (ssize_t)bytes_written;
  }

  // Callers use errno to distinguish transient failures from a closed output.
  switch (GetLastError()) {
  case ERROR_BROKEN_PIPE:
  case ERROR_NO_DATA:
    errno = EPIPE;
    break;
  case ERROR_INVALID_HANDLE:
    errno = EBADF;
    break;
  case ERROR_DISK_FULL:
    errno = ENOSPC;
    break;
  case ERROR_ACCESS_DENIED:
    errno = EACCES;
    break;
  default:
    errno = EIO;
    break;
  }
  return -1;
}

