  FILE *file = NULL;
  errno_t err = fopen_s(&file, filename, mode);
  if (err != 0 || file == NULL) {
    return NULL;
  }

  int fd = _fileno(file);
  if (fd >= 0) {
    NAMED_REGISTER_FD(fd, name);
  }

  return file;
}

