asciichat_error_t platform_memcpy(void *dest, size_t dest_size, const void *src, size_t count) {
  // Validate parameters
  if (!dest || !src) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid pointers for memcpy");
  }

  if (count > dest_size) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Buffer overflow protection: count=%zu > dest_size=%zu", count, dest_size);
  }

#ifdef __STDC_LIB_EXT1__
  // Use memcpy_s if available (C11 Annex K)
  errno_t err = memcpy_s(dest, dest_size, src, count);
  if (err != 0) {
    return SET_ERRNO_SYS(ERROR_PLATFORM_INIT, "Platform initialization failed");
  }
  return ASCIICHAT_OK;
#else
  // Fallback to standard memcpy with bounds already checked
  memcpy(dest, src, count);
  return ASCIICHAT_OK;
#endif
}

asciichat_error_t platform_memset(void *dest, size_t dest_size, int ch, size_t count) {
  // Validate parameters
  if (!dest) {
    SET_ERRNO(ERROR_INVALID_PARAM, "Invalid pointer for memset");
    return ERROR_INVALID_PARAM;
  }

  if (count > dest_size) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Buffer overflow protection: count=%zu > dest_size=%zu", count, dest_size);
  }

#ifdef __STDC_LIB_EXT1__
  // Use memset_s if available (C11 Annex K)
  errno_t err = memset_s(dest, dest_size, ch, count);
  return err; // Returns 0 on success, non-zero on error
#else
  // Fallback to standard memset with bounds already checked
  memset(dest, ch, count);
  return 0; // Success
#endif
}

asciichat_error_t platform_memmove(void *dest, size_t dest_size, const void *src, size_t count) {
  // Validate parameters
  if (!dest || !src) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid pointers for memmove");
  }

  if (count > dest_size) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Buffer overflow protection: count=%zu > dest_size=%zu", count, dest_size);
  }

#ifdef __STDC_LIB_EXT1__
  // Use memmove_s if available (C11 Annex K)
  errno_t err = memmove_s(dest, dest_size, src, count);
  if (err != 0) {

    return SET_ERRNO_SYS(ERROR_BUFFER_OVERFLOW, "memmove_s failed");
  }
  return ASCIICHAT_OK;
#else
  // Fallback to standard memmove with bounds already checked
  memmove(dest, src, count);
  return ASCIICHAT_OK;
#endif
}

asciichat_error_t platform_resolve_hostname_to_ipv4(const char *hostname, char *ipv4_out, size_t ipv4_out_size) {
  if (!hostname || !ipv4_out || ipv4_out_size == 0) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters for hostname resolution");
  }

  // Initialize Winsock on Windows (required for getaddrinfo)
  WSADATA wsaData;
  if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
    return SET_ERRNO_SYS(ERROR_NETWORK, "Network operation failed");
  }

  struct addrinfo hints, *result = NULL;
  memset(&hints, 0, sizeof(hints));
  hints.ai_family = AF_INET;       // IPv4 only
  hints.ai_socktype = SOCK_STREAM; // TCP
  hints.ai_flags = 0;
  hints.ai_protocol = 0;

  int ret = getaddrinfo(hostname, NULL, &hints, &result);
  if (ret != 0) {
    WSACleanup();
    return SET_ERRNO_SYS(ERROR_NETWORK, "Network operation failed");
  }

  if (!result) {
    freeaddrinfo(result);
    WSACleanup();
    return SET_ERRNO(ERROR_NETWORK, "No address found for hostname: %s", hostname);
  }

  // Extract IPv4 address from first result
  asciichat_error_t format_result = format_ip_address(result->ai_family, result->ai_addr, ipv4_out, ipv4_out_size);
  freeaddrinfo(result);
  WSACleanup();

  if (format_result != ASCIICHAT_OK) {
    return format_result;
  }

  return ASCIICHAT_OK;
}

asciichat_error_t platform_load_system_ca_certs(char **pem_data_out, size_t *pem_size_out) {
  if (!pem_data_out || !pem_size_out) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid parameters for CA cert loading");
  }

  // Open the Windows system root certificate store
  HCERTSTORE hStore = CertOpenSystemStoreA(0, "ROOT");
  if (!hStore) {
    return SET_ERRNO_SYS(ERROR_CRYPTO, "Crypto operation failed");
  }

  // Allocate buffer for PEM data (start with 256KB, can grow)
  size_t pem_capacity = 256 * 1024;
  size_t pem_size = 0;
  char *pem_data = SAFE_MALLOC(pem_capacity, char *);
  if (!pem_data) {
    CertCloseStore(hStore, 0);
    return SET_ERRNO(ERROR_MEMORY, "Failed to allocate memory for CA certificates");
  }

  // Enumerate all certificates in the store
  PCCERT_CONTEXT pCertContext = NULL;
  while ((pCertContext = CertEnumCertificatesInStore(hStore, pCertContext)) != NULL) {
    // Convert DER to PEM format (Base64 with headers)
    // Certificate is in pCertContext->pbCertEncoded (DER format)

    // Calculate Base64 size needed (4/3 of input + padding)
    DWORD base64_size = 0;
    if (!CryptBinaryToStringA(pCertContext->pbCertEncoded, pCertContext->cbCertEncoded, CRYPT_STRING_BASE64HEADER, NULL,
                              &base64_size)) {
      continue; // Skip this cert
    }

    // Ensure we have enough space in PEM buffer
    while (pem_size + base64_size + 100 > pem_capacity) {
      pem_capacity *= 2;
      char *new_pem_data = SAFE_REALLOC(pem_data, pem_capacity, char *);
      if (!new_pem_data) {
        SAFE_FREE(pem_data);
        CertFreeCertificateContext(pCertContext);
        CertCloseStore(hStore, 0);
        return SET_ERRNO(ERROR_CRYPTO, "Failed to convert certificate to PEM format");
      }
      pem_data = new_pem_data;
    }

    // Convert DER to Base64 with "-----BEGIN CERTIFICATE-----" header
    DWORD written = (DWORD)(pem_capacity - pem_size);
    if (CryptBinaryToStringA(pCertContext->pbCertEncoded, pCertContext->cbCertEncoded, CRYPT_STRING_BASE64HEADER,
                             pem_data + pem_size, &written)) {
      pem_size += written - 1; // -1 to exclude null terminator added by CryptBinaryToStringA

      // Add newline separator between certificates for proper PEM parsing
      // CryptBinaryToStringA might not always include a trailing newline
      if (pem_size > 0 && pem_data[pem_size - 1] != '\n') {
        pem_data[pem_size++] = '\n';
      }
    }
  }

  CertCloseStore(hStore, 0);

  if (pem_size == 0) {
    SAFE_FREE(pem_data);
    return SET_ERRNO(ERROR_CRYPTO, "No CA certificates found in system store");
  }

  // Null-terminate the PEM data
  pem_data[pem_size] = '\0';

  *pem_data_out = pem_data;
  *pem_size_out = pem_size;
  return 0;
}

bool platform_get_temp_dir(char *temp_dir, size_t path_size) {
  if (temp_dir == NULL || path_size == 0) {
    return false;
  }

  // Try multiple temp directory candidates
  const char *candidates[] = {SAFE_GETENV("TEMP"), SAFE_GETENV("TMP"), "C:\\Temp", NULL};

  for (int i = 0; candidates[i] != NULL; i++) {
    const char *temp = candidates[i];
    if (temp == NULL) {
      continue;
    }

    // Check if buffer is large enough
    if (strlen(temp) >= path_size) {
      continue;
    }

    // Verify the directory exists and is writable
    // _access with mode 06 checks for read+write permission
    if (_access(temp, 06) == 0) {
      // Directory exists and is writable
      SAFE_STRNCPY(temp_dir, temp, path_size);
      return true;
    }
  }

  // No writable temp directory found
  return false;
}

bool platform_get_cwd(char *cwd, size_t path_size) {
  if (!cwd || path_size == 0) {
    return false;
  }

  DWORD len = GetCurrentDirectoryA((DWORD)path_size, cwd);
  if (len == 0 || len >= path_size) {
    return false;
  }

  return true;
}

int platform_access(const char *path, int mode) {
  if (!path) {
    return -1;
  }

  // Windows _access uses the same mode values as our platform-independent modes:
  // 0 = exists, 2 = write, 4 = read, 6 = read+write
  return _access(path, mode);
}

platform_stderr_redirect_handle_t platform_stderr_redirect_to_null(void) {
  platform_stderr_redirect_handle_t handle = {.original_fd = -1, .devnull_fd = -1};

  handle.original_fd = _dup(STDERR_FILENO);
  if (handle.original_fd < 0)
    return handle;

  if (_sopen_s(&handle.devnull_fd, "NUL", _O_WRONLY, _SH_DENYNO, 0) != 0) {
    handle.devnull_fd = -1;
  }
  if (handle.devnull_fd < 0) {
    _close(handle.original_fd);
    handle.original_fd = -1;
    return handle;
  }

  if (_dup2(handle.devnull_fd, STDERR_FILENO) < 0) {
    _close(handle.original_fd);
    _close(handle.devnull_fd);
    handle.original_fd = -1;
    handle.devnull_fd = -1;
  }

  return handle;
}

void platform_stderr_restore(platform_stderr_redirect_handle_t handle) {
  if (handle.original_fd >= 0) {
    _dup2(handle.original_fd, STDERR_FILENO);
    _close(handle.original_fd);
  }
  if (handle.devnull_fd >= 0) {
    _close(handle.devnull_fd);
  }
}

void platform_stdio_redirect_to_null_permanent(void) {
  int devnull = -1;
  if (_sopen_s(&devnull, "NUL", _O_WRONLY, _SH_DENYNO, 0) == 0 && devnull >= 0) {
    _dup2(devnull, STDOUT_FILENO);
    _dup2(devnull, STDERR_FILENO);
    _close(devnull);
  }
}

platform_stderr_redirect_handle_t platform_stdout_stderr_redirect_to_null(void) {
  platform_stderr_redirect_handle_t handle = {.original_fd = -1, .devnull_fd = -1};

  int saved_stdout = _dup(STDOUT_FILENO);
  int saved_stderr = _dup(STDERR_FILENO);
  if (saved_stdout < 0 || saved_stderr < 0) {
    if (saved_stdout >= 0)
      _close(saved_stdout);
    if (saved_stderr >= 0)
      _close(saved_stderr);
    return handle;
  }

  int devnull = -1;
  if (_sopen_s(&devnull, "NUL", _O_WRONLY, _SH_DENYNO, 0) != 0 || devnull < 0) {
    _close(saved_stdout);
    _close(saved_stderr);
    return handle;
  }

  if (_dup2(devnull, STDOUT_FILENO) < 0 || _dup2(devnull, STDERR_FILENO) < 0) {
    _close(devnull);
    _close(saved_stdout);
    _close(saved_stderr);
    return handle;
  }

  _close(devnull);
  handle.original_fd = saved_stdout;
  handle.devnull_fd = saved_stderr;
  return handle;
}

void platform_stdout_stderr_restore(platform_stderr_redirect_handle_t handle) {
  if (handle.original_fd >= 0) {
    _dup2(handle.original_fd, STDOUT_FILENO);
    _close(handle.original_fd);
  }
  if (handle.devnull_fd >= 0) {
    _dup2(handle.devnull_fd, STDERR_FILENO);
    _close(handle.devnull_fd);
  }
}

void platform_force_exit(int exit_code) {
  ExitProcess((UINT)exit_code);
}

asciichat_error_t platform_register_signal_handlers(const platform_signal_handler_t *handlers, int count) {
  if (!handlers || count <= 0) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Invalid handlers or count");
  }

  for (int i = 0; i < count; i++) {
    int sig = handlers[i].sig;
    // Windows CRT supports signal() for SIGINT, SIGTERM, SIGABRT, SIGFPE, SIGSEGV, SIGILL
    if (sig == SIGINT || sig == SIGTERM || sig == SIGABRT) {
      signal(sig, handlers[i].handler);
      log_debug("Registered signal handler for signal %d", sig);
    } else {
      // SIGPIPE, SIGWINCH, SIGUSR1/2 don't exist on Windows - silently skip
      log_debug("Signal %d not available on Windows, skipping", sig);
    }
  }

  return ASCIICHAT_OK;
}

asciichat_error_t platform_request_timer_precision(int precision) {
  /* timeBeginPeriod requests coarse timer precision on Windows */
  MMRESULT result = timeBeginPeriod((UINT)precision);
  if (result != TIMERR_NOERROR) {
    return SET_ERRNO(ERROR_GENERAL, "timeBeginPeriod() failed with error %u", result);
  }
  return ASCIICHAT_OK;
}

asciichat_error_t platform_restore_timer_resolution(void) {
  /* timeEndPeriod restores default timer resolution on Windows */
  MMRESULT result = timeEndPeriod(1);
  if (result != TIMERR_NOERROR) {
    return SET_ERRNO(ERROR_GENERAL, "timeEndPeriod() failed with error %u", result);
  }
  return ASCIICHAT_OK;
}

int get_binary_file_address_offsets(const void *addr, platform_binary_match_t *matches, int max_matches) {
  HANDLE proc = GetCurrentProcess();
  HMODULE modules[512];
  DWORD needed = 0;
  int count = 0;
  uintptr_t addr_int = (uintptr_t)addr;

  if (!EnumProcessModules(proc, modules, sizeof(modules), &needed)) {
    log_debug("EnumProcessModules failed");
    return 0;
  }

  DWORD module_count = needed / sizeof(HMODULE);
  if (module_count > 512) {
    module_count = 512; // Cap at our array size
  }

  for (DWORD i = 0; i < module_count && count < max_matches; i++) {
    MODULEINFO mod_info;
    char mod_path[PLATFORM_MAX_PATH_LENGTH];

    if (!GetModuleInformation(proc, modules[i], &mod_info, sizeof(mod_info))) {
      continue;
    }

    if (!GetModuleFileNameA(modules[i], mod_path, sizeof(mod_path))) {
      continue;
    }

    // Check if address falls within this module
    uintptr_t base = (uintptr_t)mod_info.lpBaseOfDll;
    uintptr_t end = base + mod_info.SizeOfImage;

    if (addr_int >= base && addr_int < end) {
      strncpy_s(matches[count].path, PLATFORM_MAX_PATH_LENGTH, mod_path, PLATFORM_MAX_PATH_LENGTH - 1);
      matches[count].path[PLATFORM_MAX_PATH_LENGTH - 1] = '\0';
      matches[count].file_offset = addr_int - base;

#ifndef NDEBUG
      log_debug("[Windows EnumProcessModules] addr=%p matches %s (offset=%lx, base=%p)", addr, mod_path,
                matches[count].file_offset, (void *)base);
#endif
      count++;
    }
  }

  return count;
}

int platform_execute_subprocess(const char *executable, const char **argv, char *output_buffer, size_t output_size) {
  if (!executable || !argv) {
    log_error("platform_execute_subprocess: invalid parameters");
    return -1;
  }

  // Build command line from argv array
  // Windows CreateProcess needs a single command line string.
  // Arguments with spaces need quoting.
  size_t cmd_len = 0;
  for (int i = 0; argv[i] != NULL; i++) {
    cmd_len += strlen(argv[i]) + 3; // +3 for quotes and space
  }

  if (cmd_len == 0) {
    log_error("Empty command line");
    return -1;
  }

  char *command_line = SAFE_MALLOC(cmd_len + 1, char *);
  if (!command_line) {
    return -1;
  }

  // Build command line with quoting for arguments containing spaces
  size_t pos = 0;
  for (int i = 0; argv[i] != NULL; i++) {
    if (i > 0) {
      command_line[pos++] = ' ';
    }
    bool needs_quotes = (strchr(argv[i], ' ') != NULL || strchr(argv[i], '\t') != NULL);
    int result;
    if (needs_quotes) {
      result = SAFE_SNPRINTF(command_line + pos, cmd_len + 1 - pos, "\"%s\"", argv[i]);
    } else {
      result = SAFE_SNPRINTF(command_line + pos, cmd_len + 1 - pos, "%s", argv[i]);
    }
    if (result < 0) {
      log_error("Failed to build command line");
      SAFE_FREE(command_line);
      return -1;
    }
    pos += (size_t)result;
  }

  // Set up pipes for output capture if requested
  HANDLE stdout_read = NULL;
  HANDLE stdout_write = NULL;
  bool capture_output = (output_buffer && output_size > 0);

  if (capture_output) {
    SECURITY_ATTRIBUTES sa = {
        .nLength = sizeof(SECURITY_ATTRIBUTES), .bInheritHandle = TRUE, .lpSecurityDescriptor = NULL};
    if (!CreatePipe(&stdout_read, &stdout_write, &sa, 0)) {
      log_error("Failed to create pipe for output capture: error %lu", GetLastError());
      SAFE_FREE(command_line);
      return -1;
    }
    // The read end should not be inherited by the child
    SetHandleInformation(stdout_read, HANDLE_FLAG_INHERIT, 0);
  }

  // Create process
  STARTUPINFOA startup_info;
  PROCESS_INFORMATION process_info;
  ZeroMemory(&startup_info, sizeof(startup_info));
  startup_info.cb = sizeof(startup_info);
  ZeroMemory(&process_info, sizeof(process_info));

  if (capture_output) {
    startup_info.hStdOutput = stdout_write;
    startup_info.hStdError = stdout_write;
    startup_info.dwFlags |= STARTF_USESTDHANDLES;
  }

  BOOL success = CreateProcessA(NULL,           // lpApplicationName - NULL so PATH is searched
                                command_line,   // lpCommandLine - full command line
                                NULL,           // lpProcessAttributes
                                NULL,           // lpThreadAttributes
                                capture_output, // bInheritHandles - only when capturing output
                                0,              // dwCreationFlags
                                NULL,           // lpEnvironment
                                NULL,           // lpCurrentDirectory
                                &startup_info,  // lpStartupInfo
                                &process_info   // lpProcessInformation
  );

  SAFE_FREE(command_line);

  if (!success) {
    DWORD error = GetLastError();
    log_error("Failed to execute %s: error code %lu", executable, error);
    if (stdout_read)
      CloseHandle(stdout_read);
    if (stdout_write)
      CloseHandle(stdout_write);
    return -1;
  }

  // Close the write end of the pipe in the parent so ReadFile can detect EOF
  if (stdout_write) {
    CloseHandle(stdout_write);
    stdout_write = NULL;
  }

  // Read child stdout if capturing
  if (capture_output && stdout_read) {
    size_t total_read = 0;
    DWORD bytes_read = 0;
    while (total_read < output_size - 1) {
      BOOL ok =
          ReadFile(stdout_read, output_buffer + total_read, (DWORD)(output_size - 1 - total_read), &bytes_read, NULL);
      if (!ok || bytes_read == 0)
        break;
      total_read += bytes_read;
    }
    output_buffer[total_read] = '\0';
    CloseHandle(stdout_read);
    stdout_read = NULL;
  }

  // Wait for process to complete
  DWORD wait_result = WaitForSingleObject(process_info.hProcess, INFINITE);
  DWORD exit_code = 0;
  BOOL got_code = GetExitCodeProcess(process_info.hProcess, &exit_code);

  // Clean up handles
  CloseHandle(process_info.hProcess);
  CloseHandle(process_info.hThread);
  if (stdout_read)
    CloseHandle(stdout_read);

  if (wait_result != WAIT_OBJECT_0) {
    log_error("Failed to wait for process: error code %lu", GetLastError());
    return -1;
  }

  if (!got_code) {
    log_error("Failed to get process exit code: error code %lu", GetLastError());
    return -1;
  }

  return (int)exit_code;
}

