int platform_isatty(int fd) {
  if (!_isatty(fd)) {
    return 0;
  }

  intptr_t os_handle = _get_osfhandle(fd);
  if (os_handle == -1) {
    return 0;
  }

  DWORD console_mode = 0;
  return GetConsoleMode((HANDLE)os_handle, &console_mode) != 0;
}

const char *platform_ttyname(int fd) {
  // Windows doesn't have ttyname, return "CON" for console
  if (platform_isatty(fd)) {
    return "CON";
  }
  return NULL;
}

static void *resize_detection_thread(void *arg) {
  (void)arg;
  HANDLE hConsoleInput = GetStdHandle(STD_INPUT_HANDLE);
  if (hConsoleInput == INVALID_HANDLE_VALUE) {
    log_error("Failed to get console input handle for resize detection");
    return NULL;
  }

  // Enable window input events
  DWORD console_mode;
  if (!GetConsoleMode(hConsoleInput, &console_mode)) {
    log_error("Failed to get console mode for resize detection");
    return NULL;
  }

  // Add WINDOW_INPUT flag to enable window buffer size events
  console_mode |= ENABLE_WINDOW_INPUT;
  if (!SetConsoleMode(hConsoleInput, console_mode)) {
    log_error("Failed to enable window input events for resize detection");
    return NULL;
  }

  log_dev("Windows console resize detection thread started");

  // Store last known size to detect actual changes
  CONSOLE_SCREEN_BUFFER_INFO last_csbi = {0};
  if (GetConsoleScreenBufferInfo(GetStdHandle(STD_OUTPUT_HANDLE), &last_csbi)) {
    log_dev("Initial console size: %dx%d", last_csbi.srWindow.Right - last_csbi.srWindow.Left + 1,
            last_csbi.srWindow.Bottom - last_csbi.srWindow.Top + 1);
  }

  while (!atomic_load_bool(&g_resize_thread_should_exit)) {
    INPUT_RECORD input_record;
    DWORD events_read = 0;

    // Wait for console input with timeout (100ms)
    DWORD wait_result = WaitForSingleObject(hConsoleInput, 100);
    if (wait_result == WAIT_TIMEOUT) {
      continue;
    }
    if (wait_result != WAIT_OBJECT_0) {
      continue; // Error or unexpected result
    }

    // Read console input events
    if (!ReadConsoleInput(hConsoleInput, &input_record, 1, &events_read)) {
      continue;
    }

    if (events_read == 0) {
      continue;
    }

    // Check for window buffer size event
    if (input_record.EventType == WINDOW_BUFFER_SIZE_EVENT) {
      CONSOLE_SCREEN_BUFFER_INFO csbi;
      HANDLE hConsoleOutput = GetStdHandle(STD_OUTPUT_HANDLE);

      if (GetConsoleScreenBufferInfo(hConsoleOutput, &csbi)) {
        int new_cols = csbi.srWindow.Right - csbi.srWindow.Left + 1;
        int new_rows = csbi.srWindow.Bottom - csbi.srWindow.Top + 1;

        // Only trigger callback if size actually changed
        int old_cols = last_csbi.srWindow.Right - last_csbi.srWindow.Left + 1;
        int old_rows = last_csbi.srWindow.Bottom - last_csbi.srWindow.Top + 1;

        if (new_cols != old_cols || new_rows != old_rows) {
          log_dev("Console resized: %dx%d -> %dx%d", old_cols, old_rows, new_cols, new_rows);

          // Update last known size
          last_csbi = csbi;

          // Trigger callback if registered
          if (g_resize_callback != NULL) {
            g_resize_callback(new_cols, new_rows);
          }
        }
      }
    }
  }

  log_dev("Windows console resize detection thread exiting");
  return NULL;
}

int terminal_start_resize_detection(terminal_resize_callback_t callback) {
  if (atomic_load_bool(&g_resize_detection_active)) {
    log_warn("Resize detection already active");
    return 0; // Already running
  }

  if (callback == NULL) {
    log_error("Cannot start resize detection with NULL callback");
    return -1;
  }

  g_resize_callback = callback;
  atomic_store_bool(&g_resize_thread_should_exit, false);

  if (asciichat_thread_create(&g_resize_thread, "resize_detect", resize_detection_thread, NULL) != 0) {
    log_error("Failed to create resize detection thread");
    g_resize_callback = NULL;
    return -1;
  }

  atomic_store_bool(&g_resize_detection_active, true);
  log_info("Windows console resize detection started");
  return 0;
}

void terminal_stop_resize_detection(void) {
  if (!atomic_load_bool(&g_resize_detection_active)) {
    return; // Not running
  }

  atomic_store_bool(&g_resize_thread_should_exit, true);
  // Wait for thread to exit
  asciichat_thread_join(&g_resize_thread, NULL);
  atomic_store_bool(&g_resize_detection_active, false);
  g_resize_callback = NULL;
}

asciichat_error_t terminal_get_size_fd(int fd, terminal_size_t *size) {
  if (!size)
    return SET_ERRNO(ERROR_INVALID_PARAM, "Terminal size output is NULL");
  *size = (terminal_size_t){0};
  CONSOLE_SCREEN_BUFFER_INFO info;
  HANDLE handle = (HANDLE)_get_osfhandle(fd);
  if (!GetConsoleScreenBufferInfo(handle, &info))
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Cannot query terminal descriptor %d", fd);
  size->cols = info.srWindow.Right - info.srWindow.Left + 1;
  size->rows = info.srWindow.Bottom - info.srWindow.Top + 1;
  return ASCIICHAT_OK;
}

asciichat_error_t terminal_get_size(terminal_size_t *size) {
  CONSOLE_SCREEN_BUFFER_INFO csbi;
  HANDLE h = GetStdHandle(STD_OUTPUT_HANDLE);

  if (h == INVALID_HANDLE_VALUE) {
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");
  }

  if (GetConsoleScreenBufferInfo(h, &csbi)) {
    size->cols = csbi.srWindow.Right - csbi.srWindow.Left + 1;
    size->rows = csbi.srWindow.Bottom - csbi.srWindow.Top + 1;
    return ASCIICHAT_OK;
  }

  return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");
}

const char *get_tty_path(void) {
  return "CON";
}

asciichat_error_t terminal_set_raw_mode(bool enable) {
  HANDLE hStdin = GetStdHandle(STD_INPUT_HANDLE);
  if (hStdin == INVALID_HANDLE_VALUE) {
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");
  }

  DWORD mode;
  if (!GetConsoleMode(hStdin, &mode)) {
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");
  }

  if (enable) {
    mode &= ~((DWORD)ENABLE_LINE_INPUT | (DWORD)ENABLE_ECHO_INPUT);
  } else {
    mode |= (DWORD)((DWORD)ENABLE_LINE_INPUT | (DWORD)ENABLE_ECHO_INPUT);
  }

  if (!SetConsoleMode(hStdin, mode)) {
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");
  }
  return 0;
}

asciichat_error_t terminal_set_echo(bool enable) {
  HANDLE hStdin = GetStdHandle(STD_INPUT_HANDLE);
  if (hStdin == INVALID_HANDLE_VALUE) {
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");
  }

  DWORD mode;
  if (!GetConsoleMode(hStdin, &mode)) {
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");
  }

  if (enable) {
    // Windows requires line input whenever echo is enabled.
    mode |= (DWORD)(ENABLE_LINE_INPUT | ENABLE_ECHO_INPUT);
  } else {
    mode &= ~(DWORD)ENABLE_ECHO_INPUT;
  }

  if (!SetConsoleMode(hStdin, mode)) {
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");
  }
  return 0;
}

static void _init_terminal_cache(void) {
  if (g_terminal_cache.initialized) {
    return;
  }

  // Detect UTF-8 support
  g_terminal_cache.utf8_support = 0;

  // Check if console output code page is UTF-8 (65001)
  UINT cp = GetConsoleOutputCP();
  if (cp == 65001) {
    g_terminal_cache.utf8_support = 1;
  } else {
    // Check for Windows Terminal via environment variable
    const char *wt_session = SAFE_GETENV("WT_SESSION");
    if (wt_session != NULL) {
      g_terminal_cache.utf8_support = 1;
    } else {
      // Check for ConEmu
      const char *conemu = SAFE_GETENV("ConEmuPID");
      if (conemu != NULL) {
        g_terminal_cache.utf8_support = 1;
      } else {
        // Check for newer Windows Console Host with VT support
        HANDLE hOut = GetStdHandle(STD_OUTPUT_HANDLE);
        if (hOut != INVALID_HANDLE_VALUE) {
          DWORD mode;
          if (GetConsoleMode(hOut, &mode)) {
            // ENABLE_VIRTUAL_TERMINAL_PROCESSING (0x0004) indicates modern console
            if (mode & 0x0004) {
              g_terminal_cache.utf8_support = 1;
            }
          }
        }
      }
    }
  }

  // Windows 10+ always supports colors and Unicode
  g_terminal_cache.color_support = 1;
  g_terminal_cache.unicode_support = 1;

  g_terminal_cache.initialized = 1;
}

bool terminal_supports_utf8(void) {
  _init_terminal_cache();
  return g_terminal_cache.utf8_support;
}

bool terminal_supports_color(void) {
  _init_terminal_cache();
  return g_terminal_cache.color_support;
}

bool terminal_supports_unicode(void) {
  _init_terminal_cache();
  return g_terminal_cache.unicode_support;
}

asciichat_error_t terminal_clear_screen(void) {
  system("cls");
  return ASCIICHAT_OK;
}

asciichat_error_t terminal_move_cursor(int row, int col) {
  HANDLE hConsole = GetStdHandle(STD_OUTPUT_HANDLE);
  if (hConsole == INVALID_HANDLE_VALUE)
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");

  COORD coord;
  coord.X = (SHORT)col;
  coord.Y = (SHORT)row;

  return SetConsoleCursorPosition(hConsole, coord) ? 0 : -1;
}

asciichat_error_t terminal_move_cursor_relative(int offset) {
  if (offset == 0) {
    return ASCIICHAT_OK;
  }

  HANDLE hConsole = GetStdHandle(STD_OUTPUT_HANDLE);
  if (hConsole == INVALID_HANDLE_VALUE)
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");

  // Get current cursor position
  CONSOLE_SCREEN_BUFFER_INFO csbi;
  if (!GetConsoleScreenBufferInfo(hConsole, &csbi)) {
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Failed to get cursor position");
  }

  // Calculate new position
  SHORT newX = csbi.dwCursorPosition.X + (SHORT)offset;

  // Clamp to valid range (0 to buffer width - 1)
  if (newX < 0) {
    newX = 0;
  } else if (newX >= csbi.dwSize.X) {
    newX = csbi.dwSize.X - 1;
  }

  // Move to new position
  COORD newCoord;
  newCoord.X = newX;
  newCoord.Y = csbi.dwCursorPosition.Y;

  return SetConsoleCursorPosition(hConsole, newCoord) ? ASCIICHAT_OK
                                                      : SET_ERRNO_SYS(ERROR_TERMINAL, "Failed to move cursor");
}

void terminal_enable_ansi(void) {
  // Enable ANSI escape sequences on Windows 10+
  HANDLE hOut = GetStdHandle(STD_OUTPUT_HANDLE);
  if (hOut != INVALID_HANDLE_VALUE) {
    DWORD mode;
    if (GetConsoleMode(hOut, &mode)) {
      mode |= 0x0004; // ENABLE_VIRTUAL_TERMINAL_PROCESSING
      SetConsoleMode(hOut, mode);
    }
  }
}

asciichat_error_t terminal_set_buffering(bool line_buffered) {
  // Windows console doesn't have direct line buffering control
  // This is typically handled at the C runtime level
  if (line_buffered) {
    (void)setvbuf(stdout, NULL, _IOLBF, 0);
  } else {
    (void)setvbuf(stdout, NULL, _IONBF, 0);
  }
  return ASCIICHAT_OK;
}

asciichat_error_t terminal_flush(int fd) {
  (void)fd; // Windows console APIs operate on stdout, not arbitrary file descriptors
  return fflush(stdout);
}

asciichat_error_t terminal_get_cursor_position(int *row, int *col) {
  CONSOLE_SCREEN_BUFFER_INFO csbi;
  HANDLE hOut = GetStdHandle(STD_OUTPUT_HANDLE);

  if (hOut == INVALID_HANDLE_VALUE) {
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");
  }

  if (!GetConsoleScreenBufferInfo(hOut, &csbi)) {
    return SET_ERRNO_SYS(ERROR_TERMINAL, "Terminal operation failed");
  }

  if (row)
    *row = csbi.dwCursorPosition.Y + 1; // Convert to 1-based
  if (col)
    *col = csbi.dwCursorPosition.X + 1; // Convert to 1-based

  return 0;
}

asciichat_error_t terminal_save_cursor(void) {
  // Try ANSI escape sequence first (Windows 10+)
  printf("\033[s");
  (void)fflush(stdout);
  return ASCIICHAT_OK;
}

asciichat_error_t terminal_restore_cursor(void) {
  // Try ANSI escape sequence first (Windows 10+)
  printf("\033[u");
  (void)fflush(stdout);
  return 0;
}

asciichat_error_t terminal_set_title(const char *title) {
  if (!title) {
    return SET_ERRNO(ERROR_INVALID_PARAM, "Terminal title must not be NULL");
  }
  if (SetConsoleTitleA(title)) {
    return ASCIICHAT_OK;
  }
  return SET_ERRNO(ERROR_TERMINAL, "Failed to set console title (Windows error %lu)", (unsigned long)GetLastError());
}

asciichat_error_t terminal_ring_bell(void) {
  // Use Windows beep
  Beep(800, 200); // 800Hz for 200ms
  return ASCIICHAT_OK;
}

static bool windows_try_enable_vt_processing(HANDLE hOut) {
  if (hOut == INVALID_HANDLE_VALUE) {
    return false;
  }

  DWORD mode = 0;
  if (!GetConsoleMode(hOut, &mode)) {
    return false;
  }

  // Try to enable ANSI VT processing
  return SetConsoleMode(hOut, mode | ENABLE_VIRTUAL_TERMINAL_PROCESSING);
}

asciichat_error_t terminal_cursor_hide(void) {
  // Only operate in interactive mode
  if (!terminal_is_interactive()) {
    return ASCIICHAT_OK;
  }

  HANDLE hOut = GetStdHandle(STD_OUTPUT_HANDLE);

  // Try VT processing first (Windows 10.1607+)
  if (windows_try_enable_vt_processing(hOut)) {
    printf("\033[?25l");
    (void)fflush(stdout);
    return ASCIICHAT_OK;
  }

  // Fallback to console API for older Windows
  CONSOLE_CURSOR_INFO cursorInfo;
  if (hOut != INVALID_HANDLE_VALUE && GetConsoleCursorInfo(hOut, &cursorInfo)) {
    cursorInfo.bVisible = FALSE;
    if (SetConsoleCursorInfo(hOut, &cursorInfo)) {
      return ASCIICHAT_OK;
    }
  }

  return ASCIICHAT_OK;
}

asciichat_error_t terminal_cursor_show(void) {
  // Only operate in interactive mode
  if (!terminal_is_interactive()) {
    return ASCIICHAT_OK;
  }

  HANDLE hOut = GetStdHandle(STD_OUTPUT_HANDLE);

  // Try VT processing first (Windows 10.1607+)
  if (windows_try_enable_vt_processing(hOut)) {
    printf("\033[?25h");
    (void)fflush(stdout);
    return ASCIICHAT_OK;
  }

  // Fallback to console API for older Windows
  CONSOLE_CURSOR_INFO cursorInfo;
  if (hOut != INVALID_HANDLE_VALUE && GetConsoleCursorInfo(hOut, &cursorInfo)) {
    cursorInfo.bVisible = TRUE;
    if (SetConsoleCursorInfo(hOut, &cursorInfo)) {
      return ASCIICHAT_OK;
    }
  }

  return ASCIICHAT_OK;
}

asciichat_error_t terminal_set_scroll_region(int top, int bottom) {
  // Use ANSI escape sequence (Windows 10+ with VT processing enabled)
  printf("\033[%d;%dr", top, bottom);
  (void)fflush(stdout);
  return ASCIICHAT_OK;
}

asciichat_error_t terminal_reset(int fd) {
  // Reset using ANSI escape sequence
  const char *reset_seq = "\033c"; // Full reset
  HANDLE h = (HANDLE)_get_osfhandle(fd);

  if (h != INVALID_HANDLE_VALUE) {
    DWORD written;
    WriteConsole(h, reset_seq, (DWORD)strlen(reset_seq), &written, NULL);
  } else {
    // Fall back to stdout if handle is invalid
    printf("%s", reset_seq);
    (void)fflush(stdout);
  }

  // Also reset Windows console attributes
  HANDLE hOut = GetStdHandle(STD_OUTPUT_HANDLE);
  if (hOut != INVALID_HANDLE_VALUE) {
    SetConsoleTextAttribute(hOut, FOREGROUND_RED | FOREGROUND_GREEN | FOREGROUND_BLUE);
  }

  return ASCIICHAT_OK;
}

asciichat_error_t terminal_cursor_home(int fd) {
  (void)fd; // Windows console APIs operate on stdout, not arbitrary file descriptors
  // Use ANSI escape sequence (Windows 10+ with VT processing enabled)
  if (printf("\033[H") < 0) {
    return SET_ERRNO(ERROR_TERMINAL, "Failed to clear screen");
  }
  return fflush(stdout);
}

asciichat_error_t terminal_clear_scrollback(int fd) {
  (void)fd; // Windows console APIs operate on stdout, not arbitrary file descriptors
  // Use ANSI escape sequence (Windows 10+ with VT processing enabled)
  if (printf("\033[3J") < 0) {
    return SET_ERRNO(ERROR_TERMINAL, "Failed to clear screen and scrollback");
  }
  return fflush(stdout);
}

asciichat_error_t get_terminal_size(unsigned short int *width, unsigned short int *height) {
  CONSOLE_SCREEN_BUFFER_INFO csbi;
  HANDLE console_handle = GetStdHandle(STD_OUTPUT_HANDLE);
  const char *cols_env;
  const char *lines_env;
  uint32_t env_width;
  uint32_t env_height;

  // Check if output handle is a valid console (not a redirected file/pipe)
  if (console_handle != INVALID_HANDLE_VALUE && GetFileType(console_handle) == FILE_TYPE_CHAR) {
    if (GetConsoleScreenBufferInfo(console_handle, &csbi)) {
      // Use window size, not buffer size
      *width = (unsigned short int)(csbi.srWindow.Right - csbi.srWindow.Left + 1);
      *height = (unsigned short int)(csbi.srWindow.Bottom - csbi.srWindow.Top + 1);
      log_dev("Windows terminal size from console: %ux%u", *width, *height);
      return ASCIICHAT_OK;
    }
  }

  // Output is redirected (not a console) or failed to get console info
  log_dev("Windows: output is redirected (not a console), using env or defaults");

  // Environment variable fallback
  cols_env = SAFE_GETENV("COLUMNS");
  lines_env = SAFE_GETENV("LINES");

  *width = OPT_WIDTH_DEFAULT;
  *height = OPT_HEIGHT_DEFAULT;

  if (cols_env && lines_env) {
    env_width = 0;
    env_height = 0;
    // Parse width and height with safe range validation (1 to USHRT_MAX)
    if (parse_uint32(cols_env, &env_width, 1, (uint32_t)USHRT_MAX) == ASCIICHAT_OK &&
        parse_uint32(lines_env, &env_height, 1, (uint32_t)USHRT_MAX) == ASCIICHAT_OK) {
      *width = (unsigned short int)env_width;
      *height = (unsigned short int)env_height;
      log_dev("Windows terminal size from env: %ux%u", *width, *height);
      return ASCIICHAT_OK;
    }
  }

  log_dev("Windows terminal size fallback: %ux%u (defaults)", *width, *height);
  // Don't return error - just use default size
  return ASCIICHAT_OK;
}

tty_info_t get_current_tty(void) {
  tty_info_t result = {-1, NULL, false};

  // On Windows, use CON for console output
  result.fd = platform_open("windows_console", "CON", _O_WRONLY, 0);
  if (result.fd >= 0) {
    result.path = "CON";
    result.owns_fd = true;
    log_debug("Windows TTY: CON (fd=%d)", result.fd);
    return result;
  }

  log_debug("Failed to open CON device: %s", SAFE_STRERROR(errno));
  return result; // No TTY available
}

bool is_valid_tty_path(const char *path) {
  if (!path || strlen(path) == 0) {
    return false;
  }

  // Only CON is valid on Windows
  return (_stricmp(path, "CON") == 0);
}

static terminal_color_mode_t detect_windows_color_support(void) {
  // Check if we can enable ANSI processing
  HANDLE console_handle = GetStdHandle(STD_OUTPUT_HANDLE);
  if (console_handle == INVALID_HANDLE_VALUE) {
    // Don't log here - avoid color changes during detection
    return TERM_COLOR_NONE;
  }

  DWORD console_mode = 0;
  if (!GetConsoleMode(console_handle, &console_mode)) {
    // Don't log here - avoid color changes during detection
    // Even if we can't get console mode, modern Windows terminals support ANSI colors
    // Check for Windows Terminal or other modern terminals
    const char *wt_session = SAFE_GETENV("WT_SESSION");
    const char *conemu = SAFE_GETENV("ConEmuPID");
    if (wt_session || conemu) {
      // Don't log here - avoid color changes during detection
      return TERM_COLOR_TRUECOLOR;
    }
    return TERM_COLOR_NONE;
  }

  // Try to enable ANSI escape sequence processing
  DWORD new_mode = console_mode | ENABLE_VIRTUAL_TERMINAL_PROCESSING;
  if (SetConsoleMode(console_handle, new_mode)) {
    // Success! Windows supports ANSI escapes, assume truecolor
    // Don't log here - avoid color changes during detection
    return TERM_COLOR_TRUECOLOR;
  }

  // Even if SetConsoleMode fails, modern Windows terminals still support ANSI colors
  // Check for Windows Terminal or other modern terminals
  const char *wt_session = SAFE_GETENV("WT_SESSION");
  const char *conemu = SAFE_GETENV("ConEmuPID");
  if (wt_session || conemu) {
    // Don't log here - avoid color changes during detection
    return TERM_COLOR_TRUECOLOR;
  }

  // For regular Windows console, try to detect if it's Windows 10+ (which supports ANSI)
  // This is a fallback for cases where console mode detection fails
  // Use modern Windows version detection via RtlGetVersion
  typedef LONG(WINAPI * RtlGetVersionPtr)(PRTL_OSVERSIONINFOW);
  HMODULE hMod = GetModuleHandleW(L"ntdll.dll");
  if (hMod) {
    RtlGetVersionPtr fxPtr = (RtlGetVersionPtr)GetProcAddress(hMod, "RtlGetVersion");
    if (fxPtr != NULL) {
      RTL_OSVERSIONINFOW osInfo = {0};
      osInfo.dwOSVersionInfoSize = sizeof(osInfo);
      if (fxPtr(&osInfo) == 0) {
        if (osInfo.dwMajorVersion >= 10) {
          // Don't log here - avoid color changes during detection
          return TERM_COLOR_TRUECOLOR;
        }
        // Don't log here - avoid color changes during detection
        return TERM_COLOR_16; // Fallback to 16-color for older Windows
      }
    }
  }

  // Final fallback: assume modern Windows with ANSI support
  // Don't log here - avoid color changes during detection
  return TERM_COLOR_TRUECOLOR;
}

static bool detect_windows_utf8_support(void) {
  UINT codepage = GetConsoleOutputCP();
  // Don't log here - avoid color changes during detection
  return (codepage == CP_UTF8);
}

terminal_capabilities_t detect_terminal_capabilities(void) {
  terminal_capabilities_t caps = {0};

  // Detect color support level
  caps.color_level = detect_windows_color_support();

  // Set capability flags based on color level
  switch (caps.color_level) {
  case TERM_COLOR_TRUECOLOR:
    caps.capabilities |= TERM_CAP_COLOR_TRUE;
    caps.capabilities |= TERM_CAP_COLOR_256;
    caps.capabilities |= TERM_CAP_COLOR_16;
    caps.color_count = 16777216;
    caps.detection_reliable = true;
    break;

  case TERM_COLOR_256:
    caps.capabilities |= TERM_CAP_COLOR_256;
    caps.capabilities |= TERM_CAP_COLOR_16;
    caps.color_count = 256;
    caps.detection_reliable = true;
    break;

  case TERM_COLOR_16:
    caps.capabilities |= TERM_CAP_COLOR_16;
    caps.color_count = 16;
    caps.detection_reliable = false;
    break;

  case TERM_COLOR_AUTO:
    // TERM_COLOR_AUTO should never be returned from detection - treat as NONE
    // Fall through intentionally
  case TERM_COLOR_NONE:
    caps.color_count = 0;
    caps.detection_reliable = false;
    break;
  }

  // Detect UTF-8 support
  caps.utf8_support = detect_windows_utf8_support();
  if (caps.utf8_support) {
    caps.capabilities |= TERM_CAP_UTF8;
  }

  // Background color support (assume yes if any color support)
  if (caps.color_level > TERM_COLOR_NONE) {
    caps.capabilities |= TERM_CAP_BACKGROUND;
  }

  // Store environment variables for debugging
  const char *term = SAFE_GETENV("TERM");
  const char *colorterm = SAFE_GETENV("COLORTERM");

  SAFE_STRNCPY(caps.term_type, term ? term : "windows-console", sizeof(caps.term_type) - 1);
  SAFE_STRNCPY(caps.colorterm, colorterm ? colorterm : "", sizeof(caps.colorterm) - 1);

  // Set default FPS for Windows terminals
  int fps = GET_OPTION(fps);
  if (fps > 0) {
    caps.desired_fps = (uint8_t)(fps > 144 ? 144 : fps);
  } else {
    caps.desired_fps = DEFAULT_MAX_FPS; // 60 FPS on Windows with timeBeginPeriod(1)
  }

  // Don't log here - log after colors are initialized to avoid color changes
  // The log will be done in log_redetect_terminal_capabilities() after detection

  return caps;
}

const char *terminal_color_level_name(terminal_color_mode_t level) {
  switch (level) {
  case TERM_COLOR_NONE:
    return "monochrome";
  case TERM_COLOR_16:
    return "16-color";
  case TERM_COLOR_256:
    return "256-color";
  case TERM_COLOR_TRUECOLOR:
    return "truecolor";
  default:
    return "unknown";
  }
}

const char *terminal_capabilities_summary(const terminal_capabilities_t *caps) {
  static char summary[256];

  safe_snprintf(summary, sizeof(summary), "%s (%d colors), UTF-8: %s, TERM: %s, COLORTERM: %s",
                terminal_color_level_name(caps->color_level), caps->color_count,
                (caps->capabilities & TERM_CAP_UTF8) ? "yes" : "no", caps->term_type, caps->colorterm);

  return summary;
}

void test_terminal_output_modes(void) {
  printf("Testing Windows terminal output modes:\n");

  // Test basic ANSI colors (16-color)
  printf("  16-color: ");
  for (int i = 30; i <= 37; i++) {
    printf("\033[%dm█\033[0m", i);
  }
  printf("\n");

  // Test 256-color mode
  printf("  256-color: ");
  for (int i = 0; i < 16; i++) {
    printf("\033[38;5;%dm█\033[0m", i);
  }
  printf("\n");

  // Test truecolor mode
  printf("  Truecolor: ");
  for (int i = 0; i < 16; i++) {
    int r = (i * 255) / 15;
    printf("\033[38;2;%d;0;0m█\033[0m", r);
  }
  printf("\n");

  // Test Unicode characters
  printf("  Unicode: ");
  printf("░▒▓\n");
}

terminal_capabilities_t apply_color_mode_override(terminal_capabilities_t caps) {
#ifndef NDEBUG
  // In debug builds, force no-color mode for Claude Code (LLM doesn't need colors, saves tokens)
  // However, respect --color=true which explicitly forces colors ON
  if (GET_OPTION(color_mode) == COLOR_MODE_AUTO && platform_getenv("CLAUDECODE") &&
      GET_OPTION(color) != COLOR_SETTING_TRUE) {
    log_dev("CLAUDECODE detected: forcing no color mode");
    caps.color_level = TERM_COLOR_NONE;
    caps.capabilities &= ~((uint32_t)TERM_CAP_COLOR_16 | (uint32_t)TERM_CAP_COLOR_256 | (uint32_t)TERM_CAP_COLOR_TRUE);
    caps.color_count = 0;
    return caps;
  }
#endif

  // Handle color mode overrides
  switch (GET_OPTION(color_mode)) {
  case COLOR_MODE_AUTO:
    // Use detected capabilities as-is
    break;

  case COLOR_MODE_NONE:
    caps.color_level = TERM_COLOR_NONE;
    caps.color_count = 2;
    caps.capabilities &= ~((uint32_t)TERM_CAP_COLOR_TRUE | (uint32_t)TERM_CAP_COLOR_256 | (uint32_t)TERM_CAP_COLOR_16);
    break;

  case COLOR_MODE_16_COLOR:
    caps.color_level = TERM_COLOR_16;
    caps.color_count = 16;
    caps.capabilities &= ~((uint32_t)TERM_CAP_COLOR_TRUE | (uint32_t)TERM_CAP_COLOR_256);
    caps.capabilities |= (uint32_t)TERM_CAP_COLOR_16;
    break;

  case COLOR_MODE_256_COLOR:
    caps.color_level = TERM_COLOR_256;
    caps.color_count = 256;
    caps.capabilities &= ~(uint32_t)TERM_CAP_COLOR_TRUE;
    caps.capabilities |= ((uint32_t)TERM_CAP_COLOR_256 | (uint32_t)TERM_CAP_COLOR_16);
    break;

  case COLOR_MODE_TRUECOLOR:
    caps.color_level = TERM_COLOR_TRUECOLOR;
    caps.color_count = 16777216;
    caps.capabilities |= TERM_CAP_COLOR_TRUE | TERM_CAP_COLOR_256 | TERM_CAP_COLOR_16;
    break;
  }

  // Handle render mode overrides
  switch (GET_OPTION(render_mode)) {
  case RENDER_MODE_FOREGROUND:
    caps.capabilities &= ~(uint32_t)TERM_CAP_BACKGROUND;
    break;

  case RENDER_MODE_BACKGROUND:
    caps.capabilities |= TERM_CAP_BACKGROUND;
    break;

  case RENDER_MODE_HALF_BLOCK:
    caps.capabilities |= TERM_CAP_UTF8 | TERM_CAP_BACKGROUND;
    break;
  }

  // Handle UTF-8 override (force UTF-8 ON if user specified --utf8 true)
  if (GET_OPTION(force_utf8) == UTF8_SETTING_TRUE) {
    caps.utf8_support = true;
    caps.capabilities |= TERM_CAP_UTF8;
  }

  // Include client's render mode preference
  caps.render_mode = GET_OPTION(render_mode);

  return caps;
}

static inline float _calculate_luminance(uint8_t r, uint8_t g, uint8_t b) {
  return (0.2126f * r + 0.7152f * g + 0.0722f * b) / 255.0f;
}

bool terminal_has_dark_background(void) {
  // Try to query actual terminal background color via OSC 11
  uint8_t bg_r, bg_g, bg_b;
  if (terminal_query_background_color(&bg_r, &bg_g, &bg_b)) {
    // Calculate luminance from actual background color
    float luminance = _calculate_luminance(bg_r, bg_g, bg_b);
    return (luminance < 0.5f); // Dark if luminance < 50%
  }

  // Fall back to heuristic detection using environment variables

  // Check COLORFGBG environment variable (some Windows terminals set this)
  const char *colorfgbg = platform_getenv("COLORFGBG");
  if (colorfgbg) {
    const char *semicolon = strchr(colorfgbg, ';');
    if (semicolon && *(semicolon + 1)) {
      char *endptr;
      errno = 0;
      long bg_val = strtol(semicolon + 1, &endptr, 10);
      if (*endptr == '\0' && errno == 0 && bg_val >= 0 && bg_val <= INT_MAX) {
        int bg = (int)bg_val;
        if (bg >= 8) {
          return false; // Light background
        } else if (bg < 8) {
          return true; // Dark background
        }
      } else {
        log_error("terminal_is_dark_background: Invalid color value in COLORFGBG: %s", semicolon + 1);
      }
    }
  }

  // Check for VS Code terminal
  const char *term_program = platform_getenv("TERM_PROGRAM");
  if (term_program && strcmp(term_program, "vscode") == 0) {
    return true; // VS Code terminals are typically dark
  }

  // Check for Windows Terminal (modern terminals are typically dark)
  const char *wt_session = platform_getenv("WT_SESSION");
  if (wt_session) {
    return true; // Windows Terminal defaults to dark
  }

  // Default to dark background for Windows (most modern terminals)
  return true;
}

bool terminal_query_background_color(uint8_t *bg_r, uint8_t *bg_g, uint8_t *bg_b) {
  // Try to open CON device for direct terminal access
  HANDLE hConsole = CreateFileA("CONIN$", GENERIC_READ | GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE, NULL,
                                OPEN_EXISTING, 0, NULL);

  if (hConsole == INVALID_HANDLE_VALUE) {
    return false;
  }

  // Save original console mode
  DWORD old_mode;
  if (!GetConsoleMode(hConsole, &old_mode)) {
    CloseHandle(hConsole);
    return false;
  }

  // Set raw mode for reading response
  DWORD new_mode = old_mode & ~((DWORD)(ENABLE_LINE_INPUT | ENABLE_ECHO_INPUT));
  new_mode |= ENABLE_VIRTUAL_TERMINAL_INPUT;
  if (!SetConsoleMode(hConsole, new_mode)) {
    CloseHandle(hConsole);
    return false;
  }

  // Get output handle for writing query
  HANDLE hOut = GetStdHandle(STD_OUTPUT_HANDLE);
  if (hOut == INVALID_HANDLE_VALUE) {
    SetConsoleMode(hConsole, old_mode);
    CloseHandle(hConsole);
    return false;
  }

  // Send OSC 11 query (query background color)
  const char *query = "\x1b]11;?\x1b\\";
  DWORD written;
  if (!WriteConsoleA(hOut, query, (DWORD)strlen(query), &written, NULL)) {
    SetConsoleMode(hConsole, old_mode);
    CloseHandle(hConsole);
    return false;
  }

  // Read response with timeout (format: ESC]11;rgb:RRRR/GGGG/BBBBESC\ or BEL)
  char response[256];
  DWORD total_read = 0;
  DWORD start_time = GetTickCount();
  DWORD timeout_ms = 100;

  while (total_read < sizeof(response) - 1 && (GetTickCount() - start_time) < timeout_ms) {
    DWORD available = 0;
    INPUT_RECORD records[32];
    DWORD num_read = 0;

    // Check if input is available (non-blocking)
    if (!GetNumberOfConsoleInputEvents(hConsole, &available) || available == 0) {
      Sleep(10);
      continue;
    }

    // Read input events
    if (!ReadConsoleInput(hConsole, records, 32, &num_read)) {
      break;
    }

    // Process keyboard events
    for (DWORD i = 0; i < num_read && total_read < sizeof(response) - 1; i++) {
      if (records[i].EventType == KEY_EVENT && records[i].Event.KeyEvent.bKeyDown) {
        char c = records[i].Event.KeyEvent.uChar.AsciiChar;
        if (c != 0) {
          response[total_read++] = c;

          // Check for end of response (backslash or BEL)
          if (c == '\\' || c == '\x07') {
            goto parse_response;
          }
        }
      }
    }
  }

parse_response:
  // Restore console mode
  SetConsoleMode(hConsole, old_mode);
  CloseHandle(hConsole);

  if (total_read < 10) {
    return false; // Response too short
  }

  response[total_read] = '\0';

  // Parse response: ESC]11;rgb:RRRR/GGGG/BBBB...
  const char *rgb_start = strstr(response, "rgb:");
  if (!rgb_start) {
    return false;
  }
  rgb_start += 4; // Skip "rgb:"

  // Parse hex values (RRRR/GGGG/BBBB) using strtoul
  char *end = NULL;
  unsigned long r16 = strtoul(rgb_start, &end, 16);
  if (!end || *end != '/') {
    return false;
  }
  unsigned long g16 = strtoul(end + 1, &end, 16);
  if (!end || *end != '/') {
    return false;
  }
  unsigned long b16 = strtoul(end + 1, &end, 16);

  // Convert from 16-bit to 8-bit
  *bg_r = (uint8_t)(r16 >> 8);
  *bg_g = (uint8_t)(g16 >> 8);
  *bg_b = (uint8_t)(b16 >> 8);
  return true;
}

