void __sanitizer_cov_trace_pc_guard_init(uint32_t *start, uint32_t *stop) {
  if (start == NULL || stop == NULL || start == stop) {
    return;
  }

  if (*start != 0U) {
    return;
  }

  uint32_t counter = 1U;
  for (uint32_t *it = start; it < stop; ++it) {
    if (*it == 0U) {
      *it = counter++;
    }
  }
}

