static void render_test_label(image_t *image) {
  static const uint8_t glyphs[4][7] = {
      {4, 4, 31, 4, 4, 5, 2},     // t
      {0, 0, 14, 17, 31, 16, 15}, // e
      {0, 0, 15, 16, 14, 1, 30},  // s
      {4, 4, 31, 4, 4, 5, 2},     // t
  };
  int scale = image->w / 31;
  if (scale > image->h / 22)
    scale = image->h / 22;
