const uint8_t *test_pattern_rgba(test_pattern_t *p) {
  if (!p || !p->image)
    return NULL;
  size_t count = (size_t)p->image->w * p->image->h;
  if (!p->rgba)
    p->rgba = SAFE_MALLOC(count * 4, uint8_t *);
  for (size_t i = 0; i < count; i++) {
