  double phase = fmod(time_ms, index ? 4000 : 10000) / (index ? 4000 : 10000);
  rgb_pixel_t dark = {16, 24, 32}, white = {255, 255, 255};
  rgb_pixel_t first = hue(phase * 360, 0.5), last = hue(fmod(phase + 0.5, 1) * 360, 0.5);
