  double cx = w + radius - phase * (w + radius * 2), cy = h / 2.0 + sin(phase * 12.566370614359172) * h / 4.0;
  rgb_pixel_t colors[12];
  for (int i = 0; i < 12; i++)
    colors[i] = hue(i * 30, 0.55);
