        if (d2 > (radius + 0.75) * (radius + 0.75))
          continue;
        double coverage = 1;
        if (d2 > (radius - 0.75) * (radius - 0.75)) {
          int inside = 0;
          for (int sy = 0; sy < 4; sy++)
            for (int sx = 0; sx < 4; sx++) {
              double dx = x + (sx + 0.5) / 4 - cx, dy = y + (sy + 0.5) / 4 - cy;
              if (dx * dx + dy * dy < radius * radius)
