void ob_reserve(outbuf_t *ob, size_t need) {
  if (!ob)
    return;
  if (ob->cap == 0) {
    // Always allocate at least default capacity on first call
    size_t ncap = 4096;
    while (ncap < ob->len + need)
      ncap = (ncap * 3) / 2;
    // SAFE_REALLOC handles NULL ptr as malloc - this is safe
    ob->buf = SAFE_REALLOC(ob->buf, ncap, char *);
    ob->cap = ncap;
  } else if (ob->len + need > ob->cap) {
    // Expand existing buffer
    size_t ncap = ob->cap;
    while (ncap < ob->len + need)
      ncap = (ncap * 3) / 2;
    ob->buf = SAFE_REALLOC(ob->buf, ncap, char *);
    ob->cap = ncap;
  }
}

void ob_putc(outbuf_t *ob, char c) {
  if (!ob)
    return;
  ob_reserve(ob, 1);
  ob->buf[ob->len++] = c;
}

void ob_write(outbuf_t *ob, const void *s, size_t n) {
  if (!ob || n == 0)
    return;
  ob_reserve(ob, n);
  SAFE_MEMCPY(ob->buf + ob->len, ob->cap - ob->len, s, n);
  ob->len += n;
}

void ob_term(outbuf_t *ob) {
  if (!ob)
    return;
  // Reserve space for null terminator if needed
  if (ob->len >= ob->cap) {
    ob_reserve(ob, 1);
  }
  // Append null terminator WITHOUT incrementing length
  // (null terminator is not part of the string length)
  ob->buf[ob->len] = '\0';
}

void ob_u8(outbuf_t *ob, uint8_t v) {
  if (!ob)
    return;
  if (v >= 100) {
    uint8_t d0 = v / 100;
    uint8_t r = v % 100;
    uint8_t d1 = r / 10;
    uint8_t d2 = r % 10;
    ob_putc(ob, '0' + d0);
    ob_putc(ob, '0' + d1);
    ob_putc(ob, '0' + d2);
  } else if (v >= 10) {
    uint8_t d1 = v / 10;
    uint8_t d2 = v % 10;
    ob_putc(ob, '0' + d1);
    ob_putc(ob, '0' + d2);
  } else {
    ob_putc(ob, '0' + v);
  }
}

void ob_u32(outbuf_t *ob, uint32_t v) {
  if (!ob)
    return;
  char tmp[10];
  int i = 0;
  do {
    tmp[i++] = '0' + (v % 10u);
    v /= 10u;
  } while (v);
  ob_reserve(ob, (size_t)i);
  while (i--)
    ob->buf[ob->len++] = tmp[i];
}

