  for (int y = 0; y < h; y++) {
    luminance_fn((const uint8_t *)(image->pixels + (size_t)y * w), luminance_row, (size_t)w);
    for (int x = 0; x < w; x++) {
      rgb_pixel_t pixel = image->pixels[y * w + x];

