      uint8_t safe_luminance = clamp_rgb(luminance);
      uint8_t luma_idx = (uint8_t)(safe_luminance >> 2); // 0-63 index (same as SIMD)
      const utf8_char_t *char_info = &utf8_cache->cache64[luma_idx];

