          }
        }
      }

      x = j;
    }

    emit_reset(&ob);
    if (y + 2 < height) {
      ob_putc(&ob, '\n');
    }
    cur_fg = cur_bg = -1;
  }

  ob_term(&ob);
  return ob.buf;
}

