      for (; j < width; ++j) {
        const uint8_t *qT = rowT + (size_t)j * 3u;
        uint8_t color_fg2 = rgb_to_256color(qT[0], qT[1], qT[2]);

        uint8_t color_bg2 = color_fg2;
        if (rowB) {
          const uint8_t *qB = rowB + (size_t)j * 3u;
          color_bg2 = rgb_to_256color(qB[0], qB[1], qB[2]);
        }

        if (color_fg2 != color_fg || color_bg2 != color_bg)
          break;
      }
      uint32_t run = (uint32_t)(j - x);

      // Check if transparent
      bool is_transparent = (rT == 0 && gT == 0 && bT == 0 && rB == 0 && gB == 0 && bB == 0);

      if (is_transparent) {
        if (cur_fg != -1 || cur_bg != -1) {
          emit_reset(&ob);
          cur_fg = cur_bg = -1;
        }
        // Emit spaces for transparent area (no RLE for padding)
        for (uint32_t k = 0; k < run; ++k) {
          ob_write(&ob, " ", 1);
        }
      } else {
        // Emit 256-color codes if changed
        if (cur_fg != color_fg) {
          char buf[16];
          char *ptr = append_256color_fg(buf, color_fg);
          ob_write(&ob, buf, (size_t)(ptr - buf));
          cur_fg = color_fg;
        }
        if (cur_bg != color_bg) {
          char buf[16];
          char *ptr = append_256color_bg(buf, color_bg);
          ob_write(&ob, buf, (size_t)(ptr - buf));
          cur_bg = color_bg;
        }

        ob_write(&ob, HB, 3);
        if (rep_is_profitable(run)) {
          emit_rep(&ob, run - 1);
        } else {
          for (uint32_t k = 1; k < run; ++k) {
            ob_write(&ob, HB, 3);
          }
        }
      }

      x = j;
    }

    emit_reset(&ob);
    if (y + 2 < height) {
      ob_putc(&ob, '\n');
    }
    cur_fg = cur_bg = -1;
  }

  ob_term(&ob);
  return ob.buf;
}

