  mediaSource,
  onStartWebcam,
  onStopWebcam,
  webcamActionLabels,
  onUploadClick,
  videoRef,
  showConnectionButton = false,
  onConnectionClick,
  onSettingsClick,
  onDeviceSetupClick,
  showSettingsButton = true,
  settingsOpen = false,
  compactVerticalSpacing = false,
  statusControls,
}: PageControlBarProps) {
  const getFpsColor = () => {
    if (fps === undefined || fps === null) return "text-terminal-8";
    if (targetFps === undefined) return "text-terminal-2"; // default green

    const difference = targetFps - fps;
    if (difference >= 10) return "text-terminal-1"; // red if 10+ fps slower
    return "text-terminal-2"; // green if near target
  };

  const showWebcamButton = onStartWebcam || onStopWebcam;

  const handleTogglePause = () => {
    if (!videoRef?.current) return;
    if (videoRef.current.paused) {
      void videoRef.current.play();
    } else {
      videoRef.current.pause();
    }
  };

  const handleRestart = () => {
    if (!videoRef?.current) return;
    videoRef.current.currentTime = 0;
    void videoRef.current.play();
  };

  const handleToggleMute = () => {
    if (!videoRef?.current) return;
    videoRef.current.muted = !videoRef.current.muted;
  };

  return (
    <div
      className={`${compactVerticalSpacing ? "px-0 py-0 border-0" : "px-4 py-3 border-b border-terminal-8"} flex-shrink-0`}
    >
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-3">
          {statusDotColor && (
            <div className="flex items-center gap-2">
              <div className={`w-2 h-2 rounded-full ${statusDotColor}`} />
              {title && <span className="text-sm font-semibold">{title}</span>}
            </div>
          )}
          {!statusDotColor && title && (
            <h2 className="text-sm font-semibold">{title}</h2>
          )}
          {dimensions && dimensions.cols > 0 && (
            <span className="text-xs text-terminal-8">
              {dimensions.cols}x{dimensions.rows}
            </span>
          )}
          {status && (
            <span className="status text-xs text-terminal-8">{status}</span>
          )}
          {fps !== undefined && (
            <span className={`text-xs ${getFpsColor()}`}>
              FPS: {fps}
              {targetFps && ` / ${targetFps}`}
            </span>
          )}
          {fps !== undefined && showBandwidth && <BandwidthMeter />}
          {statusControls && (
            <div className="flex items-center gap-2">{statusControls}</div>
          )}
        </div>
        <div className="flex flex-wrap gap-2">
          {/* File playback controls (shown when playing a video file) */}
