const readFile = async (
    file: File | undefined,
    setContents: (value: string) => void,
    setName: (value: string) => void,
    validate: (value: string) => void | Promise<void>,
  ) => {
    if (!file) return;
    const contents = await readCryptoKeyFile(file);
    setContents(contents);
    setName(file.name);
    await validate(contents);
  };

