        .then(() => {
          console.log(
            `[Mirror] Calling startWebcam at ${performance.now().toFixed(0)}ms`,
          );
          return startWebcam();
        })
        .then(() => {
          console.log(
            `[Mirror] startWebcam completed at ${performance.now().toFixed(0)}ms`,
