                    </button>
                    {connectionState === ConnectionState.CONNECTED ? (
                      <button
                        type="button"
                        onClick={disconnectMedia}
                        className="border border-red-700 bg-red-700 text-white cursor-pointer hover:bg-red-800 hover:border-red-800 rounded px-3 py-2"
