function AsciiRenderer(
    {
      keyboardEnabled = true,
      splashEnabled = true,
      uiLoading,
      uiMessage,
      onUiAction,
      onDimensionsChange,
      onFpsChange,
      error,
      showFps = true,
      connectionState,
      wasmModuleReady,
      initializeOptions = true,
      matrixMode = false,
      zalgo = 0,
      columns = 0,
      rows = 0,
    },
    ref,
  ) {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    // Initialize renderer and get refs
    const {
      moduleRef,
      setupDoneRef,
      rendererPtrRef,
      resizeTimeoutRef,
      setUpdateDimensions,
      triggerRendererRecreate,
    } = useInitAsciiRenderer({
      canvasRef: canvasRef as RefObject<HTMLCanvasElement | null>,
      wasmModuleReady,
      initializeOptions,
      matrixMode,
      columns,
      rows,
    });

    // Set up imperative handle and get updateDimensions + fpsDisplayRef
    const { updateDimensions, fpsDisplayRef, onKeyDown } =
      useAsciiRendererHandle({
        ref,
        uiLoading:
          splashEnabled &&
          (uiLoading ?? (connectionState === 1 || connectionState === 2)),
        uiMessage,
        onUiAction,
        moduleRef,
        setupDoneRef,
        rendererPtrRef,
        canvasRef: canvasRef as RefObject<HTMLCanvasElement | null>,
        resizeTimeoutRef,
        showFps,
        zalgo,
        onFpsChange,
        onDimensionsChange,
        onRecreateRenderer: triggerRendererRecreate,
      });

    // Provide updateDimensions to the initialization hook
    setUpdateDimensions(updateDimensions);

    return (
      <div className="ascii-canvas-container w-full h-full min-w-0 min-h-0 flex flex-col items-center justify-center overflow-hidden relative flex-1">
        <style>
          {`
          canvas {
            display: block;
            image-rendering: pixelated;
            image-rendering: crisp-edges;
          }
        `}
        </style>
        <canvas
          ref={canvasRef}
          tabIndex={keyboardEnabled ? 0 : -1}
          aria-label={
            keyboardEnabled
              ? "ASCII terminal. Press question mark for keyboard settings."
              : "ASCII demo"
          }
          onKeyDown={keyboardEnabled ? onKeyDown : undefined}
          onPointerDown={
            keyboardEnabled ? (event) => event.currentTarget.focus() : undefined
          }
          className="ascii-canvas max-w-full max-h-full shrink-0 object-contain"
        />
        {/* Disconnected overlay - only show if error or explicitly disconnected */}
        {connectionState === 4 && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/40 rounded pointer-events-none">
            <div className="text-5xl font-bold text-red-500 drop-shadow-lg">
              CONNECTION ERROR
            </div>
          </div>
        )}

        {/* FPS counter - hidden, displayed in control bar instead */}
        {showFps && (
          <div ref={fpsDisplayRef} style={{ display: "none" }}>
            --
          </div>
        )}

        {/* Error bar */}
        {error && (
          <div className="px-4 pb-2">
            <div className="p-4 bg-terminal-1 text-terminal-fg rounded">
              {error}
            </div>
          </div>
        )}
      </div>
    );
  }

export function startGridStabilityProbe(canvas: HTMLCanvasElement): void {
  if (canvas.dataset["gridProbe"]) return;
  const started = performance.now() + 10_000;
  const result = {
    samples: 0,
    minCanvasTop: Infinity,
    maxCanvasTop: -Infinity,
    minPatternTop: Infinity,
    maxPatternTop: -Infinity,
    complete: false,
  };
  canvas.dataset["gridProbe"] = JSON.stringify(result);
  const timer = setInterval(() => {
    if (!canvas.isConnected) {
      clearInterval(timer);
      return;
    }
    if (performance.now() < started) return;
    const top = canvas.getBoundingClientRect().top;
    result.minCanvasTop = Math.min(result.minCanvasTop, top);
    result.maxCanvasTop = Math.max(result.maxCanvasTop, top);
    const context = canvas.getContext("2d");
    if (context) {
      const pixels = context.getImageData(
        0,
        0,
        canvas.width,
        canvas.height,
      ).data;
      let patternTop = -1;
      for (let y = 0; y < canvas.height && patternTop < 0; y++) {
        for (let x = 0; x < canvas.width; x += 2) {
          const offset = (y * canvas.width + x) * 4;
          if (
            pixels[offset]! < 30 &&
            pixels[offset + 1]! > 180 &&
            pixels[offset + 2]! < 30
          ) {
            patternTop = y;
            break;
          }
        }
      }
      if (patternTop >= 0) {
        result.minPatternTop = Math.min(result.minPatternTop, patternTop);
        result.maxPatternTop = Math.max(result.maxPatternTop, patternTop);
        result.samples++;
      }
    }
    result.complete = performance.now() - started >= 60_000;
    canvas.dataset["gridProbe"] = JSON.stringify(result);
    if (result.complete) clearInterval(timer);
  }, 250);
}

