        changedFrameTimesRef.current.length > 0 &&
        changedFrameTimesRef.current[0]! < cutoff
      ) {
        changedFrameTimesRef.current.shift();
      }
      const fps = changedFrameTimesRef.current.length;
      if (lastReportedFpsRef.current === fps) return;
